// ---------- AGENDAMENTOS ----------
// Todo cron passa por agendar(): registra o que está realmente agendado (usado no resumo de
// inicialização) e loga início/fim/duração/erro de cada execução — antes vários crons rodavam
// (ou falhavam) sem deixar rastro no log.
const AGENDAMENTOS = [];
// Crons que já imprimem a própria linha de "iniciando" — o wrapper só loga o fim/erro deles.
const CRONS_COM_LOG_PROPRIO = new Set([
  'Lembretes do ciclo menstrual', 'Avisos de período fértil', 'Verificação de início do período',
  'Acompanhamento diário do período', 'Polling do extrato bancário (Sicredi + Neon)'
]);

function descreverCron(expr) {
  const p = String(expr).trim().split(/\s+/);
  if (p.length !== 5) return String(expr);
  const [min, hora, dia, mes, dow] = p;
  const dias = ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb'];
  const hhmm = (/^\d+$/.test(min) && /^\d+$/.test(hora)) ? `${hora.padStart(2, '0')}:${min.padStart(2, '0')}` : null;
  if (/^\*\/\d+$/.test(min) && hora === '*' && dia === '*' && mes === '*' && dow === '*') return `a cada ${min.slice(2)} min`;
  if (hhmm && dia === '*' && mes === '*' && dow === '*') return `todo dia às ${hhmm}`;
  if (hhmm && dia === '*' && mes === '*') return `${dow.split(',').map((d) => dias[Number(d) % 7] || d).join('/')} às ${hhmm}`;
  if (hhmm && /^\d+$/.test(dia) && mes === '*' && dow === '*') return `dia ${dia} às ${hhmm}`;
  return String(expr);
}

function agendar(expr, nome, fn, opts = {}) {
  AGENDAMENTOS.push({ expr, nome, quando: descreverCron(expr) });
  return cron.schedule(expr, async (...args) => {
    const t0 = Date.now();
    const dur = () => `${((Date.now() - t0) / 1000).toFixed(1)}s`;
    if (!CRONS_COM_LOG_PROPRIO.has(nome)) console.log(`⏰ [CRON] ${nome} — iniciando`);
    try {
      const r = await fn(...args);
      console.log(`✅ [CRON] ${nome} — concluído em ${dur()}`);
      return r;
    } catch (error) {
      console.error(`❌ [CRON] ${nome} — falhou após ${dur()}: ${error && error.message ? error.message : error}`);
    }
  }, opts);
}
