function getParcelDate(referenceDate, monthOffset, desiredDay) {
  let target = referenceDate.clone().add(monthOffset, 'months').date(desiredDay);
  const lastDay = target.daysInMonth();
  if (desiredDay > lastDay) {
    target = target.date(lastDay);
  }
  return target;
}

// Regra do ciclo de fatura do cartão de crédito: compras feitas entre o dia 05 de um mês
// e o dia 04 do mês seguinte são todas registradas com a data do dia 05 do mês seguinte
// (dia de fechamento -> já entra na fatura seguinte). Ex.: compra em 29/08 -> registrada em 05/09.
// Recebe e devolve uma data no formato 'YYYY-MM-DD'.
function calcularDataFaturaCartao(dataCompraISO) {
  const m = moment(dataCompraISO, 'YYYY-MM-DD', true);
  if (!m.isValid()) return dataCompraISO;
  const dia = m.date();
  // .date(5) primeiro evita o bug de overflow do moment ao somar mês em dias 29-31
  // (ex: 31/01 + 1 mês vira 03/03 em vez de fev, porque fevereiro não tem dia 31)
  let resultado = m.clone().date(5);
  if (dia >= 5) {
    resultado = resultado.add(1, 'month');
  }
  return resultado.format('YYYY-MM-DD');
}
