function traceTx(event, payload) {
  try {
    if (!TRACE_TX) return;
    const data = payload && typeof payload === 'object' ? payload : { value: payload };
    if (TRACE_TX_MATCH) {
      let hay = '';
      try {
        hay = JSON.stringify({ event, ...data }).toLowerCase();
      } catch (e) {
        hay = String(event || '').toLowerCase();
      }
      if (!hay.includes(TRACE_TX_MATCH)) return;
    }
    const out = { ts: moment().toISOString(), event, ...data };
    console.log('TRACE_TX', JSON.stringify(out));
  } catch (_) {}
}

