// Função para identificar e mapear estabelecimento
function mapearEstabelecimento(textoOCR) {
    if (!textoOCR) return null;
    
    const textoUpper = textoOCR.toUpperCase();
    
    // Procurar por correspondência no mapa
    for (const [busca, nomeSalvar] of Object.entries(ESTABELECIMENTOS_MAP)) {
        if (textoUpper.includes(busca.toUpperCase())) {
            return {
                encontrado: true,
                buscaOriginal: busca,
                nomeMapeado: nomeSalvar,
                nomeOriginal: extrairNomeEstabelecimento(textoOCR, busca)
            };
        }
    }
    
    return { encontrado: false, nomeMapeado: null };
}

// Função para extrair o nome exato do estabelecimento do texto OCR
function extrairNomeEstabelecimento(textoOCR, termoBusca) {
    const linhas = textoOCR.split('\n');
    
    for (const linha of linhas) {
        const linhaUpper = linha.toUpperCase();
        const index = linhaUpper.indexOf(termoBusca.toUpperCase());
        
        if (index !== -1) {
            // Pega o nome completo (geralmente está na mesma linha)
            // Remove caracteres especiais e limita tamanho
            let nome = linha.trim();
            
            // Remove palavras comuns que não são parte do nome
            nome = nome.replace(/\b(PAGAMENTO|CARTAO|DEBITO|CREDITO|VALOR|TOTAL)\b/gi, '');
            nome = nome.replace(/\d+/g, ''); // Remove números
            nome = nome.replace(/[^\w\s]/g, ''); // Remove pontuação
            
            return nome.trim() || termoBusca;
        }
    }
    
    return termoBusca;
}

