// Sessões gravadas em SQLite (dados-financeiros/sessions.db) em vez do MemoryStore padrão,
// para o login sobreviver a reinícios do pm2 — antes, cada restart derrubava todo mundo e a
// dashboard aberta passava a mostrar "Erro ao carregar dashboard".
class SqliteSessionStore extends session.Store {
  constructor(file) {
    super();
    fs.mkdirSync(path.dirname(file), { recursive: true });
    this.db = new Database(file);
    this.db.pragma('journal_mode = WAL');
    this.db.exec('CREATE TABLE IF NOT EXISTS sessions (sid TEXT PRIMARY KEY, sess TEXT NOT NULL, expires INTEGER NOT NULL)');
    this.stmtGet = this.db.prepare('SELECT sess FROM sessions WHERE sid = ? AND expires > ?');
    this.stmtSet = this.db.prepare('INSERT OR REPLACE INTO sessions (sid, sess, expires) VALUES (?, ?, ?)');
    this.stmtTouch = this.db.prepare('UPDATE sessions SET expires = ? WHERE sid = ?');
    this.stmtDestroy = this.db.prepare('DELETE FROM sessions WHERE sid = ?');
    this.stmtPurge = this.db.prepare('DELETE FROM sessions WHERE expires <= ?');
    this.stmtPurge.run(Date.now());
    setInterval(() => {
      try { this.stmtPurge.run(Date.now()); } catch (_) {}
    }, 60 * 60 * 1000).unref();
  }

  static expiresOf(sess) {
    const exp = sess && sess.cookie && sess.cookie.expires ? new Date(sess.cookie.expires).getTime() : NaN;
    return Number.isFinite(exp) ? exp : Date.now() + 24 * 60 * 60 * 1000;
  }

  get(sid, cb) {
    try {
      const row = this.stmtGet.get(sid, Date.now());
      cb(null, row ? JSON.parse(row.sess) : null);
    } catch (err) { cb(err); }
  }

  set(sid, sess, cb) {
    try {
      this.stmtSet.run(sid, JSON.stringify(sess), SqliteSessionStore.expiresOf(sess));
      cb && cb(null);
    } catch (err) { cb && cb(err); }
  }

  touch(sid, sess, cb) {
    try {
      this.stmtTouch.run(SqliteSessionStore.expiresOf(sess), sid);
      cb && cb(null);
    } catch (err) { cb && cb(err); }
  }

  destroy(sid, cb) {
    try {
      this.stmtDestroy.run(sid);
      cb && cb(null);
    } catch (err) { cb && cb(err); }
  }
}

