function requireAuth(req, res, next) {
  if (!(req.session && req.session.user)) {
    if (String(req.originalUrl || '').startsWith('/api/')) {
      return res.status(401).json({ success: false, error: 'NOT_AUTHENTICATED', redirect: '/login' });
    }
    return res.redirect('/login');
  }

  const pathName = String(req.path || '');
  if (pathName.startsWith('/assinatura') || pathName === '/api/check-payment-status') {
    return next();
  }
  if (pathName === '/biometria' || pathName.startsWith('/api/biometric/') || pathName.startsWith('/face-models')) {
    return next();
  }

  const sessionRole = req.session.user && req.session.user.role ? String(req.session.user.role) : 'user';
  if (sessionRole === 'admin') return next();

  try {
    if (!db) return res.status(503).json({ success: false, error: 'DB_NOT_READY' });
    const userId = Number(req.session.user && typeof req.session.user.id !== 'undefined' ? req.session.user.id : NaN);
    if (!Number.isFinite(userId)) return res.redirect('/login');

    const row = db.prepare(`
      SELECT role, plan_type, plan_expires_at, subscription_status, trial_ended_at
      FROM users
      WHERE id = ?
      LIMIT 1
    `).get(userId);

    if (!row) return res.redirect('/login');
    if (row.role === 'admin') return next();

    const now = moment();
    const planType = String(row.plan_type || 'free');
    const status = row.subscription_status ? String(row.subscription_status) : null;
    const planExpiresOk = row.plan_expires_at && moment(row.plan_expires_at).isAfter(now);
    const trialOk = row.trial_ended_at && moment(row.trial_ended_at).isAfter(now);

    const planOk = (planType !== 'free' && planExpiresOk) || (status === 'active' && planExpiresOk) || (status === 'trial' && trialOk);
    if (planOk) {
      // Verificação facial semanal: se cadastrou rosto e não verificou na última semana, redireciona
      try {
        const bio = getBiometricStatus(userId);
        if (bio.needsFaceVerification) {
          if (pathName.startsWith('/api/')) {
            return res.status(403).json({ success: false, error: 'FACE_VERIFICATION_REQUIRED', redirect: '/biometria' });
          }
          return res.redirect('/biometria');
        }
      } catch (_) {}
      return next();
    }

    if (pathName.startsWith('/api/')) {
      return res.status(403).json({ success: false, error: 'SUBSCRIPTION_REQUIRED', redirect: '/assinatura/renovar' });
    }
    return res.redirect('/assinatura/renovar');
  } catch (_) {
    return next();
  }
}

function requireAdmin(req, res, next) {
  if (req.session.user && req.session.user.role === 'admin') {
    return next();
  }
  res.status(403).json({ error: 'Acesso negado. Apenas administradores.' });
}

function normalizeEmailLike(value) {
  const v = String(value || '').trim().toLowerCase();
  if (!v) return null;
  if (v.includes('@')) return v;
  return `${v}@local`;
}

function hashPassword(password) {
  const pwd = String(password || '');
  const salt = crypto.randomBytes(16);
  const key = crypto.scryptSync(pwd, salt, 64);
  return `scrypt$${salt.toString('base64')}$${key.toString('base64')}`;
}

function verifyPassword(password, storedHash) {
  try {
    const pwd = String(password || '');
    const stored = String(storedHash || '');
    if (!stored.startsWith('scrypt$')) return false;
    const parts = stored.split('$');
    if (parts.length !== 3) return false;
    const salt = Buffer.from(parts[1], 'base64');
    const expected = Buffer.from(parts[2], 'base64');
    const actual = crypto.scryptSync(pwd, salt, expected.length);
    return crypto.timingSafeEqual(actual, expected);
  } catch (_) {
    return false;
  }
}

function setupGoogleAuth() {
  try {
    if (!passport || !GoogleStrategy) return;
    const clientID = String(process.env.GOOGLE_CLIENT_ID || '').trim();
    const clientSecret = String(process.env.GOOGLE_CLIENT_SECRET || '').trim();
    const publicUrl = String(process.env.PUBLIC_URL || `http://localhost:${PORT}`).trim();
    const baseUrl = publicUrl.endsWith('/') ? publicUrl.slice(0, -1) : publicUrl;
    if (!clientID || !clientSecret) return;

    passport.serializeUser((user, done) => done(null, user && user.id ? user.id : null));
    passport.deserializeUser((id, done) => {
      try {
        if (!db || !id) return done(null, false);
        const user = db.prepare('SELECT id, email, name, role, plan_type FROM users WHERE id = ?').get(id);
        done(null, user || false);
      } catch (e) {
        done(e);
      }
    });

    passport.use(new GoogleStrategy({
      clientID,
      clientSecret,
      callbackURL: `${baseUrl}/auth/google/callback`,
      passReqToCallback: true
    }, (req, accessToken, refreshToken, profile, done) => {
      try {
        if (!db) return done(new Error('DB_NOT_READY'));

        const adminLinkId = req && req.adminLinkUserId;
        if (adminLinkId) {
          const adminUser = db.prepare(`SELECT id, email, name, role, plan_type FROM users WHERE id = ? AND role = 'admin' LIMIT 1`).get(adminLinkId);
          if (adminUser) {
            try { saveGoogleOAuthTokens(adminUser.id, accessToken, refreshToken); } catch (e) {}
            console.log(`🔗 [google] Conta Google vinculada ao admin id=${adminUser.id} (sessão mantida, sem troca de usuário)`);
            return done(null, adminUser);
          }
        }
        const email = profile && profile.emails && profile.emails[0] ? profile.emails[0].value : null;
        if (!email) return done(new Error('E-mail não obtido do Google'));

        let user = db.prepare('SELECT id, email, name, role, plan_type FROM users WHERE lower(email) = ? LIMIT 1').get(String(email).trim().toLowerCase());
        if (!user) {
          const nowMoment = moment().tz('America/Sao_Paulo');
          const now = nowMoment.toISOString();
          const trialEnd = nowMoment.clone().add(7, 'days').toISOString();
          const name = profile && profile.displayName ? profile.displayName : String(email).split('@')[0];
          const info = db.prepare(`
            INSERT INTO users (
              email, password_hash, name, role, plan_type, plan_expires_at, telegram_id,
              created_at, updated_at,
              trial_started_at, trial_ended_at, subscription_status
            )
            VALUES (?, ?, ?, 'user', 'free', NULL, NULL, ?, ?, ?, ?, 'trial')
          `).run(String(email).trim().toLowerCase(), 'oauth$google', name, now, now, now, trialEnd);
          user = db.prepare('SELECT id, email, name, role, plan_type FROM users WHERE id = ?').get(info.lastInsertRowid);
          try { copyGlobalCategoriesToUser(info.lastInsertRowid, String(email).split('@')[0]); } catch (e) {}

          try {
            const adminEmail = process.env.ADMIN_EMAIL || process.env.EMAIL_USER;
            const nowStr = moment().tz('America/Sao_Paulo').format('DD/MM/YYYY HH:mm:ss');
            const userName = (profile && profile.displayName) ? profile.displayName : String(email).split('@')[0];
            const plainMessage =
              `🆕 *NOVO USUÁRIO VIA GOOGLE*\n\n` +
              `👤 Nome: ${userName}\n` +
              `📧 E-mail: ${email}\n` +
              `📅 Data: ${nowStr}`;

            for (const chatId of TG_CHAT_IDS) {
              try {
                bot.telegram.sendMessage(chatId, plainMessage, { parse_mode: 'Markdown' })
                  .then(() => console.log(`✅ Telegram enviado para ${chatId}`))
                  .catch((err) => console.error(`❌ Erro Telegram ${chatId}:`, err && err.message ? err.message : err));
              } catch (err) {
                console.error(`❌ Erro Telegram ${chatId}:`, err && err.message ? err.message : err);
              }
            }

            if (WHATSAPP_ENABLED) {
              enviarWhatsAppParaTodos(String(plainMessage || '').replace(/\*/g, ''))
                .then(() => console.log(`✅ WhatsApp enviado para o grupo: ${WHATSAPP_GRUPO_TRANSACOES}`))
                .catch((err) => console.error('❌ Erro WhatsApp:', err && err.message ? err.message : err));
            }

            if (adminEmail) {
              const html =
                '<h2>🆕 Novo usuário cadastrado via Google</h2>' +
                `<p><strong>Nome:</strong> ${userName}</p>` +
                `<p><strong>E-mail:</strong> ${email}</p>` +
                `<p><strong>Data/hora:</strong> ${nowStr}</p>` +
                '<hr />' +
                '<p>Este usuário acabou de se conectar ao sistema pela primeira vez usando a conta Google.</p>';
              enviarEmail(adminEmail, '🆕 Novo usuário via Google', html)
                .then((r) => {
                  if (r && r.success) console.log(`✅ E-mail enviado para ${adminEmail}`);
                  else console.error('❌ Erro ao enviar e-mail:', (r && r.error) ? r.error : 'Falha ao enviar e-mail');
                })
                .catch((err) => console.error('❌ Erro ao enviar e-mail:', err && err.message ? err.message : err));
            }
          } catch (e) {}
        }

        try {
          saveGoogleOAuthTokens(user && user.id ? user.id : null, accessToken, refreshToken);
        } catch (e) {}

        return done(null, user);
      } catch (e) {
        return done(e);
      }
    }));

    googleAuthEnabled = true;
  } catch (_) {}
}

function saveGoogleOAuthTokens(userId, accessToken, refreshToken) {
  try {
    const uid = Number(userId);
    if (!db || !Number.isFinite(uid)) return;
    if (!tableHasColumn('users', 'google_access_token')) return;
    const access = accessToken ? String(accessToken) : null;
    const refresh = refreshToken ? String(refreshToken) : null;
    const nowIso = moment().toISOString();
    if (refresh && tableHasColumn('users', 'google_refresh_token')) {
      db.prepare(`
        UPDATE users
        SET google_access_token = ?,
            google_refresh_token = ?,
            google_token_updated_at = ?,
            google_token_expires_at = COALESCE(google_token_expires_at, NULL)
        WHERE id = ?
      `).run(access, refresh, nowIso, uid);
      return;
    }
    db.prepare(`
      UPDATE users
      SET google_access_token = ?,
          google_token_updated_at = ?
      WHERE id = ?
    `).run(access, nowIso, uid);
  } catch (_) {}
}

function getGoogleOAuthTokens(userId) {
  try {
    const uid = Number(userId);
    if (!db || !Number.isFinite(uid)) return null;
    if (!tableHasColumn('users', 'google_access_token')) return null;
    const row = db.prepare(`
      SELECT
        google_access_token AS accessToken,
        google_refresh_token AS refreshToken,
        google_token_expires_at AS expiresAt
      FROM users
      WHERE id = ?
      LIMIT 1
    `).get(uid);
    if (!row) return null;
    return {
      accessToken: row.accessToken ? String(row.accessToken) : null,
      refreshToken: row.refreshToken ? String(row.refreshToken) : null,
      expiresAt: typeof row.expiresAt === 'number' ? row.expiresAt : (row.expiresAt ? Number(row.expiresAt) : null)
    };
  } catch (_) {
    return null;
  }
}

function updateGoogleAccessToken(userId, accessToken, expiresInSeconds) {
  try {
    const uid = Number(userId);
    if (!db || !Number.isFinite(uid)) return;
    if (!tableHasColumn('users', 'google_access_token')) return;
    const nowIso = moment().toISOString();
    const expiresAt = Number.isFinite(Number(expiresInSeconds))
      ? (Date.now() + Math.max(0, Number(expiresInSeconds)) * 1000)
      : null;
    if (tableHasColumn('users', 'google_token_expires_at')) {
      db.prepare(`
        UPDATE users
        SET google_access_token = ?,
            google_token_expires_at = ?,
            google_token_updated_at = ?
        WHERE id = ?
      `).run(accessToken ? String(accessToken) : null, expiresAt, nowIso, uid);
      return;
    }
    db.prepare(`
      UPDATE users
      SET google_access_token = ?,
          google_token_updated_at = ?
      WHERE id = ?
    `).run(accessToken ? String(accessToken) : null, nowIso, uid);
  } catch (_) {}
}

async function refreshGoogleAccessToken(userId) {
  const tokens = getGoogleOAuthTokens(userId);
  if (!tokens || !tokens.refreshToken) return { success: false, error: 'NO_REFRESH_TOKEN' };
  const clientID = String(process.env.GOOGLE_CLIENT_ID || '').trim();
  const clientSecret = String(process.env.GOOGLE_CLIENT_SECRET || '').trim();
  if (!clientID || !clientSecret) return { success: false, error: 'GOOGLE_OAUTH_NOT_CONFIGURED' };

  try {
    const params = new URLSearchParams();
    params.set('client_id', clientID);
    params.set('client_secret', clientSecret);
    params.set('refresh_token', tokens.refreshToken);
    params.set('grant_type', 'refresh_token');

    const resp = await axios.post('https://oauth2.googleapis.com/token', params.toString(), {
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      timeout: 15000
    });

    const accessToken = resp && resp.data && resp.data.access_token ? String(resp.data.access_token) : null;
    const expiresIn = resp && resp.data && resp.data.expires_in ? Number(resp.data.expires_in) : null;
    if (!accessToken) return { success: false, error: 'REFRESH_FAILED_NO_ACCESS_TOKEN' };
    updateGoogleAccessToken(userId, accessToken, expiresIn);
    return { success: true, accessToken };
  } catch (e) {
    return { success: false, error: 'REFRESH_FAILED', details: e && e.response && e.response.data ? e.response.data : (e && e.message ? e.message : 'Erro ao renovar token') };
  }
}

let transporter = null;

function getTransporter() {
  if (transporter) return transporter;
  const user = process.env.EMAIL_USER;
  const pass = process.env.EMAIL_PASS;
  if (!user || !pass) {
    console.warn('⚠️ SMTP não configurado (EMAIL_USER/EMAIL_PASS faltando) – envio de e-mail desabilitado');
    return null;
  }
  transporter = nodemailer.createTransport({
    service: 'gmail',
    auth: { user, pass }
  });
  return transporter;
}

async function enviarEmail(destinatario, assunto, corpoHtml) {
  const trans = getTransporter();
  if (!trans) return { success: false, error: 'SMTP_NOT_CONFIGURED' };
  try {
    const info = await trans.sendMail({
      from: process.env.EMAIL_FROM || `"Sistema Financeiro" <${process.env.EMAIL_USER}>`,
      to: destinatario,
      subject: assunto,
      html: corpoHtml
    });
    return { success: true, messageId: info.messageId };
  } catch (error) {
    console.error('❌ Erro ao enviar e-mail:', error);
    return { success: false, error: error.message };
  }
}

async function createGoogleCalendarEventForTransaction(userId, transaction, options = {}) {
  const tokens = getGoogleOAuthTokens(userId);
  if (!tokens || !tokens.refreshToken) {
    return { success: false, error: 'GOOGLE_CALENDAR_NOT_CONNECTED', connectUrl: '/auth/google/calendar' };
  }

  const txDate = String(transaction && transaction.date ? transaction.date : '').trim();
  const isFuture = txDate ? moment(txDate, 'YYYY-MM-DD', true).isAfter(moment(), 'day') : false;
  if (!isFuture) {
    return { success: false, error: 'NOT_FUTURE_TRANSACTION' };
  }

  const time = typeof options.time === 'string' && /^\d{2}:\d{2}$/.test(options.time) ? options.time : '09:00';
  const reminderMinutesRaw = options.reminderMinutes;
  const reminderMinutesNum = Number.isFinite(Number(reminderMinutesRaw)) ? Math.max(0, Math.min(40320, parseInt(reminderMinutesRaw))) : 60;
  const tz = 'America/Sao_Paulo';
  const start = moment.tz(`${txDate} ${time}`, 'YYYY-MM-DD HH:mm', tz);
  const end = start.clone().add(15, 'minutes');
  if (!start.isValid() || !end.isValid()) {
    return { success: false, error: 'INVALID_DATE_TIME' };
  }

  const amount = Number.isFinite(Number(transaction.amount)) ? Number(transaction.amount) : null;
  const summaryParts = [];
  summaryParts.push(transaction.type === 'expense' ? 'Despesa' : 'Receita');
  if (transaction.description) summaryParts.push(String(transaction.description).trim());
  const summary = summaryParts.filter(Boolean).join(': ').slice(0, 120);

  const descParts = [];
  if (amount !== null) descParts.push(`Valor: R$ ${amount.toFixed(2)}`);
  if (transaction.category) descParts.push(`Categoria: ${String(transaction.category)}`);
  if (transaction.paymentMethod) descParts.push(`Pagamento: ${String(transaction.paymentMethod)}`);
  const description = descParts.join('\n').slice(0, 2000);

  const requestBody = {
    summary,
    description,
    start: { dateTime: start.toISOString(), timeZone: tz },
    end: { dateTime: end.toISOString(), timeZone: tz },
    reminders: {
      useDefault: false,
      overrides: [{ method: 'popup', minutes: reminderMinutesNum }]
    }
  };

  const calendarId = 'primary';
  const url = `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(calendarId)}/events`;

  async function doRequest(accessToken) {
    return axios.post(url, requestBody, {
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      },
      timeout: 15000
    });
  }

  try {
    const accessToken = tokens.accessToken;
    if (!accessToken) {
      const refreshed = await refreshGoogleAccessToken(userId);
      if (!refreshed.success) return { success: false, error: refreshed.error || 'NO_ACCESS_TOKEN' };
      const resp = await doRequest(refreshed.accessToken);
      const eventId = resp && resp.data && resp.data.id ? String(resp.data.id) : null;
      return eventId ? { success: true, eventId } : { success: false, error: 'CALENDAR_EVENT_NOT_CREATED' };
    }

    const resp = await doRequest(accessToken);
    const eventId = resp && resp.data && resp.data.id ? String(resp.data.id) : null;
    return eventId ? { success: true, eventId } : { success: false, error: 'CALENDAR_EVENT_NOT_CREATED' };
  } catch (e) {
    const status = e && e.response ? Number(e.response.status) : null;
    if (status === 401) {
      const refreshed = await refreshGoogleAccessToken(userId);
      if (!refreshed.success) return { success: false, error: 'GOOGLE_TOKEN_EXPIRED' };
      try {
        const resp2 = await doRequest(refreshed.accessToken);
        const eventId = resp2 && resp2.data && resp2.data.id ? String(resp2.data.id) : null;
        return eventId ? { success: true, eventId } : { success: false, error: 'CALENDAR_EVENT_NOT_CREATED' };
      } catch (e2) {
        return { success: false, error: 'GOOGLE_CALENDAR_API_ERROR', details: e2 && e2.response && e2.response.data ? e2.response.data : (e2 && e2.message ? e2.message : 'Erro Google Agenda') };
      }
    }
    return { success: false, error: 'GOOGLE_CALENDAR_API_ERROR', details: e && e.response && e.response.data ? e.response.data : (e && e.message ? e.message : 'Erro Google Agenda') };
  }
}

const SHARED_LEDGER_OWNER = String(process.env.SHARED_LEDGER_OWNER || 'user1').trim().toLowerCase();
const SHARED_LEDGER_USERS = String(process.env.SHARED_LEDGER_USERS || 'user1,user2')
  .split(/[,;\s]+/)
  .map((v) => String(v || '').trim().toLowerCase())
  .filter(Boolean);
const _sharedLedgerUsersSet = new Set(SHARED_LEDGER_USERS);
const _ledgerIdCacheByUserId = new Map();
let _ledgerOwnerIdCache = null;

function normalizeLedgerUsername(username) {
  const u = String(username || '').trim().toLowerCase();
  if (!u) return u;
  if (_sharedLedgerUsersSet.has(u)) return SHARED_LEDGER_OWNER || u;
  return u;
}

function getUserIdByUsername(username) {
  try {
    if (!db) return null;
    const u = normalizeLedgerUsername(username);
    if (!u) return null;
    const emailLower = String(u).toLowerCase();
    const localEmail = emailLower.includes('@') ? emailLower : `${emailLower}@local`;
    const likeEmail = emailLower.includes('@') ? emailLower : `${emailLower}@%`;
    const row = db.prepare(`
      SELECT id
      FROM users
      WHERE lower(email) = ? OR lower(email) LIKE ?
      ORDER BY CASE WHEN lower(email) = ? THEN 0 ELSE 1 END, id ASC
      LIMIT 1
    `).get(localEmail, likeEmail, localEmail);
    const id = row ? Number(row.id) : NaN;
    return Number.isFinite(id) ? id : null;
  } catch (_) {
    return null;
  }
}

// Item 14: detecta (sem corrigir sozinho) transações onde o texto 'user' e o 'user_id' apontam
// para pessoas diferentes — o mesmo tipo de inconsistência que corrigimos manualmente nas 11
// transações da User2/User1. Usa a MESMA resolução que o resto do sistema já usa
// (getUserIdByUsername), então "inconsistente" aqui significa exatamente o que o app já
// consideraria errado. Só avisa; a correção em si é uma decisão de dado, não automática.
function verificarConsistenciaUserTransactions() {
  try {
    if (!db || !tableHasColumn('transactions', 'user_id')) return { total: 0, exemplos: [] };
    const linhas = db.prepare(`
      SELECT transaction_id, description, user, user_id, amount, date
      FROM transactions
      WHERE user IS NOT NULL
    `).all();
    const inconsistentes = [];
    for (const l of linhas) {
      const esperado = getUserIdByUsername(l.user);
      // user_id NULL também conta: o INSERT esqueceu a coluna e a transação fica sem dono
      if (esperado !== null && (l.user_id === null || Number(esperado) !== Number(l.user_id))) {
        inconsistentes.push({ ...l, user_id_esperado: esperado });
      }
    }
    return { total: inconsistentes.length, exemplos: inconsistentes.slice(0, 10) };
  } catch (error) {
    console.error('❌ [Consistência user/user_id] Erro:', error.message);
    return { total: 0, exemplos: [] };
  }
}

async function alertarInconsistenciasUserTransactions() {
  const { total, exemplos } = verificarConsistenciaUserTransactions();
  if (total === 0) return;
  console.log(`⚠️ [Consistência] ${total} transação(ões) com user/user_id divergentes`);
  const linhas = exemplos.map(e => `• ${e.description} (R$ ${Number(e.amount).toFixed(2)}, ${e.date}) — user='${e.user}' mas user_id=${e.user_id} (esperado ${e.user_id_esperado})`);
  const msg = `⚠️ *INCONSISTÊNCIA user/user_id EM TRANSAÇÕES*\n\n` +
    `Total: ${total} transação(ões)\n\n${linhas.join('\n')}${total > exemplos.length ? `\n… e mais ${total - exemplos.length}` : ''}\n\n` +
    `Isso não foi corrigido automaticamente — avise para revisar e decidir a correção.`;
  for (const chatId of TG_CHAT_IDS) {
    try { await bot.telegram.sendMessage(chatId, msg, { parse_mode: 'Markdown' }); } catch (e) {}
  }
}

function mapUserIdToLedgerUserId(userId) {
  // userId === null/undefined não pode virar Number(null) === 0 aqui: 0 é um user_id "válido"
  // pro resto da função (faz SELECT ... WHERE id = 0, não acha ninguém, e devolve 0 mesmo assim
  // em vez de propagar "sem usuário" pra quem chamou aplicar o fallback certo).
  if (userId === null || typeof userId === 'undefined') return null;
  const idNum = Number(userId);
  if (!Number.isFinite(idNum)) return null;
  if (_ledgerIdCacheByUserId.has(idNum)) return _ledgerIdCacheByUserId.get(idNum);
  let mapped = idNum;
  try {
    if (db && tableHasColumn('users', 'email')) {
      const row = db.prepare(`SELECT email FROM users WHERE id = ? LIMIT 1`).get(idNum);
      const email = row && row.email ? String(row.email).toLowerCase() : '';
      const base = email ? email.split('@')[0] : '';
      if (base && _sharedLedgerUsersSet.has(base) && base !== SHARED_LEDGER_OWNER) {
        if (_ledgerOwnerIdCache === null) _ledgerOwnerIdCache = getUserIdByUsername(SHARED_LEDGER_OWNER);
        if (Number.isFinite(Number(_ledgerOwnerIdCache))) mapped = Number(_ledgerOwnerIdCache);
      }
    }
  } catch (_) {}
  _ledgerIdCacheByUserId.set(idNum, mapped);
  return mapped;
}

function mergeSharedLedgerTransactions() {
  try {
    if (!db) return;
    if (!SHARED_LEDGER_OWNER) return;
    if (!_sharedLedgerUsersSet.has(SHARED_LEDGER_OWNER)) return;
    const sharedUsers = Array.from(_sharedLedgerUsersSet).filter((u) => u && u !== SHARED_LEDGER_OWNER);
    if (!sharedUsers.length) return;

    const hasUserId = tableHasColumn('transactions', 'user_id');
    const ownerId = hasUserId ? getUserIdByUsername(SHARED_LEDGER_OWNER) : null;

    if (hasUserId && Number.isFinite(Number(ownerId))) {
      const otherIds = sharedUsers
        .map((u) => getUserIdByUsername(u))
        .filter((v) => Number.isFinite(Number(v)))
        .map((v) => Number(v));
      if (otherIds.length) {
        const placeholders = otherIds.map(() => '?').join(', ');
        db.prepare(`UPDATE transactions SET user_id = ?, user = ? WHERE user_id IN (${placeholders})`).run(
          Number(ownerId),
          SHARED_LEDGER_OWNER,
          ...otherIds
        );
      }
    }

    const placeholdersUsers = sharedUsers.map(() => '?').join(', ');
    db.prepare(`UPDATE transactions SET user = ? WHERE lower(user) IN (${placeholdersUsers})`).run(SHARED_LEDGER_OWNER, ...sharedUsers);
  } catch (_) {}
}

function resolveUserContext(userRef) {
  if (Number.isFinite(Number(userRef)) && typeof userRef !== 'object') {
    const id = Number(userRef);
    const mapped = mapUserIdToLedgerUserId(id);
    return { userId: Number.isFinite(mapped) ? mapped : (Number.isFinite(id) ? id : null), username: '' };
  }
  if (userRef && typeof userRef === 'object') {
    const rawUsername = String(userRef.username || userRef.user || userRef.email || '').trim().toLowerCase();
    const username = normalizeLedgerUsername(rawUsername);
    const id = Number(userRef.id);
    const mappedId = Number.isFinite(id) ? mapUserIdToLedgerUserId(id) : null;
    const finalId = Number.isFinite(Number(mappedId)) ? Number(mappedId) : (Number.isFinite(id) ? id : null);
    return { userId: finalId, username };
  }
  const username = normalizeLedgerUsername(String(userRef || '').trim().toLowerCase());
  try {
    if (db && tableHasColumn('users', 'id') && username) {
      const emailLike = username.includes('@') ? username : `${username}@local`;
      const row = db.prepare(`SELECT id FROM users WHERE lower(email) = ? LIMIT 1`).get(String(emailLike).toLowerCase());
      if (row && Number.isFinite(Number(row.id))) return { userId: Number(row.id), username };
    }
  } catch (_) {}
  return { userId: null, username };
}

function buildUserWhere(tableName, userRef, legacyColumn = 'user') {
  const ctx = resolveUserContext(userRef);
  const hasUserId = tableHasColumn(tableName, 'user_id');
  if (hasUserId) {
    if (ctx.userId === null) return { clause: '1=0', params: [], ctx, hasUserId: true };
    return { clause: 'user_id = ?', params: [ctx.userId], ctx, hasUserId: true };
  }
  if (ctx.username) return { clause: `${legacyColumn} = ?`, params: [ctx.username], ctx, hasUserId: false };
  return { clause: '1=0', params: [], ctx, hasUserId: false };
}

