// Transações da conta no período (YYYY-MM-DD), com paginação. Lança erro se a API falhar
// (quem chama decide como tratar — o extrato mostra "indisponível" em vez de esconder).
async function getMercadoPagoMagazineTransactions(fromDate, toDate) {
  const apiKey = await getMercadoPagoMagazineApiKey();
  const resultados = [];
  for (let page = 1; page <= 5; page++) {
    const response = await axios.get(`${PLUGGY_API_URL}/transactions`, {
      params: { accountId: MP_MAGAZINE_ACCOUNT_ID, from: fromDate, to: toDate, pageSize: 100, page },
      headers: { 'X-API-KEY': apiKey }
    });
    resultados.push(...(response.data.results || []));
    if (page >= (response.data.totalPages || 1)) break;
  }
  return resultados;
}


