// Modelos Llama antigos (llama-3.3-70b-versatile, llama-3.1-8b-instant, llama-3.2-*-vision-preview,
// llama-3.1-405b-reasoning, llama-guard-3-8b, gemma2-9b-it, mistral-saba-24b, qwen-2.5-32b) foram
// descontinuados/movidos para o tier Enterprise da Groq. Lista atualizada com os equivalentes
// gratuitos mais próximos ainda ativos no tier free/developer da Groq.
// (qwen/qwen3.6-27b foi removido: não consta em GET /openai/v1/models da conta.)
const GROQ_FREE_FALLBACK_MODELS = {
  large: [
    'openai/gpt-oss-120b',
    'qwen/qwen3.8-27b'
  ],
  medium: [
    'openai/gpt-oss-20b',
    'qwen/qwen3.8-27b',
    'openai/gpt-oss-safeguard-20b'
  ],
  vision: [
    'qwen/qwen3.8-27b'
  ]
};

function pickFallbackModel(currentModel) {
  const model = String(currentModel || '').toLowerCase();
  const hasVision = model.includes('vision') || model.includes('scout') || model.includes('4-') || model.includes('qwen3.6') || model.includes('qwen3.8') || model.includes('multimodal');
  const isLarge = model.includes('120b') || model.includes('70b') || model.includes('405b') || model.includes('90b') || model.includes('32b') || model.includes('27b') || model.includes('24b');

  let list = hasVision
    ? GROQ_FREE_FALLBACK_MODELS.vision
    : isLarge
      ? GROQ_FREE_FALLBACK_MODELS.large
      : GROQ_FREE_FALLBACK_MODELS.medium;

  const filtered = list.filter((m) => m.toLowerCase() !== model);
  if (filtered.length) return filtered[0];
  return list[0];
}

function isGroqModelNotFoundError(error) {
  const status = Number(error?.response?.status || error?.status || 0);
  const body = error?.response?.data || {};
  const bodyText = typeof body === 'string' ? body : JSON.stringify(body || {});
  const message = (typeof body?.error?.message === 'string' ? body.error.message : String(error?.message || '')).toLowerCase();
  if (status === 404) return true;
  if (message.includes('model') && (message.includes('not found') || message.includes('invalid') || message.includes('não encontrado') || message.includes('inválido'))) return true;
  if (bodyText.toLowerCase().includes('model') && bodyText.toLowerCase().includes('not found')) return true;
  return false;
}

function describeGroqError(error, payloadModel = '') {
  const status = Number(error?.response?.status || error?.status || 0);
  const code = String(error?.code || error?.errno || '').toUpperCase();
  const body = error?.response?.data || {};
  const errMsg = typeof body?.error?.message === 'string'
    ? body.error.message
    : (typeof body?.error === 'string' ? body.error : String(error?.message || 'Erro desconhecido'));
  const errType = typeof body?.error?.type === 'string' ? body.error.type : '';
  return `[HTTP ${status || code || '?'}] ${payloadModel ? `model=${payloadModel}; ` : ''}${errType ? `${errType}: ` : ''}${errMsg}`;
}

function isRetryableGroqTransportError(error) {
  const code = String(error?.code || error?.errno || '').toUpperCase();
  const message = String(error?.message || '').toLowerCase();
  const status = Number(error?.response?.status || error?.status || 0);

  if ([408, 409, 425, 429, 500, 502, 503, 504].includes(status)) return true;
  if (['ERR_STREAM_PREMATURE_CLOSE', 'ECONNRESET', 'ETIMEDOUT', 'ECONNABORTED', 'EAI_AGAIN'].includes(code)) return true;
  if (message.includes('premature close')) return true;
  if (message.includes('socket hang up')) return true;
  if (message.includes('network error')) return true;
  if (message.includes('timeout')) return true;
  return false;
}

// ---- Rate limit (HTTP 429) da Groq ----
// O limite (TPM/TPD) é por modelo. Em vez de esperar e falhar, troca para outro modelo
// e lembra (em memória) que o modelo limitado está "esfriando" até o horário informado
// pela Groq, para que as próximas chamadas já saiam direto no reserva. Depois desse
// horário o modelo principal volta a ser usado automaticamente.
// Chamadas com imagem só podem ir para modelos com visão.
const GROQ_RATE_LIMIT_FALLBACKS = {
  'openai/gpt-oss-120b': ['openai/gpt-oss-20b', 'qwen/qwen3.8-27b'],
  'openai/gpt-oss-20b': ['openai/gpt-oss-120b', 'qwen/qwen3.8-27b']
};
const GROQ_RATE_LIMIT_VISION_FALLBACKS = ['qwen/qwen3.8-27b'];
const GROQ_RATE_LIMIT_SHORT_WAIT_MS = 2500;   // até aqui vale esperar e repetir no mesmo modelo
const GROQ_RATE_LIMIT_MAX_WAIT_MS = 15000;    // teto de espera TOTAL por chamada por causa de 429
const GROQ_RATE_LIMIT_DEFAULT_WAIT_MS = 10000;
const groqModelCooldownUntil = new Map();     // modelo (minúsculo) -> epoch ms

function isGroqRateLimitError(error) {
  return Number(error?.response?.status || error?.status || 0) === 429;
}

// Tempo até o limite liberar: header Retry-After (segundos) ou "try again in 12.27s" / "1m30.5s" / "450ms".
function getGroqRetryAfterMs(error) {
  const header = Number(error?.response?.headers?.['retry-after']);
  if (Number.isFinite(header) && header > 0) return Math.ceil(header * 1000);

  const body = error?.response?.data;
  const message = String(typeof body?.error?.message === 'string' ? body.error.message : (error?.message || ''));
  const token = message.match(/try again in\s+([0-9a-z.]+)/i);
  if (token) {
    const unitMs = { h: 3600000, m: 60000, s: 1000, ms: 1 };
    let total = 0;
    for (const part of token[1].matchAll(/([\d.]+)(ms|h|m|s)/gi)) {
      total += parseFloat(part[1]) * unitMs[part[2].toLowerCase()];
    }
    if (total > 0) return Math.ceil(total);
  }
  return GROQ_RATE_LIMIT_DEFAULT_WAIT_MS;
}

function markGroqModelCooldown(model, ms) {
  groqModelCooldownUntil.set(String(model || '').toLowerCase(), Date.now() + ms);
}

function isGroqModelCoolingDown(model) {
  const key = String(model || '').toLowerCase();
  const until = groqModelCooldownUntil.get(key);
  if (!until) return false;
  if (until <= Date.now()) {
    groqModelCooldownUntil.delete(key);
    return false;
  }
  return true;
}

function groqPayloadHasImage(payload) {
  return (payload?.messages || []).some(
    (m) => Array.isArray(m?.content) && m.content.some((part) => part?.type === 'image_url')
  );
}

function pickRateLimitFallbackModel(payload, alreadyTriedModels) {
  const model = String(payload?.model || '').toLowerCase();
  const candidates = groqPayloadHasImage(payload)
    ? GROQ_RATE_LIMIT_VISION_FALLBACKS
    : (GROQ_RATE_LIMIT_FALLBACKS[model] || []);
  return candidates.find((m) => !alreadyTriedModels.has(m.toLowerCase()) && !isGroqModelCoolingDown(m)) || null;
}

async function createGroqChatCompletion(payload, meta = {}) {
  const { location = 'sistema-mobile-3004.js:groq-http' } = meta;
  let lastError = null;
  let attempts = 0;
  const maxAttempts = 3;
  let currentModel = String(payload?.model || '');
  let rateLimitWaitedMs = 0;
  const alreadyTriedModels = new Set();

  while (attempts < maxAttempts || alreadyTriedModels.size < 2) {
    attempts += 1;

    // Modelo já sabidamente limitado (429 recente)? Vai direto para o reserva, sem gastar uma chamada.
    if (isGroqModelCoolingDown(payload?.model)) {
      const preferred = pickRateLimitFallbackModel(payload, alreadyTriedModels);
      if (preferred) {
        alreadyTriedModels.add(String(payload.model).toLowerCase());
        console.warn(`⚠️ Groq: "${payload.model}" está com rate limit em ${location}; usando "${preferred}".`);
        payload = { ...payload, model: preferred };
      }
    }

    alreadyTriedModels.add(String(payload?.model || '').toLowerCase());

    try {
      if (!GROQ_API_KEY) {
        throw new Error('GROQ_API_KEY não configurada');
      }

      // reasoning_effort 'low'/'medium'/'high' só existe nos gpt-oss; os modelos reserva rejeitam.
      const body = { ...payload };
      if (body.reasoning_effort && !/gpt-oss/i.test(String(body.model || ''))) delete body.reasoning_effort;

      const response = await axios.post(
        'https://api.groq.com/openai/v1/chat/completions',
        body,
        {
          headers: {
            Authorization: `Bearer ${GROQ_API_KEY}`,
            'Content-Type': 'application/json',
            'Accept-Encoding': 'identity'
          },
          timeout: 45000,
          maxContentLength: Infinity,
          maxBodyLength: Infinity
        }
      );

      if (alreadyTriedModels.size > 1) {
        console.warn(`✅ Groq: fallback bem-sucedido em ${location}. Modelo usado: ${payload.model}`);
      }
      return response.data;
    } catch (error) {
      lastError = error;
      currentModel = String(payload?.model || '');

      const notFound = isGroqModelNotFoundError(error);
      if (notFound) {
        const fallback = pickFallbackModel(currentModel);
        if (fallback && !alreadyTriedModels.has(fallback.toLowerCase())) {
          console.warn(
            `⚠️ Groq: modelo "${currentModel}" inválido/indisponível em ${location} ` +
            `(${describeGroqError(error, currentModel)}). ` +
            `Tentando fallback para "${fallback}"…`
          );
          payload = { ...payload, model: fallback };
          alreadyTriedModels.add(fallback.toLowerCase());
          continue;
        }
      }

      if (isGroqRateLimitError(error)) {
        const waitMs = getGroqRetryAfterMs(error);

        // Espera longa: marca o modelo como limitado e troca (o limite é por modelo).
        // A troca não conta como tentativa. Espera curta não vale a troca.
        if (waitMs > GROQ_RATE_LIMIT_SHORT_WAIT_MS) {
          markGroqModelCooldown(currentModel, waitMs);
          const fallback = pickRateLimitFallbackModel(payload, alreadyTriedModels);
          if (fallback) {
            console.warn(
              `⚠️ Groq 429 em ${location} (${describeGroqError(error, currentModel)}); ` +
              `liberado em ~${Math.ceil(waitMs / 1000)}s. Trocando para "${fallback}".`
            );
            payload = { ...payload, model: fallback };
            attempts -= 1;
            continue;
          }
        }

        // Sem reserva disponível (ou espera curta): espera o tempo informado e repete, respeitando
        // o teto de espera total desta chamada (evita segurar a requisição por dezenas de segundos).
        if (attempts < maxAttempts && rateLimitWaitedMs + waitMs <= GROQ_RATE_LIMIT_MAX_WAIT_MS) {
          rateLimitWaitedMs += waitMs + 100;
          console.warn(
            `⚠️ Groq 429 em ${location} (${describeGroqError(error, currentModel)}); ` +
            `aguardando ${Math.ceil(waitMs / 1000)}s. Nova tentativa ${attempts + 1}/${maxAttempts}.`
          );
          await sleep(waitMs + 100);
          continue;
        }
        break;
      }

      const shouldRetry = attempts < maxAttempts && isRetryableGroqTransportError(error);
      if (shouldRetry) {
        console.warn(
          `⚠️ Falha transitória na Groq em ${location} (${describeGroqError(error, currentModel)}); ` +
          `nova tentativa ${attempts + 1}/${maxAttempts}.`
        );
      }
      if (!shouldRetry) break;
      await sleep(400 * attempts);
    }
  }

  if (lastError) {
    const modelReported = String(payload?.model || currentModel);
    console.error(
      `❌ Groq falhou definitivamente em ${location} após ${attempts} tentativa(s): ` +
      `${describeGroqError(lastError, modelReported)}`
    );
  }

  throw lastError;
}
