const storage = multer.memoryStorage();
const upload = multer({
  storage: storage,
  limits: {
    fileSize: 10 * 1024 * 1024, // 10MB
    files: 1
  },
  fileFilter: (req, file, cb) => {
    const allowedTypes = /jpeg|jpg|png|pdf/;
    const extname = allowedTypes.test(path.extname(file.originalname).toLowerCase());
    const mimetype = allowedTypes.test(file.mimetype);
    
    if (mimetype && extname) {
      return cb(null, true);
    } else {
      cb(new Error('Apenas imagens (JPEG, PNG) e PDF são permitidos'));
    }
  }
});
// Função de verificação de permissão -1
function checkTelegramPermission(ctx) {
  const userId = String(ctx && ctx.from && ctx.from.id ? ctx.from.id : '');
  const text = String(ctx && ctx.message && ctx.message.text ? ctx.message.text : '');

  if (text.startsWith('/start') || text.startsWith('/link')) return true;

  try {
    if (db) {
      const row = db.prepare(`SELECT id, role FROM users WHERE telegram_id = ? LIMIT 1`).get(userId);
      if (row && row.role !== 'blocked') return true;
    }
  } catch (_) {}

  return ALLOWED_TG_IDS.includes(userId);
}

const pendingTelegramLinkTokens = new Map();

function generateTelegramLinkToken() {
  return crypto.randomBytes(4).toString('hex');
}

function applyTelegramLinkToken(token, chatId) {
  const t = String(token || '').trim();
  const cid = String(chatId || '').trim();
  if (!t) return { success: false, error: 'MISSING_TOKEN' };
  if (!cid) return { success: false, error: 'INVALID_TELEGRAM_ID' };
  if (!db) return { success: false, error: 'DB_NOT_READY' };

  const pending = pendingTelegramLinkTokens.get(t);
  if (!pending || typeof pending.userId !== 'number') return { success: false, error: 'TOKEN_INVALID' };
  if (typeof pending.expiresAt === 'number' && pending.expiresAt <= Date.now()) {
    pendingTelegramLinkTokens.delete(t);
    return { success: false, error: 'TOKEN_EXPIRED' };
  }

  const existing = db.prepare(`SELECT id FROM users WHERE telegram_id = ? LIMIT 1`).get(cid);
  if (existing && Number(existing.id) !== Number(pending.userId)) {
    return { success: false, error: 'TELEGRAM_ALREADY_LINKED' };
  }

  const info = db.prepare(`UPDATE users SET telegram_id = ? WHERE id = ?`).run(cid, pending.userId);
  pendingTelegramLinkTokens.delete(t);
  if (!info || info.changes !== 1) return { success: false, error: 'LINK_FAILED' };
  return { success: true, userId: pending.userId };
}

setInterval(() => {
  const now = Date.now();
  for (const [token, data] of pendingTelegramLinkTokens.entries()) {
    if (!data || typeof data.expiresAt !== 'number' || data.expiresAt <= now) {
      pendingTelegramLinkTokens.delete(token);
    }
  }
}, 60 * 1000);
// ============== BANCO DE DADOS ==============
let db;

const chatMemory = new Map();
const MAX_MEMORY = 6;

function getChatHistory(userId, lastN = 4) {
  const key = String(userId ?? '');
  const history = chatMemory.get(key) || [];
  return history.slice(-lastN).map((msg) => ({ role: msg.role, content: msg.content }));
}

function addToChatMemory(userId, role, content) {
  const key = String(userId ?? '');
  let mem = chatMemory.get(key) || [];
  const c = String(content || '').trim();
  if (!c) return;
  mem.push({ role, content: c.slice(0, 1200), timestamp: Date.now() });
  if (mem.length > MAX_MEMORY * 2) mem = mem.slice(-MAX_MEMORY * 2);
  chatMemory.set(key, mem);
}

function initDatabase() {
  try {
    if (!fs.existsSync(DATA_DIR)) {
      fs.mkdirSync(DATA_DIR, { recursive: true });
    }
    
    if (!fs.existsSync(RECEIPTS_DIR)) {
      fs.mkdirSync(RECEIPTS_DIR, { recursive: true });
      console.log(`📁 Pasta de recibos criada: ${RECEIPTS_DIR}`);
    }
    
    const dbOptions = { fileMustExist: false };
    if (SQLITE_VERBOSE) dbOptions.verbose = console.log;
    db = new Database(DB_FILE, dbOptions);
    
    try {
      const dbPath = String(DB_FILE || '');
      const preferred = dbPath.includes('/gvfs/') ? 'DELETE' : 'WAL';
      db.pragma(`journal_mode = ${preferred}`);
    } catch (e) {
      try { db.pragma('journal_mode = DELETE'); } catch (_) {}
    }
    db.pragma('foreign_keys = ON');
    db.pragma('busy_timeout = 5000');
    
    createTables();
    migrateFromJSON();
    bootstrapUsersFromLegacy();
    ensureUserIdColumns();
    ensureChatLogsColumns();
    backfillUserIds();
    mergeSharedLedgerTransactions();
    
    console.log('✅ Banco de dados SQLite inicializado');
    return db;
  } catch (error) {
    console.error('❌ Erro ao inicializar banco de dados:', error);
    throw error;
  }
}

function ensureChatLogsColumns() {
  try {
    if (!db) return;
    if (!tableHasColumn('chat_logs', 'tokens_used')) {
      try { db.exec('ALTER TABLE chat_logs ADD COLUMN tokens_used INTEGER'); } catch (e) {}
    }
    if (!tableHasColumn('chat_logs', 'response_time_ms')) {
      try { db.exec('ALTER TABLE chat_logs ADD COLUMN response_time_ms INTEGER'); } catch (e) {}
    }
    if (!tableHasColumn('chat_logs', 'context')) {
      try { db.exec('ALTER TABLE chat_logs ADD COLUMN context TEXT'); } catch (e) {}
    }
  } catch (e) {
    console.error('❌ Erro ao ajustar colunas do chat_logs:', e.message);
  }
}
async function startApp() {
    initDatabase();

//     bot.launch();
    
    // Configura os webhooks na API da Pluggy
    await setupNeonWebhook();
    // await setupSicrediWebhook(); // se criar para o Sicredi também
    
    console.log(`Servidor rodando na porta ${PORT}`);
}
