function carregarMapeamentosEstabelecimentos() {
    try {
        const mapPath = path.join(DATA_DIR, 'estabelecimentos-map.json');
        if (fs.existsSync(mapPath)) {
            const savedMap = JSON.parse(fs.readFileSync(mapPath, 'utf8'));
            Object.assign(ESTABELECIMENTOS_MAP, savedMap);
            console.log(`📋 ${Object.keys(ESTABELECIMENTOS_MAP).length} mapeamentos de estabelecimentos carregados`);
        }
    } catch (error) {
        console.error('❌ Erro ao carregar mapeamentos:', error);
    }
}

function getCategoriesForTelegramUser(telegramIdStr) {
    try {
        const telegramId = String(telegramIdStr || '').trim();
        if (!telegramId) return getCategories();
        let dbUser = null;
        try {
            if (db) {
                dbUser = db.prepare(`SELECT id, email, name, role FROM users WHERE telegram_id = ? LIMIT 1`).get(telegramId);
            }
        } catch (e) {}

        // Celular novo/segunda conta do User1 sem telegram_id cadastrado na tabela users:
        // cai para a conta principal dele (mesma regra de getUserIdByTelegramId).
        if (!dbUser && db && USER1_TG_IDS.includes(telegramId)) {
            try {
                const fallbackId = getUserIdByUsername('user1');
                if (fallbackId !== null && Number.isFinite(Number(fallbackId))) {
                    dbUser = db.prepare(`SELECT id, email, name, role FROM users WHERE id = ? LIMIT 1`).get(Number(fallbackId));
                }
            } catch (e) {}
        }

        const isAdmin = !!(dbUser && dbUser.role === 'admin');
        const fallbackUsername = getSystemUserFromTelegramId(telegramId);
        const usernameFromEmail = dbUser && dbUser.email ? String(dbUser.email).split('@')[0] : '';
        const username = (usernameFromEmail || fallbackUsername || '').toLowerCase();
        const userId = dbUser && typeof dbUser.id !== 'undefined' ? Number(dbUser.id) : null;
        return getCategories(userId, username, isAdmin);
    } catch (e) {
        return getCategories();
    }
}

