function getMenstrualTracking(userId) {
  try {
    const row = db.prepare(`
      SELECT id, user_id, cycle_start_date, status, last_asked_date, days_count
      FROM menstrual_tracking
      WHERE user_id = ?
      LIMIT 1
    `).get(userId);
    return row || null;
  } catch (e) {
    console.error('Erro getMenstrualTracking:', e.message);
    return null;
  }
}

function upsertMenstrualTracking(userId, data) {
  try {
    const { cycle_start_date, status, last_asked_date, days_count } = data;
    const now = moment().toISOString();
    const stmt = db.prepare(`
      INSERT INTO menstrual_tracking (user_id, cycle_start_date, status, last_asked_date, days_count, updated_at)
      VALUES (?, ?, ?, ?, ?, ?)
      ON CONFLICT(user_id) DO UPDATE SET
        cycle_start_date = excluded.cycle_start_date,
        status = excluded.status,
        last_asked_date = excluded.last_asked_date,
        days_count = excluded.days_count,
        updated_at = excluded.updated_at
    `);
    stmt.run(userId, cycle_start_date || null, status, last_asked_date || null, days_count || 0, now);
    return true;
  } catch (e) {
    console.error('Erro upsertMenstrualTracking:', e.message);
    return false;
  }
}

function resetMenstrualTracking(userId) {
  try {
    db.prepare(`
      DELETE FROM menstrual_tracking
      WHERE user_id = ?
    `).run(userId);
    return true;
  } catch (e) {
    console.error('Erro resetMenstrualTracking:', e.message);
    return false;
  }
}

const USER_PATTERNS_MIN_CONFIDENCE = Number(process.env.USER_PATTERNS_MIN_CONFIDENCE || 0.6);
const USER_PATTERNS_MIN_TOTAL = Number(process.env.USER_PATTERNS_MIN_TOTAL || 1.2);
const USER_PATTERNS_OVERRIDE_TOTAL = Number(process.env.USER_PATTERNS_OVERRIDE_TOTAL || 1.5);
// Nome de estabelecimento costuma ser 1 palavra só (ex: "redemacajreis"), então a soma de
// confiança nunca chega em USER_PATTERNS_OVERRIDE_TOTAL (pensado para várias keywords de
// categoria). Usa um limite próprio, mais baixo, para a correção de descrição "pegar" já na 1ª vez.
const USER_DESC_PATTERNS_OVERRIDE_TOTAL = Number(process.env.USER_DESC_PATTERNS_OVERRIDE_TOTAL || 0.9);
const USER_PATTERNS_MAX_PER_USER = Number(process.env.USER_PATTERNS_MAX_PER_USER || 500);
const USER_PATTERNS_PRUNE_MONTHS = Number(process.env.USER_PATTERNS_PRUNE_MONTHS || 6);

const KEYWORD_STOPWORDS = new Set([
  'paguei', 'pagamento', 'pago', 'gastei', 'gasto', 'recebi', 'recebido', 'ganhei', 'ganho',
  'de', 'do', 'da', 'dos', 'das', 'no', 'na', 'nos', 'nas', 'em', 'para', 'com', 'por', 'sem', 'sobre',
  'um', 'uma', 'uns', 'umas', 'o', 'a', 'os', 'as', 'e', 'ou',
  'ao', 'aos', 'à', 'às', 'pra', 'pro', 'pela', 'pelo', 'pelas', 'pelos',
  'meu', 'minha', 'meus', 'minhas', 'seu', 'sua', 'seus', 'suas',
  'hoje', 'ontem', 'amanha', 'agora', 'mes', 'ano',
  'r', 'rs', 'reais', 'real'
]);

function normalizeKeywordText(input) {
  return String(input || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function extractKeywords(description) {
  const cleaned = normalizeKeywordText(description)
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (!cleaned) return [];

  const tokens = cleaned.split(' ').filter(Boolean);
  const isSignificant = (t) => {
    if (!t) return false;
    if (t.length < 3) return false;
    if (KEYWORD_STOPWORDS.has(t)) return false;
    if (/^\d+$/.test(t)) return false;
    return true;
  };

  const keywords = [];
  for (const t of tokens) {
    if (isSignificant(t)) keywords.push(t);
  }

  for (let i = 0; i < tokens.length; i++) {
    for (const n of [2, 3]) {
      if (i + n - 1 >= tokens.length) continue;
      const first = tokens[i];
      const last = tokens[i + n - 1];
      if (!isSignificant(first) || !isSignificant(last)) continue;
      const ngram = tokens.slice(i, i + n).join(' ');
      if (ngram.length <= 40) keywords.push(ngram);
    }
  }

  return Array.from(new Set(keywords)).slice(0, 60);
}

function getUserIdByTelegramId(telegramId) {
  try {
    if (!db) return null;
    const tgid = String(telegramId || '').trim();
    if (!tgid) return null;
    const row = db.prepare(`SELECT id FROM users WHERE telegram_id = ? LIMIT 1`).get(tgid);
    const id = row ? Number(row.id) : NaN;
    if (Number.isFinite(id)) return id;
    // Celular novo/segunda conta do User1 (USER1_TG_IDS) sem telegram_id cadastrado na
    // tabela users: cai para a conta principal dele em vez de ficar sem dono (sem cartões/categorias).
    if (USER1_TG_IDS.includes(tgid)) {
      const fallbackId = getUserIdByUsername('user1');
      if (fallbackId !== null && Number.isFinite(Number(fallbackId))) return Number(fallbackId);
    }
    return null;
  } catch (_) {
    return null;
  }
}

function getUserCreditCards(telegramId) {
  try {
    if (!db) return [];
    const userId = getUserIdByTelegramId(telegramId);
    if (!Number.isFinite(Number(userId))) return [];
    const cards = db.prepare(`
      SELECT id, name FROM credit_cards WHERE user_id = ? ORDER BY name
    `).all(Number(userId));
    return (cards || []).map(c => String(c && c.name ? c.name : '')).filter(Boolean);
  } catch (e) {
    return [];
  }
}

function enforceUserPatternLimit(userId) {
  try {
    if (!db) return;
    const uid = Number(userId);
    if (!Number.isFinite(uid)) return;
    const max = Number.isFinite(USER_PATTERNS_MAX_PER_USER) ? USER_PATTERNS_MAX_PER_USER : 500;
    if (!Number.isFinite(max) || max <= 0) return;

    const row = db.prepare(`SELECT COUNT(*) as count FROM user_patterns WHERE user_id = ?`).get(uid);
    const count = row ? Number(row.count) : 0;
    if (!Number.isFinite(count) || count <= max) return;
    const excess = count - max;
    if (excess <= 0) return;

    db.prepare(`
      DELETE FROM user_patterns
      WHERE id IN (
        SELECT id
        FROM user_patterns
        WHERE user_id = ?
        ORDER BY COALESCE(last_used, created_at) ASC, occurrences ASC, confidence ASC, id ASC
        LIMIT ?
      )
    `).run(uid, excess);
  } catch (_) {}
}

function learnUserPatterns(userId, description, chosenCategory) {
  try {
    if (!db) return { success: false, learned: 0 };
    const uid = Number(userId);
    if (!Number.isFinite(uid)) return { success: false, learned: 0 };
    const category = String(chosenCategory || '').trim();
    if (!category) return { success: false, learned: 0 };

    const keywords = extractKeywords(description);
    if (!keywords.length) return { success: true, learned: 0 };

    const stmt = db.prepare(`
      INSERT INTO user_patterns (user_id, keyword, suggested_category, confidence, occurrences, last_used)
      VALUES (?, ?, ?, 1.0, 1, DATETIME('now', 'localtime'))
      ON CONFLICT(user_id, keyword, suggested_category) DO UPDATE SET
        confidence = (confidence * occurrences + 1.0) / (occurrences + 1),
        occurrences = occurrences + 1,
        last_used = DATETIME('now', 'localtime')
    `);

    const tx = db.transaction((kws) => {
      for (const kw of kws) {
        stmt.run(uid, kw, category);
      }
      enforceUserPatternLimit(uid);
    });

    tx(keywords);
    return { success: true, learned: keywords.length };
  } catch (_) {
    return { success: false, learned: 0 };
  }
}

function getBestUserPatternCategory(userId, description, opts = {}) {
  try {
    if (!db) return null;
    const uid = Number(userId);
    if (!Number.isFinite(uid)) return null;
    const minConfidence = Number.isFinite(Number(opts.minConfidence)) ? Number(opts.minConfidence) : USER_PATTERNS_MIN_CONFIDENCE;
    const keywords = extractKeywords(description);
    if (!keywords.length) return null;

    const kws = keywords.slice(0, 40);
    const placeholders = kws.map(() => '?').join(', ');
    const row = db.prepare(`
      SELECT suggested_category as category, SUM(confidence) as totalConfidence
      FROM user_patterns
      WHERE user_id = ?
        AND keyword IN (${placeholders})
        AND confidence >= ?
      GROUP BY suggested_category
      ORDER BY totalConfidence DESC
      LIMIT 1
    `).get(uid, ...kws, minConfidence);

    if (!row || !row.category) return null;
    const total = Number(row.totalConfidence);
    if (!Number.isFinite(total) || total <= 0) return null;
    return { category: String(row.category), totalConfidence: total, keywords: kws };
  } catch (_) {
    return null;
  }
}

function enforceUserDescPatternLimit(userId) {
  try {
    if (!db) return;
    const uid = Number(userId);
    if (!Number.isFinite(uid)) return;
    const max = Number.isFinite(USER_PATTERNS_MAX_PER_USER) ? USER_PATTERNS_MAX_PER_USER : 500;
    if (!Number.isFinite(max) || max <= 0) return;

    const row = db.prepare(`SELECT COUNT(*) as count FROM user_desc_patterns WHERE user_id = ?`).get(uid);
    const count = row ? Number(row.count) : 0;
    if (!Number.isFinite(count) || count <= max) return;
    const excess = count - max;
    if (excess <= 0) return;

    db.prepare(`
      DELETE FROM user_desc_patterns
      WHERE id IN (
        SELECT id
        FROM user_desc_patterns
        WHERE user_id = ?
        ORDER BY COALESCE(last_used, created_at) ASC, occurrences ASC, confidence ASC, id ASC
        LIMIT ?
      )
    `).run(uid, excess);
  } catch (_) {}
}

// Grava a correção manual de descrição (ex: OCR leu "redemacajreis", usuário ajustou para
// "redemac") a partir das palavras-chave do texto original, para reaplicar automaticamente
// da próxima vez que o mesmo estabelecimento aparecer no comprovante.
function learnUserDescPattern(userId, originalText, correctedDesc) {
  try {
    if (!db) return { success: false, learned: 0 };
    const uid = Number(userId);
    if (!Number.isFinite(uid)) return { success: false, learned: 0 };
    const desc = String(correctedDesc || '').trim();
    if (!desc) return { success: false, learned: 0 };

    const keywords = extractKeywords(originalText);
    if (!keywords.length) return { success: true, learned: 0 };

    const stmt = db.prepare(`
      INSERT INTO user_desc_patterns (user_id, keyword, corrected_desc, confidence, occurrences, last_used)
      VALUES (?, ?, ?, 1.0, 1, DATETIME('now', 'localtime'))
      ON CONFLICT(user_id, keyword, corrected_desc) DO UPDATE SET
        confidence = (confidence * occurrences + 1.0) / (occurrences + 1),
        occurrences = occurrences + 1,
        last_used = DATETIME('now', 'localtime')
    `);

    const tx = db.transaction((kws) => {
      for (const kw of kws) {
        stmt.run(uid, kw, desc);
      }
      enforceUserDescPatternLimit(uid);
    });

    tx(keywords);
    return { success: true, learned: keywords.length };
  } catch (_) {
    return { success: false, learned: 0 };
  }
}

function getBestUserDescPattern(userId, text, opts = {}) {
  try {
    if (!db) return null;
    const uid = Number(userId);
    if (!Number.isFinite(uid)) return null;
    const minConfidence = Number.isFinite(Number(opts.minConfidence)) ? Number(opts.minConfidence) : USER_PATTERNS_MIN_CONFIDENCE;
    const keywords = extractKeywords(text);
    if (!keywords.length) return null;

    const kws = keywords.slice(0, 40);
    const placeholders = kws.map(() => '?').join(', ');
    const row = db.prepare(`
      SELECT corrected_desc as desc, SUM(confidence) as totalConfidence
      FROM user_desc_patterns
      WHERE user_id = ?
        AND keyword IN (${placeholders})
        AND confidence >= ?
      GROUP BY corrected_desc
      ORDER BY totalConfidence DESC
      LIMIT 1
    `).get(uid, ...kws, minConfidence);

    if (!row || !row.desc) return null;
    const total = Number(row.totalConfidence);
    if (!Number.isFinite(total) || total <= 0) return null;
    return { desc: String(row.desc), totalConfidence: total, keywords: kws };
  } catch (_) {
    return null;
  }
}

function pruneUserPatterns() {
  try {
    if (!db) return { success: false };
    const months = Number.isFinite(USER_PATTERNS_PRUNE_MONTHS) ? USER_PATTERNS_PRUNE_MONTHS : 6;
    const cutoff = Math.max(1, Math.floor(months));
    db.prepare(`
      DELETE FROM user_patterns
      WHERE last_used IS NOT NULL
        AND last_used < DATETIME('now', '-' || ? || ' months', 'localtime')
        AND occurrences <= 1
        AND confidence < ?
    `).run(cutoff, USER_PATTERNS_MIN_CONFIDENCE);
    return { success: true };
  } catch (_) {
    return { success: false };
  }
}

function ensureUserIdColumns() {
  try {
    const targets = [
      { table: 'transactions', column: 'user_id', ddl: 'ALTER TABLE transactions ADD COLUMN user_id INTEGER' },
      { table: 'categories', column: 'user_id', ddl: 'ALTER TABLE categories ADD COLUMN user_id INTEGER' },
      { table: 'ai_cache', column: 'user_id', ddl: 'ALTER TABLE ai_cache ADD COLUMN user_id INTEGER' },
      { table: 'chat_logs', column: 'user_id', ddl: 'ALTER TABLE chat_logs ADD COLUMN user_id INTEGER' },
      { table: 'push_subscriptions', column: 'user_id', ddl: 'ALTER TABLE push_subscriptions ADD COLUMN user_id INTEGER' },
      { table: 'fgts_balances', column: 'user_id', ddl: 'ALTER TABLE fgts_balances ADD COLUMN user_id INTEGER' }
    ];

    for (const t of targets) {
      if (!tableHasColumn(t.table, t.column)) {
        try { db.exec(t.ddl); } catch (e) {}
        try { db.exec(`CREATE INDEX IF NOT EXISTS idx_${t.table}_${t.column} ON ${t.table}(${t.column})`); } catch (e) {}
      }
    }
  } catch (e) {
    console.error('❌ Erro ao ajustar colunas user_id:', e.message);
  }
}

