function migrateFromJSON() {
  try {
    const count = db.prepare('SELECT COUNT(*) as count FROM transactions').get();
    if (count.count > 0) {
      console.log('📊 Dados já migrados para SQLite');
      return;
    }
    
    const transactionsFile = path.join(DATA_DIR, 'transacoes.json');
    if (fs.existsSync(transactionsFile)) {
      try {
        const data = fs.readFileSync(transactionsFile, 'utf8');
        const transactions = JSON.parse(data);
        
        const insertTransaction = db.prepare(`
          INSERT OR IGNORE INTO transactions 
          (transaction_id, description, amount, type, category, payment_method, date, user, user_name, receipt_image, created_at)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `);
        
        const insertMany = db.transaction((txs) => {
          for (const t of txs) {
            let fileName = null;
            if (t.receipt_image || t.receiptImage) {
              fileName = saveReceiptFile(t.receipt_image || t.receiptImage, 'migrated', 'image');
            }
            
            insertTransaction.run(
              t.id || Date.now().toString(),
              t.description || 'Sem descrição',
              parseFloat(t.amount) || 0,
              t.type || 'expense',
              t.category || 'Outros',
              t.paymentMethod || 'Não informado',
              t.date || moment().format('YYYY-MM-DD'),
              t.user || 'unknown',
              t.userName || t.user || 'Usuário',
              fileName,
              t.createdAt || moment().toISOString()
            );
          }
        });
        
        insertMany(transactions);
        console.log(`✅ Migradas ${transactions.length} transações`);
      } catch (error) {
        console.log('ℹ️ Erro ao migrar transações:', error.message);
      }
    }
    
    insertDefaultCategories();
    normalizeCafeCategoriesInDb();
    console.log('✅ Categorias padrão inseridas');
    
  } catch (error) {
    console.error('❌ Erro na migração:', error);
  }
}

function insertDefaultCategories() {
  try {
    const insertCategory = db.prepare(`
      INSERT OR IGNORE INTO categories (type, name) VALUES (?, ?)
    `);
    
    for (const cat of DEFAULT_INCOME_CATEGORIES) {
      insertCategory.run('income', cat);
    }
    
    for (const cat of DEFAULT_EXPENSE_CATEGORIES) {
      insertCategory.run('expense', cat);
    }
    
    for (const method of DEFAULT_PAYMENT_METHODS) {
      insertCategory.run('payment_method', method);
    }
  } catch (error) {
    console.error('❌ Erro ao inserir categorias padrão:', error);
  }
}

function normalizeCafeCategoriesInDb() {
  try {
    if (!db) return;
    const targetCategory = 'Café ou Pão'; // a variante já usada na maioria das transações

    const transactionsUpdated = db.prepare(`
      UPDATE transactions
      SET category = ?
      WHERE lower(category) LIKE '%cafe%' OR lower(category) LIKE '%café%'
    `).run(targetCategory).changes;

    const categoriesDeleted = db.prepare(`
      DELETE FROM categories
      WHERE lower(name) LIKE '%cafe%' OR lower(name) LIKE '%café%'
    `).run().changes;
    db.prepare(`INSERT OR IGNORE INTO categories (type, name) VALUES (?, ?)`).run('expense', targetCategory);

    let scopedDeleted = 0;
    try {
      scopedDeleted = db.prepare(`
        DELETE FROM categories_scoped
        WHERE lower(name) LIKE '%cafe%' OR lower(name) LIKE '%café%'
      `).run().changes;
      if (tableHasColumn('categories_scoped', 'type')) {
        if (tableHasColumn('categories_scoped', 'user_id') && tableHasColumn('categories_scoped', 'user')) {
          const scopedRows = db.prepare(`
            SELECT DISTINCT user_id, user
            FROM transactions
            WHERE category = ?
              AND user_id IS NOT NULL
              AND user IS NOT NULL
          `).all(targetCategory);
          const insertScoped = db.prepare(`
            INSERT OR IGNORE INTO categories_scoped (type, name, user_id, user)
            VALUES (?, ?, ?, ?)
          `);
          for (const row of scopedRows) {
            insertScoped.run('expense', targetCategory, row.user_id, row.user);
          }
        }
      }
    } catch (_) {}

    let userPatternsUpdated = 0;
    try {
      userPatternsUpdated = db.prepare(`
        UPDATE user_patterns
        SET suggested_category = ?
        WHERE lower(suggested_category) LIKE '%cafe%' OR lower(suggested_category) LIKE '%café%'
      `).run(targetCategory).changes;
    } catch (_) {}

    if (transactionsUpdated || categoriesDeleted || scopedDeleted || userPatternsUpdated) {
      console.log(`✅ Categoria Café ou Pão normalizada: transactions=${transactionsUpdated}, categories=${categoriesDeleted}, categories_scoped=${scopedDeleted}, user_patterns=${userPatternsUpdated}`);
    }
  } catch (error) {
    console.error('❌ Erro ao normalizar categoria Café ou Pão:', error.message);
  }
}

// Item 7: alerta de orçamento por categoria. Limites configurados via /orcamento_definir no
// Telegram (tabela category_budgets). Dispara UMA vez por categoria/mês quando o gasto do mês
// (soma de 'expense') alcança o limite — dedup em category_budget_alerts_sent pra não repetir
// a cada nova compra na mesma categoria no mesmo mês.
async function verificarOrcamentoCategoria(category) {
  try {
    if (!db || !category) return;
    const limite = db.prepare(`SELECT limite FROM category_budgets WHERE category = ?`).get(category);
    if (!limite) return; // categoria sem limite configurado — nada a verificar

    const mesAtual = moment().format('YYYY-MM');
    const jaAlertado = db.prepare(`SELECT 1 FROM category_budget_alerts_sent WHERE category = ? AND year_month = ?`).get(category, mesAtual);
    if (jaAlertado) return;

    const gasto = db.prepare(`
      SELECT COALESCE(SUM(amount), 0) as total
      FROM transactions
      WHERE category = ? AND type = 'expense' AND strftime('%Y-%m', date) = ?
    `).get(category, mesAtual);

    const total = Number(gasto && gasto.total || 0);
    if (total < Number(limite.limite)) return;

    const claim = db.prepare(`INSERT OR IGNORE INTO category_budget_alerts_sent (category, year_month, sent_at) VALUES (?, ?, ?)`)
      .run(category, mesAtual, moment().toISOString());
    if (claim.changes === 0) return; // outra chamada concorrente já reivindicou o alerta

    const msg = `🚨 *ORÇAMENTO ESTOURADO: ${category}*\n\n` +
      `Gasto no mês: ${formatBRL(total)}\n` +
      `Limite: ${formatBRL(Number(limite.limite))}\n\n` +
      `_Use /orcamento para ver todas as categorias._`;
    for (const chatId of TG_CHAT_IDS) {
      try { await bot.telegram.sendMessage(chatId, msg, { parse_mode: 'Markdown' }); } catch (e) {}
    }
  } catch (error) {
    console.error('❌ [Orçamento] Erro ao verificar categoria:', error.message);
  }
}

// Item 6: relatório mensal consolidado — total por categoria do mês anterior, comparado com o
// mês retrasado, mais receita/despesa/saldo do período. Roda no dia 1 às 09:00 (ver agendar()).
// Item 9: avisa 3 dias antes do vencimento da fatura, uma vez por fatura (dedup por bill.id).
async function verificarVencimentoFaturaCartao() {
  try {
    if (!db) return;
    const resultado = await getNeonCreditCardBill();
    if (!resultado.success || !resultado.atual) return;
    const b = resultado.atual;
    if (!b.dueDate || !b.id) return;

    const diasParaVencer = moment(b.dueDate).startOf('day').diff(moment().startOf('day'), 'days');
    if (diasParaVencer < 0 || diasParaVencer > 3) return;

    const claim = db.prepare(`INSERT OR IGNORE INTO bill_due_alerts_sent (bill_id, sent_at) VALUES (?, ?)`).run(String(b.id), moment().toISOString());
    if (claim.changes === 0) return;

    const msg = `💳 *FATURA DO CARTÃO VENCE EM ${diasParaVencer === 0 ? 'HOJE' : diasParaVencer + ' DIA(S)'}*\n\n` +
      `📅 Vencimento: ${moment(b.dueDate).format('DD/MM/YYYY')}\n` +
      `💰 Total: ${formatBRL(b.totalAmount)}\n` +
      (b.minimumPaymentAmount != null ? `💵 Mínimo: ${formatBRL(b.minimumPaymentAmount)}\n` : '');
    for (const chatId of TG_CHAT_IDS) {
      try { await bot.telegram.sendMessage(chatId, msg, { parse_mode: 'Markdown' }); } catch (e) {}
    }
  } catch (error) {
    console.error('❌ [Fatura] Erro ao verificar vencimento:', error.message);
  }
}

async function enviarRelatorioMensal() {
  try {
    if (!db) return;
    const mesAnterior = moment().subtract(1, 'month');
    const mesRetrasado = moment().subtract(2, 'months');
    const ymAnterior = mesAnterior.format('YYYY-MM');
    const ymRetrasado = mesRetrasado.format('YYYY-MM');

    const porCategoria = db.prepare(`
      SELECT category, type, SUM(amount) as total
      FROM transactions
      WHERE strftime('%Y-%m', date) = ?
      GROUP BY category, type
      ORDER BY total DESC
    `).all(ymAnterior);

    const totalAnteriorPorCategoria = {};
    db.prepare(`
      SELECT category, SUM(amount) as total
      FROM transactions
      WHERE strftime('%Y-%m', date) = ? AND type = 'expense'
      GROUP BY category
    `).all(ymRetrasado).forEach(r => { totalAnteriorPorCategoria[r.category] = Number(r.total); });

    const totais = db.prepare(`
      SELECT
        COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE 0 END), 0) as receita,
        COALESCE(SUM(CASE WHEN type='expense' THEN amount ELSE 0 END), 0) as despesa
      FROM transactions
      WHERE strftime('%Y-%m', date) = ?
    `).get(ymAnterior);

    if (!porCategoria.length) {
      console.log(`ℹ️ [Relatório mensal] Nenhuma transação em ${ymAnterior}, relatório não enviado.`);
      return;
    }

    const despesasPorCategoria = porCategoria.filter(r => r.type === 'expense').slice(0, 10);
    const linhas = despesasPorCategoria.map(r => {
      const anterior = totalAnteriorPorCategoria[r.category];
      let variacao = '';
      if (anterior) {
        const pct = ((Number(r.total) - anterior) / anterior) * 100;
        variacao = ` (${pct >= 0 ? '+' : ''}${pct.toFixed(0)}% vs mês anterior)`;
      }
      return `• ${r.category}: ${formatBRL(r.total)}${variacao}`;
    });

    const saldo = Number(totais.receita) - Number(totais.despesa);
    const msg = `📊 *RELATÓRIO MENSAL — ${mesAnterior.format('MMMM/YYYY').toUpperCase()}*\n\n` +
      `💰 Receitas: ${formatBRL(totais.receita)}\n` +
      `💸 Despesas: ${formatBRL(totais.despesa)}\n` +
      `${saldo >= 0 ? '✅' : '⚠️'} Saldo do mês: ${formatBRL(saldo)}\n\n` +
      `*Top categorias (despesas):*\n${linhas.join('\n')}`;

    for (const chatId of TG_CHAT_IDS) {
      try { await bot.telegram.sendMessage(chatId, msg, { parse_mode: 'Markdown' }); } catch (e) {}
    }
    console.log(`✅ [Relatório mensal] Enviado para ${ymAnterior}`);
  } catch (error) {
    console.error('❌ [Relatório mensal] Erro:', error.message);
  }
}

function checkGasolinaAlert(user) {
    try {
        const ledgerUser = normalizeLedgerUsername(user);
        const now = moment();
        const currentMonth = now.format('YYYY-MM');
        
        // Buscar gastos com gasolina no mês atual
        const userFilter = buildUserWhere('transactions', ledgerUser, 'user');
        const gasolinaData = db.prepare(`
            SELECT 
                COALESCE(SUM(amount), 0) as total_gasolina,
                COUNT(*) as count_transacoes
            FROM transactions 
            WHERE ${userFilter.clause}
            AND strftime('%Y-%m', date) = ?
            AND (
                LOWER(description) LIKE '%gasolina%' 
                OR LOWER(description) LIKE '%combustível%'
                OR LOWER(description) LIKE '%combustivel%'
                OR LOWER(description) LIKE '%posto%'
                OR LOWER(category) = 'gasolina'
                OR LOWER(category) LIKE '%combustível%'
                OR LOWER(category) LIKE '%combustivel%'
            )
            AND type = 'expense'
        `).get(...userFilter.params, currentMonth);

        const totalGasolina = parseFloat(gasolinaData?.total_gasolina || 0);
        const countTransacoes = parseInt(gasolinaData?.count_transacoes || 0);
        
        console.log(`🔍 Verificando gasolina para ${ledgerUser}: R$ ${totalGasolina.toFixed(2)} (${countTransacoes} transações)`);
        
        const LIMITE_REEMBOLSO_GASOLINA = 640;
        
        // Lógica de alerta corrigida
        if (totalGasolina === 0) {
            return {
                alert: false,
                total: 0,
                message: `⛽ *SEM GASTOS DE GASOLINA*\n\nNenhum gasto registrado neste mês.`
            };
        }
        else if (totalGasolina < LIMITE_REEMBOLSO_GASOLINA) {
            const restante = LIMITE_REEMBOLSO_GASOLINA - totalGasolina;
            return {
                alert: false,
                total: totalGasolina,
                message: `⛽ *DENTRO DO LIMITE*\n\n` +
                        `Gasto atual: R$ ${totalGasolina.toFixed(2)}\n` +
                        `Limite restante: R$ ${restante.toFixed(2)}\n` +
                        `Limite total: R$ ${LIMITE_REEMBOLSO_GASOLINA.toFixed(2)}`
            };
        }
        else if (totalGasolina >= LIMITE_REEMBOLSO_GASOLINA && totalGasolina < (LIMITE_REEMBOLSO_GASOLINA + 1)) {
            return {
                alert: true,
                total: totalGasolina,
                message: `⚠️ *ATENÇÃO: LIMITE ATINGIDO!*\n\n` +
                        `Você gastou R$ ${totalGasolina.toFixed(2)} em gasolina este mês.\n\n` +
                        `💰 *LIMITE DE REEMBOLSO: R$ ${LIMITE_REEMBOLSO_GASOLINA.toFixed(2)}*\n` +
                        `💸 *"A partir de agora o custo será do seu bolso!"*`
            };
        }
        else {
            const excedente = totalGasolina - LIMITE_REEMBOLSO_GASOLINA;
            return {
                alert: true,
                total: totalGasolina,
                message: `🚨 *LIMITE ULTRAPASSADO!*\n\n` +
                        `Total gasto: R$ ${totalGasolina.toFixed(2)}\n` +
                        `Limite de reembolso: R$ ${LIMITE_REEMBOLSO_GASOLINA.toFixed(2)}\n` +
                        `💸 *Do seu bolso: R$ ${excedente.toFixed(2)}*\n\n` +
                        `_O reembolso cobre apenas R$ ${LIMITE_REEMBOLSO_GASOLINA.toFixed(2)}_`
            };
        }
        
    } catch (error) {
        console.error('❌ Erro ao verificar alerta de gasolina:', error);
        return {
            alert: false,
            total: 0,
            error: error.message
        };
    }
}
// ============== FUNÇÃO PARA CALCULAR FATURAS DE CARTÃO ==============
function calculateCardFaturas(user, mes = null) {
    try {
        const now = moment();
        const currentMonth = mes || now.format('YYYY-MM');   // mes 'YYYY-MM': fatura de outro mês (aviso por compra)
        const userFilter = buildUserWhere('transactions', user, 'user');

        const faturas = {
            banrisul: 0,
            magazine: 0,
            bradesco: 0,
            success: true,
            monthLabel: currentMonth
        };

        const knownCards = [
            { display: 'banrisul', keyword: 'BANRISUL' },
            { display: 'magazine', keyword: 'MAGAZINE' },
            { display: 'bradesco', keyword: 'BRADESCO' }
        ];

        const ctx = userFilter && userFilter.ctx ? userFilter.ctx : resolveUserContext(user);
        const userId = ctx && Number.isFinite(Number(ctx.userId)) ? Number(ctx.userId) : null;
        const username = ctx && ctx.username ? String(ctx.username) : '';

        let creditCards = [];
        try {
            const hasCreditCardsTable = db.prepare(`
                SELECT name FROM sqlite_master
                WHERE type='table' AND name='credit_cards'
                LIMIT 1
            `).get();
            if (hasCreditCardsTable && userId !== null && tableHasColumn('credit_cards', 'user_id')) {
                const rows = db.prepare(`
                    SELECT name FROM credit_cards
                    WHERE user_id = ?
                    ORDER BY name
                `).all(userId);
                creditCards = (rows || []).map(r => String(r.name || '').trim()).filter(Boolean);
            }
        } catch (e) {
            console.warn('⚠️ Erro ao buscar cartões de crédito:', e && e.message ? e.message : e);
        }

        let paymentMethods = [];
        try {
            const hasScopedTable = db.prepare(`
                SELECT name FROM sqlite_master
                WHERE type='table' AND name='categories_scoped'
                LIMIT 1
            `).get();
            if (hasScopedTable && tableHasColumn('categories_scoped', 'type') && tableHasColumn('categories_scoped', 'name')) {
                if (userId !== null && tableHasColumn('categories_scoped', 'user_id')) {
                    const rows = db.prepare(`
                        SELECT name FROM categories_scoped
                        WHERE type = 'payment_method' AND user_id = ?
                        ORDER BY name
                    `).all(userId);
                    paymentMethods = (rows || []).map(r => String(r.name || '').trim()).filter(Boolean);
                } else if (username && tableHasColumn('categories_scoped', 'user')) {
                    const rows = db.prepare(`
                        SELECT name FROM categories_scoped
                        WHERE type = 'payment_method' AND user = ?
                        ORDER BY name
                    `).all(username);
                    paymentMethods = (rows || []).map(r => String(r.name || '').trim()).filter(Boolean);
                }
            }
        } catch (e) {
            console.warn('⚠️ Erro ao buscar métodos de pagamento (categories_scoped):', e && e.message ? e.message : e);
        }

        let legacyPaymentMethods = [];
        try {
            const hasCategoriesTable = db.prepare(`
                SELECT name FROM sqlite_master
                WHERE type='table' AND name='categories'
                LIMIT 1
            `).get();
            if (hasCategoriesTable && tableHasColumn('categories', 'type') && tableHasColumn('categories', 'name')) {
                const rows = db.prepare(`
                    SELECT name FROM categories
                    WHERE type = 'payment_method'
                      AND (user = 'system' OR (user_id IS NULL AND user IS NULL))
                    ORDER BY name
                `).all();
                legacyPaymentMethods = (rows || []).map(r => String(r.name || '').trim()).filter(Boolean);
            }
        } catch (e) {
            console.warn('⚠️ Erro ao buscar métodos de pagamento (categories legado):', e && e.message ? e.message : e);
        }

        const normalizeKeyword = (value) => {
            const s = String(value || '').trim().toUpperCase();
            if (!s) return '';
            return s.replace(/[%_]/g, '').slice(0, 80);
        };

        const mappedNamesByDisplay = { banrisul: [], magazine: [], bradesco: [] };
        const cardCandidates = [...creditCards, ...paymentMethods, ...legacyPaymentMethods];
        for (const cardName of cardCandidates) {
            const upperName = normalizeKeyword(cardName);
            if (!upperName) continue;
            for (const known of knownCards) {
                if (upperName.includes(known.keyword)) {
                    mappedNamesByDisplay[known.display].push(upperName);
                    break;
                }
            }
        }

        const sumExpensesByKeywords = (keywords) => {
            const cleaned = (keywords || []).map(normalizeKeyword).filter(Boolean);
            const unique = [];
            for (const k of cleaned) if (!unique.includes(k)) unique.push(k);
            if (unique.length === 0) return 0;
            const limited = unique.slice(0, 12);

            const conditions = [];
            const params = [];
            for (const k of limited) {
                conditions.push(`(
                    UPPER(description) LIKE ?
                    OR UPPER(payment_method) LIKE ?
                    OR UPPER(category) LIKE ?
                )`);
                const like = `%${k}%`;
                params.push(like, like, like);
            }

            const row = db.prepare(`
                SELECT SUM(amount) as total
                FROM transactions
                WHERE ${userFilter.clause}
                AND strftime('%Y-%m', date) = ?
                AND type = 'expense'
                AND (${conditions.join(' OR ')})
            `).get(...userFilter.params, currentMonth, ...params);
            return row && row.total ? Number(row.total) : 0;
        };

        for (const known of knownCards) {
            const keywords = [known.keyword, ...(mappedNamesByDisplay[known.display] || [])];
            faturas[known.display] = sumExpensesByKeywords(keywords);
        }

        return faturas;
    } catch (error) {
        console.error('❌ Erro ao calcular faturas dos cartões:', error);
        return {
            success: false,
            error: error.message,
            banrisul: 0,
            magazine: 0,
            bradesco: 0,
            monthLabel: moment().format('YYYY-MM')
        };
    }
}
// ============== FUNÇÃO: TOTAL "MAGAZINE" DO MÊS SEGUINTE AO ATUAL ==============
// Soma todas as transações de despesa cuja descrição, categoria ou método de pagamento
// contenham a palavra "magazine", sempre referentes ao mês seguinte ao mês corrente.
function calculateMagazineNextMonthTotal(user) {
    try {
        const nextMonth = moment().add(1, 'month').format('YYYY-MM');
        const userFilter = buildUserWhere('transactions', user, 'user');

        const row = db.prepare(`
            SELECT SUM(amount) as total
            FROM transactions
            WHERE ${userFilter.clause}
            AND strftime('%Y-%m', date) = ?
            AND type = 'expense'
            AND (
                UPPER(description) LIKE '%MAGAZINE%'
                OR UPPER(payment_method) LIKE '%MAGAZINE%'
                OR UPPER(category) LIKE '%MAGAZINE%'
            )
        `).get(...userFilter.params, nextMonth);

        return {
            success: true,
            total: row && row.total ? Number(row.total) : 0,
            monthLabel: nextMonth
        };
    } catch (error) {
        console.error('❌ Erro ao calcular total Magazine do mês seguinte:', error);
        return {
            success: false,
            error: error.message,
            total: 0,
            monthLabel: moment().add(1, 'month').format('YYYY-MM')
        };
    }
}

// Conta de Energia: agrega por mes (de um ano) o total de transacoes cuja descricao,
// metodo de pagamento ou categoria contenham a palavra-chave "CONTA DE LUZ", e calcula
// a media mensal (considerando apenas os meses que tiveram algum lancamento).
// Soma por mês (jan..dez) das despesas do ano cujo description/payment_method/category contém `keyword`
// (maiúsculo). Base de calcularContaEnergiaPorMes e calcularAlimentacaoPorMes.
// excluirMesAtual: o mês em andamento aparece em `months` (com isMesAtual) mas fica fora da média.
function calcularGastoMensalPorPalavraChave(user, year, { keyword, label, excluirMesAtual = false }) {
    try {
        const anoAlvo = Number(year) || moment().year();
        const userFilter = buildUserWhere('transactions', user, 'user');
        const pattern = `%${keyword}%`;

        const rows = db.prepare(`
            SELECT strftime('%m', date) as mes, SUM(amount) as total, COUNT(*) as qtd
            FROM transactions
            WHERE ${userFilter.clause}
            AND strftime('%Y', date) = ?
            AND type = 'expense'
            AND (
                UPPER(description) LIKE ?
                OR UPPER(payment_method) LIKE ?
                OR UPPER(category) LIKE ?
            )
            GROUP BY mes
        `).all(...userFilter.params, String(anoAlvo), pattern, pattern, pattern);

        const porMes = {};
        (rows || []).forEach(r => {
            const idx = Number(r.mes);
            if (Number.isFinite(idx)) porMes[idx] = { total: Number(r.total || 0), count: Number(r.qtd || 0) };
        });

        const nomesMeses = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
        const agora = moment();
        const anoAtualReal = agora.year();
        const mesAtualReal = agora.month() + 1;

        const months = [];
        let somaTotais = 0;
        let mesesComDado = 0;
        for (let m = 1; m <= 12; m++) {
            const info = porMes[m] || { total: 0, count: 0 };
            const isMesAtual = excluirMesAtual && anoAlvo === anoAtualReal && m === mesAtualReal;
            const item = { month: m, label: nomesMeses[m - 1], total: info.total, count: info.count };
            if (excluirMesAtual) item.isMesAtual = isMesAtual;
            months.push(item);
            if (info.count > 0 && !isMesAtual) {
                somaTotais += info.total;
                mesesComDado += 1;
            }
        }

        const media = mesesComDado > 0 ? somaTotais / mesesComDado : 0;

        return { success: true, year: anoAlvo, months, media, mesesComDado };
    } catch (error) {
        console.error(`❌ Erro ao calcular ${label} por mês:`, error);
        return {
            success: false,
            error: error.message,
            year: Number(year) || moment().year(),
            months: [],
            media: 0,
            mesesComDado: 0
        };
    }
}

function calcularContaEnergiaPorMes(user, year) {
    return calcularGastoMensalPorPalavraChave(user, year, { keyword: 'CONTA DE LUZ', label: 'Conta de Energia' });
}

// Alimentação: mesma lógica da Conta de Energia, mas filtrando pela palavra-chave
// "aliment" (radical de "Alimentação"/"alimentacao", sem os caracteres acentuados
// "ç"/"ã" — o UPPER() nativo do SQLite não faz o case-fold correto de acentos, então
// usar o radical sem acento evita esse problema e ainda cobre "Alimentação",
// "alimentacao" digitado sem acento, etc.)
function calcularAlimentacaoPorMes(user, year) {
    // Regra: o mês atual (em andamento) NUNCA entra no cálculo da média — só conta
    // depois que o mês tiver terminado, pra não subestimar a média com um mês parcial.
    return calcularGastoMensalPorPalavraChave(user, year, { keyword: 'ALIMENT', label: 'Alimentação', excluirMesAtual: true });
}

