// 1. Função para buscar TODAS as contas de investimento do Neon
async function getNeonInvestmentAccounts() {
  try {
    const apiKey = await getPluggyApiKey();
    
    const response = await axios.get(`${PLUGGY_API_URL}/accounts?itemId=${NEON_ITEM_ID}`, {
      headers: { 'X-API-KEY': apiKey }
    });
    
    const accounts = response.data.results || [];
    
    // Filtra apenas contas de investimento (Caixinhas)
    const investmentAccounts = accounts.filter(acc => 
      acc.type === 'FIXED_INCOME' || 
      acc.type === 'INVESTMENT' ||
      acc.subtype === 'CDB'
    );
    
    console.log(`📊 Neon - Total de caixinhas encontradas: ${investmentAccounts.length}`);
    investmentAccounts.forEach((acc, i) => {
      console.log(`   ${i+1}. ${acc.name || acc.subtype || 'Caixinha'}: R$ ${acc.balance?.toFixed(2) || '0,00'}`);
    });
    
    return {
      success: true,
      accounts: investmentAccounts,
      totalBalance: investmentAccounts.reduce((sum, acc) => sum + (acc.balance || 0), 0)
    };
    
  } catch (error) {
    console.error('❌ Erro ao buscar caixinhas do Neon:', error.message);
    return { success: false, error: error.message, accounts: [] };
  }
}
// ============== FUNÇÃO PARA BUSCAR TRANSAÇÕES DE UMA CONTA ESPECÍFICA ==============
async function getAccountTransactions(accountId, fromDate = null, toDate = null, accountInfo = {}) {
    try {
        const apiKey = await getPluggyApiKey();
        
        let url = `${PLUGGY_API_URL}/transactions?accountId=${accountId}&pageSize=100`;
        
        if (fromDate) url += `&from=${fromDate}`;
        if (toDate) url += `&to=${toDate}`;
        
        const response = await axios.get(url, {
            headers: { 'X-API-KEY': apiKey }
        });
        
        return {
            success: true,
            transactions: (response.data.results || []).map(t => ({
                ...t,
                accountInfo: {
                    id: accountId,
                    name: accountInfo.name || accountInfo.subtype || 'Caixinha',
                    type: accountInfo.type,
                    subtype: accountInfo.subtype
                }
            })),
            total: response.data.total || 0
        };
        
    } catch (error) {
        console.error(`❌ Erro ao buscar transações da conta ${accountId}:`, error.message);
        return { success: false, error: error.message, transactions: [] };
    }
}
// ============== VERIFICADOR AUTOMÁTICO A CADA 5 MINUTOS ==============
let ultimaVerificacao = null;
let transacoesProcessadas = new Set(); // Cache em memória para evitar duplicatas

async function verificarNovasTransacoes() {
    const inicio = Date.now();
    console.log(`\n🔍 [${moment().format('DD/MM/YYYY HH:mm:ss')}] INICIANDO VERIFICAÇÃO AUTOMÁTICA DE TRANSAÇÕES...`);
    
    try {
        // Buscar transações dos últimos 7 dias (para garantir que pega tudo)
        const hoje = moment();
        const seteDiasAtras = moment().subtract(7, 'days');
        const dataInicio = seteDiasAtras.format('YYYY-MM-DD');
        const dataFim = hoje.format('YYYY-MM-DD');
        
        console.log(`📅 Período de busca: ${dataInicio} até ${dataFim}`);
        
        // Buscar transações de todos os bancos
        const apiKey = await getSicrediApiKey(); // usado só pelo Sicredi abaixo; Neon busca sua própria chave
        
        // Buscas paralelas para melhor performance
        const [sicrediResponse, neonResult] = await Promise.all([
            // Sicredi
            axios.get(
                `${PLUGGY_API_URL}/transactions?accountId=${SICREDI_ACCOUNT_ID}&from=${dataInicio}&to=${dataFim}&pageSize=100`,
                { headers: { 'X-API-KEY': apiKey } }
            ).catch(err => ({ data: { results: [] } })),
            
            // Neon (todas as contas)
            getAllNeonTransactions(dataInicio, dataFim)
        ]);
        
        // Processar transações do Sicredi
        const sicrediTransacoes = (sicrediResponse.data?.results || []).map(t => ({
            ...t,
            bank: 'Sicredi',
            accountType: 'Conta Corrente',
            uniqueId: `sicredi_${t.id}`
        }));
        
        // Processar transações do Neon
        const neonTransacoes = (neonResult.transactions || []).map(t => ({
            ...t,
            bank: 'Neon',
            accountType: t.conta || 'Conta Corrente',
            uniqueId: `neon_${t.id}`
        }));
        
        // Combinar todas as transações
        const todasTransacoes = [...sicrediTransacoes, ...neonTransacoes];
        
        // Ordenar por data (mais recentes primeiro)
        todasTransacoes.sort((a, b) => moment(b.date).valueOf() - moment(a.date).valueOf());
        
        console.log(`📊 Total de transações encontradas: ${todasTransacoes.length}`);
        
        // Identificar transações não notificadas
        const novasTransacoes = [];
        const now = moment().toISOString();
        
        for (const transacao of todasTransacoes) {
            // Verificar se já foi notificada no banco
            const jaNotificada = db.prepare(`
                SELECT COUNT(*) as count FROM transaction_notifications 
                WHERE transaction_id = ?
            `).get(transacao.uniqueId).count > 0;
            
            // Verificar se está no cache em memória
            const emCache = transacoesProcessadas.has(transacao.uniqueId);
            
            // Se for CREDIT (entrada) e ainda não foi notificada
            if (!jaNotificada && !emCache && transacao.amount > 0) {
                novasTransacoes.push(transacao);
                transacoesProcessadas.add(transacao.uniqueId);
                
                // Registrar no banco imediatamente para evitar duplicatas em caso de falha
                db.prepare(`
                    INSERT OR IGNORE INTO transaction_notifications 
                    (transaction_id, bank, amount, description, date, notified_at)
                    VALUES (?, ?, ?, ?, ?, ?)
                `).run(
                    transacao.uniqueId,
                    transacao.bank,
                    Math.abs(transacao.amount),
                    transacao.description || 'Sem descrição',
                    transacao.date.split('T')[0],
                    now
                );
            }
        }
        
        // Se encontrou novas transações, notificar
        if (novasTransacoes.length > 0) {
            console.log(`💰 ENCONTRADAS ${novasTransacoes.length} NOVA(S) TRANSAÇÃO(ÕES)!`);
            
            for (const transacao of novasTransacoes) {
                // Item 11: antes chamava notificarNovaTransacao() -> salvarTransacaoNoBanco(),
                // um SEGUNDO caminho de gravação com esquema de transaction_id diferente do usado
                // pelo polling/webhook (t.id bruto vs pluggy_sicredi_/neon_ prefixado) — risco real
                // de duplicar a mesma transação vinda pelos dois caminhos. Agora usa as MESMAS
                // funções que o resto do sistema usa, com o mesmo dedup e todos os recursos novos
                // (filtro de transferência interna, normalização de categoria, orçamento, push).
                if (transacao.bank === 'Sicredi') {
                    await salvarTransacaoSicredi(transacao, transacao.accountType || 'Conta Corrente');
                } else if (transacao.bank === 'Neon') {
                    await salvarTransacaoNeon(transacao, { name: transacao.accountType, type: transacao.accountType });
                } else {
                    console.warn(`⚠️ [verificarNovasTransacoes] Banco desconhecido: ${transacao.bank}`);
                }
                // Pequeno delay entre notificações para não floodar
                await sleep(1000);
            }
            
            // Registrar no log
            console.log(`✅ ${novasTransacoes.length} notificação(ões) enviada(s)`);
        } else {
            console.log(`ℹ️ Nenhuma transação nova encontrada.`);
        }
        
        // Limpar cache antigo (manter apenas últimas 24h)
        limparCacheTransacoes();
        
        ultimaVerificacao = moment().toDate();
        const duracao = ((Date.now() - inicio) / 1000).toFixed(2);
        console.log(`✅ Verificação concluída em ${duracao}s`);
        
        return {
            success: true,
            novasTransacoes: novasTransacoes.length,
            totalTransacoes: todasTransacoes.length,
            duracao: `${duracao}s`
        };
        
    } catch (error) {
        console.error('❌ Erro na verificação automática:', error);
        
        // Enviar alerta de erro (apenas uma vez por hora para não floodar)
        const ultimoErroNotificado = db.prepare(`
            SELECT notified_at FROM transaction_notifications 
            WHERE transaction_id = 'erro_monitoramento' 
            ORDER BY notified_at DESC LIMIT 1
        `).get();
        
        const agora = moment();
        const umaHoraAtras = moment().subtract(1, 'hour');
        
        if (!ultimoErroNotificado || moment(ultimoErroNotificado.notified_at).isBefore(umaHoraAtras)) {
            for (const chatId of TG_CHAT_IDS) {
                await bot.telegram.sendMessage(
                    chatId,
                    `🚨 *ALERTA DO SISTEMA*\n\nOcorreu um erro no monitoramento automático:\n\`\`\`\n${error.message}\n\`\`\`\n\nO sistema continuará tentando a cada 1 minutos.`,
                    { parse_mode: 'Markdown' }
                );
            }
            
            // Registrar erro para não repetir
            db.prepare(`
                INSERT OR REPLACE INTO transaction_notifications 
                (transaction_id, bank, description, notified_at)
                VALUES ('erro_monitoramento', 'sistema', ?, ?)
            `).run(error.message, agora.toISOString());
        }
        
        return { success: false, error: error.message };
    }
}
// Item 11: sem chamadores desde a mudança em verificarNovasTransacoes (usava um esquema de
// transaction_id diferente do resto do sistema — risco de duplicar). Mantida só como histórico;
// não remova a chamada em outro lugar sem passar por salvarTransacaoSicredi/salvarTransacaoNeon.
async function notificarNovaTransacao(transacao) {
    try {
        // PIX enviado nunca é salvo direto: vai para a fila de aprovação (Telegram + dashboard).
        if (ehPixEnviado(transacao)) {
            if (transacao.bank === 'Sicredi') {
                await salvarTransacaoSicredi(transacao, transacao.accountType || 'Conta Corrente');
            } else if (transacao.bank === 'Neon') {
                await salvarTransacaoNeon(transacao, { name: transacao.accountType, type: transacao.accountType });
            }
            return true;
        }

        const valorFormatado = formatBRL(Math.abs(transacao.amount));
        
        const dataFormatada = moment(transacao.date).format('DD/MM/YYYY HH:mm');
        
        const bankEmoji = transacao.bank === 'Sicredi' ? '🏦' : '💳';
        const accountInfo = transacao.accountType || 'Conta Corrente';
        
        // Usar HTML em vez de Markdown para evitar problemas com caracteres especiais
        const mensagem = [
            `💰 <b>NOVA TRANSAÇÃO DETECTADA</b>`,
            `━━━━━━━━━━━━━━━━━━━━`,
            `${bankEmoji} <b>Banco:</b> ${transacao.bank} - ${accountInfo}`,
            `📝 <b>Descrição:</b> ${escapeHtml(transacao.description || 'Sem descrição')}`,
            `💵 <b>Valor:</b> ${valorFormatado}`,
            `📅 <b>Data:</b> ${dataFormatada}`,
            `🆔 <b>ID:</b> <code>${transacao.uniqueId}</code>`,
            `━━━━━━━━━━━━━━━━━━━━`,
            `<i>Detectado automaticamente pelo monitoramento</i>`
        ].join('\n');
        
        const envios = TG_CHAT_IDS.map(async (chatId) => {
            try {
                await bot.telegram.sendMessage(chatId, mensagem, {
                    parse_mode: 'HTML',
                    reply_markup: {
                        inline_keyboard: [[
                            { text: '🔍 Ver no Dashboard', url: PUBLIC_URL },
                            { text: '✅ OK', callback_data: 'dismiss_notification' }
                        ]]
                    }
                });
                console.log(`✅ Notificação enviada para ${chatId}`);
                return true;
            } catch (err) {
                console.error(`❌ Erro ao enviar para ${chatId}:`, err.message);
                
                // Se falhar com HTML, tenta sem parse_mode
                try {
                    await bot.telegram.sendMessage(chatId, mensagem.replace(/<[^>]*>/g, ''), {
                        reply_markup: {
                            inline_keyboard: [[
                                { text: '🔍 Ver no Dashboard', url: PUBLIC_URL },
                                { text: '✅ OK', callback_data: 'dismiss_notification' }
                            ]]
                        }
                    });
                    console.log(`✅ Notificação (texto puro) enviada para ${chatId}`);
                    return true;
                } catch (fallbackErr) {
                    console.error(`❌ Falha total para ${chatId}:`, fallbackErr.message);
                    return false;
                }
            }
        });
        
        await Promise.all(envios);
        await salvarTransacaoNoBanco(transacao, transacao.bank);
        return true;
    } catch (error) {
        console.error('❌ Erro ao notificar:', error);
        return false;
    }
}
// ============== FUNÇÃO DE ESCAPE HTML ==============

async function enviarAlertaErro(error) {
    const agora = moment();
    const umaHoraAtras = moment(agora).subtract(1, 'hour');

    const ultimoErro = db.prepare(`
        SELECT notified_at FROM transaction_notifications 
        WHERE transaction_id = 'erro_monitoramento' 
        ORDER BY notified_at DESC LIMIT 1
    `).get();

    if (!ultimoErro || moment(ultimoErro.notified_at).isBefore(umaHoraAtras)) {
        const mensagemErro = `🚨 <b>ALERTA DO SISTEMA</b>\n\n` +
                             `Ocorreu um erro no monitoramento:\n` +
                             `<code>${error.message}</code>\n\n` +
                             `<i>O sistema tentará novamente em 1 minuto.</i>`;

        for (const chatId of TG_CHAT_IDS) {
            await bot.telegram.sendMessage(chatId, mensagemErro, { parse_mode: 'HTML' });
        }

        db.prepare(`
            INSERT OR REPLACE INTO transaction_notifications 
            (transaction_id, bank, description, notified_at)
            VALUES ('erro_monitoramento', 'sistema', ?, ?)
        `).run(error.message, agora.toISOString());
    }
}
// Função para limpar cache antigo
function limparCacheTransacoes() {
    try {
        // Remover do banco transações com mais de 30 dias
        const trintaDiasAtras = moment().subtract(30, 'days');
        
        db.prepare(`
            DELETE FROM transaction_notifications 
            WHERE date < ? AND transaction_id NOT LIKE 'erro_%'
        `).run(trintaDiasAtras.format('YYYY-MM-DD'));
        
        // Limpar cache em memória (manter apenas últimas 1000)
        if (transacoesProcessadas.size > 1000) {
            const arrayCache = Array.from(transacoesProcessadas);
            transacoesProcessadas = new Set(arrayCache.slice(-500));
        }
        
    } catch (error) {
        console.error('❌ Erro ao limpar cache:', error);
    }
}

// 2. Função para buscar transações de TODAS as Caixinhas
async function getAllInvestmentTransactions(fromDate = null, toDate = null) {
  try {
    console.log('\n📈 Buscando transações de todas as Caixinhas Neon...');
    
    const apiKey = await getPluggyApiKey();
    const investmentAccounts = await getNeonInvestmentAccounts();
    
    if (!investmentAccounts.success) {
      throw new Error(investmentAccounts.error);
    }
    
    let allInvestmentTransactions = [];
    let accountsProcessed = [];
    
    // Busca transações de CADA caixinha individualmente
    for (const account of investmentAccounts.accounts) {
      console.log(`\n📊 Buscando transações da caixinha: ${account.name || account.subtype || 'Sem nome'} (${account.id})`);
      
      try {
        let url = `${PLUGGY_API_URL}/transactions?accountId=${account.id}&pageSize=100`;
        
        if (fromDate) url += `&from=${fromDate}`;
        if (toDate) url += `&to=${toDate}`;
        
        const response = await axios.get(url, {
          headers: { 'X-API-KEY': apiKey }
        });
        
        const transactions = (response.data.results || []).map(t => ({
          ...t,
          accountInfo: {
            id: account.id,
            name: account.name || account.subtype || 'Caixinha',
            type: account.subtype || account.type,
            balance: account.balance
          },
          investmentType: 'caixinha' // Identificador para seu sistema
        }));
        
        allInvestmentTransactions.push(...transactions);
        console.log(`   → ${transactions.length} transações encontradas`);
        
        accountsProcessed.push({
          id: account.id,
          name: account.name || account.subtype || 'Caixinha',
          balance: account.balance,
          transactionsCount: transactions.length
        });
        
      } catch (err) {
        console.error(`   ❌ Erro na caixinha ${account.id}:`, err.message);
      }
      
      // Pequena pausa para não sobrecarregar a API
      await sleep(500);
    }
    
    // Ordena por data (mais recente primeiro)
    allInvestmentTransactions.sort((a, b) => moment(b.date).valueOf() - moment(a.date).valueOf());
    
    console.log(`\n📊 RESUMO DAS CAIXINHAS:`);
    accountsProcessed.forEach(a => {
      console.log(`   • ${a.name}: R$ ${a.balance?.toFixed(2) || '0,00'} (${a.transactionsCount} transações)`);
    });
    console.log(`\n📈 TOTAL GERAL: ${allInvestmentTransactions.length} transações de investimento`);
    console.log(`💰 Saldo total investido: R$ ${investmentAccounts.totalBalance.toFixed(2)}`);
    
    return {
      success: true,
      transactions: allInvestmentTransactions,
      total: allInvestmentTransactions.length,
      accounts: investmentAccounts.accounts,
      accountsSummary: accountsProcessed,
      totalBalance: investmentAccounts.totalBalance
    };
    
  } catch (error) {
    console.error('❌ Erro ao buscar transações de investimento:', error.message);
    return { success: false, error: error.message, transactions: [], accounts: [] };
  }
}

// 3. Função para classificar transações de investimento
function classifyInvestmentTransaction(transaction, accountInfo) {
  const description = (transaction.description || '').toLowerCase();
  const originalAmount = transaction.amount || 0;
  
  // Classifica o tipo de operação baseado na descrição
  let operationType = 'unknown';
  let subcategory = 'Investimentos - Outros';
  
  if (description.includes('aplicação') || description.includes('aplicacao')) {
    operationType = 'application'; // Aplicação (saída da conta corrente)
    subcategory = 'Investimentos - Aplicação';
  } 
  else if (description.includes('resgate')) {
    operationType = 'redemption'; // Resgate (entrada na conta corrente)
    subcategory = 'Investimentos - Resgate';
  }
  else if (description.includes('vencimento') || description.includes('rendimento')) {
    operationType = 'maturity'; // Vencimento/Rendimento
    subcategory = 'Investimentos - Rendimentos';
  }
  else if (description.includes('cdb')) {
    operationType = 'cdb';
    subcategory = 'Investimentos - CDB';
  }
  
  // Determina o tipo para o sistema (income = entrada, expense = saída)
  // Para investimentos: aplicação é saída (expense), resgate/rendimento é entrada (income)
  let systemType = 'expense'; // padrão é saída
  if (operationType === 'redemption' || operationType === 'maturity') {
    systemType = 'income';
  }
  
  // Se for CREDIT da Pluggy e for resgate, força income
  if (transaction.type === 'CREDIT' && originalAmount > 0) {
    systemType = 'income';
  }
  // Se for DEBIT da Pluggy e for aplicação, força expense
  else if (transaction.type === 'DEBIT' && originalAmount > 0) {
    systemType = 'expense';
  }
  
  // Nome da caixinha para o método de pagamento
  const accountDisplayName = accountInfo.name || accountInfo.type || 'Caixinha';
  
  return {
    ...transaction,
    operationType,
    subcategory,
    category: 'Investimentos', // ✅ CATEGORIA ÚNICA PRINCIPAL
    investmentAccount: accountDisplayName,
    investmentBalance: accountInfo.balance,
    systemType,
    // Método de pagamento personalizado
    paymentMethod: `Neon - ${accountDisplayName}`,
    // Descrição enriquecida
    enrichedDescription: transaction.description || `Movimentação em ${accountDisplayName}`
  };
}

// 4. Função para consolidar em uma única categoria "Investimentos"
async function consolidateInvestmentTransactions(user = 'user1', fromDate = null, toDate = null) {
  try {
    console.log('\n🔄 CONSOLIDANDO TRANSAÇÕES DE INVESTIMENTOS...');
    
    // Busca todas as transações de investimento
    const investmentData = await getAllInvestmentTransactions(fromDate, toDate);
    
    if (!investmentData.success) {
      return { success: false, error: investmentData.error };
    }
    
    let consolidated = [];
    let byOperation = {
      applications: 0,
      redemptions: 0,
      earnings: 0,
      other: 0
    };
    
    let byAccount = {};
    
    for (const transaction of investmentData.transactions) {
      // Classifica a transação
      const classified = classifyInvestmentTransaction(transaction, transaction.accountInfo);
      
      // Atualiza contadores
      if (classified.operationType === 'application') byOperation.applications++;
      else if (classified.operationType === 'redemption') byOperation.redemptions++;
      else if (classified.operationType === 'maturity') byOperation.earnings++;
      else byOperation.other++;
      
      // Contador por conta
      const accountName = classified.investmentAccount;
      if (!byAccount[accountName]) {
        byAccount[accountName] = { count: 0, totalAmount: 0 };
      }
      byAccount[accountName].count++;
      byAccount[accountName].totalAmount += Math.abs(classified.amount || 0);
      
      // Prepara para salvar no banco com categoria "Investimentos"
      const dbTransaction = {
        transaction_id: `neon_invest_${transaction.id}_${Date.now()}`,
        description: classified.enrichedDescription,
        original_description: transaction.description,
        amount: Math.abs(transaction.amount || 0),
        type: classified.systemType, // 'income' para resgates, 'expense' para aplicações
        category: 'Investimentos', // ✅ CATEGORIA ÚNICA
        subcategory: classified.subcategory,
        payment_method: classified.paymentMethod,
        date: transaction.date ? transaction.date.split('T')[0] : moment().format('YYYY-MM-DD'),
        user: user,
        user_name: user === 'user1' ? 'Usuário 1' : 'User2',
        created_at: moment().toISOString(),
        metadata: JSON.stringify({
          originalType: transaction.type,
          operationType: classified.operationType,
          accountBalance: transaction.accountInfo.balance,
          accountName: transaction.accountInfo.name,
          accountId: transaction.accountInfo.id,
          pluggyTransactionId: transaction.id
        })
      };
      
      consolidated.push(dbTransaction);
    }
    
    // Calcula totais financeiros
    const totals = {
      totalApplications: consolidated
        .filter(t => t.type === 'expense')
        .reduce((sum, t) => sum + t.amount, 0),
      totalRedemptions: consolidated
        .filter(t => t.type === 'income')
        .reduce((sum, t) => sum + t.amount, 0),
      netInvested: 0,
      totalTransactions: consolidated.length
    };
    
    totals.netInvested = totals.totalApplications - totals.totalRedemptions;
    
    console.log(`\n📊 RESUMO DA CONSOLIDAÇÃO:`);
    console.log(`   • Total de transações: ${consolidated.length}`);
    console.log(`   • Aplicações: ${byOperation.applications} (R$ ${totals.totalApplications.toFixed(2)})`);
    console.log(`   • Resgates: ${byOperation.redemptions} (R$ ${totals.totalRedemptions.toFixed(2)})`);
    console.log(`   • Rendimentos: ${byOperation.earnings}`);
    console.log(`   • Saldo líquido investido: R$ ${totals.netInvested.toFixed(2)}`);
    
    console.log(`\n📊 TRANSAÇÕES POR CAIXINHA:`);
    Object.entries(byAccount).forEach(([name, data]) => {
      console.log(`   • ${name}: ${data.count} transações (R$ ${data.totalAmount.toFixed(2)})`);
    });
    
    return {
      success: true,
      transactions: consolidated,
      totals,
      byOperation,
      byAccount,
      accounts: investmentData.accounts,
      accountsSummary: investmentData.accountsSummary,
      totalBalance: investmentData.totalBalance,
      totalTransactions: consolidated.length
    };
    
  } catch (error) {
    console.error('❌ Erro ao consolidar investimentos:', error);
    return { success: false, error: error.message };
  }
}

// 5. Função para salvar transações de investimento no banco
async function saveInvestmentTransactions(user = 'user1') {
  try {
    console.log('\n💾 SALVANDO TRANSAÇÕES DE INVESTIMENTO NO BANCO...');
    
    // Busca últimos 30 dias
    const toDate = moment().format('YYYY-MM-DD');
    const fromDate = moment().subtract(30, 'days').format('YYYY-MM-DD');
    
    console.log(`📅 Período: ${fromDate} até ${toDate}`);
    
    const consolidated = await consolidateInvestmentTransactions(user, fromDate, toDate);
    
    if (!consolidated.success) {
      throw new Error(consolidated.error);
    }
    
    let saved = 0;
    let duplicates = 0;
    let errors = 0;
    
    const hasUserId = tableHasColumn('transactions', 'user_id');
    const insertStmt = db.prepare(`
      INSERT OR IGNORE INTO transactions 
      (transaction_id, description, amount, type, category, payment_method, date, user, user_name, created_at${hasUserId ? ', user_id' : ''})
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?${hasUserId ? ', ?' : ''})
    `);
    
    // Usa transação do banco para performance
    const saveMany = db.transaction((transactions) => {
      for (const t of transactions) {
        try {
          // Mesmos filtros dos outros caminhos do Pluggy: transferência entre as próprias contas e
          // resgate da caixinha "Reforma da casa" não são receita/despesa real
          if (ehTransferenciaInterna(t.description) || ehSomenteNotificar(t.description)) continue;
          const result = insertStmt.run(
            t.transaction_id,
            t.description,
            t.amount,
            t.type,
            t.category, // ✅ SEMPRE "Investimentos"
            t.payment_method,
            t.date,
            t.user,
            t.user_name,
            t.created_at,
            ...(hasUserId ? [Number.isFinite(Number(getUserIdByUsername(t.user))) ? Number(getUserIdByUsername(t.user)) : null] : [])
          );
          
          if (result.changes > 0) {
            saved++;
            
            // Log detalhado para debugging
            const tipo = t.type === 'income' ? '💰 RESGATE' : '💸 APLICAÇÃO';
            console.log(`   ${tipo}: ${t.description} - R$ ${t.amount.toFixed(2)} (${t.payment_method})`);
          } else {
            duplicates++;
          }
        } catch (err) {
          errors++;
          console.error(`   ❌ Erro ao salvar ${t.transaction_id}:`, err.message);
        }
      }
    });
    
    // Executa a transação
    saveMany(consolidated.transactions);
    
    console.log(`\n📊 RESUMO DO SALVAMENTO:`);
    console.log(`   • Novas transações: ${saved}`);
    console.log(`   • Duplicadas: ${duplicates}`);
    console.log(`   • Erros: ${errors}`);
    console.log(`\n💰 TOTAIS CONSOLIDADOS:`);
    console.log(`   • Aplicações totais: R$ ${consolidated.totals.totalApplications.toFixed(2)}`);
    console.log(`   • Resgates totais: R$ ${consolidated.totals.totalRedemptions.toFixed(2)}`);
    console.log(`   • Saldo líquido investido: R$ ${consolidated.totals.netInvested.toFixed(2)}`);
    console.log(`   • Saldo atual nas caixinhas: R$ ${consolidated.totalBalance.toFixed(2)}`);
    
    // Se houver novas transações, notifica no Telegram
    if (saved > 0) {
      const mensagemTelegram = `
📊 *NOVAS TRANSAÇÕES EM CAIXINHAS NEON*
━━━━━━━━━━━━━━━━━━━━
📈 *Resumo da Sincronização:*
• ${saved} nova(s) transação(ões)
• ${duplicates} duplicada(s)

💰 *Movimentações:*
• Aplicações: R$ ${consolidated.totals.totalApplications.toFixed(2)}
• Resgates: R$ ${consolidated.totals.totalRedemptions.toFixed(2)}
• Saldo líquido: R$ ${consolidated.totals.netInvested.toFixed(2)}

🏦 *Saldo atual nas caixinhas:*
R$ ${consolidated.totalBalance.toFixed(2)}
━━━━━━━━━━━━━━━━━━━━
_Atualizado em: ${moment().format('DD/MM/YYYY HH:mm:ss')}_
      `;
      
      for (const chatId of TG_CHAT_IDS) {
        try {
          await bot.telegram.sendMessage(chatId, mensagemTelegram, { parse_mode: 'Markdown' });
        } catch (err) {
          console.error(`❌ Erro ao notificar Telegram ${chatId}:`, err.message);
        }
      }
    }
    
    return {
      success: true,
      saved,
      duplicates,
      errors,
      totals: consolidated.totals,
      totalBalance: consolidated.totalBalance
    };
    
  } catch (error) {
    console.error('❌ Erro ao salvar investimentos:', error);
    return { success: false, error: error.message };
  }
}

// 6. Função para calcular resumo dos investimentos do banco de dados
function getInvestmentSummaryFromDB(user) {
  try {
    const ledgerUser = normalizeLedgerUsername(user);
    const userFilter = buildUserWhere('transactions', ledgerUser, 'user');
    // Busca todas as transações de investimento
    const investments = db.prepare(`
      SELECT 
        id,
        transaction_id,
        description,
        amount,
        type,
        category,
        payment_method,
        date,
        user_name,
        substr(payment_method, 7) as account_name
      FROM transactions 
      WHERE ${userFilter.clause}
        AND category = 'Investimentos'
      ORDER BY date DESC
    `).all(...userFilter.params);
    
    // Calcula totais
    let totalApplied = 0;
    let totalRedeemed = 0;
    let byAccount = {};
    
    investments.forEach(inv => {
      if (inv.type === 'expense') {
        totalApplied += inv.amount;
      } else {
//         totalRedeemed += inv.amount;
      }
      
      const account = inv.account_name || 'Outros';
      if (!byAccount[account]) {
        byAccount[account] = { applied: 0, redeemed: 0, count: 0 };
      }
      
      if (inv.type === 'expense') {
        byAccount[account].applied += inv.amount;
      } else {
        byAccount[account].redeemed += inv.amount;
      }
      byAccount[account].count++;
    });
    
    const netInvested = totalApplied - totalRedeemed;
    
    return {
      success: true,
      totalTransactions: investments.length,
      totalApplied,
      totalRedeemed,
      netInvested,
      byAccount,
      recentTransactions: investments.slice(0, 10)
    };
    
  } catch (error) {
    console.error('❌ Erro ao buscar resumo de investimentos:', error);
    return { success: false, error: error.message };
  }
}

// 7. Endpoint para consultar investimentos consolidados
app.get('/api/investimentos/consolidado', requireAuth, async (req, res) => {
  try {
    const { from, to, sync } = req.query;
    const user = req.session.user.username;
    
    // Se sync=true, busca dados atualizados da API
    if (sync === 'true') {
      console.log('🔄 Sincronizando investimentos com a API Neon...');
      
      const result = await saveInvestmentTransactions(user);
      
      if (result.success) {
        const summary = getInvestmentSummaryFromDB(user);
        
        res.json({
          success: true,
          message: 'Investimentos sincronizados com sucesso!',
          sync: result,
          summary: summary.success ? summary : null,
          timestamp: moment().toISOString()
        });
      } else {
        res.status(500).json(result);
      }
      return;
    }
    
    // Se não sync, retorna dados do banco
    const summary = getInvestmentSummaryFromDB(user);
    
    if (summary.success) {
      // Formata para exibição
      const formatCurrency = formatBRL;
      
      res.json({
        success: true,
        data: {
          totals: {
            totalTransactions: summary.totalTransactions,
            totalApplied: formatCurrency(summary.totalApplied),
            totalRedeemed: formatCurrency(summary.totalRedeemed),
            netInvested: formatCurrency(summary.netInvested)
          },
          byAccount: Object.entries(summary.byAccount).map(([account, data]) => ({
            account,
            applied: formatCurrency(data.applied),
            redeemed: formatCurrency(data.redeemed),
            net: formatCurrency(data.applied - data.redeemed),
            count: data.count
          })),
          recentTransactions: summary.recentTransactions.map(t => ({
            id: t.transaction_id,
            date: moment(t.date).format('DD/MM/YYYY'),
            description: t.description,
            amount: formatCurrency(t.amount),
            type: t.type === 'income' ? 'Resgate' : 'Aplicação',
            account: t.payment_method
          }))
        }
      });
    } else {
      res.status(500).json(summary);
    }
    
  } catch (error) {
    console.error('❌ Erro na rota de investimentos:', error);
    res.status(500).json({ 
      success: false, 
      error: 'Erro ao consultar investimentos' 
    });
  }
});

// 8. Endpoint para sincronizar investimentos manualmente
app.post('/api/investimentos/sincronizar', requireAuth, async (req, res) => {
  try {
    const user = req.session.user.username;
    
    // Apenas admin pode forçar sincronização
    if (req.session.user.role !== 'admin') {
      return res.status(403).json({ 
        success: false, 
        error: 'Apenas administradores podem sincronizar manualmente' 
      });
    }
    
    console.log(`🔄 Sincronização manual de investimentos solicitada por ${user}`);
    
    const result = await saveInvestmentTransactions(user);
    
    if (result.success) {
      res.json({
        success: true,
        message: 'Investimentos sincronizados com sucesso!',
        data: result,
        timestamp: moment().toISOString()
      });
    } else {
      res.status(500).json(result);
    }
    
  } catch (error) {
    console.error('❌ Erro na sincronização:', error);
    res.status(500).json({ 
      success: false, 
      error: 'Erro ao sincronizar investimentos' 
    });
  }
});

