// ============== ROTAS DO CICLO MENSTRUAL ==============
// O ciclo é da User2: quando um admin (User1) usa a página /menstrual, lê e grava no usuário
// dela — antes gravava no próprio admin, que os crons ignoram, e nenhum aviso saía.
const CICLO_USER_ID = Number(process.env.CICLO_USER_ID || 2);
function cicloUserId(req) {
  const u = req.session.user;
  return u.role === 'admin' ? CICLO_USER_ID : u.id;
}
app.get('/api/ciclo', requireAuth, (req, res) => {
  try {
    const userId = cicloUserId(req);
    const cycles = db.prepare(`SELECT id, start_date, duration, created_at FROM menstrual_cycles WHERE user_id = ? ORDER BY start_date DESC`).all(userId);
    res.json({ success: true, cycles });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

app.post('/api/ciclo', requireAuth, (req, res) => {
  try {
    const { startDate, duration } = req.body;
    if (!startDate || !duration || duration < 1) {
      return res.status(400).json({ success: false, error: 'Dados inválidos' });
    }
    const userId = cicloUserId(req);
    db.prepare(`INSERT INTO menstrual_cycles (user_id, start_date, duration) VALUES (?, ?, ?)`).run(userId, startDate, duration);
    res.json({ success: true });
  } catch (error) {
    res.status(400).json({ success: false, error: error.message });
  }
});

function deleteAllMenstrualCycles(req, res) {
  try {
    const userId = cicloUserId(req);
    const result = db.prepare(`DELETE FROM menstrual_cycles WHERE user_id = ?`).run(userId);
    res.json({
      success: true,
      deletedCount: Number(result && typeof result.changes !== 'undefined' ? result.changes : 0)
    });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
}

app.delete('/api/ciclo', requireAuth, deleteAllMenstrualCycles);
app.post('/api/ciclo/limpar', requireAuth, deleteAllMenstrualCycles);
app.post('/api/ciclo/clear', requireAuth, deleteAllMenstrualCycles);

app.delete('/api/ciclo/:id', requireAuth, (req, res) => {
  try {
    const userId = cicloUserId(req);
    const id = req.params.id;
    const result = db.prepare(`DELETE FROM menstrual_cycles WHERE id = ? AND user_id = ?`).run(id, userId);
    if (result.changes > 0) {
      res.json({ success: true });
    } else {
      res.status(404).json({ success: false, error: 'Não encontrado' });
    }
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

