bot.command('testarciclo', async (ctx) => {
  if (!checkTelegramPermission(ctx)) return ctx.reply('🚫 Sem permissão.');

  try {
    const telegramId = String(ctx.from.id || '');
    const adminUser = db.prepare(`
      SELECT id, name, role
      FROM users
      WHERE telegram_id = ?
      LIMIT 1
    `).get(telegramId);

    if (!adminUser || adminUser.role !== 'admin') {
      return ctx.reply('🚫 Apenas administradores podem usar este comando.');
    }

    const args = String(ctx.message?.text || '').trim().split(/\s+/).slice(1);
    if (args.length === 0) {
      return replyWithMarkdownSafe(ctx, [
        '🧪 *Comando de teste do ciclo*',
        '',
        'Use um dos formatos:',
        '`/testarciclo status USER_ID`',
        '`/testarciclo lembrete USER_ID [dias]`',
        '`/testarciclo inicio USER_ID`',
        '`/testarciclo ativartracking USER_ID [dias]`',
        '`/testarciclo tracking USER_ID`',
        '`/testarciclo resettracking USER_ID`'
      ].join('\n'));
    }

    const action = String(args[0] || '').toLowerCase();
    const targetUserId = Number(args[1]);
    if (!Number.isFinite(targetUserId) || targetUserId <= 0) {
      return ctx.reply('❌ Informe um `USER_ID` válido. Exemplo: /testarciclo status 2', { parse_mode: 'Markdown' });
    }

    const targetUser = db.prepare(`
      SELECT id, name, telegram_id, whatsapp, role
      FROM users
      WHERE id = ?
      LIMIT 1
    `).get(targetUserId);

    if (!targetUser) {
      return ctx.reply(`❌ Usuária com ID ${targetUserId} não encontrada.`);
    }

    if (action === 'status') {
      const tracking = getMenstrualTracking(targetUserId);
      const nextPeriod = getNextPeriodPrediction(targetUserId);
      const fertileWindow = getFertileWindow(targetUserId);
      const totalCycles = db.prepare(`SELECT COUNT(*) AS total FROM menstrual_cycles WHERE user_id = ?`).get(targetUserId)?.total || 0;

      return replyWithMarkdownSafe(ctx, [
        `🩺 *Status do ciclo: ${targetUser.name || `Usuária ${targetUserId}`}*`,
        '',
        `• ID: ${targetUserId}`,
        `• Telegram: ${targetUser.telegram_id ? 'vinculado' : 'não vinculado'}`,
        `• WhatsApp: ${targetUser.whatsapp ? 'vinculado' : 'não vinculado'}`,
        `• Total de ciclos: ${totalCycles}`,
        `• Próximo período: ${nextPeriod ? formatDate(nextPeriod) : '—'}`,
        `• Janela fértil: ${fertileWindow ? `${formatDate(fertileWindow.start)} a ${formatDate(fertileWindow.end)}` : '—'}`,
        `• Tracking: ${tracking ? `${tracking.status} | início ${tracking.cycle_start_date || '—'} | dias ${tracking.days_count || 0} | última pergunta ${tracking.last_asked_date || '—'}` : 'inexistente'}`
      ].join('\n'));
    }

    if (action === 'lembrete') {
      const daysUntil = Number.isFinite(Number(args[2])) ? Math.max(0, Number(args[2])) : 2;
      const sent = await sendMenstrualReminder(targetUserId, daysUntil);
      return ctx.reply(sent
        ? `✅ Lembrete manual enviado para ${targetUser.name || `usuária ${targetUserId}`} (${daysUntil} dia(s)).`
        : `❌ Não foi possível enviar o lembrete para ${targetUser.name || `usuária ${targetUserId}`}.`);
    }

    if (action === 'inicio') {
      const sent = await sendStartConfirmation(targetUserId);
      return ctx.reply(sent
        ? `✅ Pergunta de início enviada para ${targetUser.name || `usuária ${targetUserId}`}.`
        : `❌ Não foi possível enviar a pergunta de início. Verifique se a usuária possui Telegram vinculado.`);
    }

    if (action === 'ativartracking') {
      const daysCount = Number.isFinite(Number(args[2])) ? Math.max(1, Number(args[2])) : 1;
      const cycleStartDate = moment().subtract(daysCount - 1, 'days').format('YYYY-MM-DD');

      db.prepare(`
        INSERT INTO menstrual_cycles (user_id, start_date, duration)
        VALUES (?, ?, ?)
        ON CONFLICT(user_id, start_date) DO UPDATE SET
          duration = CASE
            WHEN excluded.duration > duration THEN excluded.duration
            ELSE duration
          END
      `).run(targetUserId, cycleStartDate, daysCount);

      upsertMenstrualTracking(targetUserId, {
        status: 'tracking',
        cycle_start_date: cycleStartDate,
        days_count: daysCount,
        last_asked_date: null
      });

      return ctx.reply(`✅ Tracking ativado para ${targetUser.name || `usuária ${targetUserId}`} com ${daysCount} dia(s), início em ${formatDate(cycleStartDate)}.`);
    }

    if (action === 'tracking') {
      const tracking = getMenstrualTracking(targetUserId);
      if (!tracking || tracking.status !== 'tracking') {
        return ctx.reply('❌ Não há tracking ativo para essa usuária. Use `/testarciclo ativartracking USER_ID [dias]` primeiro.', { parse_mode: 'Markdown' });
      }

      const sent = await sendTrackingQuestion(targetUserId);
      return ctx.reply(sent
        ? `✅ Pergunta de acompanhamento enviada para ${targetUser.name || `usuária ${targetUserId}`}.`
        : `❌ Não foi possível enviar a pergunta de acompanhamento. Verifique se a usuária possui Telegram vinculado.`);
    }

    if (action === 'resettracking') {
      const ok = resetMenstrualTracking(targetUserId);
      return ctx.reply(ok
        ? `✅ Tracking removido para ${targetUser.name || `usuária ${targetUserId}`}.`
        : `❌ Não foi possível remover o tracking dessa usuária.`);
    }

    return ctx.reply('❌ Ação inválida. Use: status, lembrete, inicio, ativartracking, tracking ou resettracking.');
  } catch (e) {
    console.error('Erro no comando /testarciclo:', e.message);
    return ctx.reply(`❌ Erro ao executar teste do ciclo: ${e.message}`);
  }
});
// ========== RADARR: LANÇAMENTOS DIGITAIS ==========
const ical = require('node-ical');   // 👈 Instale com: npm install node-ical
const RADARR_FEED_URL = 'http://localhost:7878/feed/v3/calendar/Radarr.ics?apikey=10beec39eed44c3d9899191a2a7726b3';
const RADARR_STATE_FILE = path.join(__dirname, 'radarr_digital_state.json');

async function checkDigitalReleases() {
  try {
    const events = await ical.async.fromURL(RADARR_FEED_URL);
    const today = moment().tz('America/Sao_Paulo').startOf('day');

    let state = {};
    if (fs.existsSync(RADARR_STATE_FILE)) {
      state = JSON.parse(fs.readFileSync(RADARR_STATE_FILE, 'utf8'));
    }

    let notificados = 0;

    for (const [uid, event] of Object.entries(events)) {
      if (event.type !== 'VEVENT') continue;

      const start = moment(event.start);
      if (!start.isSame(today, 'day')) continue;

      const summary = event.summary || '';
      // Ajuste o filtro conforme o padrão do seu Radarr
      if (!summary.toLowerCase().includes('digital')) continue;

      if (state[uid]) continue;

      const match = summary.match(/^(.*?)\s*\((\d{4})\)/);
      const title = match ? match[1].trim() : summary.replace(/\s*-\s*Digital$/i, '').trim();
      const year = match ? match[2] : '';

      let message = `🎬 *${title}*`;
      if (year) message += ` (${year})`;
      message += `\n📅 Lançamento digital hoje!`;

      let imageBuffer = null;
      if (process.env.TMDB_API_KEY && title) {
        try {
          const searchUrl = `https://api.themoviedb.org/3/search/movie?api_key=${process.env.TMDB_API_KEY}&query=${encodeURIComponent(title)}&year=${year}`;
          const resp = await fetch(searchUrl);
          const data = await resp.json();
          if (data.results && data.results.length > 0) {
            const posterPath = data.results[0].poster_path;
            if (posterPath) {
              const imgResp = await fetch(`https://image.tmdb.org/t/p/w500${posterPath}`);
              if (imgResp.ok) imageBuffer = Buffer.from(await imgResp.arrayBuffer());
            }
          }
        } catch (e) { /* fallback */ }
      }

      // Usa a função de notificação já existente (Telegram + WhatsApp)
      await notificarTelegram({
        description: message,
        amount: 0,
        type: 'expense',
        category: 'Radarr',
        paymentMethod: 'Digital Release',
        date: moment().format('YYYY-MM-DD'),
        user: 'sistema',
        userName: 'Radarr'
      }, imageBuffer);

      state[uid] = { notifiedAt: moment().toISOString() };
      notificados++;
    }

    if (notificados > 0) {
      fs.writeFileSync(RADARR_STATE_FILE, JSON.stringify(state, null, 2));
      console.log(`✅ ${notificados} lançamento(s) digital(is) notificado(s).`);
    }
  } catch (error) {
    console.error('❌ Erro ao verificar lançamentos digitais:', error);
  }
}

