// ========== CRON: Verificação diária de lembretes (8:00) ==========
agendar('0 8 * * *', 'Lembretes do ciclo menstrual', async () => {
  console.log('⏰ [Cron] Verificando lembretes de ciclo menstrual (8:00)');
  try {
    const users = db.prepare(`
      SELECT id, name, telegram_id, whatsapp
      FROM users
      WHERE (role IS NULL OR role != 'admin') AND (telegram_id IS NOT NULL OR whatsapp IS NOT NULL)
    `).all();

    const today = moment().startOf('day');
    for (const user of users) {
      const nextPeriodStr = getNextPeriodPrediction(user.id);
      if (!nextPeriodStr) continue;

      const daysUntil = moment(nextPeriodStr, 'YYYY-MM-DD').diff(today, 'days');
      if (daysUntil === 2) {
        await sendMenstrualReminder(user.id, daysUntil);
      }
    }
  } catch (e) {
    console.error('Erro no cron de lembretes:', e.message);
  }
}, { timezone: 'America/Sao_Paulo' });

// ========== CRON: Avisos de período fértil (7:30) ==========
agendar('30 7 * * *', 'Avisos de período fértil', async () => {
  console.log('⏰ [Cron] Verificando avisos de período fértil (7:30)');
  try {
    const users = db.prepare(`
      SELECT id, name, telegram_id, whatsapp
      FROM users
      WHERE (role IS NULL OR role != 'admin') AND (telegram_id IS NOT NULL OR whatsapp IS NOT NULL)
    `).all();

    const today = moment().startOf('day');
    for (const user of users) {
      const fertileWindow = getFertileWindow(user.id);
      if (!fertileWindow || !fertileWindow.start) continue;

      const diffStart = moment(fertileWindow.start, 'YYYY-MM-DD').diff(today, 'days');
      if (diffStart === 1) {
        await sendFertileWindowReminder(user.id, 'before');
      } else if (diffStart === -1) {
        await sendFertileWindowReminder(user.id, 'after');
      }
    }
  } catch (e) {
    console.error('Erro no cron de período fértil:', e.message);
  }
}, { timezone: 'America/Sao_Paulo' });

// ========== CRON: Verificação de início do período (9:00) ==========
agendar('0 9 * * *', 'Verificação de início do período', async () => {
  console.log('⏰ [Cron] Verificando início de período (9:00)');
  try {
    const users = db.prepare(`
      SELECT id, name, telegram_id
      FROM users
      WHERE (role IS NULL OR role != 'admin') AND telegram_id IS NOT NULL
    `).all();

    const today = moment().startOf('day');
    const todayStr = today.format('YYYY-MM-DD');

    for (const user of users) {
      const nextPeriodStr = getNextPeriodPrediction(user.id);
      if (!nextPeriodStr) continue;

      const diffDays = today.diff(moment(nextPeriodStr, 'YYYY-MM-DD'), 'days');
      const tracking = getMenstrualTracking(user.id);

      if (tracking) {
        if (tracking.status === 'tracking') continue;
        if (tracking.status === 'waiting_confirmation' && tracking.last_asked_date === todayStr) continue;
      }

      if (diffDays >= 0 && diffDays <= 1) {
        await sendStartConfirmation(user.id);
      }
    }
  } catch (e) {
    console.error('Erro no cron de início:', e.message);
  }
}, { timezone: 'America/Sao_Paulo' });

// ========== CRON: Acompanhamento diário do período (10:00) ==========
agendar('0 10 * * *', 'Acompanhamento diário do período', async () => {
  console.log('⏰ [Cron] Acompanhamento diário do período (10:00)');
  try {
    const trackings = db.prepare(`
      SELECT user_id, days_count, last_asked_date
      FROM menstrual_tracking
      WHERE status = 'tracking'
    `).all();

    const today = moment().format('YYYY-MM-DD');
    for (const tracking of trackings) {
      if (tracking.last_asked_date === today) continue;

      const user = db.prepare(`
        SELECT id, telegram_id
        FROM users
        WHERE id = ? AND telegram_id IS NOT NULL
      `).get(tracking.user_id);

      if (!user) continue;
      await sendTrackingQuestion(tracking.user_id);
    }
  } catch (e) {
    console.error('Erro no cron de acompanhamento:', e.message);
  }
}, { timezone: 'America/Sao_Paulo' });

