// ============== WEBHOOK PLUGGY UNIFICADO - CORRIGIDO ==============
// Só aceita notificações das nossas duas aplicações Pluggy (Sicredi/Neon e Mercado Pago - Magazine).
// Sem essa checagem, qualquer um que descubra a URL pública poderia disparar processamento falso.
// 401 não gera retentativa na Pluggy, então notificações de outras contas são descartadas sem ruído.
const CLIENT_IDS_PLUGGY_VALIDOS = new Set([PLUGGY_CLIENT_ID, PLUGGY_MP_CLIENT_ID].filter(Boolean));
app.post('/api/pluggy-webhook', async (req, res) => {
  if (!CLIENT_IDS_PLUGGY_VALIDOS.has(req.body?.clientId)) {
    console.log(`🚫 Webhook Pluggy rejeitado: clientId desconhecido (${req.body?.clientId || 'ausente'})`);
    return res.status(401).json({ error: 'clientId desconhecido' });
  }
  console.log('\n🔔 ===== WEBHOOK PLUGGY RECEBIDO =====');
  console.log(`📅 Hora: ${moment().format('DD/MM/YYYY HH:mm:ss')}`);
  console.log(`🎯 Evento: ${req.body?.event || 'Desconhecido'}`);
  console.log(`📦 Body recebido:`, JSON.stringify(req.body, null, 2));
  
  // Responde IMEDIATAMENTE (200 OK) para evitar retentativas
  res.status(200).json({ 
    received: true, 
    timestamp: moment().toISOString(),
    server: PUBLIC_URL
  });
  
  // Processa em segundo plano
  setTimeout(async () => {
    try {
      const { event, itemId } = req.body;
      
      // ========== ROTEAMENTO CORRETO ==========
      if (itemId === SICREDI_ITEM_ID) {
        console.log('🏦 Processando webhook do SICREDI...');
        await processPluggyWebhook(req.body);
      } 
      else if (itemId === NEON_ITEM_ID) {
        console.log('💳 Processando webhook do NEON...');
        await processNeonWebhook(req.body);
      } 
      else if (itemId === MP_MAGAZINE_ITEM_ID) {
        console.log('🟦 Processando webhook do MERCADO PAGO - MAGAZINE...');
        await processMercadoPagoMagazineWebhook(req.body);
      }
      else if (itemId === CAIXA_ITEM_ID) {
        console.log('🏛️ Processando webhook da CAIXA...');
        await processCaixaWebhook(req.body);
      }
      else {
        console.log(`⚠️ Item desconhecido: ${itemId}`);
      }
      
    } catch (error) {
      console.error('❌ Erro no processamento do webhook:', error);
    }
  }, 100);
});
// 2. FUNÇÃO DE NOTIFICAÇÃO (Markdown V1 fix)
async function renotificarTransacaoFaltante(transacao, banco, accountType) {
  try {
    const tipo = transacao.type === 'CREDIT' ? 'income' : 'expense';
    const tipoEmoji = transacao.type === 'CREDIT' ? '💰' : '💸';
    const tipoTexto = transacao.type === 'CREDIT' ? 'RECEITA' : 'DESPESA';
    const valor = Math.abs(transacao.amount);
    
    const dataOriginal = moment(transacao.date).format('DD/MM/YYYY');
    const agora = moment().format('DD/MM/YYYY HH:mm:ss');
    
    // Escapar caracteres especiais se usar MarkdownV2, 
    // mas aqui manteremos Markdown simples para compatibilidade
    const mensagem = [
      `🔄 *TRANSAÇÃO RESTAURADA*`,
      `━━━━━━━━━━━━━━━━━━━━`,
      `🏦 *Banco:* ${banco} - ${accountType}`,
      `📋 *Descrição:* ${transacao.description || 'Sem descrição'}`,
      `💰 *Valor:* R$ ${valor.toFixed(2)}`,
      `${tipoEmoji} *Tipo:* ${tipoTexto}`,
      `📅 *Data original:* ${dataOriginal}`,
      `━━━━━━━━━━━━━━━━━━━━`,
      `🆔 *ID:* ${transacao.id}`,
      `⏰ *Reenviado em:* ${agora}`
    ].join('\n');
    
    const envios = TG_CHAT_IDS.map(chatId => 
      bot.telegram.sendMessage(chatId, mensagem, {
        parse_mode: 'Markdown',
        reply_markup: {
          inline_keyboard: [[
            { text: '🔍 Dashboard', url: PUBLIC_URL },
            { text: '✅ OK', callback_data: 'dismiss_notification' }
          ]]
        }
      }).catch(err => console.error(`Erro chat ${chatId}:`, err.message))
    );
    
    await Promise.all(envios);

    // Log no DB
    db.prepare(`
      INSERT INTO chat_logs (user, question, answer, context, created_at) 
      VALUES (?, ?, ?, ?, ?)
    `).run(
      'sistema',
      'TRANSACAO_RESTAURADA',
      `Restaurada: ${transacao.id}`,
      JSON.stringify({ id: transacao.id, valor, banco }),
      moment().toISOString()
    );
    
    return { success: true };
  } catch (error) {
    console.error('❌ Erro renotificar:', error);
    return { success: false };
  }
}
