// ============== CORRIGIR URL DO WEBHOOK NEON ==============
app.post('/api/neon/corrigir-webhook-url', requireAuth, async (req, res) => {
  try {
    if (req.session.user.role !== 'admin') {
      return res.status(403).json({ success: false, error: 'Apenas admin' });
    }
    
    const apiKey = await getPluggyApiKey();
    
    // URL CORRETA (sem barra dupla)
    const urlCorreta = PUBLIC_URL.endsWith('/') 
      ? `${PUBLIC_URL.slice(0, -1)}/api/pluggy-webhook` 
      : `${PUBLIC_URL}/api/pluggy-webhook`;
    
    console.log(`🔧 Corrigindo webhook Neon para: ${urlCorreta}`);
    
    // Atualizar webhook do Neon
    const neonResponse = await axios.patch(
      `${PLUGGY_API_URL}/items/${NEON_ITEM_ID}`,
      { webhookUrl: urlCorreta },
      { headers: { 'X-API-KEY': apiKey } }
    );
    
    console.log('✅ Webhook Neon corrigido:', neonResponse.data.webhookUrl);
    
    // Atualizar webhook do Sicredi também
    const sicrediResponse = await axios.patch(
      `${PLUGGY_API_URL}/items/${SICREDI_ITEM_ID}`,
      { webhookUrl: urlCorreta },
      { headers: { 'X-API-KEY': apiKey } }
    );
    
    console.log('✅ Webhook Sicredi corrigido:', sicrediResponse.data.webhookUrl);
    
    res.json({
      success: true,
      message: 'URLs dos webhooks corrigidas!',
      webhookUrl: urlCorreta,
      neon: neonResponse.data.webhookUrl,
      sicredi: sicrediResponse.data.webhookUrl
    });
    
  } catch (error) {
    console.error('❌ Erro:', error.response?.data || error.message);
    res.status(500).json({ 
      success: false, 
      error: error.response?.data || error.message 
    });
  }
});
