const formatarMoeda = formatBRL;

const formatarData = (data) => {
    return moment(data).format('DD/MM/YYYY HH:mm:ss');
};

// Gera o template de texto para os saldos
async function buildSaldosMessage(tituloTopo) {
  const [sicrediSaldo, sicrediPoupancaSaldo, neonSaldo, mpSaldo, caixaSaldo, caixaPoupancaSaldo] = await Promise.all([
    getSicrediBalance(),
    getSicrediPoupancaBalance(),
    getNeonBalance(),
    getMercadoPagoMagazineBalance(),
    getCaixaBalance(),
    getCaixaPoupancaBalance()
  ]);

  let mensagem = `${tituloTopo}\n`;
  mensagem += `━━━━━━━━━━━━━━━━━━━━\n\n`;
  mensagem += gerarMensagemSaldo('🏦 *SICREDI*', sicrediSaldo);
  mensagem += gerarMensagemSaldo('🏦 *SICREDI*', sicrediPoupancaSaldo);
  mensagem += gerarMensagemSaldo('💳 *NEON*', neonSaldo);
  mensagem += gerarMensagemSaldo(`🟦 *${MP_MAGAZINE_NOME.toUpperCase()}*`, mpSaldo);
  mensagem += gerarMensagemSaldo('🏛️ *CAIXA*', caixaSaldo);
  mensagem += gerarMensagemSaldo('🏛️ *CAIXA*', caixaPoupancaSaldo);

  // Item 8: total consolidado — só soma o que respondeu com sucesso.
  const todos = [sicrediSaldo, sicrediPoupancaSaldo, neonSaldo, mpSaldo, caixaSaldo, caixaPoupancaSaldo];
  const comFalha = todos.filter(s => !s.success).length;
  const total = todos.filter(s => s.success).reduce((acc, s) => acc + Number(s.balance || 0), 0);

  mensagem += `━━━━━━━━━━━━━━━━━━━━\n`;
  mensagem += `💰 *TOTAL CONSOLIDADO: ${formatarMoeda(total)}*\n`;
  if (comFalha > 0) mensagem += `⚠️ ${comFalha} conta(s) não respondeu(ram) e não entra(m) no total\n`;
  mensagem += `━━━━━━━━━━━━━━━━━━━━\n`;
  mensagem += `_Consulta: ${moment().format('DD/MM/YYYY HH:mm:ss')}_`;

  return { mensagem, total, comFalha };
}

const gerarMensagemSaldo = (titulo, saldo) => {
    if (!saldo.success) return `${titulo}\n❌ Erro ao consultar\n\n`;

    const tipo = saldo.subtype === 'SAVINGS_ACCOUNT' ? 'Poupança' : 'Conta Corrente';
    return [
        `${titulo} - ${tipo}`,
        `💵 Saldo: \`${formatarMoeda(saldo.balance)}\``,
        `📅 Atualizado: ${formatarData(saldo.updatedAt)}`,
        ''
    ].join('\n');
};
