// Comando para ver status do monitoramento
bot.command('statusmonitor', async (ctx) => {
    if (!checkTelegramPermission(ctx)) return;
    
    try {
        const stats = db.prepare(`
            SELECT 
                COUNT(*) as total_notificadas,
                COUNT(DISTINCT bank) as bancos,
                MIN(notified_at) as primeira,
                MAX(notified_at) as ultima
            FROM transaction_notifications 
            WHERE notified_at > datetime('now', '-1 day')
            AND transaction_id NOT LIKE 'erro_%'
        `).get();
        
        const ultimas = db.prepare(`
            SELECT bank, amount, description, notified_at 
            FROM transaction_notifications 
            WHERE transaction_id NOT LIKE 'erro_%'
            ORDER BY notified_at DESC 
            LIMIT 5
        `).all();
        
        const ultimaExecucao = ultimaVerificacao ? 
            moment(ultimaVerificacao).format('DD/MM/YYYY HH:mm:ss') : 
            'Ainda não executado';
        
        let mensagem = `📊 <b>STATUS DO MONITORAMENTO</b>\n\n`;
        mensagem += `⏱️ <b>Intervalo:</b> 1 minuto\n`;
        mensagem += `🕒 <b>Última execução:</b> ${ultimaExecucao}\n`;
        mensagem += `📅 <b>Últimas 24h:</b> ${stats.total_notificadas || 0} transações\n`;
        mensagem += `🏦 <b>Bancos monitorados:</b> ${stats.bancos || 0}\n\n`;
        
        if (ultimas.length > 0) {
            mensagem += `📋 <b>Últimas notificações:</b>\n`;
            ultimas.forEach((t, i) => {
                const valor = formatBRL(t.amount);
                const data = moment(t.notified_at).format('HH:mm:ss');
                // Escapamos a descrição para evitar que caracteres como "<" ou "&" quebrem o HTML
                const desc = escapeHtml(t.description || 'Sem descrição');
                mensagem += `${i+1}. ${t.bank} - <b>${valor}</b> (${data})\n`;
            });
        }
        
        await ctx.replyWithHTML(mensagem);
        
    } catch (error) {
        console.error('Erro no status:', error);
        ctx.reply('❌ Erro ao buscar status do monitoramento');
    }
});
