// 4. COMANDO VERIFICAR (Ajuste de lógica de data)
bot.command('verificarfaltantes', async (ctx) => {
  try {
    await ctx.reply('🔍 Verificando últimos 7 dias...');
    
    const apiKey = await getPluggyApiKey();
    const apiKeySicredi = await getSicrediApiKey();
    const hoje = moment().toISOString();
    const seteDiasAtras = moment().subtract(7, 'days').toISOString();
    
    // Busca paralela
    const [sicrediRes, neonRes] = await Promise.all([
      axios.get(`${PLUGGY_API_URL}/transactions`, {
        params: { accountId: SICREDI_ACCOUNT_ID, from: seteDiasAtras, to: hoje, pageSize: 100 },
        headers: { 'X-API-KEY': apiKeySicredi }
      }),
      axios.get(`${PLUGGY_API_URL}/transactions`, {
        params: { accountId: NEON_ACCOUNT_ID, from: seteDiasAtras, to: hoje, pageSize: 100 },
        headers: { 'X-API-KEY': apiKey }
      })
    ]);

    let faltantes = [];
    const processarLista = (lista, bancoNome) => {
      lista.forEach(t => {
        const id = `pluggy_${bancoNome.toLowerCase()}_${t.id}`;
        const ex = db.prepare('SELECT transaction_id FROM transactions WHERE transaction_id = ?').get(id);
        if (!ex) {
          faltantes.push({ ...t, banco: bancoNome, nossoId: id });
        }
      });
    };

    processarLista(sicrediRes.data.results || [], 'Sicredi');
    processarLista(neonRes.data.results || [], 'Neon');

    if (faltantes.length === 0) {
      return ctx.reply('✅ Tudo em dia!');
    }

    // Armazenar na sessão (Certifique-se que o middleware de session está ativo)
    ctx.session = ctx.session || {};
    ctx.session.transacoesFaltantes = faltantes;

    let txt = `🚨 *FALTANTES: ${faltantes.length}*\n\n`;
    faltantes.slice(0, 5).forEach((t, i) => {
      txt += `${i+1}. ${t.banco}: R$ ${Math.abs(t.amount).toFixed(2)} - ${t.description}\n`;
    });

    await ctx.reply(txt, {
      parse_mode: 'Markdown',
      reply_markup: {
        inline_keyboard: [
          [{ text: '🔄 RESTAURAR TODAS', callback_data: 'restaurar_todas' }],
          [{ text: '❌ Cancelar', callback_data: 'cancelar_verificacao' }]
        ]
      }
    });
    
  } catch (e) {
    console.error(e);
    ctx.reply('❌ Erro na verificação.');
  }
});
// ============== FUNÇÕES DE PROCESSAMENTO DE IMAGEM ==============
async function processCroppedImage(base64Image, cropData) {
  try {
    const base64Data = base64Image.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");
    const buffer = Buffer.from(base64Data, 'base64');
    
    let image = sharp(buffer);
    
    if (cropData && cropData.width > 0 && cropData.height > 0) {
      try {
        const metadata = await image.metadata();
        image = image.extract({
          left: Math.max(0, Math.round(cropData.x || 0)),
          top: Math.max(0, Math.round(cropData.y || 0)),
          width: Math.min(Math.round(cropData.width), metadata.width || 1000),
          height: Math.min(Math.round(cropData.height), metadata.height || 1000)
        });
      } catch (cropError) {
        console.warn('⚠️ Erro no crop, usando imagem original:', cropError.message);
      }
    }
    
    const processedBuffer = await image
      .jpeg({ quality: 80 })
      .toBuffer();
    
    return processedBuffer;
  } catch (error) {
    console.error('❌ Erro ao processar imagem:', error);
    try {
      const base64Data = base64Image.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");
      return Buffer.from(base64Data, 'base64');
    } catch (fallbackError) {
      return null;
    }
  }
}

async function saveReceiptFile(fileBuffer, originalName, fileType) {
  try {
    const extension = fileType === 'pdf' ? 'pdf' : 'jpg';
    const fileName = `receipt_${Date.now()}_${Math.random().toString(36).substr(2, 5)}.${extension}`;
    const filePath = path.join(RECEIPTS_DIR, fileName);

    if (fileType !== 'pdf') {
      await sharp(fileBuffer)
        .jpeg({ quality: 80 })
        .toFile(filePath);
    } else {
      fs.writeFileSync(filePath, fileBuffer);
    }
    
    console.log(`📁 Arquivo salvo: ${fileName} (${fileType})`);
    return fileName;
  } catch (error) {
    console.error('❌ Erro ao salvar arquivo:', error);
    return null;
  }
}

