async function sendGasolinaAlert(user) {
    try {
        const alert = checkGasolinaAlert(user);
        const nome = user === 'user1' ? 'User1' : 'User2';
        
        console.log(`🚨 Verificando alerta de gasolina para ${nome} (${user}): R$ ${alert.total.toFixed(2)}`);
        
        // ALERTA DETECTADO? (true se >= 640)
        if (alert.alert) {
            console.log(`⚠️ ALERTA DETECTADO para ${nome}! Valor: R$ ${alert.total.toFixed(2)}`);
            
            const envios = TG_CHAT_IDS.map(async (chatId) => {
                try {
                    await bot.telegram.sendMessage(
                        chatId,
                        alert.message,
                        { 
                            parse_mode: 'Markdown',
                            disable_notification: false
                        }
                    );
                    console.log(`✅ Alerta de gasolina enviado para ${chatId} - ${nome}`);
                    return true;
                } catch (err) {
                    console.error(`❌ Erro ao enviar alerta para ${chatId}:`, err.message);
                    return false;
                }
            });

            await Promise.all(envios);
            
            return {
                success: true,
                sent: true,
                alert: true,
                total: alert.total,
                message: alert.message,
                user: nome
            };
        }
        
        console.log(`ℹ️ Sem alerta para ${nome}: R$ ${alert.total.toFixed(2)}`);
        return {
            success: true,
            sent: false,
            alert: false,
            total: alert.total,
            user: nome
        };
        
    } catch (error) {
        console.error('❌ Erro ao enviar alerta de gasolina:', error);
        return {
            success: false,
            error: error.message
        };
    }
}

