async function sendBeneficiosResumoParaTodos() {
  const saldos = getCardBalances('user1');
  if (!saldos || !saldos.success) {
    const msg = '❌ Não foi possível consultar os benefícios (Flash/Pluxee).';
    await Promise.allSettled(TG_CHAT_IDS.map((chatId) => bot.telegram.sendMessage(chatId, msg, { parse_mode: 'Markdown' })));
    await enviarWhatsAppParaTodos(msg);
    return;
  }
  const now = moment().tz('America/Sao_Paulo');
  const diaAtual = now.date();
  const ultimoDiaMes = now.clone().endOf('month').date();
  const diasRestantes = (ultimoDiaMes - diaAtual) + 1;
  const saldoFlash = Number(saldos.data?.Flash?.balance || 0);
  const saldoPluxee = Number(saldos.data?.Pluxee?.balance || 0);
  const saldoTotal = saldoFlash + saldoPluxee;
  const disponivelDia = diasRestantes > 0 ? (saldoTotal / diasRestantes) : saldoTotal;
  const fmt = formatBRL;
  const msg =
    `💳 *Benefícios (Flash + Pluxee)*\n\n` +
    `🚀 Flash: ${fmt(saldoFlash)}\n` +
    `💰 Pluxee: ${fmt(saldoPluxee)}\n` +
    `📊 *Total disponível:* ${fmt(saldoTotal)}\n\n` +
    `📅 Dias restantes no mês: ${diasRestantes}\n` +
    `🎯 Limite diário sugerido: ${fmt(disponivelDia)}`;
  await Promise.allSettled(TG_CHAT_IDS.map((chatId) => bot.telegram.sendMessage(chatId, msg, { parse_mode: 'Markdown' })));
  await enviarWhatsAppParaTodos(msg);
}

let _backupDirReady = false;
let _backupRunning = false;

function ensureBackupDir() {
  if (_backupDirReady) return BACKUP_DIR;
  const desiredDir = BACKUP_DIR;
  try {
    if (!fs.existsSync(desiredDir)) fs.mkdirSync(desiredDir, { recursive: true });
    _backupDirReady = true;
    return BACKUP_DIR;
  } catch (err) {
    const fallbackDir = path.join(DATA_DIR, 'backups');
    try {
      if (!fs.existsSync(fallbackDir)) fs.mkdirSync(fallbackDir, { recursive: true });
      BACKUP_DIR = fallbackDir;
      _backupDirReady = true;
      return BACKUP_DIR;
    } catch (e) {
      throw new Error(`Não foi possível criar diretório de backup: ${desiredDir} (fallback também falhou: ${fallbackDir})`);
    }
  }
}

async function commandExists(cmd) {
  const { exec } = require('child_process');
  return await new Promise((resolve) => {
    exec(`command -v ${cmd} >/dev/null 2>&1`, (err) => resolve(!err));
  });
}

async function createBackupArchive(tempDir, outPathWithoutExt) {
  const { exec } = require('child_process');
  const zipOk = await commandExists('zip');
  if (zipOk) {
    const zipPath = `${outPathWithoutExt}.zip`;
    // ionice -c3 (06/10): o zip de milhares de comprovantes no HD de 4 TB (SMR) só usa o disco quando ele está
    // livre — antes travava o Jellyfin por mais de meia hora. nice -n 19 pelo mesmo motivo na CPU.
    const zipCommand = `cd "${tempDir}" && ionice -c3 nice -n 19 zip -r "${zipPath}" . > /dev/null 2>&1`;
    await new Promise((resolve, reject) => {
      exec(zipCommand, (error) => (error ? reject(error) : resolve()));
    });
    return { archivePath: zipPath, archiveFile: path.basename(zipPath) };
  }

  const tarOk = await commandExists('tar');
  if (tarOk) {
    const tarPath = `${outPathWithoutExt}.tar.gz`;
    const tarCommand = `ionice -c3 nice -n 19 tar -czf "${tarPath}" -C "${tempDir}" . > /dev/null 2>&1`;
    await new Promise((resolve, reject) => {
      exec(tarCommand, (error) => (error ? reject(error) : resolve()));
    });
    return { archivePath: tarPath, archiveFile: path.basename(tarPath) };
  }

  throw new Error('Nem zip nem tar estão disponíveis no sistema para compactar o backup');
}

async function performBackup() {
  if (_backupRunning) {
    return { success: false, error: 'Backup já está em execução', backupFile: null, size: 0 };
  }
  _backupRunning = true;
  let tempDir = null;

  try {
    const backupDir = ensureBackupDir();
    const timestamp = moment().format('YYYY-MM-DD_HHmmss');
    const outBase = path.join(backupDir, `financeiro_backup_${timestamp}`);
    tempDir = path.join(backupDir, `temp_${timestamp}`);

    console.log(`\n📦 [BACKUP] Iniciando backup em ${moment().format('DD/MM/YYYY HH:mm:ss')}`);
    console.log(`📁 Destino: ${backupDir}`);

    try {
      const { exec } = require('child_process');
      const df = await new Promise((resolve) => {
        exec(`df -BG "${backupDir}"`, (err, stdout) => (err ? resolve(null) : resolve(stdout)));
      });
      if (df) {
        const lines = df.split('\n');
        const availLine = lines[1];
        if (availLine) {
          const avail = availLine.match(/(\d+)G/);
          if (avail && Number(avail[1]) < 1) console.warn('⚠️ Pouco espaço disponível no disco de backup (<1GB)');
        }
      }
    } catch (e) {}

    if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true });

    const dbDest = path.join(tempDir, 'finance.db');
    let dbBackedUp = false;
    try {
      if (db && typeof db.backup === 'function') {
        await db.backup(dbDest);
        dbBackedUp = true;
        console.log('✅ Banco de dados copiado');
      }
    } catch (err) {
      console.warn('⚠️ Falha no backup nativo, tentando cópia manual:', err.message);
    }

    if (!dbBackedUp) {
      fs.copyFileSync(DB_FILE, dbDest);
      console.log('✅ Banco de dados copiado (método manual)');
    }

    if (fs.existsSync(RECEIPTS_DIR)) {
      const receiptsFiles = fs.readdirSync(RECEIPTS_DIR).filter((f) => f !== '.' && f !== '..' && !f.startsWith('.'));
      if (receiptsFiles.length > 0) {
        const receiptsBackupDir = path.join(tempDir, 'receipts');
        fs.mkdirSync(receiptsBackupDir, { recursive: true });
        for (const file of receiptsFiles) {
          fs.copyFileSync(path.join(RECEIPTS_DIR, file), path.join(receiptsBackupDir, file));
        }
        console.log(`✅ ${receiptsFiles.length} recibos copiados`);
      } else {
        console.log('ℹ️ Nenhum recibo encontrado para backup');
      }
    }

    const { archivePath, archiveFile } = await createBackupArchive(tempDir, outBase);
    if (!fs.existsSync(archivePath)) throw new Error('Falha ao criar arquivo de backup compactado');

    const stats = fs.statSync(archivePath);
    const sizeMB = Number((stats.size / (1024 * 1024)).toFixed(2));
    console.log(`✅ Backup concluído: ${archiveFile} (${sizeMB} MB)`);

    const allBackups = fs
      .readdirSync(backupDir)
      .filter((f) => (f.startsWith('financeiro_backup_') && (f.endsWith('.zip') || f.endsWith('.tar.gz'))))
      .map((f) => ({
        name: f,
        path: path.join(backupDir, f),
        mtime: fs.statSync(path.join(backupDir, f)).mtime
      }))
      .sort((a, b) => b.mtime - a.mtime);

    const toDelete = allBackups.slice(MAX_BACKUPS);
    for (const del of toDelete) {
      try {
        fs.unlinkSync(del.path);
        console.log(`🗑️ Backup antigo removido: ${del.name}`);
      } catch (e) {
        console.warn(`⚠️ Não foi possível remover backup antigo: ${del.name}`);
      }
    }

    try {
      fs.rmSync(tempDir, { recursive: true, force: true });
    } catch (e) {}

    return {
      success: true,
      backupFile: archiveFile,
      size: sizeMB,
      fullPath: archivePath,
      keptBackups: Math.min(allBackups.length, MAX_BACKUPS),
      deletedBackups: toDelete.length
    };
  } catch (error) {
    if (error && error.code === 'ENOSPC') {
      const d = diskUsage(BACKUP_DIR);
      console.error(`❌ Erro no backup: SEM ESPAÇO em ${BACKUP_DIR}${d ? ` (${d.usedPct}% usado, ${d.freeGB.toFixed(2)} GB livres)` : ''}. Libere espaço no destino ou aponte BACKUP_DIR para outro disco.`);
    } else {
      console.error('❌ Erro no backup:', error);
    }
    try {
      if (tempDir && fs.existsSync(tempDir)) fs.rmSync(tempDir, { recursive: true, force: true });
    } catch (e) {}
    return { success: false, error: error.message, backupFile: null, size: 0 };
  } finally {
    _backupRunning = false;
  }
}

