function calcularMediaDiariaAlimentacao(user) {
  try {
    const ledgerUser = normalizeLedgerUsername(user);
    const now = moment().tz('America/Sao_Paulo');
    const currentMonth = now.format('YYYY-MM');
    const currentDay = now.date();
    const userFilter = buildUserWhere('transactions', ledgerUser, 'user');

    const alimentacaoData = db
      .prepare(
        `
        SELECT 
          COALESCE(SUM(amount), 0) as total_gasto, 
          COUNT(*) as count_transacoes
        FROM transactions 
        WHERE ${userFilter.clause}
          AND strftime('%Y-%m', date) = ? 
          AND type = 'expense' 
          AND ( 
            category = 'Alimentação' 
            OR category LIKE '%Mercado%' 
            OR category LIKE '%Supermercado%' 
            OR LOWER(description) LIKE '%ifood%' 
            OR LOWER(description) LIKE '%restaurante%' 
            OR LOWER(description) LIKE '%mercado%' 
            OR LOWER(description) LIKE '%supermercado%' 
            OR LOWER(description) LIKE '%açougue%' 
            OR LOWER(description) LIKE '%padaria%' 
          )
      `
      )
      .get(...userFilter.params, currentMonth);

    const totalGasto = Number(alimentacaoData?.total_gasto || 0);
    const mediaDiaria = currentDay > 0 ? totalGasto / currentDay : 0;
    const transacoesCount = Number(alimentacaoData?.count_transacoes || 0);

    const daysInMonth = now.daysInMonth();
    const projecaoFimMes = mediaDiaria * daysInMonth;

    const lastMonth = now.clone().subtract(1, 'month');
    const lastMonthStr = lastMonth.format('YYYY-MM');
    const lastMonthDays = lastMonth.daysInMonth();

    const lastMonthUserFilter = buildUserWhere('transactions', ledgerUser, 'user');
    const lastMonthData = db
      .prepare(
        `
        SELECT COALESCE(SUM(amount), 0) as total_gasto 
        FROM transactions 
        WHERE ${lastMonthUserFilter.clause}
          AND strftime('%Y-%m', date) = ? 
          AND type = 'expense' 
          AND ( 
            category = 'Alimentação' 
            OR category LIKE '%Mercado%' 
            OR category LIKE '%Supermercado%' 
            OR LOWER(description) LIKE '%ifood%' 
            OR LOWER(description) LIKE '%restaurante%' 
            OR LOWER(description) LIKE '%mercado%' 
          )
      `
      )
      .get(...lastMonthUserFilter.params, lastMonthStr);

    const totalGastoMesAnterior = Number(lastMonthData?.total_gasto || 0);
    const mediaDiariaMesAnterior = lastMonthDays > 0 ? totalGastoMesAnterior / lastMonthDays : 0;
    const variacaoPercentual =
      mediaDiariaMesAnterior > 0 ? ((mediaDiaria - mediaDiariaMesAnterior) / mediaDiariaMesAnterior) * 100 : 0;

    return {
      success: true,
      user: ledgerUser,
      totalGasto,
      mediaDiaria,
      transacoesCount,
      currentDay,
      daysInMonth,
      projecaoFimMes,
      mediaMesAnterior: mediaDiariaMesAnterior,
      variacaoPercentual,
      totalMesAnterior: totalGastoMesAnterior
    };
  } catch (error) {
    console.error(`❌ Erro ao calcular média alimentação para ${user}:`, error);
    return { success: false, error: error.message };
  }
}

async function sendAlimentacaoDiario() {
  console.log(`\n🍽️ [ALIMENTAÇÃO] Gerando relatório diário em ${moment().tz('America/Sao_Paulo').format('DD/MM/YYYY HH:mm:ss')}`);
  const ledgerUser = normalizeLedgerUsername('user1');

  const formatarMoeda = formatBRL;

  const dados = calcularMediaDiariaAlimentacao(ledgerUser);
  if (!dados.success) return;

  const now = moment().tz('America/Sao_Paulo');
  const currentDay = now.date();
  const daysInMonth = now.daysInMonth();

  let statusEmoji = '🟢';
  let statusTexto = 'Dentro da média';
  if (dados.mediaDiaria > 80) {
    statusEmoji = '🔴';
    statusTexto = 'Acima do ideal!';
  } else if (dados.mediaDiaria > 50) {
    statusEmoji = '🟡';
    statusTexto = 'Atenção';
  }

  const progressBarLength = 20;
  const daysProgress = Math.min(progressBarLength, Math.round((currentDay / daysInMonth) * progressBarLength));
  const progressBar = '█'.repeat(daysProgress) + '░'.repeat(progressBarLength - daysProgress);

  let message = `🍽️ *RELATÓRIO DIÁRIO DE ALIMENTAÇÃO*\n`;
  message += `━━━━━━━━━━━━━━━━━━━━\n\n`;
  message += `📅 *Dia:* ${currentDay}/${daysInMonth}\n`;
  message += `${progressBar} ${Math.round((currentDay / daysInMonth) * 100)}%\n\n`;
  message += `💰 *Total gasto no mês:* ${formatarMoeda(dados.totalGasto)}\n`;
  message += `📊 *Média diária:* ${formatarMoeda(dados.mediaDiaria)}\n`;
  message += `📝 *Transações:* ${dados.transacoesCount}\n\n`;

  if (dados.totalMesAnterior > 0) {
    const variacao = dados.variacaoPercentual;
    const variacaoEmoji = variacao > 0 ? '📈' : variacao < 0 ? '📉' : '➡️';
    const variacaoTexto = variacao > 0 ? `+${variacao.toFixed(1)}%` : `${variacao.toFixed(1)}%`;
    message += `📊 *Comparação com mês anterior:*\n`;
    message += `   ${variacaoEmoji} ${variacaoTexto}\n`;
    message += `   Média anterior: ${formatarMoeda(dados.mediaMesAnterior)}\n\n`;
  }

  message += `🎯 *Projeção fim do mês:* ${formatarMoeda(dados.projecaoFimMes)}\n`;
  message += `━━━━━━━━━━━━━━━━━━━━\n`;
  message += `${statusEmoji} *Status:* ${statusTexto}\n\n`;

  if (dados.mediaDiaria > 80) message += `💡 *Dica:* Tente reduzir gastos com delivery e planeje refeições caseiras.\n`;
  else if (dados.mediaDiaria > 50) message += `💡 *Dica:* Faça uma lista de compras para evitar desperdícios.\n`;
  else message += `💡 *Dica:* Continue assim! Gastos controlados com alimentação.\n`;

  message += `\n_Atualizado: ${now.format('DD/MM/YYYY [às] HH:mm')}_`;

  for (const chatId of TG_CHAT_IDS) {
    try {
      await bot.telegram.sendMessage(chatId, message, { parse_mode: 'Markdown' });
      console.log(`✅ Relatório alimentação enviado para ${chatId}`);
    } catch (err) {
      console.error(`❌ Erro ao enviar relatório para ${chatId}:`, err.message);
    }
  }
  await enviarWhatsAppParaTodos(message);

  try {
    db.prepare(
      `
      INSERT INTO chat_logs (user, question, answer, context, created_at) 
      VALUES (?, ?, ?, ?, ?)
    `
    ).run(
      'sistema',
      'RELATORIO_ALIMENTACAO_DIARIO',
      `Relatório diário de alimentação enviado (ledger compartilhado)`,
      JSON.stringify({ timestamp: moment().toISOString() }),
      moment().toISOString()
    );
  } catch (err) {
    console.warn('⚠️ Erro ao logar:', err.message);
  }
}

/**
 * Envia relatório diário de simulação de investimento CDI
 * @param {string} period - 'morning' ou 'evening' (para saudação)
 */
async function registrarTransacaoAutomaticaCDI({ now, saldo, taxaCDI, rendimentoDiario }) {
  try {
    const ledgerUser = 'user1';
    const hasUserId = tableHasColumn('transactions', 'user_id');
    const ledgerUserId = hasUserId ? getUserIdByUsername(ledgerUser) : null;
    const txDate = now.clone().format('YYYY-MM-DD');
    const txId = `cdi_liquido_${ledgerUser}_${txDate}`;
    const userName = 'Sistema CDI';
    const description = `Rendimento líquido diário CDI automático (${now.format('DD/MM/YYYY')})`;
    const category = 'Investimentos';
    const paymentMethod = 'Rendimento CDI';
    const amount = Number(Number(rendimentoDiario || 0).toFixed(2));

    if (!Number.isFinite(amount) || amount <= 0) {
      return { success: false, skipped: true, reason: 'invalid_amount' };
    }

    const existing = db.prepare(`
      SELECT id, amount, description, date${hasUserId ? ', user_id as userId' : ''}
      FROM transactions
      WHERE transaction_id = ?
      LIMIT 1
    `).get(txId);

    if (existing) {
      const sameAmount = Math.abs(Number(existing.amount || 0) - amount) < 0.005;
      const sameDescription = String(existing.description || '') === description;
      const sameDate = String(existing.date || '') === txDate;
      const sameUserId = !hasUserId || Number(existing.userId) === Number(ledgerUserId);

      if (sameAmount && sameDescription && sameDate && sameUserId) {
        return {
          success: true,
          status: 'unchanged',
          transaction: {
            transactionId: txId,
            transaction_id: txId,
            description,
            amount,
            type: 'income',
            category,
            paymentMethod,
            payment_method: paymentMethod,
            user: ledgerUser,
            userName,
            user_name: userName,
            date: txDate
          }
        };
      }

      if (hasUserId) {
        db.prepare(`
          UPDATE transactions
          SET description = ?, amount = ?, type = 'income', category = ?, payment_method = ?, date = ?, user = ?, user_name = ?, user_id = ?, updated_at = DATETIME('now', 'localtime')
          WHERE transaction_id = ?
        `).run(description, amount, category, paymentMethod, txDate, ledgerUser, userName, Number.isFinite(Number(ledgerUserId)) ? Number(ledgerUserId) : null, txId);
      } else {
        db.prepare(`
          UPDATE transactions
          SET description = ?, amount = ?, type = 'income', category = ?, payment_method = ?, date = ?, user = ?, user_name = ?, updated_at = DATETIME('now', 'localtime')
          WHERE transaction_id = ?
        `).run(description, amount, category, paymentMethod, txDate, ledgerUser, userName, txId);
      }
    } else {
      if (hasUserId) {
        db.prepare(`
          INSERT INTO transactions
          (transaction_id, description, amount, type, category, payment_method, date, user, user_name, created_at, user_id)
          VALUES (?, ?, ?, 'income', ?, ?, ?, ?, ?, DATETIME('now', 'localtime'), ?)
        `).run(txId, description, amount, category, paymentMethod, txDate, ledgerUser, userName, Number.isFinite(Number(ledgerUserId)) ? Number(ledgerUserId) : null);
      } else {
        db.prepare(`
          INSERT INTO transactions
          (transaction_id, description, amount, type, category, payment_method, date, user, user_name, created_at)
          VALUES (?, ?, ?, 'income', ?, ?, ?, ?, ?, DATETIME('now', 'localtime'))
        `).run(txId, description, amount, category, paymentMethod, txDate, ledgerUser, userName);
      }
    }

    const transaction = {
      transactionId: txId,
      transaction_id: txId,
      description,
      amount,
      type: 'income',
      category,
      paymentMethod,
      payment_method: paymentMethod,
      user: ledgerUser,
      userId: Number.isFinite(Number(ledgerUserId)) ? Number(ledgerUserId) : null,
      userName,
      user_name: userName,
      date: txDate,
      note: `📈 Receita automática diária de CDI gerada às ${now.format('DD/MM/YYYY HH:mm')}\n💰 Saldo base considerado: ${formatBRL(Number(saldo || 0))}\n📊 Taxa CDI usada: ${(Number(taxaCDI || 0) * 100).toFixed(2)}% a.a.`
    };

    return { success: true, status: existing ? 'updated' : 'inserted', transaction };
  } catch (error) {
    console.error('❌ Erro ao registrar transação automática de CDI:', error.message);
    return { success: false, error: error.message };
  }
}

async function sendInvestmentCDIDaily(period = 'evening') {
  try {
    const now = moment().tz('America/Sao_Paulo');
    const usuario = normalizeLedgerUsername('user1');
    const formatarMoeda = formatBRL;

    // 1. Obter saldo total investido
    const investido = getTotalInvested(usuario);
    if (!investido.success || investido.totalInvested <= 0) {
      console.log('ℹ️ Nenhum saldo investido para gerar relatório CDI');
      const msg = `📭 Nenhum saldo investido encontrado.\nComece a investir hoje mesmo! 💰\nAcesse o dashboard para simular aplicações em CDB.`;
      for (const chatId of TG_CHAT_IDS) {
        try { await bot.telegram.sendMessage(chatId, msg); } catch (e) {}
      }
      await enviarWhatsAppParaTodos(msg);
      return;
    }
    const saldo = investido.totalInvested;

    // 2. Obter taxa CDI atual (com validação)
    let taxaCDI = 0.14; // fallback padrão (14% a.a.)
    try {
      const hoje = moment().format('DD/MM/YYYY');
      const noventaDiasAtras = moment().subtract(90, 'days').format('DD/MM/YYYY');
      const url = `https://api.bcb.gov.br/dados/serie/bcdata.sgs.11/dados?formato=json&dataInicial=${noventaDiasAtras}&dataFinal=${hoje}`;
      const response = await axios.get(url, { timeout: 5000 });
      const dados = response.data;
      if (Array.isArray(dados) && dados.length > 0) {
        // Pega o último valor (mais recente)
        const ultimo = parseFloat(dados[dados.length - 1].valor);
        if (!isNaN(ultimo) && ultimo > 0) {
          // O valor da API já está em percentual (ex: 14.00)
          // Se o valor estiver entre 5 e 20 (percentual), consideramos válido
          if (ultimo >= 5 && ultimo <= 20) {
            taxaCDI = ultimo / 100; // converte para decimal (0.14)
            console.log(`✅ Taxa CDI obtida: ${ultimo}% a.a.`);
          } else {
            console.warn(`⚠️ Taxa CDI fora do intervalo esperado (${ultimo}%), usando fallback de 14%`);
          }
        }
      }
    } catch (e) {
      console.warn('⚠️ Erro ao buscar taxa CDI (usando fallback 14%):', e.message);
    }

    // 3. Cálculos (mesma lógica anterior)
    const diasUteisPorAno = 252;
    const diasUteis = 30;
    const taxaDiaria = Math.pow(1 + taxaCDI, 1 / diasUteisPorAno) - 1;
    const rendimentoBruto = saldo * (Math.pow(1 + taxaDiaria, diasUteis) - 1);
    const aliquotaIR = 0.225; // até 180 dias
    const rendimentoLiquido = rendimentoBruto * (1 - aliquotaIR);
    const rendimentoDiario = rendimentoLiquido / diasUteis;

    // Comparação Poupança
    const rendimentoPoupancaMensal = saldo * (0.7 * taxaCDI) * (diasUteis / 365);
    const diferenca = rendimentoLiquido - rendimentoPoupancaMensal;

    const txResult = await registrarTransacaoAutomaticaCDI({
      now,
      saldo,
      taxaCDI,
      rendimentoDiario
    });

    if (txResult && txResult.success && txResult.status !== 'unchanged' && txResult.transaction) {
      try {
        await notificarTelegram(txResult.transaction);
      } catch (e) {
        console.error('❌ Erro ao notificar Telegram da transação CDI:', e.message);
      }

      try {
        const valorFmt = formatarMoeda(txResult.transaction.amount);
        const waMessage = [
          '💰 NOVA RECEITA REGISTRADA',
          '━━━━━━━━━━━━━━━━━━━━',
          `📝 Descrição: ${txResult.transaction.description}`,
          `💵 Valor: ${valorFmt}`,
          `📂 Categoria: ${txResult.transaction.category}`,
          `💳 Método: ${txResult.transaction.paymentMethod}`,
          `👤 Registrado por: ${txResult.transaction.userName}`,
          `📅 Data: ${now.format('DD/MM/YYYY')}`,
          '━━━━━━━━━━━━━━━━━━━━',
          `🆔 ID: ${txResult.transaction.transactionId}`,
          `⏰ ${now.format('DD/MM/YYYY HH:mm:ss')}`
        ].join('\n');
        await enviarWhatsAppGrupoTexto(WHATSAPP_GRUPO_TRANSACOES, waMessage);
      } catch (e) {
        console.error('❌ Erro ao notificar WhatsApp da transação CDI:', e.message);
      }
    }

    // 4. Montar mensagem (mesma estrutura)
    const saudacao = period === 'morning' ? 'Bom dia! 🌅' : 'Boa noite! 🌙';
    const titulo = `📈 *SIMULAÇÃO DE INVESTIMENTO CDI* - ${now.format('DD/MM/YYYY')}`;
    const corpo = `
💰 *Saldo investido:* ${formatarMoeda(saldo)}
📊 *Taxa CDI:* ${(taxaCDI * 100).toFixed(2)}% a.a.
💹 *Rendimento diário estimado:* ${formatarMoeda(rendimentoDiario)}
📅 *Projeção em 30 dias (líq.):* ${formatarMoeda(rendimentoLiquido)}
📆 *Projeção em 12 meses (líq.):* ${formatarMoeda(rendimentoLiquido * 12)}

💡 *Comparação com Poupança (30 dias):*
• Poupança renderia: ${formatarMoeda(rendimentoPoupancaMensal)}
• CDI (líq.) supera Poupança em: ${formatarMoeda(diferenca)}
${diferenca > 0 ? '✅ Recomendação: mantenha em CDB/LCI para melhor rentabilidade.' : '⚠️ Considere rever a alocação, a Poupança pode estar mais vantajosa.'}
🧾 *Transação automática CDI:* ${txResult && txResult.success ? (txResult.status === 'unchanged' ? 'já registrada hoje' : 'registrada com sucesso') : 'não registrada'}
━━━━━━━━━━━━━━━━━━━━
_Atualizado em ${now.format('DD/MM/YYYY [às] HH:mm')}_
`;

    const mensagemFinal = `${saudacao}\n${titulo}\n${corpo}`;

    // 5. Enviar para Telegram e WhatsApp
    for (const chatId of TG_CHAT_IDS) {
      try {
        await bot.telegram.sendMessage(chatId, mensagemFinal, { parse_mode: 'Markdown' });
        console.log(`✅ Relatório CDI enviado para ${chatId}`);
      } catch (err) {
        console.error(`❌ Erro Telegram ${chatId}:`, err.message);
      }
    }
    // Vai pro grupo fixo (mesmo das notificações de transação), não mais para cada número.
    // WhatsApp entende *negrito* e _itálico_ igual ao Markdown do Telegram, então a formatação é mantida.
    const okGrupoCDI = await enviarWhatsAppGrupoTexto(WHATSAPP_GRUPO_TRANSACOES, mensagemFinal);
    console.log(okGrupoCDI ? '✅ Relatório CDI enviado para o grupo do WhatsApp' : '⚠️ Relatório CDI não foi enviado para o grupo do WhatsApp');

    // Echo Dot: fala o "Rendimento diário estimado" do relatório, sempre que o relatório sai (mesmo se a
    // transação do dia já estava registrada). Falha aqui nunca derruba nada: o relatório já foi enviado.
    try {
      await falarRendimentoCDINaEcho(rendimentoDiario);
    } catch (e) {
      console.error('❌ [Echo] Não consegui falar o rendimento diário estimado do CDI:', e.message);
    }

  } catch (error) {
    console.error('❌ Erro em sendInvestmentCDIDaily:', error);
  }
}

function gerarRelatorioGasolinaSemanal(user) {
  try {
    const ledgerUser = normalizeLedgerUsername(user);
    const userFilter = buildUserWhere('transactions', ledgerUser, 'user');
    const now = moment().tz('America/Sao_Paulo');
    const startOfWeek = now.clone().startOf('isoWeek');
    const endOfWeek = now.clone().endOf('isoWeek');
    const currentMonth = now.format('YYYY-MM');

    const semanaData = db
      .prepare(
        `
        SELECT 
          COALESCE(SUM(amount), 0) as total_semana, 
          COUNT(*) as count_semana 
        FROM transactions 
        WHERE ${userFilter.clause}
          AND date >= ? 
          AND date <= ? 
          AND type = 'expense' 
          AND ( 
            LOWER(description) LIKE '%gasolina%' 
            OR LOWER(description) LIKE '%combustível%' 
            OR LOWER(description) LIKE '%combustivel%' 
            OR LOWER(description) LIKE '%posto%' 
            OR LOWER(category) = 'gasolina' 
          )
      `
      )
      .get(...userFilter.params, startOfWeek.format('YYYY-MM-DD'), endOfWeek.format('YYYY-MM-DD'));

    const mesData = db
      .prepare(
        `
        SELECT 
          COALESCE(SUM(amount), 0) as total_mes, 
          COUNT(*) as count_mes 
        FROM transactions 
        WHERE ${userFilter.clause}
          AND strftime('%Y-%m', date) = ? 
          AND type = 'expense' 
          AND ( 
            LOWER(description) LIKE '%gasolina%' 
            OR LOWER(description) LIKE '%combustível%' 
            OR LOWER(description) LIKE '%combustivel%' 
            OR LOWER(description) LIKE '%posto%' 
            OR LOWER(category) = 'gasolina' 
          )
      `
      )
      .get(...userFilter.params, currentMonth);

    const totalSemana = Number(semanaData?.total_semana || 0);
    const totalMes = Number(mesData?.total_mes || 0);
    const limiteReembolsoGasolina = 640;
    const restanteMes = Math.max(0, limiteReembolsoGasolina - totalMes);
    const percentualUtilizado = limiteReembolsoGasolina > 0 ? Math.min(100, (totalMes / limiteReembolsoGasolina) * 100) : 0;

    const abastecimentosSemana = db
      .prepare(
        `
        SELECT date, description, amount 
        FROM transactions 
        WHERE ${userFilter.clause}
          AND date >= ? 
          AND date <= ? 
          AND type = 'expense' 
          AND ( 
            LOWER(description) LIKE '%gasolina%' 
            OR LOWER(description) LIKE '%combustível%' 
            OR LOWER(description) LIKE '%combustivel%' 
            OR LOWER(description) LIKE '%posto%' 
            OR LOWER(category) = 'gasolina' 
          ) 
        ORDER BY date DESC
      `
      )
      .all(...userFilter.params, startOfWeek.format('YYYY-MM-DD'), endOfWeek.format('YYYY-MM-DD'));

    return {
      success: true,
      user: ledgerUser,
      totalSemana,
      totalMes,
      limiteReembolsoGasolina,
      restanteMes,
      percentualUtilizado,
      abastecimentosSemana,
      semanaPeriodo: { inicio: startOfWeek.format('DD/MM'), fim: endOfWeek.format('DD/MM') }
    };
  } catch (error) {
    console.error(`❌ Erro ao gerar relatório gasolina para ${user}:`, error);
    return { success: false, error: error.message };
  }
}

async function sendGasolinaSemanal() {
  console.log(`\n⛽ [GASOLINA] Gerando relatório semanal em ${moment().tz('America/Sao_Paulo').format('DD/MM/YYYY HH:mm:ss')}`);
  const usuario = { username: 'user1', name: 'User1' };

  const formatarMoeda = formatBRL;

  const dados = gerarRelatorioGasolinaSemanal(usuario.username);
  if (!dados.success) return;

  const now = moment().tz('America/Sao_Paulo');
  const weekNumber = now.isoWeek();

  const progressBarLength = 20;
  const percentual = dados.percentualUtilizado;
  const filledBars = Math.min(progressBarLength, Math.round((percentual / 100) * progressBarLength));
  const progressBar = '█'.repeat(filledBars) + '░'.repeat(progressBarLength - filledBars);

  let statusEmoji = '🟢';
  let statusTexto = 'Dentro do limite';
  if (dados.totalMes >= dados.limiteReembolsoGasolina) {
    statusEmoji = '🔴';
    statusTexto = 'LIMITE EXCEDIDO!';
  } else if (dados.totalMes > dados.limiteReembolsoGasolina * 0.8) {
    statusEmoji = '🟡';
    statusTexto = 'Próximo do limite';
  }

  let message = `⛽ *RELATÓRIO SEMANAL DE GASOLINA*\n`;
  message += `👤 *${usuario.name.toUpperCase()}*\n`;
  message += `━━━━━━━━━━━━━━━━━━━━\n\n`;
  message += `📅 *Semana:* ${dados.semanaPeriodo.inicio} a ${dados.semanaPeriodo.fim}\n`;
  message += `🔢 *Semana ${weekNumber} de ${now.year()}*\n\n`;
  message += `⛽ *Gastos da semana:* ${formatarMoeda(dados.totalSemana)}\n`;
  message += dados.abastecimentosSemana.length > 0 ? `   (${dados.abastecimentosSemana.length} abastecimento(s))\n` : '   (Nenhum abastecimento)\n';
  message += `━━━━━━━━━━━━━━━━━━━━\n`;
  message += `📊 *Acumulado no mês:* ${formatarMoeda(dados.totalMes)}\n`;
  message += `🎯 *Limite de reembolso:* ${formatarMoeda(dados.limiteReembolsoGasolina)}\n`;
  message += `${progressBar} ${dados.percentualUtilizado.toFixed(1)}%\n\n`;
  message += `💰 *Restante do mês:* ${formatarMoeda(dados.restanteMes)}\n`;
  message += `━━━━━━━━━━━━━━━━━━━━\n`;
  message += `${statusEmoji} *Status:* ${statusTexto}\n`;

  if (dados.abastecimentosSemana.length > 0) {
    message += `\n🧾 *Detalhes da semana:*\n`;
    dados.abastecimentosSemana.slice(0, 6).forEach((a) => {
      const data = moment(a.date).format('DD/MM');
      const desc = String(a.description || 'Abastecimento').slice(0, 35);
      message += `• ${data} - ${formatarMoeda(a.amount)} - ${desc}\n`;
    });
    if (dados.abastecimentosSemana.length > 6) message += `• ... +${dados.abastecimentosSemana.length - 6} item(ns)\n`;
  }

  message += `\n_Atualizado: ${now.format('DD/MM/YYYY [às] HH:mm')}_`;

  for (const chatId of TG_CHAT_IDS) {
    try {
      await bot.telegram.sendMessage(chatId, message, { parse_mode: 'Markdown' });
      console.log(`✅ Relatório gasolina enviado para ${chatId} (${usuario.name})`);
    } catch (err) {
      console.error(`❌ Erro ao enviar relatório para ${chatId}:`, err.message);
    }
  }
  await enviarWhatsAppParaTodos(message);
}

const FGTS_DEFAULT_VALUES = { user1: 200.00, user2: 150.00 };
const FGTS_DEFAULT_AUTO_ENABLED = true;

const FGTS_LOG_LEVEL = String(process.env.FGTS_LOG_LEVEL || process.env.LOG_LEVEL || 'info').toLowerCase();
const FGTS_LOG_RICH = String(process.env.FGTS_LOG_RICH || process.env.FGTS_DEBUG || '').trim() === '1';
function fgtsLevelRank(level) {
  if (level === 'error') return 0;
  if (level === 'warn') return 1;
  if (level === 'info') return 2;
  if (level === 'debug') return 3;
  return 2;
}
function fgtsShouldLog(level) {
  return fgtsLevelRank(level) <= fgtsLevelRank(FGTS_LOG_LEVEL);
}
function fgtsSafeJson(value) {
  try {
    const seen = new WeakSet();
    const out = JSON.stringify(value, (key, val) => {
      if (key && typeof key === 'string') {
        const k = key.toLowerCase();
        if (k.includes('token') || k.includes('secret') || k.includes('password') || k.includes('access') || k.includes('refresh')) return '[redacted]';
      }
      if (typeof val === 'string' && val.length > 800) return val.slice(0, 800) + '...';
      if (val && typeof val === 'object') {
        if (seen.has(val)) return '[circular]';
        seen.add(val);
      }
      return val;
    });
    return out;
  } catch (e) {
    try { return String(value); } catch (_) { return '[unserializable]'; }
  }
}
function fgtsLog(level, event, data) {
  const lvl = String(level || 'info').toLowerCase();
  if (!fgtsShouldLog(lvl)) return;
  const ts = new Date().toISOString();
  const payload = data && typeof data !== 'undefined' ? ' ' + fgtsSafeJson(data) : '';
  const line = `[FGTS] ${ts} ${lvl.toUpperCase()} ${String(event || '').trim() || 'event'}${payload}`;
  if (lvl === 'error') return console.error(line);
  if (lvl === 'warn') return console.warn(line);
  if (lvl === 'debug') return console.log(line);
  return console.log(line);
}

function calcularMesesNaEmpresa(dataEntrada) {
  if (!dataEntrada) return null;
  const inicio = moment(String(dataEntrada), 'YYYY-MM-DD', true);
  if (!inicio.isValid()) {
    fgtsLog('warn', 'calcularMesesNaEmpresa.invalid_date', { dataEntrada: String(dataEntrada) });
    return null;
  }
  const hoje = moment().tz('America/Sao_Paulo').startOf('day');
  if (inicio.isAfter(hoje)) return 0;
  const months = hoje.diff(inicio, 'months', true);
  if (!Number.isFinite(Number(months))) return null;
  return months;
}

function calcularMediaDepositoMensal(saldoAtual, dataEntrada) {
  const meses = calcularMesesNaEmpresa(dataEntrada);
  if (!Number.isFinite(meses) || meses <= 0) return null;
  const saldo = Number(saldoAtual || 0);
  if (!Number.isFinite(saldo) || saldo <= 0) return null;
  const media = saldo / meses;
  return Number.isFinite(media) && media > 0 ? Number(media.toFixed(2)) : null;
}

function getFgtsConfig(username) {
  const started = Date.now();
  try {
    if (!db) return { balance: 0, dataEntrada: null, media: null, autoEnabled: false };
    const uname = String(username || '').toLowerCase().trim();
    if (!uname) return { balance: 0, dataEntrada: null, media: null, autoEnabled: false };
    if (FGTS_LOG_RICH) fgtsLog('debug', 'getFgtsConfig.start', { username: uname });

    const row = db.prepare(`
      SELECT
        balance,
        data_entrada_empresa AS dataEntrada,
        deposito_mensal_medio AS media,
        deposito_automatico_habilitado AS autoEnabled
      FROM fgts_balances
      WHERE username = ?
      LIMIT 1
    `).get(uname);

    if (!row) {
      const defaultBalance = 0;
      const defaultAuto = FGTS_DEFAULT_AUTO_ENABLED;
      const now = moment().toISOString();
      try {
        if (tableHasColumn('fgts_balances', 'deposito_automatico_habilitado')) {
          db.prepare(`
            INSERT INTO fgts_balances (username, balance, created_at, updated_at, deposito_automatico_habilitado)
            VALUES (?, ?, ?, ?, ?)
          `).run(uname, defaultBalance, now, now, defaultAuto ? 1 : 0);
        } else {
          db.prepare(`
            INSERT INTO fgts_balances (username, balance, created_at, updated_at)
            VALUES (?, ?, ?, ?)
          `).run(uname, defaultBalance, now, now);
        }
        fgtsLog('info', 'getFgtsConfig.initialized', { username: uname, defaultBalance, defaultAuto });
      } catch (e) {
        fgtsLog('error', 'getFgtsConfig.init_failed', { username: uname, error: e.message });
      }
      fgtsLog('info', 'getFgtsConfig.done', { username: uname, balance: defaultBalance, autoEnabled: defaultAuto, ms: Date.now() - started });
      return { balance: defaultBalance, dataEntrada: null, media: null, autoEnabled: defaultAuto };
    }

    const result = {
      balance: Number(row.balance) || 0,
      dataEntrada: row.dataEntrada ? String(row.dataEntrada) : null,
      media: row.media !== null && typeof row.media !== 'undefined' ? Number(row.media) : null,
      autoEnabled: Number(row.autoEnabled) === 1
    };
    fgtsLog('info', 'getFgtsConfig.done', { username: uname, balance: result.balance, dataEntrada: result.dataEntrada, media: result.media, autoEnabled: result.autoEnabled, ms: Date.now() - started });
    return result;
  } catch (e) {
    fgtsLog('error', 'getFgtsConfig.failed', { username: String(username || ''), error: e.message, ms: Date.now() - started });
    return { balance: 0, dataEntrada: null, media: null, autoEnabled: false };
  }
}

function updateFgtsMedia(username, dataEntrada, autoEnable = true) {
  const started = Date.now();
  try {
    if (!db) return { media: null, autoEnabled: false };
    const uname = String(username || '').toLowerCase().trim();
    if (!uname) return { media: null, autoEnabled: false };
    if (FGTS_LOG_RICH) fgtsLog('debug', 'updateFgtsMedia.start', { username: uname, dataEntrada: dataEntrada || null, autoEnable: !!autoEnable });

    const config = getFgtsConfig(uname);
    const dataStr = dataEntrada ? String(dataEntrada).trim() : null;
    let media = null;

    if (dataStr) {
      const dataMoment = moment(dataStr, 'YYYY-MM-DD', true);
      if (!dataMoment.isValid()) {
        fgtsLog('warn', 'updateFgtsMedia.invalid_date', { username: uname, dataEntrada: dataStr });
      } else if (dataMoment.isAfter(moment().tz('America/Sao_Paulo'))) {
        fgtsLog('warn', 'updateFgtsMedia.future_date', { username: uname, dataEntrada: dataStr });
      } else {
        media = calcularMediaDepositoMensal(config.balance, dataStr);
      }
    }

    const enabled = !!autoEnable;
    const now = moment().toISOString();
    let resolvedUserId = null;

    if (tableHasColumn('fgts_balances', 'user_id')) {
      const row = db.prepare(`
        SELECT id FROM users u
        WHERE lower(u.email) = lower(?) || '@local'
           OR lower(u.email) LIKE lower(?) || '@%'
        ORDER BY CASE WHEN lower(u.email) = lower(?) || '@local' THEN 0 ELSE 1 END, id ASC
        LIMIT 1
      `).get(uname, uname, uname);
      const userId = row ? Number(row.id) : null;
      resolvedUserId = Number.isFinite(Number(userId)) ? Number(userId) : null;
      db.prepare(`
        INSERT INTO fgts_balances (username, balance, created_at, updated_at, user_id, data_entrada_empresa, deposito_mensal_medio, deposito_automatico_habilitado)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(username) DO UPDATE SET
          updated_at = excluded.updated_at,
          user_id = excluded.user_id,
          data_entrada_empresa = excluded.data_entrada_empresa,
          deposito_mensal_medio = excluded.deposito_mensal_medio,
          deposito_automatico_habilitado = excluded.deposito_automatico_habilitado
      `).run(uname, config.balance, now, now, userId, dataStr, media, enabled ? 1 : 0);
    } else {
      db.prepare(`
        INSERT INTO fgts_balances (username, balance, created_at, updated_at, data_entrada_empresa, deposito_mensal_medio, deposito_automatico_habilitado)
        VALUES (?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(username) DO UPDATE SET
          updated_at = excluded.updated_at,
          data_entrada_empresa = excluded.data_entrada_empresa,
          deposito_mensal_medio = excluded.deposito_mensal_medio,
          deposito_automatico_habilitado = excluded.deposito_automatico_habilitado
      `).run(uname, config.balance, now, now, dataStr, media, enabled ? 1 : 0);
    }

    fgtsLog('info', 'updateFgtsMedia.done', { username: uname, userId: resolvedUserId, dataEntrada: dataStr, media, autoEnabled: enabled, ms: Date.now() - started });
    return { media, autoEnabled: enabled };
  } catch (e) {
    fgtsLog('error', 'updateFgtsMedia.failed', { username: String(username || ''), dataEntrada: dataEntrada || null, error: e.message, ms: Date.now() - started });
    return { media: null, autoEnabled: false };
  }
}

function updateFgtsBalance(username, valor, operacao = 'set') {
  const started = Date.now();
  try {
    if (!db) return 0;
    const uname = String(username || '').toLowerCase().trim();
    if (!uname) return 0;
    const v = Number(valor);
    if (!Number.isFinite(v) || (operacao !== 'set' && v <= 0)) {
      fgtsLog('warn', 'updateFgtsBalance.invalid_value', { username: uname, operacao, valor });
      return getFgtsConfig(uname).balance;
    }

    const atual = getFgtsConfig(uname).balance;
    let finalSaldo = atual;
    if (operacao === 'add') finalSaldo = atual + v;
    else if (operacao === 'sub') finalSaldo = atual - v;
    else finalSaldo = v;
    if (!Number.isFinite(finalSaldo) || finalSaldo < 0) finalSaldo = 0;

    const now = moment().toISOString();
    let resolvedUserId = null;
    if (tableHasColumn('fgts_balances', 'user_id')) {
      const row = db.prepare(`
        SELECT id FROM users u
        WHERE lower(u.email) = lower(?) || '@local'
           OR lower(u.email) LIKE lower(?) || '@%'
        ORDER BY CASE WHEN lower(u.email) = lower(?) || '@local' THEN 0 ELSE 1 END, id ASC
        LIMIT 1
      `).get(uname, uname, uname);
      const userId = row ? Number(row.id) : null;
      resolvedUserId = Number.isFinite(Number(userId)) ? Number(userId) : null;
      db.prepare(`
        INSERT INTO fgts_balances (username, balance, created_at, updated_at, user_id)
        VALUES (?, ?, ?, ?, ?)
        ON CONFLICT(username) DO UPDATE SET balance = excluded.balance, updated_at = excluded.updated_at, user_id = excluded.user_id
      `).run(uname, finalSaldo, now, now, userId);
    } else {
      db.prepare(`
        INSERT INTO fgts_balances (username, balance, created_at, updated_at)
        VALUES (?, ?, ?, ?)
        ON CONFLICT(username) DO UPDATE SET balance = excluded.balance, updated_at = excluded.updated_at
      `).run(uname, finalSaldo, now, now);
    }

    const cfg = getFgtsConfig(uname);
    if (cfg.dataEntrada) {
      updateFgtsMedia(uname, cfg.dataEntrada, cfg.autoEnabled);
    }

    fgtsLog('info', 'updateFgtsBalance.done', { username: uname, userId: resolvedUserId, operacao, valor: v, saldoAnterior: atual, saldoNovo: finalSaldo, ms: Date.now() - started });
    return finalSaldo;
  } catch (e) {
    fgtsLog('error', 'updateFgtsBalance.failed', { username: String(username || ''), operacao, valor, error: e.message, ms: Date.now() - started });
    return 0;
  }
}

function recalcularMediaParaUsuario(username) {
  const started = Date.now();
  fgtsLog('info', 'recalcularMediaParaUsuario.start', { username: String(username || '') });
  const config = getFgtsConfig(username);
  if (!config.dataEntrada) {
    fgtsLog('warn', 'recalcularMediaParaUsuario.no_data_entrada', { username: String(username || ''), ms: Date.now() - started });
    return { media: null, autoEnabled: config.autoEnabled };
  }
  const out = updateFgtsMedia(username, config.dataEntrada, config.autoEnabled);
  fgtsLog('info', 'recalcularMediaParaUsuario.done', { username: String(username || ''), media: out.media, autoEnabled: out.autoEnabled, ms: Date.now() - started });
  return out;
}

async function adicionarFGTSAutomatico(options = {}) {
  const started = Date.now();
  try {
    if (!db) return { success: false, error: 'DB_NOT_READY' };
    const force = Boolean(options && options.force);
    const hoje = moment().tz('America/Sao_Paulo');
    const diaAtual = hoje.date();
    fgtsLog('info', 'adicionarFGTSAutomatico.start', { force, diaAtual, date: hoje.format('YYYY-MM-DD') });
    if (diaAtual !== 1 && !force) {
      fgtsLog('info', 'adicionarFGTSAutomatico.skipped', { force, diaAtual, ms: Date.now() - started });
      return { success: false, skipped: true, day: diaAtual };
    }

    const usuarios = db.prepare(`
      SELECT username, data_entrada_empresa, deposito_mensal_medio, deposito_automatico_habilitado, balance
      FROM fgts_balances
      WHERE deposito_automatico_habilitado = 1
        AND data_entrada_empresa IS NOT NULL
        AND data_entrada_empresa != ''
    `).all();

    const resultados = [];
    const fmt = formatBRL;

    for (const row of usuarios) {
      const username = String(row.username || '').toLowerCase().trim();
      const media = Number(row.deposito_mensal_medio || 0);
      if (!username) continue;
      if (!Number.isFinite(media) || media <= 0) {
        fgtsLog('warn', 'adicionarFGTSAutomatico.media_invalida', { username, media });
        resultados.push({ username, sucesso: false, motivo: 'media_invalida', media });
        continue;
      }

      const saldoAnterior = Number(row.balance || 0);
      const novoSaldo = updateFgtsBalance(username, media, 'add');
      resultados.push({ username, sucesso: true, valorAdicionado: media, saldoAnterior, novoSaldo });

      let userRow = null;
      try {
        userRow = db.prepare(`
          SELECT telegram_id, whatsapp, name
          FROM users u
          WHERE lower(u.email) = lower(?) || '@local'
             OR lower(u.email) LIKE lower(?) || '@%'
          ORDER BY CASE WHEN lower(u.email) = lower(?) || '@local' THEN 0 ELSE 1 END, id ASC
          LIMIT 1
        `).get(username, username, username);
      } catch (e) {}

      const userTelegram = userRow && userRow.telegram_id ? String(userRow.telegram_id).trim() : '';
      const userWhatsapp = userRow && userRow.whatsapp ? String(userRow.whatsapp).trim() : '';
      const userName = userRow && userRow.name ? String(userRow.name).trim() : username;

      const mensagem = `🏦 *CRÉDITO FGTS MENSAL* - ${userName}\n━━━━━━━━━━━━━━━━━━━━\n💰 Valor depositado: ${fmt(media)}\n📊 Saldo anterior: ${fmt(saldoAnterior)}\n✅ Novo saldo: ${fmt(novoSaldo)}\n📅 ${hoje.format('DD/MM/YYYY HH:mm:ss')}`;

      if (userTelegram && bot && bot.telegram) {
        try {
          await bot.telegram.sendMessage(userTelegram, mensagem, { parse_mode: 'Markdown' });
          fgtsLog('info', 'adicionarFGTSAutomatico.notificacao_telegram', { username, telegramId: userTelegram });
        } catch (e) {
          fgtsLog('error', 'adicionarFGTSAutomatico.telegram_failed', { username, error: e.message });
        }
      }

      // WhatsApp vai pro grupo fixo (não mais pro número do usuário).
      if (WHATSAPP_ENABLED) {
        try {
          await enviarWhatsAppGrupoTexto(WHATSAPP_GRUPO_TRANSACOES, String(mensagem));
          fgtsLog('info', 'adicionarFGTSAutomatico.notificacao_whatsapp', { username, grupo: WHATSAPP_GRUPO_TRANSACOES });
        } catch (e) {
          fgtsLog('error', 'adicionarFGTSAutomatico.whatsapp_failed', { username, error: e.message });
        }
      }
    }

    fgtsLog('info', 'adicionarFGTSAutomatico.done', { resultados, ms: Date.now() - started });
    return { success: true, resultados };
  } catch (error) {
    fgtsLog('error', 'adicionarFGTSAutomatico.failed', { error: error.message, stack: String(error && error.stack ? error.stack : '').slice(0, 1200), ms: Date.now() - started });
    return { success: false, error: error.message };
  }
}

async function adicionarFGTSEmPrimeiroDia(options = {}) {
    try {
        return await adicionarFGTSAutomatico(options || {});
    } catch (error) {
        console.error('❌ Erro crítico no crédito mensal FGTS:', error);
        
        try {
            const erroMsg = `🚨 *ERRO NO CRÉDITO FGTS MENSAL*\n\n\`\`\`\n${error.message}\n\`\`\``;
            for (const chatId of TG_CHAT_IDS) {
                await bot.telegram.sendMessage(chatId, erroMsg, { parse_mode: 'Markdown' });
            }
        } catch (e) {}
        
        return { success: false, error: error.message };
    }
}
// ============== FUNÇÃO CORRIGIDA PARA CÁLCULO DOS CARTÕES ==============
// ============== FUNÇÕES API PLUGGY ==============

// 1. Obter Token de Acesso da Pluggy
async function getPluggyApiKey() {
  try {
    // Verificar se já temos um token válido (expira em 1 hora)
    if (pluggyApiKey && pluggyApiKeyExpiry && pluggyApiKeyExpiry > Date.now()) {
      return pluggyApiKey;
    }

    console.log('🔑 Obtendo novo token da Pluggy...');
    
    const response = await axios.post(`${PLUGGY_API_URL}/auth`, {
      clientId: PLUGGY_CLIENT_ID,
      clientSecret: PLUGGY_CLIENT_SECRET
    });

    pluggyApiKey = response.data.apiKey;
    pluggyApiKeyExpiry = Date.now() + (50 * 60 * 1000); // 50 minutos
    
    console.log('✅ Token Pluggy obtido com sucesso');
    return pluggyApiKey;
  } catch (error) {
    console.error('❌ Erro ao obter API key da Pluggy:', error.response?.data || error.message);
    throw error;
  }
}

// ============== CDI NEON (RENDA FIXA REAL, VIA /investments) ==============
// Diferente das "Caixinhas Neon" (getNeonInvestmentAccounts/getAllInvestmentTransactions, que usam
// /accounts + /transactions): isto é o produto de renda fixa (CDB) do Neon, exposto pela Pluggy em
// /investments (posição) e /investments/{id}/transactions (aportes e resgates de cada aplicação).
async function buscarMovimentosCdiNeon() {
  const apiKey = await getPluggyApiKey();
  const invResp = await axios.get(`${PLUGGY_API_URL}/investments`, {
    params: { itemId: NEON_ITEM_ID },
    headers: { 'X-API-KEY': apiKey }
  });
  const investimentos = invResp.data.results || invResp.data || [];

  let totalAportado = 0;
  let totalResgatado = 0;
  let saldoAtual = 0;
  const movimentos = [];

  for (const inv of investimentos) {
    saldoAtual += Number(inv.balance || 0);
    try {
      const txResp = await axios.get(`${PLUGGY_API_URL}/investments/${inv.id}/transactions`, {
        headers: { 'X-API-KEY': apiKey }
      });
      const txs = txResp.data.results || txResp.data || [];
      for (const t of txs) {
        const valor = Math.abs(Number(t.amount || 0));
        const tipo = t.type === 'SELL' ? 'resgate' : 'aporte'; // BUY = aporte, SELL = resgate
        if (tipo === 'aporte') totalAportado += valor;
        else totalResgatado += valor;
        movimentos.push({
          movementId: t.id,
          investmentId: inv.id,
          investimentoNome: inv.name || inv.subtype || 'CDI Neon',
          subtype: inv.subtype || null,
          tipo,
          valor,
          data: t.date || t.tradeDate || null,
          statusInvestimento: inv.status || null
        });
      }
    } catch (txError) {
      console.error(`❌ Erro ao buscar movimentos do investimento ${inv.id} (CDI Neon):`, txError.message);
    }
  }

  movimentos.sort((a, b) => moment(b.data).valueOf() - moment(a.data).valueOf());

  return {
    investimentos: investimentos.map(inv => ({
      id: inv.id,
      nome: inv.name || inv.subtype || 'CDI Neon',
      subtype: inv.subtype || null,
      status: inv.status || null,
      saldo: Number(inv.balance || 0),
      valorOriginal: Number(inv.amountOriginal || 0),
      taxaTipo: inv.rateType || null,
      taxa: inv.rate != null ? Number(inv.rate) : null,
      vencimento: inv.dueDate || null,
      atualizadoEm: inv.updatedAt || null
    })),
    movimentos,
    resumo: { totalAportado, totalResgatado, saldoAtual }
  };
}

// Roda 1x/dia (cron abaixo): busca os movimentos e notifica no Telegram só os que ainda não foram
// vistos (dedup por movement_id em cdi_neon_movimentos_notificados). Dados do Neon no plano gratuito
// da Pluggy só atualizam a cada ~24h, então rodar com mais frequência não traria nada de novo.
async function detectarNovosMovimentosCdiNeon() {
  if (!db) return;
  const { movimentos } = await buscarMovimentosCdiNeon();
  if (!movimentos.length) return;

  const jaVistos = new Set(
    db.prepare(`SELECT movement_id FROM cdi_neon_movimentos_notificados`).all().map(r => r.movement_id)
  );
  const novos = movimentos.filter(m => !jaVistos.has(m.movementId));
  if (!novos.length) return;

  const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(v || 0));
  for (const m of novos) {
    try {
      const emoji = m.tipo === 'aporte' ? '🟢' : '🔴';
      const acao = m.tipo === 'aporte' ? 'Aporte' : 'Resgate';
      const msg = `${emoji} *${acao} no CDI Neon*\n\n💰 Valor: ${fmt(m.valor)}\n📅 Data: ${moment(m.data).format('DD/MM/YYYY')}\n🏦 ${m.investimentoNome}`;
      for (const chatId of TG_CHAT_IDS) {
        try { await bot.telegram.sendMessage(chatId, msg, { parse_mode: 'Markdown' }); } catch (e) {}
      }
    } catch (e) {
      console.error('❌ Erro ao notificar movimento do CDI Neon:', e.message);
    }
    try {
      db.prepare(`
        INSERT OR IGNORE INTO cdi_neon_movimentos_notificados (movement_id, investment_id, tipo, valor, data, notificado_em)
        VALUES (?, ?, ?, ?, ?, ?)
      `).run(m.movementId, m.investmentId, m.tipo, m.valor, m.data, moment().toISOString());
    } catch (e) {}
  }
  console.log(`🟢 [CDI Neon] ${novos.length} novo(s) movimento(s) notificado(s)`);
}


