// 4b. Salvar uma transação do Sicredi (CREDIT ou DEBIT) no banco local, com dedup real.
// Espelha o padrão já usado em salvarTransacaoNeon: INSERT direto (não passa por
// addTransaction, que gera seu próprio transaction_id aleatório e ignora qualquer
// transaction_id externo) e checa existência ANTES de inserir, usando o ID real da
// Pluggy como chave — assim uma reentrega do mesmo webhook nunca duplica a transação.
// Persiste uma transação vinda do Pluggy (Neon/Sicredi) e avisa Telegram + WhatsApp.
// Não recria transação que já existe nem a que o usuário excluiu permanentemente no dashboard.
// PIX enviado NÃO é gravado aqui: vai para a fila de aprovação (registrarPixPendente) e só
// entra em `transactions` quando o usuário aprova (skipApproval + silent, ver resolverPixPendente).
// Retorna { saved, alreadyExisted, deletedPermanently?, pendingApproval?, error?, ... }.
// Regra geral: transação de qualquer banco/Pluggy cujo texto (de quem manda ou de quem recebe)
// cite "Usuário 1 dos Passos" ou "User2" é dinheiro só mudando de lugar entre as próprias
// contas/família — não é entrada/saída real, então não é registrada nem notificada. Único ponto
// de checagem; todo caminho que salva ou notifica uma transação do Pluggy passa por aqui (ou
// chama esta função diretamente nos poucos lugares que notificam sem salvar).
// A mesma transação do Pluggy pode ter sido gravada com o id bruto (webhook antigo, antes de
// 22/09) ou com o prefixo do banco (extrato/polling). Exclusão e dedup precisam olhar TODAS as
// variantes, senão excluir uma deixa a outra livre para ser recriada pelo polling de 5 min.
const PREFIXOS_TX_BANCARIA = ['pluggy_sicredi_', 'pluggy_caixa_', 'neon_', MP_MAGAZINE_TX_PREFIX];
const REGEX_ID_PLUGGY = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
function variantesIdTransacaoBancaria(transactionId) {
  const id = String(transactionId || '');
  const prefixo = PREFIXOS_TX_BANCARIA.find(p => id.startsWith(p));
  const bruto = prefixo ? id.slice(prefixo.length) : id;
  if (!prefixo && !REGEX_ID_PLUGGY.test(bruto)) return []; // não veio de banco (lançamento manual)
  return [bruto, ...PREFIXOS_TX_BANCARIA.map(p => p + bruto)];
}

const NOMES_TRANSFERENCIA_INTERNA = ['user1 rosa dos passos', 'user2'];
function ehTransferenciaInterna(descricao) {
  const d = String(descricao || '').toLowerCase();
  return NOMES_TRANSFERENCIA_INTERNA.some(nome => d.includes(nome));
}

// Transações que devem AVISAR (Telegram/WhatsApp/push) mas NÃO ser registradas em `transactions`.
// Qualquer resgate (caixinhas do Neon como "Reforma da casa"/"futuro nenem", poupança da Caixa…)
// é dinheiro voltando pra conta corrente, não receita real. Casa com e sem prefixo
// "[Conta Corrente]", maiúsculas ("RESGATE POUPANCA INTEGRAD") e o "Complemento de resgate".
const TEXTOS_SOMENTE_NOTIFICAR = ['resgate'];
function ehSomenteNotificar(descricao) {
  const d = String(descricao || '').toLowerCase();
  return TEXTOS_SOMENTE_NOTIFICAR.some(texto => d.includes(texto));
}

// Categoria fixa por palavra no título da transação do Pluggy (pedido de 20/10/2026). Vale para
// qualquer banco, porque todo caminho passa por salvarTransacaoBancaria. Comparação sem acento
// e sem maiúsculas; a primeira regra que casar ganha. Nomes iguais aos da tabela categories.
const CATEGORIA_POR_PALAVRA_PLUGGY = [
  { palavras: ['powernet'], categoria: 'Moradia' },
  { palavras: ['ferragem', 'construcao', 'solomar'], categoria: 'Moradia - Manutenção' },
  { palavras: ['ifood'], categoria: 'Alimentação' },
  { palavras: ['oliseski'], categoria: 'Remédio Thor e Gatos' },
  { palavras: ['combustivel', 'combistivel', 'ivan'], categoria: 'Gasolina' }
];
function categoriaPorPalavraPluggy(descricao) {
  const d = String(descricao || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  const regra = CATEGORIA_POR_PALAVRA_PLUGGY.find(r => r.palavras.some(p => new RegExp(`\\b${p}\\b`).test(d) || (p.length > 5 && d.includes(p))));
  return regra ? regra.categoria : null;
}

// 22/10/2026 (pedido do usuário): PIX para estabelecimento que o usuário já lançou à mão (ex.: "PIX enviado
// para BUENACINE DISTRIBUIDORA…" → Alimentação). Sem palavra fixa e com categoria genérica, usa a categoria
// mais usada nos lançamentos anteriores com o mesmo nome (ignorando os que também ficaram genéricos).
const CATEGORIAS_GENERICAS_PLUGGY = new Set(['transferencia', 'transfers', 'outros', 'outros gastos', 'outros rendimentos']);
const PALAVRAS_VAZIAS_NOME = new Set(['ltda', 'me', 'sa', 's', 'a', 'eireli', 'epp', 'de', 'da', 'do', 'das', 'dos', 'e', 'com', 'comercio']);
function nomeContraparteTransacao(descricao) {
  const d = String(descricao || '').replace(/^\[[^\]]*\]\s*/, '').replace(/\s*\(compra \d{2}\/\d{2}\)\s*$/i, '');
  const m = d.match(/pix\s+(?:enviado|recebido)(?:\s+(?:para|de))?\s+(.+)$/i) || d.match(/c[oó]digo\s+qr(?:\s+pix)?\s+(.+)$/i) ||
    d.match(/qr\s*pix\s+(.+)$/i) || d.match(/(?:recebimento|pagamento)\s+pix\s*\|?\s*(.+)$/i);
  return m ? m[1].replace(/^[\d./-]{8,}\s+/, '').trim() : null;   // Sicredi põe o CPF/CNPJ antes do nome
}
function palavrasDoNome(texto) {
  return normalizarTextoParaComparacaoDeCategoria(texto).replace(/[^a-z0-9 ]/g, ' ').split(/\s+/)
    .filter(p => p && !/^\d+$/.test(p) && !PALAVRAS_VAZIAS_NOME.has(p));
}
function categoriaPorHistoricoPluggy(descricao, type) {
  const nome = nomeContraparteTransacao(descricao);
  if (!nome) return null;
  const palavras = palavrasDoNome(nome);
  if (palavras.length < 2 || palavras.slice(0, 2).join(' ').length < 5) return null;
  const linhas = db.prepare('SELECT description, category FROM transactions WHERE type = ? AND lower(description) LIKE ?')
    .all(type, `%${palavras[0]}%`);
  const contagem = new Map();
  for (const l of linhas) {
    const cat = String(l.category || '');
    const catNorm = normalizarTextoParaComparacaoDeCategoria(cat);
    if (!cat || CATEGORIAS_GENERICAS_PLUGGY.has(catNorm) || catNorm.startsWith('transferencia')) continue;
    // 2ª palavra pelo começo: o banco corta o nome ("PKR COMERCIO DE ALIM")
    const ps = palavrasDoNome(l.description);
    const casa = ps.some((p, i) => p === palavras[0] && ps[i + 1] && (ps[i + 1].startsWith(palavras[1]) || palavras[1].startsWith(ps[i + 1])));
    if (!casa) continue;
    contagem.set(cat, (contagem.get(cat) || 0) + 1);
  }
  let melhor = null;
  for (const [cat, n] of contagem) if (!melhor || n > melhor[1]) melhor = [cat, n];
  return melhor ? melhor[0] : null;
}

// 06/11/2026: categorização por CNPJ via ReceitaWS + Groq. Quando a transação chega com categoria
// genérica e as regras por palavra/histórico não acham nada, consulta o CNPJ do recebedor (se PIX)
// na ReceitaWS para obter CNAE e nome fantasia, depois mapeia para a categoria do sistema.
// Cache em memória (cnpj -> { info, t }) + tabela cnpj_cache (durável, sobrevive a reinícios).
// Consulta na ReceitaWS no máximo 1 vez por mês por CNPJ; dado antigo só é trocado quando a consulta funciona.
const _cnpjCache = new Map();
const CNPJ_VALIDADE_MS = 30 * 24 * 60 * 60 * 1000;
function lerCnpjDoBanco(cnpj) {
  try {
    const row = db.prepare('SELECT dados, consultado_em FROM cnpj_cache WHERE cnpj = ?').get(cnpj);
    if (!row) return null;
    return { info: row.dados ? JSON.parse(row.dados) : null, t: Date.parse(row.consultado_em) || 0 };
  } catch (e) {
    return null;
  }
}
function memorizarCnpj(cnpj, info) {
  const agora = Date.now();
  _cnpjCache.set(cnpj, { info, t: agora });
  try {
    db.prepare(`INSERT INTO cnpj_cache (cnpj, dados, consultado_em) VALUES (?, ?, ?)
      ON CONFLICT(cnpj) DO UPDATE SET dados = excluded.dados, consultado_em = excluded.consultado_em`)
      .run(cnpj, info ? JSON.stringify(info) : null, new Date(agora).toISOString());
  } catch (e) {
    console.log(`⚠️ Cache de CNPJ não gravado (${cnpj}): ${e.message}`);
  }
  return info;
}
const CNAE_PARA_CATEGORIA = {
  '5611': 'Restaurante',    // Restaurantes e similares
  '5612': 'Restaurante',    // Serviços ambulantes de alimentação
  '4711': 'Rancho',         // Supermercados
  '4712': 'Rancho',         // Minimercados, mercearias
  '4721': 'Café ou Pão',    // Padaria, laticínio, doces, balas
  '4722': 'Rancho',         // Açougue
  '4723': 'Rancho',         // Peixaria
  '4724': 'Besteira',       // Bebidas
  '4729': 'Rancho',         // Produtos alimentícios em geral
  '4731': 'Gasolina',       // Combustíveis (postos)
  '4771': 'Farmácia',       // Farmácias e drogarias
  '4772': 'Saúde',          // Cosméticos, higiene
  '4781': 'Alimentação',    // Roupas e acessórios
  '4761': 'Eletrônico e acessórios',
  '4762': 'Eletrônico e acessórios',
  '8650': 'Saúde',          // Atividades de profissionais da saúde
  '8610': 'Saúde',          // Hospitais
  '8630': 'Saúde',          // Atividades de atenção ambulatorial
  '8690': 'Saúde',          // Atividades de atenção à saúde humana
  '9311': 'Academia',       // Gestão de instalações esportivas
  '9312': 'Academia',       // Clubes sociais, esportivos
  '9313': 'Academia',       // Atividades de condicionamento físico
  '8513': 'Educação',       // Ensino fundamental
  '8520': 'Educação',       // Ensino médio
  '8531': 'Educação',       // Educação superior
  '4781': 'Moda e Beleza',  // Vestuário e acessórios
  '4782': 'Moda e Beleza',  // Calçados e artigos de viagem
  '9603': 'Moda e Beleza',  // Cabeleireiros e atividades de estética
  '4784': 'Moradia - Manutenção', // Artigos ópticos
  '4744': 'Moradia - Manutenção', // Materiais de construção
  '4741': 'Moradia - Manutenção', // Tintas e materiais para pintura
  '4742': 'Moradia - Manutenção', // Material elétrico
  '4743': 'Moradia - Manutenção', // Vidros
  '5620': 'Alimentação',    // Serviços de catering/buffet/outros
};

function cnpjDaTransacao(pluggy) {
  if (!pluggy || !pluggy.paymentData) return null;
  const debito = pluggy.type === 'DEBIT' || (pluggy.type !== 'CREDIT' && pluggy.amount < 0);
  const parte = debito ? pluggy.paymentData.receiver : pluggy.paymentData.payer;
  if (!parte || !parte.documentNumber) return null;
  if (parte.documentNumber.type !== 'CNPJ') return null;
  return String(parte.documentNumber.value || '').replace(/\D/g, '');
}

// ReceitaWS limita a taxa (HTTP 429). Ao receber 429, pausa as consultas por 1 h
// em vez de martelar a API para cada transação; falhas transitórias não ficam em cache.
let _receitaPausadaAte = 0;
async function consultarCnpj(cnpj) {
  const memoria = _cnpjCache.get(cnpj);
  if (memoria && Date.now() - memoria.t < CNPJ_VALIDADE_MS) return memoria.info;
  const doBanco = lerCnpjDoBanco(cnpj);
  if (doBanco && Date.now() - doBanco.t < CNPJ_VALIDADE_MS) {
    _cnpjCache.set(cnpj, { info: doBanco.info, t: doBanco.t });
    return doBanco.info;
  }
  // Dado vencido: sem consulta funcionando, usa o que já está gravado em vez de ficar sem nada.
  const antigo = (doBanco && doBanco.info) || (memoria && memoria.info) || null;
  if (Date.now() < _receitaPausadaAte) return antigo;
  try {
    const resp = await axios.get(`https://receitaws.com.br/v1/cnpj/${cnpj}`, { timeout: 8000 });
    const d = resp.data;
    if (d.status === 'ERROR') return memorizarCnpj(cnpj, null);
    const enderecoParts = [d.logradouro, d.numero, d.complemento, d.bairro].filter(Boolean);
    const cidadeUf = [d.municipio, d.uf].filter(Boolean).join('/');
    const info = {
      cnpj,
      nome: d.nome || '',
      fantasia: d.fantasia || '',
      cnae: (d.atividade_principal && d.atividade_principal[0] && d.atividade_principal[0].code) || '',
      cnaeTxt: (d.atividade_principal && d.atividade_principal[0] && d.atividade_principal[0].text) || '',
      endereco: enderecoParts.join(', '),
      cidadeUf,
      cep: d.cep || '',
      situacao: d.situacao || '',
      tipo: d.tipo || '',
      abertura: d.abertura || '',
      telefone: d.telefone || '',
      email: d.email || ''
    };
    return memorizarCnpj(cnpj, info);
  } catch (e) {
    if (e.response?.status === 429) {
      _receitaPausadaAte = Date.now() + 60 * 60 * 1000;
      console.log('⚠️ ReceitaWS com limite de taxa (429): consultas pausadas por 1 h.');
    } else {
      console.log(`⚠️ ReceitaWS falhou para ${cnpj}: ${e.message}`);
    }
    return antigo;
  }
}

function categoriaPorCnae(codigo) {
  const prefixo = String(codigo || '').replace(/[^0-9]/g, '').slice(0, 4);
  return CNAE_PARA_CATEGORIA[prefixo] || null;
}

async function categoriaPorCnpjGroq(nomeFantasia, cnaeTxt, descricao) {
  if (!GROQ_API_KEY) return null;
  try {
    const cats = db.prepare("SELECT DISTINCT name FROM categories WHERE type='expense'").all().map(r => r.name);
    const resp = await groq.chat.completions.create({
      model: GROQ_FREE_FALLBACK_MODELS.medium[0],
      messages: [{
        role: 'user',
        content: `Categorize esta despesa. Responda APENAS o nome exato da categoria, nada mais.\n\nEstabelecimento: ${nomeFantasia}\nRamo: ${cnaeTxt}\nTransação: ${descricao}\n\nCategorias: ${cats.join(', ')}\n\nCategoria:`
      }],
      temperature: 0,
      max_tokens: 20
    });
    const sugestao = String(resp.choices[0].message.content || '').trim();
    const existe = cats.find(c => normalizarTextoParaComparacaoDeCategoria(c) === normalizarTextoParaComparacaoDeCategoria(sugestao));
    return existe || null;
  } catch (e) {
    console.log(`⚠️ Groq categorizarCNPJ falhou: ${e.message}`);
    return null;
  }
}

async function categoriaPorCnpjPluggy(pluggy, description) {
  const cnpj = cnpjDaTransacao(pluggy);
  if (!cnpj) return null;
  const info = await consultarCnpj(cnpj);
  if (!info) return null;
  const porCnae = categoriaPorCnae(info.cnae);
  if (porCnae) {
    console.log(`🏢 CNPJ ${cnpj} → ${info.fantasia || info.nome} (${info.cnaeTxt}) → ${porCnae}`);
    return porCnae;
  }
  const porGroq = await categoriaPorCnpjGroq(info.fantasia || info.nome, info.cnaeTxt, description);
  if (porGroq) {
    console.log(`🏢🤖 CNPJ ${cnpj} → ${info.fantasia || info.nome} (${info.cnaeTxt}) → Groq: ${porGroq}`);
    return porGroq;
  }
  return null;
}

function trocarNomeFantasiaNoTitulo(description, nomeOriginal, nomeFantasia) {
  if (!nomeFantasia || !nomeOriginal) return description;
  const fantNorm = nomeFantasia.trim().toUpperCase();
  const origNorm = nomeOriginal.trim().toUpperCase();
  if (fantNorm === origNorm || !fantNorm) return description;
  const idx = description.toUpperCase().indexOf(origNorm);
  if (idx === -1) return description;
  return description.slice(0, idx) + nomeFantasia.trim().toUpperCase() + description.slice(idx + nomeOriginal.length);
}

async function enriquecerTransacaoComCnpj(pluggy, description) {
  const cnpj = cnpjDaTransacao(pluggy);
  if (!cnpj) return { description, cnpjInfo: null };
  const info = await consultarCnpj(cnpj);
  if (!info || !info.fantasia) return { description, cnpjInfo: info };
  const debito = pluggy.type === 'DEBIT' || (pluggy.type !== 'CREDIT' && pluggy.amount < 0);
  const parte = debito ? pluggy.paymentData.receiver : pluggy.paymentData.payer;
  const nomeOriginal = parte && parte.name;
  const novaDesc = trocarNomeFantasiaNoTitulo(description, nomeOriginal, info.fantasia);
  if (novaDesc !== description) console.log(`🏷️ Título: "${nomeOriginal}" → "${info.fantasia.toUpperCase()}"`);
  return { description: novaDesc, cnpjInfo: info };
}

// Item 15: normaliza o nome da categoria ANTES de gravar, não só depois (como o
// normalizeCafeCategoriesInDb fazia só pra "Café ou Pão"). Ignora acento, emoji e espaço
// duplicado na comparação — se já existe uma categoria "igual" na prática, reaproveita o nome
// dela em vez de deixar nascer mais uma variante (foi assim que "Café ou Pão" virou 5 nomes).
function normalizarTextoParaComparacaoDeCategoria(texto) {
  return String(texto || '')
    .normalize('NFKD').replace(/[̀-ͯ]/g, '') // remove acentos
    .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}️]/gu, '') // remove emoji
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

let _categoriasConhecidasCache = null;
let _categoriasConhecidasCacheAt = 0;
function normalizarNomeCategoria(nomeCategoria) {
  try {
    if (!db || !nomeCategoria) return nomeCategoria;
    if (!_categoriasConhecidasCache || Date.now() - _categoriasConhecidasCacheAt > 5 * 60 * 1000) {
      _categoriasConhecidasCache = db.prepare(`SELECT DISTINCT name FROM categories`).all().map(r => r.name);
      _categoriasConhecidasCacheAt = Date.now();
    }
    const alvo = normalizarTextoParaComparacaoDeCategoria(nomeCategoria);
    if (!alvo) return nomeCategoria;
    const existente = _categoriasConhecidasCache.find(nome => normalizarTextoParaComparacaoDeCategoria(nome) === alvo);
    return existente || nomeCategoria;
  } catch (_) {
    return nomeCategoria;
  }
}

// Avisa Telegram + WhatsApp + push de uma transação que chegou do banco. `registrada: false`
// é usado nas transações só-aviso (ehSomenteNotificar), que não vão para `transactions`.
async function notificarTransacaoBancaria({ banco, txId, description, amount, type, category, paymentMethod, date, notifyUserName, registrada = true, receipt_image, cnpjInfo }) {
    if (!receipt_image && registrada) {
        const row = db.prepare('SELECT receipt_image FROM transactions WHERE transaction_id = ?').get(txId);
        if (row && row.receipt_image) receipt_image = row.receipt_image;
    }
    const dadosNotificacao = {
        description,
        amount,
        type,
        category,
        paymentMethod,
        userName: notifyUserName,
        user: 'user1',
        date,
        transactionId: txId,
        registrada,
        receipt_image,
        cnpjInfo,
        note: registrada
            ? linhaFaturaOuSaldo({ type, paymentMethod, date, user: 'user1' })
            : 'ℹ️ Apenas aviso — NÃO registrada no sistema'
    };

    try {
        await notificarTelegram(dadosNotificacao);
    } catch (tgError) {
        console.error(`❌ Erro ao enviar Telegram da transação ${banco} ${txId}:`, tgError.message);
    }

    try {
        await notificarTransacaoWhatsApp(registrada ? dadosNotificacao : {
            ...dadosNotificacao,
            description: `${description} (apenas aviso, não registrada)`
        });
    } catch (waError) {
        console.error(`❌ Erro ao enviar WhatsApp da transação ${banco} ${txId}:`, waError.message);
    }

    // Item 5: a infraestrutura de push já existia (sendWebPushToUser, tabela
    // push_subscriptions, chaves VAPID) mas só era usada no lançamento manual e na
    // fila de aprovação de PIX — nunca nas transações que chegam sozinhas dos bancos
    // (cron de 5 min / webhook), que são a maioria. Mesmo formato de payload já usado
    // no lançamento manual, pro Service Worker não precisar de nada novo.
    if (WEB_PUSH_ENABLED) {
        try {
            const isExpense = type === 'expense';
            const titulo = !registrada
                ? (isExpense ? 'Nova despesa (não registrada)' : 'Nova receita (não registrada)')
                : (isExpense ? 'Nova despesa registrada' : 'Nova receita registrada');
            await sendWebPushToUser(SHARED_LEDGER_OWNER || 'user1', {
                title: titulo,
                body: `${description || 'Sem descrição'} • ${formatBRL(amount)}`,
                url: '/',
                icon: '/pwa/icon-192.png',
                badge: '/pwa/icon-192.png',
                transactionId: txId
            });
        } catch (pushError) {
            console.error(`❌ Erro ao enviar push da transação ${banco} ${txId}:`, pushError.message);
        }
    }
}

// Comprovante em imagem gerado com os dados do Pluggy (comprovante-pluggy.js). Falha aqui nunca impede
// a transação de ser gravada: ela só fica sem comprovante.
async function anexarComprovantePluggy({ banco, txId, description, amount, type, date, paymentMethod, pluggy, cnpjInfo }) {
    try {
        const fileName = await saveReceiptFile(gerarComprovanteSvg({ banco, txId, description, amount, type, date, paymentMethod, pluggy, cnpjInfo }), description, 'image');
        if (fileName) {
            db.prepare("UPDATE transactions SET receipt_image = ? WHERE transaction_id = ? AND (receipt_image IS NULL OR receipt_image = '')").run(fileName, txId);
        }
        return fileName;
    } catch (e) {
        console.error(`⚠️ Comprovante não gerado (${txId}):`, e.message);
        return null;
    }
}

const PREFIXOS_TX_PLUGGY = [
    { prefixo: 'pluggy_sicredi_', banco: 'Sicredi' },
    { prefixo: 'pluggy_caixa_', banco: 'Caixa' },
    { prefixo: 'neon_', banco: 'Neon' },
    { prefixo: MP_MAGAZINE_TX_PREFIX, banco: MP_MAGAZINE_NOME }
];

// Transações do Pluggy gravadas antes do comprovante automático (22/10/2026). Busca os detalhes na API
// (pagador/recebedor do PIX); a Pluggy só guarda transações recentes, então as antigas (404) saem
// com os dados que estão no banco.
async function gerarComprovantesPluggyFaltantes() {
    const onde = PREFIXOS_TX_PLUGGY.map(() => 'transaction_id LIKE ?').join(' OR ');
    const linhas = db.prepare(
        `SELECT transaction_id, description, amount, type, payment_method, date FROM transactions
         WHERE (${onde}) AND (receipt_image IS NULL OR receipt_image = '')`
    ).all(...PREFIXOS_TX_PLUGGY.map((p) => `${p.prefixo}%`));
    if (!linhas.length) return { gerados: 0, comDetalhes: 0 };
    let apiKey = null;
    try { apiKey = await getPluggyApiKey(); } catch (e) {}
    let gerados = 0, comDetalhes = 0;
    for (const t of linhas) {
        const origem = PREFIXOS_TX_PLUGGY.find((p) => t.transaction_id.startsWith(p.prefixo));
        let pluggy = null;
        if (apiKey) {
            try {
                const r = await axios.get(`${PLUGGY_API_URL}/transactions/${t.transaction_id.slice(origem.prefixo.length)}`, { headers: { 'X-API-KEY': apiKey }, timeout: 15000 });
                pluggy = r.data;
                comDetalhes++;
            } catch (e) {}
        }
        let cnpjInfo = null;
        if (pluggy) {
            const cnpj = cnpjDaTransacao(pluggy);
            if (cnpj) cnpjInfo = await consultarCnpj(cnpj);
        }
        const arquivo = await anexarComprovantePluggy({
            banco: origem.banco, txId: t.transaction_id, description: t.description, amount: Number(t.amount),
            type: t.type, date: t.date, paymentMethod: t.payment_method, pluggy, cnpjInfo
        });
        if (arquivo) gerados++;
    }
    console.log(`🧾 Comprovantes Pluggy gerados: ${gerados} de ${linhas.length} (${comDetalhes} com detalhes da API)`);
    return { gerados, comDetalhes, total: linhas.length };
}

async function salvarTransacaoBancaria({ banco, txId, description, amount, type, category, paymentMethod, date, userName, notifyUserName = userName, logLabel = banco, skipApproval = false, silent = false, exigeAprovacao = null, pluggy = null }) {
    try {
        if (ehTransferenciaInterna(description)) {
            console.log(`⏭️ [${logLabel}] Ignorada (transferência interna): ${description}`);
            return { saved: false, alreadyExisted: false, skippedInternalTransfer: true };
        }

        let cnpjInfo = null;
        if (pluggy) {
            const enriquecido = await enriquecerTransacaoComCnpj(pluggy, description);
            description = enriquecido.description;
            cnpjInfo = enriquecido.cnpjInfo;
        }

        const categoriaFixa = categoriaPorPalavraPluggy(description);
        if (!categoriaFixa && CATEGORIAS_GENERICAS_PLUGGY.has(normalizarTextoParaComparacaoDeCategoria(category))) {
            category = categoriaPorHistoricoPluggy(description, type) || category;
        }
        if (!categoriaFixa && CATEGORIAS_GENERICAS_PLUGGY.has(normalizarTextoParaComparacaoDeCategoria(category)) && pluggy) {
            const porCnpj = await categoriaPorCnpjPluggy(pluggy, description);
            if (porCnpj) category = porCnpj;
        }
        category = normalizarNomeCategoria(categoriaFixa || category);

        const foiExcluidaPermanentemente = db.prepare(
            'SELECT 1 FROM deleted_bank_transactions WHERE transaction_id = ?'
        ).get(txId);
        if (foiExcluidaPermanentemente) {
            return { saved: false, alreadyExisted: false, deletedPermanently: true };
        }

        const variantes = variantesIdTransacaoBancaria(txId);
        const idsParaChecar = variantes.length ? variantes : [txId];
        const marcadores = idsParaChecar.map(() => '?').join(', ');
        const foiExcluidaEmOutraVariante = db.prepare(
            `SELECT 1 FROM deleted_bank_transactions WHERE transaction_id IN (${marcadores}) LIMIT 1`
        ).get(...idsParaChecar);
        if (foiExcluidaEmOutraVariante) {
            return { saved: false, alreadyExisted: false, deletedPermanently: true };
        }

        const existe = db.prepare(
            `SELECT COUNT(*) as count FROM transactions WHERE transaction_id IN (${marcadores})`
        ).get(...idsParaChecar).count;
        if (existe > 0) {
            return { saved: false, alreadyExisted: true };
        }

        if (ehSomenteNotificar(description)) {
            const jaNotificada = db.prepare(
                'INSERT OR IGNORE INTO bank_transactions_somente_notificadas (transaction_id, description) VALUES (?, ?)'
            ).run(txId, description).changes === 0;
            if (jaNotificada) {
                return { saved: false, alreadyExisted: true, notifyOnly: true };
            }
            console.log(`🔔 [${logLabel}] Só notificada (não registrada): ${description} - R$ ${amount.toFixed(2)} (${type})`);
            if (!silent) {
                await notificarTransacaoBancaria({
                    banco, txId, description, amount, type, category, paymentMethod, date, notifyUserName,
                    registrada: false
                });
            }
            return { saved: false, alreadyExisted: false, notifyOnly: true };
        }

        const precisaAprovacao = exigeAprovacao === null ? descricaoIndicaPixEnviado(description) : exigeAprovacao;
        if (!skipApproval && type === 'expense' && precisaAprovacao) {
            const pendente = await registrarPixPendente({
                banco, txId, description, amount, type, category, paymentMethod, date, userName, notifyUserName, logLabel
            });
            return { saved: false, alreadyExisted: false, pendingApproval: true, ...pendente };
        }

        const hasUserId = tableHasColumn('transactions', 'user_id');
        const ledgerUserId = hasUserId ? getUserIdByUsername('user1') : null;

        const insertStmt = db.prepare(`
            INSERT INTO transactions
            (transaction_id, description, amount, type, category, payment_method, date, user, user_name, created_at${hasUserId ? ', user_id' : ''})
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?${hasUserId ? ', ?' : ''})
        `);

        const resultado = insertStmt.run(
            txId,
            description,
            amount,
            type,
            category,
            paymentMethod,
            date,
            'user1',
            userName,
            moment().toISOString(),
            ...(hasUserId ? [Number.isFinite(Number(ledgerUserId)) ? Number(ledgerUserId) : null] : [])
        );

        if (resultado.changes > 0) {
            console.log(`${type === 'income' ? '💰' : '💸'} [${logLabel}] Salva: ${description} - R$ ${amount.toFixed(2)} (${type})`);
            await anexarComprovantePluggy({ banco, txId, description, amount, type, date, paymentMethod, pluggy, cnpjInfo });

            // Notifica Telegram + WhatsApp no mesmo formato que o webhook usaria — o polling do
            // /extrato pode ser a única forma de saber de uma transação nova (webhook fora do ar).
            // `silent` é usado na aprovação de um PIX enviado: o usuário acabou de decidir, então
            // não faz sentido avisar de novo.
            if (!silent) {
                await notificarTransacaoBancaria({
                    banco, txId, description, amount, type, category, paymentMethod, date, notifyUserName,
                    registrada: true, cnpjInfo
                });

                if (type === 'expense') {
                    try { await verificarOrcamentoCategoria(category); } catch (e) {}
                }
            }

            return { saved: true, alreadyExisted: false, type, descricao: description, valor: amount, dataFormatada: date };
        }
        return { saved: false, alreadyExisted: false };
    } catch (error) {
        console.error(`❌ Erro ao salvar transação ${banco} ${txId}:`, error.message);
        return { saved: false, alreadyExisted: false, error: error.message };
    }
}

async function salvarTransacaoSicredi(transacao, accountType) {
    try {
        const finalType = transacao.type === 'CREDIT' ? 'income' : 'expense';
        return await salvarTransacaoBancaria({
            banco: 'Sicredi',
            logLabel: `Sicredi - ${accountType}`,
            txId: `pluggy_sicredi_${transacao.id}`,
            description: transacao.description || (finalType === 'income' ? `Entrada Sicredi ${accountType}` : `Saída Sicredi ${accountType}`),
            amount: Math.abs(transacao.amount),
            type: finalType,
            category: finalType === 'income' ? 'Outros Rendimentos' : 'Outros',
            paymentMethod: `Sicredi ${accountType}`,
            date: transacao.date ? moment(transacao.date).format('YYYY-MM-DD') : moment().format('YYYY-MM-DD'),
            userName: 'Sistema Sicredi',
            exigeAprovacao: pixEnviadoPrecisaAprovacao(transacao),
            pluggy: transacao
        });
    } catch (error) {
        console.error(`❌ Erro ao salvar transação Sicredi ${transacao && transacao.id}:`, error.message);
        return { saved: false, alreadyExisted: false, error: error.message };
    }
}

