// Mercado Pago - Magazine: por pedido do usuário, TODAS as transações da conta são registradas
// (diferente de Sicredi/Neon, onde só o PIX enviado é persistido). Mesmo padrão de segurança:
// INSERT com dedup pelo ID real da Pluggy, respeito às exclusões permanentes e PIX enviado
// (transferências) passando pela fila de aprovação. Pagamento por QR Pix é gravado direto.
function classificarTransacaoMercadoPago(t) {
    const desc = String(t.description || '').toLowerCase();
    const op = String(t.operationType || '');
    const viaPix = op === 'PIX' || (t.paymentData && t.paymentData.paymentMethod === 'PIX');
    const credito = t.type === 'CREDIT';
    const type = credito ? 'income' : 'expense';

    // Rendimento, empréstimo e estorno ganham categoria própria para não inflar receitas/despesas comuns
    if (/aplic_financeira/i.test(op) || desc.startsWith('rendimentos')) return { type, category: 'Rendimentos' };
    if (op === 'OPERACAO_CREDITO' || desc.includes('empréstimo') || desc.includes('emprestimo')) return { type, category: 'Empréstimos' };
    if (credito && (desc.includes('estorno') || desc.includes('reembolso'))) return { type, category: 'Estorno' };
    if (viaPix && (desc.includes('user1') || desc.includes('user2'))) return { type, category: 'Transferência entre contas' };
    return { type, category: credito ? 'Outros Rendimentos' : 'Outros Gastos' };
}

// Compra no cartão = qualquer débito da conta (Mercado Livre, Google, PIX enviado, QR Pix, boleto,
// débito de empréstimo…). PIX enviado também entra na data da fatura (a conta é um cartão), mas
// continua passando pela aprovação (ver exigeAprovacao em salvarTransacaoMercadoPagoMagazine).
// Créditos (estorno, empréstimo recebido, rendimento, PIX recebido) ficam na data real.
function ehCompraNoCartaoMercadoPago(transacao) {
    const isDebito = transacao.type === 'DEBIT' || (transacao.type !== 'CREDIT' && transacao.amount < 0);
    return isDebito;
}

// Data de lançamento na fatura do cartão. Ciclo: dia 5 (abre) até dia 4 do mês seguinte (fecha).
//  • compra no dia 5 ou depois -> dia 5 do mês seguinte (ex.: 15/09 -> 05/10)
//  • compra do dia 1 ao 4       -> dia 5 do próprio mês  (ex.: 02/09 -> 05/09, ainda no ciclo que fecha dia 4)
// Usa o dia da própria transação no fuso de São Paulo (não a hora em que o polling a encontrou).
function dataFaturaMercadoPagoMagazine(dataTransacao) {
    const compra = dataTransacao ? moment(dataTransacao) : moment();
    const fatura = compra.clone().startOf('day').date(MP_MAGAZINE_DIA_FATURA);
    if (compra.date() >= MP_MAGAZINE_DIA_FATURA) fatura.add(1, 'month');
    return fatura.format('YYYY-MM-DD');
}

// importacaoHistorica: uso manual e pontual (backfill). Grava direto, sem passar pela fila de
// aprovação de PIX enviado (a aprovação foi dada em lote pelo usuário) e sem notificar
// Telegram/WhatsApp/PWA por cada lançamento antigo.
async function salvarTransacaoMercadoPagoMagazine(transacao, { importacaoHistorica = false } = {}) {
    try {
        const { type, category } = classificarTransacaoMercadoPago(transacao);
        const dataCompra = transacao.date ? moment(transacao.date) : moment();
        let descricao = `[${MP_MAGAZINE_NOME}] ${transacao.description || (type === 'income' ? 'Entrada' : 'Saída')}`;
        let data = dataCompra.format('YYYY-MM-DD');

        // Compra no cartão vai para a data da fatura. O dia real da compra fica na descrição, já que a
        // tabela só guarda uma data.
        if (ehCompraNoCartaoMercadoPago(transacao)) {
            data = dataFaturaMercadoPagoMagazine(transacao.date);
            descricao += ` (compra ${dataCompra.format('DD/MM')})`;
        }

        return await salvarTransacaoBancaria({
            banco: MP_MAGAZINE_NOME,
            logLabel: MP_MAGAZINE_NOME,
            txId: `${MP_MAGAZINE_TX_PREFIX}${transacao.id}`,
            description: descricao,
            amount: Math.abs(transacao.amount),
            type,
            category,
            paymentMethod: MP_MAGAZINE_NOME,
            date: data,
            userName: 'Sistema Mercado Pago',
            exigeAprovacao: pixEnviadoPrecisaAprovacao(transacao),
            skipApproval: importacaoHistorica,
            silent: importacaoHistorica,
            pluggy: transacao
        });
    } catch (error) {
        console.error(`❌ Erro ao salvar transação ${MP_MAGAZINE_NOME} ${transacao && transacao.id}:`, error.message);
        return { saved: false, alreadyExisted: false, error: error.message };
    }
}

// Registra todas as transações do Mercado Pago - Magazine de uma lista já buscada (chamada por
// buscarTransacoesBancariasRaw: /extrato do Telegram, botão "Extratos" do dashboard e polling de 5 min).
async function salvarTransacoesMercadoPagoDoExtrato(transacoes) {
    let salvas = 0;
    let naFila = 0;
    for (const t of (transacoes || [])) {
        if (t.banco !== MP_MAGAZINE_NOME) continue;
        const resultado = await salvarTransacaoMercadoPagoMagazine(t);
        if (resultado.saved) salvas++;
        else if (resultado.pendingApproval && !resultado.alreadyPending) naFila++;
    }
    if (salvas > 0 || naFila > 0) {
        console.log(`🟦 [${MP_MAGAZINE_NOME}] ${salvas} transação(ões) registrada(s), ${naFila} PIX enviado(s) aguardando aprovação.`);
    }
    return salvas;
}

// Mesmo padrão do MP Magazine (salva TUDO a cada 5 min, não só PIX enviado como o Sicredi) —
// a Caixa é nova no sistema, então já entra com cobertura completa em vez de herdar o mesmo
// gap do Sicredi (que só é salvo por completo no boot ou no /verificaragora manual).
async function salvarTransacoesSicrediDoExtrato(transacoes) {
    let salvas = 0;
    let naFila = 0;
    for (const t of (transacoes || [])) {
        if (t.banco !== 'Sicredi') continue;
        const resultado = await salvarTransacaoSicredi(t, t.conta || 'Conta Corrente');
        if (resultado.saved) salvas++;
        else if (resultado.pendingApproval && !resultado.alreadyPending) naFila++;
    }
    if (salvas > 0 || naFila > 0) {
        console.log(`🏦 [Sicredi] ${salvas} transação(ões) registrada(s), ${naFila} PIX enviado(s) aguardando aprovação.`);
    }
    return salvas;
}

async function salvarTransacoesCaixaDoExtrato(transacoes) {
    let salvas = 0;
    let naFila = 0;
    for (const t of (transacoes || [])) {
        if (t.banco !== 'Caixa') continue;
        const resultado = await salvarTransacaoCaixa(t, t.conta || 'Conta Corrente');
        if (resultado.saved) salvas++;
        else if (resultado.pendingApproval && !resultado.alreadyPending) naFila++;
    }
    if (salvas > 0 || naFila > 0) {
        console.log(`🏛️ [Caixa] ${salvas} transação(ões) registrada(s), ${naFila} PIX enviado(s) aguardando aprovação.`);
    }
    return salvas;
}

// ============== ECHO DOT: FALA QUANDO CHEGA TRANSAÇÃO NOVA ==============
// Reaproveita o webhook do Home Assistant do bot de WhatsApp (HA_WEBHOOK_URL, sem porta: a 8123 não
// responde a partir do notebook). O HA monta a frase "<contato> <mensagem>" para tipo != "texto",
// então sai algo como: "Financeiro detectou uma nova despesa: Pagamento Google, 110 reais."
// Desligar só esta função: ECHO_FINANCEIRO=off no .env (o bot de WhatsApp não é afetado).
// Quem detecta é o polling do extrato (a cada 5 min): fala o que ainda não tinha visto. A primeira leitura
// de cada banco é silenciosa (linha de base), senão as transações antigas seriam faladas de uma vez.
const ECHO_FINANCEIRO_URL = String(process.env.HA_WEBHOOK_URL || '').trim();
const ECHO_FINANCEIRO_ATIVA = Boolean(ECHO_FINANCEIRO_URL) && !/^(off|false|0|nao|não)$/i.test(String(process.env.ECHO_FINANCEIRO || '').trim());
const ECHO_FINANCEIRO_MAX_POR_CICLO = 3;       // acima disso vira um resumo ("detectou N novas transações")
const ECHO_FINANCEIRO_MAX_IDADE_DIAS = 3;      // transação mais antiga que isso é só marcada como vista, sem falar
const ECHO_FINANCEIRO_BANCOS = { Sicredi: 'sicredi', Neon: 'neon', [MP_MAGAZINE_NOME]: 'mp', Caixa: 'caixa' };

// 51,91 -> "51 reais e 91 centavos" (mais confiável para a Alexa do que "R$ 51,91")
function valorParaFala(valor) {
    const totalCentavos = Math.round(Math.abs(Number(valor) || 0) * 100);
    const reais = Math.floor(totalCentavos / 100);
    const centavos = totalCentavos % 100;
    const partes = [];
    if (reais > 0 || centavos === 0) partes.push(`${reais} ${reais === 1 ? 'real' : 'reais'}`);
    if (centavos > 0) partes.push(`${centavos} ${centavos === 1 ? 'centavo' : 'centavos'}`);
    return partes.join(' e ');
}

// Tira o "[Mercado Pago - Magazine]" da frente e o "(compra 13/09)" do fim, que só servem para leitura na tela.
function tituloParaFala(descricao) {
    const limpo = String(descricao || '')
        .replace(/^\s*\[[^\]]*\]\s*/, '')
        .replace(/\s*\(compra \d\d\/\d\d\)\s*$/, '')
        .replace(/\s+/g, ' ')
        .trim()
        .slice(0, 100);
    return limpo || 'sem descrição';
}

// Fica de fora: caixinhas do Neon (movimentação interna) e aplicação/resgate/rendimento (inclui os R$ 0,01 diários).
function transacaoRelevanteParaEcho(t) {
    if (t.accountType === 'FIXED_INCOME') return false;
    if (/APLIC_FINANCEIRA/i.test(String(t.operationType || ''))) return false;
    return Math.abs(Number(t.amount)) > 0;
}

async function falarNaEcho(mensagem, contato = 'Financeiro') {
    const resposta = await fetch(ECHO_FINANCEIRO_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ contato, mensagem, tipo: 'midia' }),
        signal: AbortSignal.timeout(5000)
    });
    if (!resposta.ok) throw new Error(`Home Assistant respondeu HTTP ${resposta.status}`);
}

// `bancosConsultados`: só os bancos cuja busca deu certo agora (banco com falha não entra na linha de base).
async function anunciarNovasTransacoesNaEcho(transacoes, bancosConsultados) {
    if (!ECHO_FINANCEIRO_ATIVA) return 0;
    const marcar = db.prepare('INSERT OR IGNORE INTO echo_transacoes_vistas (transaction_id) VALUES (?)');
    const desmarcar = db.prepare('DELETE FROM echo_transacoes_vistas WHERE transaction_id = ?');
    const temLinhaDeBase = db.prepare('SELECT 1 FROM echo_transacoes_vistas WHERE transaction_id = ?');
    const chave = (banco, t) => `${ECHO_FINANCEIRO_BANCOS[banco]}_${t.id}`;
    const novas = [];

    for (const banco of bancosConsultados) {
        if (!ECHO_FINANCEIRO_BANCOS[banco]) continue;
        const lista = (transacoes || []).filter(t => t.banco === banco && t.id);
        const marcaBase = `__baseline__${banco}`;

        if (!temLinhaDeBase.get(marcaBase)) {
            if (lista.length === 0) continue;      // sem nenhuma transação não dá para saber o que já existia
            db.transaction(() => {
                for (const t of lista) marcar.run(chave(banco, t));
                marcar.run(marcaBase);
            })();
            console.log(`🔇 [Echo] Linha de base de ${banco}: ${lista.length} transação(ões) já existentes, nada falado.`);
            continue;
        }

        for (const t of lista) {
            // O INSERT OR IGNORE é atômico: se dois processos leem o extrato ao mesmo tempo, só um "ganha" e fala.
            if (marcar.run(chave(banco, t)).changes === 0) continue;
            if (!transacaoRelevanteParaEcho(t)) continue;
            if (moment().diff(moment(t.date), 'days') > ECHO_FINANCEIRO_MAX_IDADE_DIAS) continue;
            novas.push({ banco, t });
        }
    }
    if (novas.length === 0) return 0;

    let falas;
    if (novas.length > ECHO_FINANCEIRO_MAX_POR_CICLO) {
        falas = [{ mensagem: `detectou ${novas.length} novas transações`, itens: novas }];
    } else {
        falas = novas.map(({ banco, t }) => {
            const despesa = t.type === 'DEBIT' || (t.type !== 'CREDIT' && t.amount < 0);
            const aguardando = pixEnviadoPrecisaAprovacao(t) ? ' Aguardando a sua aprovação.' : '';
            return {
                mensagem: `detectou uma nova ${despesa ? 'despesa' : 'receita'}: ${tituloParaFala(t.description)}, ${valorParaFala(t.amount)}.${aguardando}`,
                itens: [{ banco, t }]
            };
        });
    }

    let faladas = 0;
    for (const fala of falas) {
        try {
            await falarNaEcho(fala.mensagem);
            faladas++;
        } catch (err) {
            // Não conseguiu falar: desmarca para tentar de novo no próximo ciclo (a regra de idade evita falar coisa velha).
            for (const { banco, t } of fala.itens) desmarcar.run(chave(banco, t));
            console.error(`❌ [Echo] Não consegui falar (${err.message}); tento de novo no próximo ciclo.`);
        }
    }
    if (faladas > 0) console.log(`🔊 [Echo] ${faladas} aviso(s) de transação nova enviado(s) ao Home Assistant.`);
    return faladas;
}

// Lançamento manual (dashboard, Telegram, foto/OCR): fala na hora, com o primeiro nome de quem lançou
// ("User1 lançou uma nova despesa: Mercado, 50 reais."). Não passa pelo polling nem pela tabela de "já vistas".
// Chamada sem await em addTransaction: se o Home Assistant estiver fora, o salvamento não atrasa nem falha.
function primeiroNomeParaFala(t) {
    return String((t && (t.userName || t.user)) || '').trim().split(/\s+/)[0] || 'Financeiro';
}

async function falarLancamentoManualNaEcho(t) {
    if (!ECHO_FINANCEIRO_ATIVA) return;
    const tipo = t.type === 'income' ? 'receita' : 'despesa';
    await falarNaEcho(`lançou uma nova ${tipo}: ${tituloParaFala(t.description)}, ${valorParaFala(t.amount)}.`, primeiroNomeParaFala(t));
}

// Compra parcelada gera N lançamentos: em vez de N falas, uma só.
async function falarParceladoNaEcho({ userName, descricao, parcelas, total }) {
    if (!ECHO_FINANCEIRO_ATIVA) return;
    await falarNaEcho(`lançou uma compra parcelada: ${tituloParaFala(descricao)}, em ${parcelas} parcelas, total de ${valorParaFala(total)}.`, primeiroNomeParaFala({ userName }));
}

// "Rendimento diário estimado" do relatório CDI das 18:58 (o mesmo valor que sai no Telegram/WhatsApp; é uma
// estimativa líquida de IR, não algo já realizado). Sai como: "Investimento CDI tem rendimento diário estimado de 11 centavos."
// O valor falado é lido do PRÓPRIO formatBRL que escreve o relatório ("R$ 1.234,56" -> 1234.56), para a Echo nunca
// dizer algo diferente do que está escrito: toFixed/Math.round arredondam pelo valor binário e divergem do
// formatBRL em casos como 1,355 (relatório "R$ 1,36", toFixed diria 35 centavos).
function valorComoNoRelatorio(valor) {
    return Number(String(formatBRL(valor)).replace(/[^\d,]/g, '').replace(',', '.'));
}

async function falarRendimentoCDINaEcho(rendimentoDiarioEstimado) {
    if (!ECHO_FINANCEIRO_ATIVA) return;
    const valor = valorComoNoRelatorio(rendimentoDiarioEstimado);
    if (!Number.isFinite(valor) || valor < 0.01) return;   // menos de 1 centavo: não há o que falar
    await falarNaEcho(`tem rendimento diário estimado de ${valorParaFala(valor)}.`, 'Investimento CDI');
}

// 4c. Detecta se uma transação (Sicredi ou Neon) é um "PIX enviado". Esse tipo de
// transação nunca é gravado automaticamente: vai para a fila de aprovação
// (pending_pix_transactions) e o usuário decide, pelo Telegram ou pelo dashboard,
// se grava em `transactions` ou descarta (ver registrarPixPendente/resolverPixPendente).
function descricaoIndicaPixEnviado(descricao) {
    const desc = String(descricao || '').toLowerCase();
    return desc.includes('pix') && desc.includes('enviad');
}

// Débito que a Pluggy classifica como PIX (operationType/paymentMethod) OU cuja descrição diz
// "pix enviado". Só o texto não basta: o Mercado Pago escreve "Pagamento com QR Pix <loja>",
// que é PIX de saída mas não contém "enviado".
function ehPixEnviado(transacao) {
    const isDebito = transacao.type === 'DEBIT' || (transacao.type !== 'CREDIT' && transacao.amount < 0);
    if (!isDebito) return false;
    const viaPix = transacao.operationType === 'PIX' || (transacao.paymentData && transacao.paymentData.paymentMethod === 'PIX');
    return Boolean(viaPix) || descricaoIndicaPixEnviado(transacao.description);
}

// Pagamento por QR Pix ("Pagamento com QR Pix <loja>", "Pagamento com Código QR Pix …"): por pedido
// do usuário é gravado automaticamente, sem passar pela aprovação. Só o texto identifica isso — a Pluggy
// não tem campo próprio para QR, e o Neon descreve todo PIX de saída como "PIX enviado para <nome>"
// (então para o Neon nada é tratado como QR). "Pagamento com código QR <loja>" (sem a palavra Pix) não é PIX.
function ehPixQr(transacao) {
    const isDebito = transacao.type === 'DEBIT' || (transacao.type !== 'CREDIT' && transacao.amount < 0);
    return isDebito && /\bqr\s*pix\b/i.test(String(transacao.description || ''));
}

// PIX enviado que exige aprovação manual: todo PIX de saída, exceto pagamento por QR Pix.
function pixEnviadoPrecisaAprovacao(transacao) {
    return ehPixEnviado(transacao) && !ehPixQr(transacao);
}

// Envia para a fila de aprovação os "PIX enviado" de uma lista já buscada (Sicredi + Neon),
// chamada a partir de buscarTransacoesBancariasRaw — ou seja, toda vez que o /extrato roda
// (Telegram ou o botão "Extratos" do dashboard). Para o Neon o webhook também cai na mesma
// fila. A fila deduplica por transaction_id, então rodar o extrato de novo não reenvia o
// aviso, e PIX já salvo/descartado é ignorado.
// Item 10: o Sicredi saiu daqui — agora tem salvarTransacoesSicrediDoExtrato (salva TUDO, não só
// PIX enviado), igual à Caixa e ao MP Magazine. Esta função ficou só de backup pro Neon (que já
// tem cobertura completa via webhook; isto é rede de segurança caso o webhook esteja fora do ar).
async function salvarPixEnviadosDoExtrato(transacoes) {
    let candidatos = 0;
    for (const t of (transacoes || [])) {
        if (t.banco !== 'Neon') continue;
        if (!ehPixEnviado(t) && !ehPixQr(t)) continue;
        candidatos++;
        try {
            const accountInfo = { name: t.conta, type: t.accountType };
            await salvarTransacaoNeon(t, accountInfo);
        } catch (err) {
            console.error(`❌ [PIX enviado / extrato] Erro ao processar (${t.banco} - ${t.id}):`, err.message);
        }
    }
    if (candidatos > 0) {
        console.log(`ℹ️ [PIX enviado / extrato] ${candidatos} PIX enviado(s) no extrato — novos aguardam aprovação; o restante já foi salvo, descartado ou está pendente.`);
    }
    return 0;
}

// ============== APROVAÇÃO DE PIX ENVIADO (Telegram + dashboard) ==============

const PIX_APROVADOR_USERNAME = 'user1';

function montarTextoPixPendente(dados, status = null) {
    const valor = formatBRL(Math.abs(dados.amount));
    const dataFmt = moment(dados.date).format('DD/MM/YYYY');
    const linhas = [
        `💸 <b>PIX ENVIADO — SALVAR?</b>`,
        `━━━━━━━━━━━━━━━━━━━━`,
        `🏦 <b>Banco:</b> ${escapeHtml(dados.logLabel || dados.banco || '')}`,
        `📝 <b>Descrição:</b> ${escapeHtml(dados.description || 'Sem descrição')}`,
        `💵 <b>Valor:</b> ${valor}`,
        `📅 <b>Data:</b> ${dataFmt}`,
        `━━━━━━━━━━━━━━━━━━━━`
    ];
    if (status === 'aprovar') {
        linhas.push(`✅ <b>SALVO</b> no banco de dados — ${moment().format('DD/MM/YYYY HH:mm')}`);
    } else if (status === 'descartar') {
        linhas.push(`🗑️ <b>DESCARTADO</b> — não foi salvo — ${moment().format('DD/MM/YYYY HH:mm')}`);
    } else {
        linhas.push(`<i>Só entra no banco de dados se você salvar.</i>`);
    }
    return linhas.join('\n');
}

function broadcastPixEvent(eventName, payload) {
    const clients = sseClientsByUser.get(PIX_APROVADOR_USERNAME);
    if (!clients) return;
    const data = JSON.stringify(payload);
    for (const res of clients) {
        try { res.write(`event: ${eventName}\ndata: ${data}\n\n`); } catch (e) {}
    }
}

// Coloca o PIX enviado na fila e avisa (Telegram + dashboard + push). Se a mesma
// transação já estiver na fila, não avisa de novo.
async function registrarPixPendente(dados) {
    const insercao = db.prepare(
        'INSERT OR IGNORE INTO pending_pix_transactions (transaction_id, banco, payload_json) VALUES (?, ?, ?)'
    ).run(dados.txId, dados.banco, JSON.stringify(dados));

    const linha = db.prepare('SELECT id FROM pending_pix_transactions WHERE transaction_id = ?').get(dados.txId);
    if (insercao.changes === 0) {
        return { alreadyPending: true, pendingId: linha && linha.id };
    }

    console.log(`⏳ [PIX enviado] Aguardando aprovação #${linha.id}: ${dados.description} - R$ ${Number(dados.amount).toFixed(2)}`);

    // Dashboard (SSE) + push do navegador, mesmo com a aba fechada
    broadcastPixEvent('pix_pending', {
        id: linha.id,
        banco: dados.logLabel || dados.banco,
        description: dados.description,
        amount: dados.amount,
        date: dados.date
    });
    try {
        await sendWebPushToUser(PIX_APROVADOR_USERNAME, {
            title: 'PIX enviado — salvar?',
            body: `${dados.description || 'Sem descrição'} • ${formatBRL(Math.abs(dados.amount))}`,
            url: '/',
            icon: '/pwa/icon-192.png',
            badge: '/pwa/icon-192.png'
        });
    } catch (e) {}

    // Telegram com botões Salvar/Descartar
    const mensagens = [];
    const texto = montarTextoPixPendente(dados);
    for (const chatId of TG_CHAT_IDS) {
        try {
            const enviada = await bot.telegram.sendMessage(chatId, texto, {
                parse_mode: 'HTML',
                reply_markup: {
                    inline_keyboard: [
                        [
                            { text: '✅ Salvar', callback_data: `pix_ok|${linha.id}` },
                            { text: '🗑️ Descartar', callback_data: `pix_no|${linha.id}` }
                        ],
                        [{ text: '🔍 Abrir Dashboard', url: PUBLIC_URL }]
                    ]
                }
            });
            mensagens.push({ chatId, messageId: enviada.message_id });
        } catch (err) {
            console.error(`❌ [PIX enviado] Erro ao avisar Telegram ${chatId}:`, err.message);
        }
    }
    if (mensagens.length > 0) {
        db.prepare('UPDATE pending_pix_transactions SET telegram_msgs = ? WHERE id = ?')
            .run(JSON.stringify(mensagens), linha.id);
    }

    return { alreadyPending: false, pendingId: linha.id };
}

// Aprova (grava em `transactions`) ou descarta (grava em deleted_bank_transactions para
// nunca mais reaparecer) um PIX pendente. Idempotente: se Telegram e dashboard clicarem
// ao mesmo tempo, só o primeiro vale.
async function resolverPixPendente(id, acao) {
    const claim = db.prepare(
        `UPDATE pending_pix_transactions SET status = 'processing' WHERE id = ? AND status = 'pending'`
    ).run(id);
    if (claim.changes === 0) {
        return { success: false, error: 'Já resolvida ou inexistente' };
    }

    const linha = db.prepare('SELECT * FROM pending_pix_transactions WHERE id = ?').get(id);
    try {
        const dados = JSON.parse(linha.payload_json);

        if (acao === 'aprovar') {
            const resultado = await salvarTransacaoBancaria({ ...dados, skipApproval: true, silent: true });
            if (!resultado.saved && !resultado.alreadyExisted) {
                throw new Error(resultado.error || 'Não foi possível salvar a transação');
            }
        } else {
            db.prepare('INSERT OR IGNORE INTO deleted_bank_transactions (transaction_id) VALUES (?)').run(dados.txId);
        }

        db.prepare('DELETE FROM pending_pix_transactions WHERE id = ?').run(id);
        console.log(`${acao === 'aprovar' ? '✅' : '🗑️'} [PIX enviado] #${id} ${acao === 'aprovar' ? 'salvo' : 'descartado'}: ${dados.description}`);

        // Remove os botões das mensagens do Telegram e mostra o resultado
        let mensagens = [];
        try { mensagens = JSON.parse(linha.telegram_msgs || '[]'); } catch (e) {}
        const textoFinal = montarTextoPixPendente(dados, acao);
        for (const m of mensagens) {
            try {
                await bot.telegram.editMessageText(m.chatId, m.messageId, undefined, textoFinal, {
                    parse_mode: 'HTML',
                    reply_markup: { inline_keyboard: [] }
                });
            } catch (e) {}
        }

        broadcastPixEvent('pix_resolved', { id, acao });
        return { success: true, acao };
    } catch (err) {
        db.prepare(`UPDATE pending_pix_transactions SET status = 'pending' WHERE id = ?`).run(id);
        console.error(`❌ [PIX enviado] Erro ao resolver #${id} (${acao}):`, err.message);
        return { success: false, error: err.message };
    }
}

bot.action(/^pix_(ok|no)\|(\d+)$/, async (ctx) => {
    try {
        if (!checkTelegramPermission(ctx)) {
            return await ctx.answerCbQuery('🚫 Sem permissão');
        }
        const acao = ctx.match[1] === 'ok' ? 'aprovar' : 'descartar';
        const resultado = await resolverPixPendente(Number(ctx.match[2]), acao);
        if (resultado.success) {
            await ctx.answerCbQuery(acao === 'aprovar' ? '✅ Transação salva' : '🗑️ Transação descartada');
        } else {
            await ctx.answerCbQuery(`⚠️ ${resultado.error}`, { show_alert: true });
        }
    } catch (error) {
        console.error('❌ Erro no callback de PIX pendente:', error);
    }
});

function requirePixAprovador(req, res, next) {
    const u = req.session && req.session.user;
    if (u && (String(u.username || '').toLowerCase() === PIX_APROVADOR_USERNAME || u.role === 'admin')) {
        return next();
    }
    return res.status(403).json({ success: false, error: 'FORBIDDEN' });
}

app.get('/api/pix-pendentes', requireAuth, requirePixAprovador, (req, res) => {
    try {
        const linhas = db.prepare(
            `SELECT id, banco, payload_json, created_at FROM pending_pix_transactions WHERE status = 'pending' ORDER BY id`
        ).all();
        const pendentes = linhas.map(l => {
            const d = JSON.parse(l.payload_json);
            return { id: l.id, banco: d.logLabel || d.banco, description: d.description, amount: d.amount, date: d.date, created_at: l.created_at };
        });
        res.json({ success: true, pendentes });
    } catch (error) {
        res.status(500).json({ success: false, error: error.message });
    }
});

for (const [rota, acao] of [['aprovar', 'aprovar'], ['descartar', 'descartar']]) {
    app.post(`/api/pix-pendentes/:id/${rota}`, requireAuth, requirePixAprovador, async (req, res) => {
        const resultado = await resolverPixPendente(Number(req.params.id), acao);
        res.status(resultado.success ? 200 : 409).json(resultado);
    });
}

// 5. Configurar Webhook da Pluggy
// Aponta o webhook de um item Pluggy (Sicredi/Neon) para `webhookUrl`, preservando o
// clientUserId/products atuais do item. `defaults` só entra quando o item não tem o campo.
async function configurarWebhookPluggyItem({ itemId, webhookUrl, label, defaults = {}, apiKeyProvider = getPluggyApiKey }) {
  const withDefault = (current, fallback) => (fallback === undefined ? current : (current || fallback));
  try {
    console.log(`🔧 Configurando webhook ${label}: ${webhookUrl}`);
    const apiKey = await apiKeyProvider();

    const itemResponse = await axios.get(`${PLUGGY_API_URL}/items/${itemId}`, {
      headers: { 'X-API-KEY': apiKey }
    });
    const currentItem = itemResponse.data;

    const response = await axios.patch(
      `${PLUGGY_API_URL}/items/${itemId}`,
      {
        webhookUrl,
        clientUserId: withDefault(currentItem.clientUserId, defaults.clientUserId),
        products: withDefault(currentItem.products, defaults.products)
      },
      { headers: { 'X-API-KEY': apiKey } }
    );

    console.log(`✅ Webhook ${label} configurado:`, {
      webhookUrl: response.data.webhookUrl,
      status: response.data.status,
      itemId: response.data.id
    });

    return { success: true, data: response.data };
  } catch (error) {
    console.error(`❌ Erro ao configurar webhook ${label}:`, error.response?.data || error.message);
    return { success: false, error: error.message };
  }
}

async function setupPluggyWebhook() {
  return configurarWebhookPluggyItem({ itemId: SICREDI_ITEM_ID, webhookUrl: WEBHOOK_URL, label: 'Sicredi', apiKeyProvider: getSicrediApiKey });
}
// 6. Processar Webhook da Pluggy (VERSÃO CORRIGIDA E MELHORADA)
async function processPluggyWebhook(webhookData) {
  try {
    console.log('\n🔔 ===== WEBHOOK PLUGGY - PROCESSAMENTO INICIADO =====');
    console.log(`📅 Hora recebimento: ${moment().format('DD/MM/YYYY HH:mm:ss')}`);
    console.log('📦 Dados COMPLETOS recebidos:', JSON.stringify(webhookData, null, 2));
    
    const { event, itemId, accountId, transactionIds, error } = webhookData;
    
    console.log(`🎯 Evento: ${event}`);
    console.log(`🏦 Item ID: ${itemId}`);
    console.log(`💳 Account ID: ${accountId || 'undefined'}`);
    console.log(`📊 Transaction IDs: ${transactionIds ? transactionIds.length : 0}`);
    console.log(`⚠️ Erro (se houver): ${error || 'Nenhum'}`);
    
    // ========== VERIFICAÇÃO DO ITEM ==========
    // Verificar se é do Sicredi
    if (itemId === SICREDI_ITEM_ID) {
      console.log('✅ Webhook do Sicredi detectado!');
      
      // Verificar qual conta (corrente ou poupança)
      let accountType = 'Conta Desconhecida';
      let isContaCorrente = false;
      let isPoupanca = false;
      
      if (accountId === SICREDI_ACCOUNT_ID) {
        accountType = 'Conta Corrente';
        isContaCorrente = true;
        console.log(`🏦 Tipo: ${accountType}`);
      } else if (accountId === SICREDI_POUPANCA_ID) {
        accountType = 'Poupança';
        isPoupanca = true;
        console.log(`🏦 Tipo: ${accountType}`);
      } else if (!accountId) {
        console.log('⚠️ Account ID não especificado no webhook');
      } else {
        console.log(`⚠️ Account ID desconhecido: ${accountId}`);
      }
      
      // ========== PROCESSAMENTO POR TIPO DE EVENTO ==========
      
      // 1. EVENTO: NOVAS TRANSAÇÕES (transactions/created)
      if (event === 'transactions/created') {
        console.log('💰 EVENTO: Nova(s) transação(ões) criada(s)');
        
        if (transactionIds && transactionIds.length > 0) {
          console.log(`📝 ${transactionIds.length} nova(s) transação(ões) para processar`);
          
          for (const txId of transactionIds) {
            console.log(`🔍 Buscando detalhes da transação: ${txId}`);
            
            try {
              const result = await getSicrediTransactionDetails(txId);
              
              if (result.success && result.data) {
                const transaction = result.data;
                console.log(`📋 Detalhes da transação:`, JSON.stringify(transaction, null, 2));

                // Verificar se é ENTRADA (CREDIT) ou SAÍDA (DEBIT)
                // Nota: este webhook não salva mais nada no banco local — por pedido
                // explícito, a única persistência do Sicredi agora é via
                // salvarPixEnviadosDoExtrato(), disparada quando o /extrato roda
                // (Telegram ou dashboard). Aqui só notifica, como antes dessa mudança.
                if (transaction.type === 'CREDIT' && transaction.amount > 0) {
                  if (ehTransferenciaInterna(transaction.description)) {
                    console.log(`⏭️ Ignorada (transferência interna): ${transaction.description}`);
                  } else {
                  console.log(`💰 NOVA ENTRADA (CREDIT): R$ ${transaction.amount.toFixed(2)}`);

                  console.log('📤 Enviando notificação para Telegram...');
                  try {
                    const mensagemTelegram = {
                      description: transaction.description || `Entrada Sicredi ${accountType}`,
                      amount: transaction.amount,
                      type: 'income',
                      paymentMethod: `Sicredi ${accountType}`,
                      userName: 'Sistema Sicredi',
                      date: transaction.date ? transaction.date.split('T')[0] : moment().format('YYYY-MM-DD')
                    };
                    const telegramResult = await notificarTelegram(mensagemTelegram);
                    if (telegramResult) {
                      console.log('✅ Notificação enviada para Telegram com sucesso!');
                    } else {
                      console.warn('⚠️ Notificação Telegram pode não ter sido enviada');
                    }
                  } catch (tgError) {
                    console.error('❌ Erro ao enviar para Telegram:', tgError.message);
                  }
                  }

                } else if (transaction.type === 'DEBIT' && transaction.amount > 0) {
                  console.log(`💸 NOVA SAÍDA (DEBIT): R$ ${transaction.amount.toFixed(2)}`);
                  console.log('ℹ️ Saídas não são notificadas nem salvas por aqui — PIX enviado é capturado via /extrato.');

                } else {
                  console.log(`⚠️ Tipo de transação desconhecido ou valor inválido: ${transaction.type}, R$ ${transaction.amount}`);
                }
                
              } else {
                console.error(`❌ Falha ao buscar detalhes da transação ${txId}:`, result.error);
              }
              
            } catch (error) {
              console.error(`❌ Erro ao processar transação ${txId}:`, error.message);
            }
          }
          
        } else {
          console.log('⚠️ Evento transactions/created mas SEM transactionIds!');
          console.log('   Isso pode indicar:');
          console.log('   1. Configuração incorreta na Pluggy');
          console.log('   2. Problema na sincronização');
          console.log('   3. Transação não capturada corretamente');
        }
      }
      
      // 2. EVENTO: ITEM ATUALIZADO (item/updated)
      else if (event === 'item/updated') {
        console.log('🔄 Item do Sicredi atualizado');
        
        // Quando o item é atualizado, buscar transações recentes
        console.log('🔍 Buscando transações das últimas 2 horas...');
        
        try {
          const duasHorasAtras = moment().subtract(2, 'hours');
          const hoje = moment();
          
          const transacoes = await getSicrediTransactions(
            duasHorasAtras.format('YYYY-MM-DD'),
            hoje.format('YYYY-MM-DD')
          );
          
          if (transacoes.success && transacoes.data.length > 0) {
            console.log(`📊 ${transacoes.data.length} transação(ões) encontrada(s) nas últimas 2 horas`);

            // Processar apenas entradas (CREDIT) não notificadas. Não salva no banco
            // aqui — a única persistência do Sicredi é via salvarPixEnviadosDoExtrato(),
            // disparada quando o /extrato roda.
            const entradas = transacoes.data.filter(t =>
              t.type === 'CREDIT' &&
              t.amount > 0 &&
              moment(t.date).isAfter(duasHorasAtras)
            );

            if (entradas.length > 0) {
              console.log(`💰 ${entradas.length} nova(s) entrada(s) encontrada(s) no item/updated`);

              for (const transacao of entradas) {
                // Verificar se já foi notificada (por ID da transação, salvo via /extrato
                // caso já tenha sido um PIX enviado — não se aplica a entradas, mas o
                // padrão de checagem por LIKE continua servindo pra evitar notificar de novo)
                const existe = db.prepare(
                  'SELECT COUNT(*) as count FROM transactions WHERE transaction_id LIKE ?'
                ).get(`%${transacao.id}%`);

                if ((!existe || existe.count === 0) && ehTransferenciaInterna(transacao.description)) {
                  console.log(`⏭️ Ignorada (transferência interna): ${transacao.description}`);
                } else if (!existe || existe.count === 0) {
                  console.log(`📤 Notificando transação atrasada: ${transacao.description}`);

                  const mensagemTelegram = {
                    description: transacao.description || 'Entrada Sicredi',
                    amount: transacao.amount,
                    type: 'income',
                    paymentMethod: 'Sicredi',
                    userName: 'Sistema',
                    date: transacao.date.split('T')[0]
                  };

                  await notificarTelegram(mensagemTelegram);
                }
              }
            }
          } else {
            console.log('ℹ️ Nenhuma transação nova encontrada no item/updated');
          }
        } catch (syncError) {
          console.error('❌ Erro ao buscar transações no item/updated:', syncError.message);
        }
      }
      
      // 3. EVENTO: LOGIN BEM-SUCEDIDO (item/login_succeeded)
      else if (event === 'item/login_succeeded') {
        console.log('🔓 Login no Sicredi bem-sucedido');
        
        // Enviar notificação de sistema
        try {
          const mensagemSistema = `✅ *CONEXÃO SICREDI ESTABELECIDA*\n\nLogin realizado com sucesso!\n\n_${moment().format('DD/MM/YYYY HH:mm:ss')}_`;
          
          for (const chatId of TG_CHAT_IDS) {
            await bot.telegram.sendMessage(
              chatId,
              mensagemSistema,
              { parse_mode: 'Markdown' }
            );
          }
          console.log('✅ Notificação de login enviada para Telegram');
        } catch (notifError) {
          console.warn('⚠️ Não foi possível enviar notificação de login:', notifError.message);
        }
      }
      
      // 4. EVENTO: ERRO NO ITEM (item/error)
      else if (event === 'item/error') {
        console.error('🚨 ERRO NO ITEM DO SICREDI:', error);
        
        // Enviar alerta de erro
        try {
          const mensagemErro = `🚨 *ERRO NO SICREDI*\n\n${error || 'Erro desconhecido'}\n\n_${moment().format('DD/MM/YYYY HH:mm:ss')}_`;
          
          for (const chatId of TG_CHAT_IDS) {
            await bot.telegram.sendMessage(
              chatId,
              mensagemErro,
              { parse_mode: 'Markdown' }
            );
          }
          console.log('⚠️ Alerta de erro enviado para Telegram');
        } catch (notifError) {
          console.error('❌ Não foi possível enviar alerta de erro:', notifError.message);
        }
      }
      
      // 5. OUTROS EVENTOS
      else {
        console.log(`ℹ️ Evento ${event} recebido (não processado especificamente)`);
        
        // Log para debug
        console.log('📋 Dados completos do evento não tratado:', JSON.stringify(webhookData, null, 2));
      }
      
    }
    // Nota: webhooks do Neon nunca chegam aqui — o roteador em /api/pluggy-webhook
    // já desvia itemId === NEON_ITEM_ID para processNeonWebhook antes de chamar esta
    // função (havia um branch morto aqui tratando isso, removido).
    // Item desconhecido
    else if (itemId !== NEON_ITEM_ID) {
      console.log(`⚠️ Webhook recebido de item desconhecido: ${itemId}`);
      console.log('   Esperado:', SICREDI_ITEM_ID, 'ou', NEON_ITEM_ID || '(Neon não configurado)');
      console.log('   Recebido:', itemId);
    }
    
    console.log('✅ ===== WEBHOOK PROCESSADO COM SUCESSO =====\n');
    
  } catch (error) {
    console.error('❌ ERRO CRÍTICO em processPluggyWebhook:', error);
    console.error('   Stack:', error.stack);
    
    // Tentar enviar alerta de erro crítico
    try {
      const mensagemErroCritico = `🚨 *ERRO CRÍTICO NO WEBHOOK*\n\n${error.message}\n\n_${moment().format('DD/MM/YYYY HH:mm:ss')}_`;
      
      for (const chatId of TG_CHAT_IDS) {
        await bot.telegram.sendMessage(
          chatId,
          mensagemErroCritico.substring(0, 400), // Limitar tamanho
          { parse_mode: 'Markdown' }
        );
      }
    } catch (telegramError) {
      console.error('❌ Não foi possível enviar alerta de erro crítico:', telegramError.message);
    }
  }
}
async function buscarTransacoesRecentes() {
  // (função só usada para o Sicredi — ver a chamada abaixo)
  try {
    console.log('\n🔍 BUSCANDO TRANSAÇÕES RECENTES DO SICREDI...');
    
    const apiKey = await getSicrediApiKey();
    
    // Buscar últimas 24 horas
    const ontem = moment().subtract(24, 'hours');
    const hoje = moment();
    
    const url = `${PLUGGY_API_URL}/transactions?accountId=${SICREDI_ACCOUNT_ID}&from=${ontem.format('YYYY-MM-DD')}&to=${hoje.format('YYYY-MM-DD')}&pageSize=50`;
    
    console.log('📡 URL:', url);
    
    const response = await axios.get(url, {
      headers: { 'X-API-KEY': apiKey },
    });
    
    const transacoes = response.data.results || [];
    
    console.log(`📊 Total de transações encontradas: ${transacoes.length}`);
    
    if (transacoes.length > 0) {
      console.log('📋 Últimas 5 transações:');
      transacoes.slice(0, 5).forEach((t, i) => {
        console.log(`   ${i+1}. ${t.date} - ${t.description} - R$ ${t.amount.toFixed(2)} (${t.type})`);
      });
      
      // Verificar se há transações CREDIT não notificadas
      const entradas = transacoes.filter(t => t.type === 'CREDIT' && t.amount > 0);
      
      if (entradas.length > 0) {
        console.log(`💰 ${entradas.length} entrada(s) (CREDIT) encontrada(s)!`);
        
        for (const transacao of entradas) {
          // Verificar se já foi notificada
          const existe = db.prepare(
            'SELECT COUNT(*) as count FROM transactions WHERE transaction_id = ?'
          ).get(`pluggy_${transacao.id}`);
          
          if (existe.count === 0 && ehTransferenciaInterna(transacao.description)) {
            console.log(`   ⏭️ Ignorada (transferência interna): ${transacao.description}`);
          } else if (existe.count === 0) {
            console.log(`   📤 Notificando: ${transacao.description} - R$ ${transacao.amount.toFixed(2)}`);
            
            await notificarTelegram({
              description: transacao.description || 'Entrada Sicredi',
              amount: transacao.amount,
              type: 'income',
              paymentMethod: 'Sicredi Conta Corrente',
              userName: 'Sistema',
              date: transacao.date.split('T')[0]
            });
          }
        }
      }
    } else {
      console.log('ℹ️ Nenhuma transação encontrada nas últimas 24 horas');
    }
    
    return transacoes;
    
  } catch (error) {
    console.error('❌ Erro ao buscar transações:', error.message);
    return [];
  }
}
