// 7. Verificar Status da Conexão Pluggy (ATUALIZADA)
// Item 16: o MeuPluggy gratuito tem um teto de 5 conexões (itens) no total, somando TODAS as
// aplicações Pluggy ligadas à mesma conta pessoal. Hoje já são 4 (Neon, Sicredi, Caixa, MP
// Magazine) — bem perto do limite. Sem isso, a próxima tentativa de conectar um banco novo
// falharia sem aviso nenhum, e a única pista seria vasculhar log.
async function verificarLimiteConexoesPluggy() {
  try {
    const apps = [
      { nome: 'Sicredi/Neon', clientId: PLUGGY_CLIENT_ID, clientSecret: PLUGGY_CLIENT_SECRET },
      { nome: 'Mercado Pago', clientId: PLUGGY_MP_CLIENT_ID, clientSecret: PLUGGY_MP_CLIENT_SECRET }
    ];
    let totalItens = 0;
    const porApp = [];
    for (const app of apps) {
      if (!app.clientId || !app.clientSecret) continue;
      try {
        const auth = await axios.post(`${PLUGGY_API_URL}/auth`, { clientId: app.clientId, clientSecret: app.clientSecret });
        const key = auth.data.apiKey;
        const resp = await axios.get(`${PLUGGY_API_URL}/items`, { headers: { 'X-API-KEY': key } });
        const itens = (resp.data.results || resp.data || []);
        const n = Array.isArray(itens) ? itens.length : 0;
        totalItens += n;
        porApp.push(`${app.nome}: ${n}`);
      } catch (e) {
        console.error(`❌ [Limite Pluggy] Erro ao consultar itens da aplicação ${app.nome}:`, e.message);
      }
    }

    const LIMITE_MEUPLUGGY_GRATUITO = 5;
    console.log(`🔌 [Limite Pluggy] ${totalItens}/${LIMITE_MEUPLUGGY_GRATUITO} conexões usadas (${porApp.join(', ')})`);

    if (totalItens >= LIMITE_MEUPLUGGY_GRATUITO - 1) {
      const msg = `⚠️ *LIMITE DO MEUPLUGGY QUASE ATINGIDO*\n\n` +
        `Conexões em uso: ${totalItens}/${LIMITE_MEUPLUGGY_GRATUITO}\n${porApp.map(p => `• ${p}`).join('\n')}\n\n` +
        `O plano gratuito só permite ${LIMITE_MEUPLUGGY_GRATUITO} contas conectadas no total. Conectar mais uma pode falhar.`;
      for (const chatId of TG_CHAT_IDS) {
        try { await bot.telegram.sendMessage(chatId, msg, { parse_mode: 'Markdown' }); } catch (e) {}
      }
    }
  } catch (error) {
    console.error('❌ [Limite Pluggy] Erro geral:', error.message);
  }
}

// Webhook de APLICAÇÃO (GET /webhooks). Vale para todos os itens da aplicação, inclusive os do
// conector MeuPluggy, que não aceitam webhookUrl no próprio item. Por isso o painel consulta aqui.
async function consultarWebhooksDaAplicacao(apiKeyProvider, nome) {
  try {
    const apiKey = await apiKeyProvider();
    const { data } = await axios.get(`${PLUGGY_API_URL}/webhooks`, {
      headers: { 'X-API-KEY': apiKey },
      timeout: 15000
    });
    const webhooks = (data.results || []).map((w) => ({ id: w.id, event: w.event, url: w.url, criadoEm: w.createdAt || null }));
    return { aplicacao: nome, configured: webhooks.some((w) => w.url === WEBHOOK_URL), webhooks };
  } catch (error) {
    return { aplicacao: nome, configured: false, erro: error.response?.data?.message || error.message, webhooks: [] };
  }
}

async function getPluggyStatus() {
    try {
        const apiKey = await getPluggyApiKey();
        const apiKeySicredi = await getSicrediApiKey();
        
        // Buscar status do item Sicredi
        const sicrediItemResponse = await axios.get(`${PLUGGY_API_URL}/items/${SICREDI_ITEM_ID}`, {
            headers: { 'X-API-KEY': apiKeySicredi }
        });
        
        // Buscar status da conta Sicredi
        const sicrediAccountResponse = await axios.get(`${PLUGGY_API_URL}/accounts/${SICREDI_ACCOUNT_ID}`, {
            headers: { 'X-API-KEY': apiKeySicredi }
        });
        
        // Buscar status do item Neon
        const neonItemResponse = await axios.get(`${PLUGGY_API_URL}/items/${NEON_ITEM_ID}`, {
            headers: { 'X-API-KEY': apiKey }
        });
        
        // Buscar status da conta Neon
        const neonAccountResponse = await axios.get(`${PLUGGY_API_URL}/accounts/${NEON_ACCOUNT_ID}`, {
            headers: { 'X-API-KEY': apiKey }
        });
        
        // Buscar última sincronização
        const connectorsResponse = await axios.get(`${PLUGGY_API_URL}/connectors`, {
            headers: { 'X-API-KEY': apiKey }
        });
        
        const sicrediConnector = connectorsResponse.data.results.find(
            conn => conn.name.includes('Sicredi') || conn.name.includes('SICREDI')
        );
        
        const neonConnector = connectorsResponse.data.results.find(
            conn => conn.name.includes('Neon') || conn.name.includes('NEON')
        );
        
        const aplicacoesWebhook = await Promise.all([
            consultarWebhooksDaAplicacao(getPluggyApiKey, 'Sicredi/Neon'),
            consultarWebhooksDaAplicacao(getMercadoPagoMagazineApiKey, 'Mercado Pago - Magazine (Sicredi, Caixa, MP)')
        ]);

        return {
            success: true,
            status: {
                sicredi: {
                    item: {
                        id: sicrediItemResponse.data.id,
                        status: sicrediItemResponse.data.status,
                        lastUpdatedAt: sicrediItemResponse.data.updatedAt,
                        webhookUrl: sicrediItemResponse.data.webhookUrl,
                        error: sicrediItemResponse.data.error
                    },
                    account: {
                        id: sicrediAccountResponse.data.id,
                        number: sicrediAccountResponse.data.number,
                        balance: sicrediAccountResponse.data.balance,
                        status: sicrediAccountResponse.data.status,
                        lastUpdatedAt: sicrediAccountResponse.data.updatedAt
                    },
                    connector: sicrediConnector ? {
                        id: sicrediConnector.id,
                        name: sicrediConnector.name,
                        status: sicrediConnector.status,
                        lastUpdatedAt: sicrediConnector.updatedAt
                    } : null
                },
                neon: {
                    item: {
                        id: neonItemResponse.data.id,
                        status: neonItemResponse.data.status,
                        lastUpdatedAt: neonItemResponse.data.updatedAt,
                        webhookUrl: neonItemResponse.data.webhookUrl,
                        error: neonItemResponse.data.error
                    },
                    account: {
                        id: neonAccountResponse.data.id,
                        number: neonAccountResponse.data.number,
                        balance: neonAccountResponse.data.balance,
                        status: neonAccountResponse.data.status,
                        lastUpdatedAt: neonAccountResponse.data.updatedAt
                    },
                    connector: neonConnector ? {
                        id: neonConnector.id,
                        name: neonConnector.name,
                        status: neonConnector.status,
                        lastUpdatedAt: neonConnector.updatedAt
                    } : null
                },
                webhook: {
                    url: WEBHOOK_URL,
                    // Verdadeiro só se as duas aplicações têm webhook apontando para o sistema
                    configured: aplicacoesWebhook.every((a) => a.configured),
                    porAplicacao: aplicacoesWebhook
                },
                api: {
                    tokenValid: pluggyApiKey && pluggyApiKeyExpiry > Date.now(),
                    tokenExpiresIn: pluggyApiKeyExpiry ? Math.max(0, pluggyApiKeyExpiry - Date.now()) / 1000 : 0
                }
            },
            timestamp: moment().toISOString(),
            server: PUBLIC_URL
        };
        
    } catch (error) {
        console.error('❌ Erro ao consultar status da Pluggy:', error.response?.data || error.message);
        
        return {
            success: false,
            error: 'Erro ao consultar status da Pluggy',
            details: error.response?.data || error.message,
            timestamp: moment().toISOString()
        };
    }
}
