// 1. Função para detectar tipo de transação Neon
// ============== FUNÇÃO PARA DETECTAR TIPO DE TRANSAÇÃO NEON (MELHORADA) ==============
function detectNeonTransactionType(transaction, accountInfo) {
    const description = (transaction.description || '').toLowerCase();
    const originalAmount = transaction.amount || 0;
    const isCredit = transaction.type === 'CREDIT';
    const isDebit = transaction.type === 'DEBIT';
    
    // Para contas de investimento (Caixinhas)
    if (accountInfo.type === 'FIXED_INCOME' || accountInfo.accountType === 'FIXED_INCOME') {
        if (description.includes('aplicação') || description.includes('aplicacao')) {
            return {
                type: 'expense', // Aplicação é saída da conta corrente
                category: 'Investimentos',
                subcategory: 'Aplicação',
                paymentMethod: `Neon - ${accountInfo.name || 'Caixinha'}`
            };
        }
        if (description.includes('resgate')) {
            return {
                type: 'income', // Resgate é entrada na conta corrente
                category: 'Investimentos',
                subcategory: 'Resgate',
                paymentMethod: `Neon - ${accountInfo.name || 'Caixinha'}`
            };
        }
        if (description.includes('vencimento') || description.includes('rendimento')) {
            return {
                type: 'income', // Rendimento é entrada
                category: 'Rendimentos',
                subcategory: 'Rendimentos',
                paymentMethod: `Neon - ${accountInfo.name || 'Caixinha'}`
            };
        }
        if (description.includes('cdb')) {
            return {
                type: isCredit ? 'income' : 'expense',
                category: 'Investimentos',
                subcategory: 'CDB',
                paymentMethod: `Neon - ${accountInfo.name || 'Caixinha'}`
            };
        }
    }
    
    // Para conta corrente
    if (accountInfo.type === 'CHECKING_ACCOUNT' || accountInfo.accountType === 'CHECKING_ACCOUNT') {
        if (description.includes('pix enviado para')) {
            if (description.includes('user1') || description.includes('user2')) {
                return {
                    type: 'expense',
                    category: 'Transferência entre contas',
                    subcategory: 'PIX',
                    paymentMethod: 'Pix Neon'
                };
            }
            return {
                type: 'expense',
                category: description.includes('pkr') ? 'Alimentação' : 'Transferência',
                subcategory: 'PIX',
                paymentMethod: 'Pix Neon'
            };
        }
        
        if (description.includes('pix recebido de')) {
            if (description.includes('user1') || description.includes('user2')) {
                return {
                    type: 'income',
                    category: 'Transferência entre contas',
                    subcategory: 'PIX',
                    paymentMethod: 'Pix Neon'
                };
            }
            return {
                type: 'income',
                category: 'Outros Rendimentos',
                subcategory: 'PIX',
                paymentMethod: 'Pix Neon'
            };
        }
        
        if (description.includes('estorno')) {
            return {
                type: 'income',
                category: 'Estorno',
                subcategory: 'Estorno',
                paymentMethod: 'Pix Neon'
            };
        }
    }
    
    // Para a nova caixinha específica (ID: 6ba80bee-ebfb-4542-a913-39157c439a7a)
    if (accountInfo.id === NEON_CAIXINHA_ID) {
        return {
            type: isCredit ? 'income' : 'expense',
            category: 'Investimentos',
            subcategory: 'Caixinha Especial',
            paymentMethod: `Neon - Caixinha Especial`
        };
    }
    
    // Default
    return {
        type: isCredit ? 'income' : 'expense',
        category: isCredit ? 'Outros Rendimentos' : 'Outros Gastos',
        subcategory: isCredit ? 'Outros' : 'Outros',
        paymentMethod: 'Neon'
    };
}
// ============== FUNÇÃO PARA EXCLUIR IMAGEM DO COMPROVANTE ==============
function deleteReceiptImage(fileName) {
    try {
        if (!fileName) return false;
        
        // Caminho completo do arquivo
        const filePath = path.join(RECEIPTS_DIR, fileName);
        
        // Verificar se o arquivo existe antes de tentar excluir
        if (fs.existsSync(filePath)) {
            fs.unlinkSync(filePath);
            console.log(`✅ Imagem excluída: ${fileName}`);
            return true;
        } else {
            console.log(`ℹ️ Imagem não encontrada: ${fileName}`);
            return false;
        }
    } catch (error) {
        console.error(`❌ Erro ao excluir imagem ${fileName}:`, error.message);
        return false;
    }
}
function deleteTransaction(transactionId, usernameOrUserObj, isAdmin = false) {
  try {
    const hasUserId = tableHasColumn('transactions', 'user_id');
    const row = hasUserId
      ? db.prepare('SELECT receipt_image, user, user_id FROM transactions WHERE transaction_id = ?').get(transactionId)
      : db.prepare('SELECT receipt_image, user FROM transactions WHERE transaction_id = ?').get(transactionId);
    
    if (!row) {
      throw new Error('Transação não encontrada');
    }
    
    const actorUsername = typeof usernameOrUserObj === 'string'
      ? String(usernameOrUserObj || '').toLowerCase()
      : String((usernameOrUserObj && usernameOrUserObj.username) || '').toLowerCase();
    const actorUserId = typeof usernameOrUserObj === 'object' && usernameOrUserObj && Number.isFinite(Number(usernameOrUserObj.id))
      ? Number(usernameOrUserObj.id)
      : null;

    if (!isAdmin) {
      if (hasUserId && actorUserId !== null) {
        if (Number(row.user_id) !== actorUserId) throw new Error('Sem permissão para excluir esta transação');
      } else {
        if (row.user !== actorUsername) throw new Error('Sem permissão para excluir esta transação');
      }
    }
    
    if (row.receipt_image) {
      deleteReceiptImage(row.receipt_image);
    }

    db.prepare('DELETE FROM transactions WHERE transaction_id = ?').run(transactionId);

    // Transação de origem bancária (Sicredi, Caixa, Neon, Mercado Pago ou id bruto do webhook antigo)?
    // Registra a exclusão permanentemente, em todas as variantes do id, para que /extrato ou o
    // polling nunca a recriem automaticamente. (Antes faltava pluggy_caixa_: excluir uma transação
    // da Caixa fazia ela voltar — e notificar de novo — no polling seguinte.)
    const variantesExcluidas = variantesIdTransacaoBancaria(transactionId);
    if (variantesExcluidas.length) {
      try {
        const registrar = db.prepare('INSERT OR IGNORE INTO deleted_bank_transactions (transaction_id) VALUES (?)');
        for (const v of variantesExcluidas) registrar.run(v);
      } catch (e) {
        console.error('⚠️ Erro ao registrar exclusão permanente da transação bancária:', e.message);
      }
    }

    return { success: true };
  } catch (error) {
    console.error('❌ Erro em deleteTransaction:', error);
    return { success: false, error: error.message };
  }
}

function copyGlobalCategoriesToUser(userId, username) {
  try {
    if (!db) return false;
    const uid = Number(userId);
    if (!Number.isFinite(uid)) return false;
    const uname = String(username || '').trim();
    if (!uname) return false;
    if (!tableHasColumn('categories_scoped', 'type')) return false;

    const hasUserIdOnGlobal = tableHasColumn('categories', 'user_id');
    const globalCats = hasUserIdOnGlobal
      ? db.prepare(`
          SELECT type, name FROM categories
          WHERE user = 'system' OR (user_id IS NULL AND user IS NULL) OR user IS NULL
        `).all()
      : db.prepare(`
          SELECT type, name FROM categories
          WHERE user = 'system' OR user IS NULL
        `).all();
    if (!globalCats || globalCats.length === 0) return false;

    const insertStmt = db.prepare(`
      INSERT OR IGNORE INTO categories_scoped (type, name, user, user_id)
      VALUES (?, ?, ?, ?)
    `);
    const tx = db.transaction((cats) => {
      for (const cat of cats) {
        insertStmt.run(cat.type, cat.name, uname, uid);
      }
    });
    tx(globalCats);
    console.log(`✅ Copiadas ${globalCats.length} categorias globais para usuário ${uname} (${uid})`);
    return true;
  } catch (error) {
    console.error('❌ Erro ao copiar categorias globais:', error);
    return false;
  }
}

function getCategories(userId = null, username = null, isAdmin = false) {
  try {
    if (!db) {
      return { income: DEFAULT_INCOME_CATEGORIES, expense: DEFAULT_EXPENSE_CATEGORIES, paymentMethods: DEFAULT_PAYMENT_METHODS };
    }

    const hasScoped = tableHasColumn('categories_scoped', 'type');
    let categories = [];

    if (isAdmin || (!Number.isFinite(Number(userId)) && !username)) {
      if (hasScoped) {
        categories = db.prepare(`
          SELECT DISTINCT type, name FROM (
            SELECT type, name FROM categories
            UNION ALL
            SELECT type, name FROM categories_scoped
          )
          ORDER BY type, name
        `).all();
      } else {
        categories = db.prepare(`
          SELECT type, name
          FROM categories
          ORDER BY type, name
        `).all();
      }
    } else {
      if (!hasScoped) return { income: [], expense: [], paymentMethods: [] };
      if (Number.isFinite(Number(userId))) {
        categories = db.prepare(`
          SELECT type, name
          FROM categories_scoped
          WHERE user_id = ?
          ORDER BY type, name
        `).all(Number(userId));
      } else if (username) {
        categories = db.prepare(`
          SELECT type, name
          FROM categories_scoped
          WHERE user = ?
          ORDER BY type, name
        `).all(String(username));
      } else {
        return { income: [], expense: [], paymentMethods: [] };
      }
    }
    
    const result = {
      income: [],
      expense: [],
      paymentMethods: []
    };
    
    categories.forEach(cat => {
      if (cat.type === 'income') {
        result.income.push(cat.name);
      } else if (cat.type === 'expense') {
        result.expense.push(cat.name);
      } else if (cat.type === 'payment_method') {
        result.paymentMethods.push(cat.name);
      }
    });
    
    if (!isAdmin && result.income.length === 0 && result.expense.length === 0 && result.paymentMethods.length === 0) {
      result.income = DEFAULT_INCOME_CATEGORIES;
      result.expense = DEFAULT_EXPENSE_CATEGORIES;
      result.paymentMethods = DEFAULT_PAYMENT_METHODS;
    }

    return result;
  } catch (error) {
    console.error('❌ Erro em getCategories:', error);
    return {
      income: DEFAULT_INCOME_CATEGORIES,
      expense: DEFAULT_EXPENSE_CATEGORIES,
      paymentMethods: DEFAULT_PAYMENT_METHODS
    };
  }
}

function addCategory(type, name, userId, username, isAdmin = false) {
  try {
    if (!db) return { success: false, error: 'DB_NOT_READY' };
    const dbType = type === 'paymentMethod' ? 'payment_method' : type;

    if (isAdmin) {
      if (tableHasColumn('categories', 'user_id')) {
        db.prepare(`
          INSERT OR IGNORE INTO categories (type, name, user, user_id)
          VALUES (?, ?, 'system', NULL)
        `).run(dbType, name);
      } else {
        db.prepare(`
          INSERT OR IGNORE INTO categories (type, name, user)
          VALUES (?, ?, 'system')
        `).run(dbType, name);
      }
      return { success: true };
    }

    if (!tableHasColumn('categories_scoped', 'type')) return { success: false, error: 'CATEGORIES_SCOPED_NOT_READY' };
    const uid = Number.isFinite(Number(userId)) ? Number(userId) : null;
    const uname = username ? String(username) : null;
    if (!uid && !uname) return { success: false, error: 'Usuário não identificado' };

    db.prepare(`
      INSERT OR IGNORE INTO categories_scoped (type, name, user, user_id)
      VALUES (?, ?, ?, ?)
    `).run(dbType, name, uname, uid);
    
    return { success: true };
  } catch (error) {
    console.error('❌ Erro em addCategory:', error);
    return { success: false, error: error.message };
  }
}

function deleteCategory(type, name, userId, username, isAdmin = false) {
  try {
    if (!db) return { success: false, error: 'DB_NOT_READY' };
    const dbType = type === 'paymentMethod' ? 'payment_method' : type;

    if (isAdmin) {
      db.prepare(`DELETE FROM categories WHERE type = ? AND name = ?`).run(dbType, name);
      return { success: true };
    }

    if (!tableHasColumn('categories_scoped', 'type')) return { success: false, error: 'CATEGORIES_SCOPED_NOT_READY' };
    if (Number.isFinite(Number(userId))) {
      db.prepare(`DELETE FROM categories_scoped WHERE type = ? AND name = ? AND user_id = ?`).run(dbType, name, Number(userId));
      return { success: true };
    }
    if (username) {
      db.prepare(`DELETE FROM categories_scoped WHERE type = ? AND name = ? AND user = ?`).run(dbType, name, String(username));
      return { success: true };
    }
    return { success: false, error: 'Usuário não identificado' };
    
  } catch (error) {
    console.error('❌ Erro em deleteCategory:', error);
    return { success: false, error: error.message };
  }
}

function getStats(user, month, year) {
  try {
    const monthStr = String(month).padStart(2, '0');
    const monthYear = `${year}-${monthStr}`;
    const userFilter = buildUserWhere('transactions', user, 'user');
    
    const currentStats = db.prepare(`
      SELECT 
        COUNT(*) as totalTransactions,
        COALESCE(SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END), 0) as totalIncome,
        COALESCE(SUM(CASE WHEN type = 'expense' THEN amount ELSE 0 END), 0) as totalExpense
      FROM transactions 
      WHERE ${userFilter.clause} AND strftime('%Y-%m', date) = ?
    `).get(...userFilter.params, monthYear);
    
    const lastMonth = month === 1 ? 12 : month - 1;
    const lastMonthYear = month === 1 ? year - 1 : year;
    const lastMonthStr = String(lastMonth).padStart(2, '0');
    const lastMonthYearStr = `${lastMonthYear}-${lastMonthStr}`;
    
    const lastMonthStats = db.prepare(`
      SELECT 
        COALESCE(SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END), 0) as totalIncome,
        COALESCE(SUM(CASE WHEN type = 'expense' THEN amount ELSE 0 END), 0) as totalExpense
      FROM transactions 
      WHERE ${userFilter.clause} AND strftime('%Y-%m', date) = ?
    `).get(...userFilter.params, lastMonthYearStr);
    
    const incomeChange = lastMonthStats.totalIncome === 0 ? 200 : 
      ((currentStats.totalIncome - lastMonthStats.totalIncome) / lastMonthStats.totalIncome * 200);
    
    const expenseChange = lastMonthStats.totalExpense === 0 ? 200 : 
      ((currentStats.totalExpense - lastMonthStats.totalExpense) / lastMonthStats.totalExpense * 200);
    
    const totalBalanceResult = db.prepare(`
      SELECT 
        COALESCE(SUM(CASE WHEN type = 'income' THEN amount ELSE -amount END), 0) as totalBalance
      FROM transactions 
      WHERE ${userFilter.clause}
    `).get(...userFilter.params);
    
    const categoryData = db.prepare(`
      SELECT 
        category,
        type,
        SUM(amount) as total,
        COUNT(*) as count
      FROM transactions 
      WHERE ${userFilter.clause} AND strftime('%Y-%m', date) = ?
      GROUP BY category, type
      ORDER BY total DESC
    `).all(...userFilter.params, monthYear);
    
    const categoryStats = {};
    categoryData.forEach(row => {
      if (!categoryStats[row.category]) {
        categoryStats[row.category] = { income: 0, expense: 0, count: 0 };
      }
      categoryStats[row.category][row.type] = row.total;
      categoryStats[row.category].count += row.count;
    });
    
    const paymentData = db.prepare(`
      SELECT 
        payment_method,
        type,
        SUM(amount) as total,
        COUNT(*) as count
      FROM transactions 
      WHERE ${userFilter.clause} AND strftime('%Y-%m', date) = ?
      GROUP BY payment_method, type
      ORDER BY count DESC
    `).all(...userFilter.params, monthYear);
    
    const paymentStats = {};
    paymentData.forEach(row => {
      if (!paymentStats[row.payment_method]) {
        paymentStats[row.payment_method] = { income: 0, expense: 0, count: 0 };
      }
      paymentStats[row.payment_method][row.type] = row.total;
      paymentStats[row.payment_method].count += row.count;
    });
    
    const recentTransactions = db.prepare(`
      SELECT 
        transaction_id as transactionId,
        description,
        amount,
        type,
        category,
        payment_method as paymentMethod,
        date,
        user_name as userName,
        receipt_image as receiptImage
      FROM transactions 
      WHERE ${userFilter.clause}
      ORDER BY date DESC, created_at DESC
      LIMIT 200
    `).all(...userFilter.params);
    
    const recentTransactionsWithUrls = recentTransactions.map(t => ({
      ...t,
      receiptImageUrl: t.receiptImage ? `/uploads/receipts/${t.receiptImage}` : null
    }));
    
    const months = db.prepare(`
      SELECT DISTINCT 
        strftime('%Y', date) as year,
        strftime('%m', date) as month,
        strftime('%Y-%m', date) as month_year
      FROM transactions 
      WHERE ${userFilter.clause}
      ORDER BY year DESC, month DESC
    `).all(...userFilter.params);
    
    const monthLabels = months.map(m => {
      const date = moment(`${m.year}-${m.month}-01`, 'YYYY-MM-DD');
      return {
        year: parseInt(m.year),
        month: parseInt(m.month),
        label: date.format('MMMM [de] YYYY')
      };
    });
    
    const currentDate = moment(`${year}-${month}-01`, 'YYYY-MM-DD');
    
    return {
      success: true,
      totalBalance: totalBalanceResult?.totalBalance || 0,
      monthBalance: currentStats.totalIncome - currentStats.totalExpense,
      totalIncome: currentStats.totalIncome || 0,
      totalExpense: currentStats.totalExpense || 0,
      incomeChange: parseFloat(incomeChange.toFixed(1)),
      expenseChange: parseFloat(expenseChange.toFixed(1)),
      totalTransactions: currentStats.totalTransactions || 0,
      categoryData: categoryStats,
      paymentMethodData: paymentStats,
      recentTransactions: recentTransactionsWithUrls,
      currentMonth: month,
      currentYear: year,
      months: monthLabels,
      monthLabel: currentDate.format('MMMM [de] YYYY')
    };
  } catch (error) {
    console.error('❌ Erro em getStats:', error);
    return {
      success: false,
      error: error.message,
      totalBalance: 0,
      monthBalance: 0,
      totalIncome: 0,
      totalExpense: 0,
      incomeChange: 0,
      expenseChange: 0,
      totalTransactions: 0,
      categoryData: {},
      paymentMethodData: {},
      recentTransactions: [],
      currentMonth: month,
      currentYear: year,
      months: [],
      monthLabel: ''
    };
  }
}

function getTotalInvested(user) {
  try {
    const userFilter = buildUserWhere('transactions', user, 'user');
    const monthlyData = db.prepare(`
      SELECT 
        strftime('%Y-%m', date) as month_year,
        strftime('%Y', date) as year,
        strftime('%m', date) as month,
        SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END) as income,
        SUM(CASE WHEN type = 'expense' THEN amount ELSE 0 END) as expense
      FROM transactions 
      WHERE ${userFilter.clause}
      GROUP BY strftime('%Y-%m', date)
      ORDER BY year DESC, month DESC
    `).all(...userFilter.params);
    
    let totalInvested = 0;
    const allMonths = [];
    
    monthlyData.forEach(row => {
      const monthBalance = row.income - row.expense;
      const date = moment(`${row.year}-${row.month}-01`, 'YYYY-MM-DD');
      
      allMonths.push({
        monthYear: row.month_year,
        balance: monthBalance,
        income: row.income,
        expense: row.expense,
        month: parseInt(row.month),
        year: parseInt(row.year),
        label: date.format('MMMM [de] YYYY')
      });
      
      totalInvested += monthBalance;
    });
    
    return {
      success: true,
      totalInvested: parseFloat(totalInvested.toFixed(2)),
      positiveMonthsCount: allMonths.filter(m => m.balance > 0).length,
      totalMonthsCount: allMonths.length,
      negativeMonthsCount: allMonths.filter(m => m.balance < 0).length,
      zeroMonthsCount: allMonths.filter(m => m.balance === 0).length,
      averageMonthlyBalance: parseFloat((totalInvested / allMonths.length || 0).toFixed(2)),
      allMonths,
      positiveMonths: allMonths.filter(m => m.balance > 0)
        .sort((a, b) => b.balance - a.balance)
    };
  } catch (error) {
    console.error('❌ Erro em getTotalInvested:', error);
    return {
      success: false,
      error: error.message,
      totalInvested: 0,
      positiveMonthsCount: 0,
      totalMonthsCount: 0,
      negativeMonthsCount: 0,
      zeroMonthsCount: 0,
      averageMonthlyBalance: 0,
      allMonths: [],
      positiveMonths: []
    };
  }
}
// ============== FUNÇÃO PARA CALCULAR DISPONÍVEL PARA GASTO ==============
function calculateAvailableToSpend(user) {
    try {
        const now = moment().tz('America/Sao_Paulo');
        const currentMonth = now.month() + 1;
        const currentYear = now.year();
        const ultimoDiaMes = now.endOf('month').date();
        const diaAtual = now.date();
        const diasRestantes = ultimoDiaMes - diaAtual;
        
        // 1. Buscar saldos dos cartões
        const saldos = getCardBalances(user);
        
        // 2. Buscar receitas do mês (para calcular orçamento disponível)
        const stats = getStats(user, currentMonth, currentYear);
        
        // 3. Buscar gastos anteriores (últimos 3 meses) para média realista
        const lastMonth = currentMonth === 1 ? 12 : currentMonth - 1;
        const lastMonthYear = currentMonth === 1 ? currentYear - 1 : currentYear;
        
        const lastMonthStats = getStats(user, lastMonth, lastMonthYear);
        const twoMonthsAgo = lastMonth === 1 ? 12 : lastMonth - 1;
        const twoMonthsAgoYear = lastMonth === 1 ? lastMonthYear - 1 : lastMonthYear;
        const twoMonthsAgoStats = getStats(user, twoMonthsAgo, twoMonthsAgoYear);
        
        // 4. Calcular médias históricas
        const gastoUltimos3Meses = [
            stats.totalExpense || 0,
            lastMonthStats.totalExpense || 0,
            twoMonthsAgoStats.totalExpense || 0
        ];
        
        const mediaGastohistorica = gastoUltimos3Meses.reduce((a, b) => a + b, 0) / 3;
        const mediaDiariaHistorica = mediaGastohistorica / 30; // média por dia
        
        // 5. Calcular disponibilidade REAL
        const disponivelTotal = saldos.success ? 
            (saldos.data.Flash.balance + saldos.data.Pluxee.balance) : 0;
        
        // 6. Gasto atual do mês
        const gastoAtual = stats.totalExpense || 0;
        const mediaAtualDiaria = diaAtual > 0 ? gastoAtual / diaAtual : 0;
        
        // 7. Calcular "disponível para gasto médio" até fim do mês
        // Opção A: Baseado na média histórica
        const disponivelBasehistorica = (mediaDiariaHistorica * diasRestantes) - disponivelTotal;
        
        // Opção B: Baseado na média atual
        const disponivelBaseAtual = (mediaAtualDiaria * diasRestantes) - disponivelTotal;
        
        // Opção C: Meta saudável (80% da média histórica)
        const metaSaudavel = (mediaDiariaHistorica * 0.8) * diasRestantes;
        const disponivelMetaSaudavel = metaSaudavel - disponivelTotal;
        
        return {
            success: true,
            data: {
                // Informações básicas
                diaAtual: diaAtual,
                ultimoDiaMes: ultimoDiaMes,
                diasRestantes: diasRestantes,
                
                // Saldos disponíveis
                saldoFlash: saldos.success ? saldos.data.Flash.balance : 0,
                saldoPluxee: saldos.success ? saldos.data.Pluxee.balance : 0,
                saldoTotalDisponivel: disponivelTotal,
                
                // Gastos
                gastoEsteMes: gastoAtual,
                gastoMedioDiarioAtual: mediaAtualDiaria,
                gastoMedioDiariohistorica: mediaDiariaHistorica,
                
                // DISPONÍVEL PARA GASTAR (VALORES NEGATIVOS = LIMITE ULTRAPASSADO)
                disponivelGastoDiario: {
                    baseadohistorica: disponivelBasehistorica,
                    baseadoAtual: disponivelBaseAtual,
                    metaSaudavel: disponivelMetaSaudavel
                },
                
                // Em termos diários
                disponivelPorDia: {
                    baseadohistorica: disponivelBasehistorica / diasRestantes,
                    baseadoAtual: disponivelBaseAtual / diasRestantes,
                    metaSaudavel: disponivelMetaSaudavel / diasRestantes
                },
                
                // Alertas
                alertas: {
                    excedeuOrcamento: disponivelTotal < 0,
                    gastoAcimaMedia: mediaAtualDiaria > mediaDiariaHistorica,
                    saldoBaixo: disponivelTotal < 200
                },
                
                // Recomendações
                recomendacao: disponivelTotal > 0 ? 
                    `Você tem R$ ${disponivelTotal.toFixed(2)} disponível para os próximos ${diasRestantes} dias` :
                    `Atenção! Você já ultrapassou seu orçamento em R$ ${Math.abs(disponivelTotal).toFixed(2)}`
            }
        };
        
    } catch (error) {
        console.error('❌ Erro ao calcular disponível para gasto:', error);
        return { success: false, error: error.message };
    }
}
// 2. Função para buscar TODAS as contas Neon
// ============== FUNÇÃO PARA BUSCAR TODAS AS CONTAS NEON (ATUALIZADA) ==============
async function getNeonAllAccounts() {
    try {
        const apiKey = await getPluggyApiKey();
        
        const response = await axios.get(`${PLUGGY_API_URL}/accounts?itemId=${NEON_ITEM_ID}`, {
            headers: { 'X-API-KEY': apiKey }
        });
        
        const accounts = response.data.results || [];
        
        // Separar contas por tipo
        const investmentAccounts = accounts.filter(acc => 
            acc.type === 'FIXED_INCOME' || 
            acc.type === 'INVESTMENT' ||
            acc.subtype === 'CDB' ||
            acc.id === NEON_CAIXINHA_ID // Inclui explicitamente a nova caixinha
        );
        
        const currentAccount = accounts.find(acc => 
            acc.type === 'CHECKING_ACCOUNT' || acc.subtype === 'CHECKING_ACCOUNT'
        );
        
        console.log(`📊 Neon - Total de contas: ${accounts.length}`);
        console.log(`   💳 Conta Corrente: ${currentAccount ? 'Sim' : 'Não'}`);
        console.log(`   📈 Investimentos: ${investmentAccounts.length}`);
        
        // Listar todas as contas encontradas
        accounts.forEach((acc, i) => {
            const tipo = acc.type === 'CHECKING_ACCOUNT' ? '💳 Conta Corrente' : 
                        acc.type === 'FIXED_INCOME' ? '📈 Caixinha' : '🏦 Outro';
            console.log(`   ${i+1}. ${tipo}: ${acc.id} - ${acc.name || acc.subtype || 'Sem nome'}: R$ ${(acc.balance || 0).toFixed(2)}`);
        });
        
        return {
            success: true,
            all: accounts,
            current: currentAccount,
            investments: investmentAccounts,
            totalInvestmentsBalance: investmentAccounts.reduce((sum, acc) => sum + (acc.balance || 0), 0)
        };
        
    } catch (error) {
        console.error('❌ Erro ao buscar contas do Neon:', error.message);
        return { success: false, error: error.message, all: [], investments: [] };
    }
}
// 3. Função para buscar TODAS as transações Neon
// ============== FUNÇÃO ATUALIZADA PARA BUSCAR TODAS AS TRANSAÇÕES NEON ==============
async function getAllNeonTransactions(fromDate = null, toDate = null) {
    try {
        console.log('\n🔍 Buscando TODAS as transações Neon (incluindo nova caixinha)...');
        
        const apiKey = await getPluggyApiKey();
        const accounts = await getNeonAllAccounts();
        
        if (!accounts.success) {
            throw new Error(accounts.error);
        }
        
        let allTransactions = [];
        let accountsProcessed = [];
        
        // Buscar transações da conta corrente
        if (accounts.current) {
            console.log(`\n📊 Buscando transações da Conta Corrente: ${accounts.current.id}`);
            
            const currentTxResult = await getAccountTransactions(
                accounts.current.id, 
                fromDate, 
                toDate,
                { name: 'Conta Corrente', type: 'CHECKING_ACCOUNT' }
            );
            
            if (currentTxResult.success) {
                const currentTx = currentTxResult.transactions.map(t => ({
                    ...t,
                    banco: 'Neon',
                    conta: 'Conta Corrente',
                    accountType: 'CHECKING_ACCOUNT',
                    icone: '💳',
                    cor: '#667eea'
                }));
                
                allTransactions.push(...currentTx);
                console.log(`   → ${currentTx.length} transações`);
                
                accountsProcessed.push({
                    id: accounts.current.id,
                    name: 'Conta Corrente',
                    type: 'CHECKING_ACCOUNT',
                    transactionsCount: currentTx.length,
                    balance: accounts.current.balance
                });
            }
        }
        
        // Buscar transações de CADA caixinha/investimento
        for (const invAccount of accounts.investments) {
            console.log(`\n📊 Buscando transações da Caixinha: ${invAccount.name || invAccount.subtype || 'Sem nome'} (${invAccount.id})`);
            
            try {
                const invTxResult = await getAccountTransactions(
                    invAccount.id,
                    fromDate,
                    toDate,
                    {
                        name: invAccount.name || invAccount.subtype || 'Caixinha',
                        type: invAccount.type,
                        subtype: invAccount.subtype
                    }
                );
                
                if (invTxResult.success) {
                    const invTx = invTxResult.transactions.map(t => ({
                        ...t,
                        banco: 'Neon',
                        conta: `📈 Caixinha: ${invAccount.name || invAccount.subtype || 'Sem nome'}`,
                        accountType: 'FIXED_INCOME',
                        investmentDetails: {
                            id: invAccount.id,
                            name: invAccount.name,
                            subtype: invAccount.subtype,
                            balance: invAccount.balance,
                            dueDate: invAccount.dueDate,
                            rate: invAccount.rate,
                            status: invAccount.status
                        },
                        icone: '📈',
                        cor: '#f39c12'
                    }));
                    
                    allTransactions.push(...invTx);
                    console.log(`   → ${invTx.length} transações`);
                    
                    accountsProcessed.push({
                        id: invAccount.id,
                        name: invAccount.name || invAccount.subtype || 'Caixinha',
                        type: invAccount.type,
                        transactionsCount: invTx.length,
                        balance: invAccount.balance
                    });
                }
                
            } catch (err) {
                console.error(`   ❌ Erro na caixinha ${invAccount.id}:`, err.message);
            }
            
            // Pequena pausa para não sobrecarregar a API
            await sleep(200);
        }
        
        // Ordenar por data (mais recentes primeiro)
        allTransactions.sort((a, b) => moment(b.date).valueOf() - moment(a.date).valueOf());
        
        console.log(`\n📊 RESUMO DAS TRANSAÇÕES NEON:`);
        accountsProcessed.forEach(a => {
            console.log(`   • ${a.name}: ${a.transactionsCount} transações (Saldo: R$ ${(a.balance || 0).toFixed(2)})`);
        });
        console.log(`\n📈 TOTAL GERAL: ${allTransactions.length} transações`);
        
        return {
            success: true,
            transactions: allTransactions,
            total: allTransactions.length,
            accounts: accountsProcessed,
            totalBalance: accounts.investments.reduce((sum, acc) => sum + (acc.balance || 0), 0) + (accounts.current?.balance || 0)
        };
        
    } catch (error) {
        console.error('❌ Erro ao buscar transações Neon:', error.message);
        return { success: false, error: error.message, transactions: [] };
    }
}
// 4. Função para salvar transação Neon com categoria correta
// ============== FUNÇÃO ATUALIZADA PARA SALVAR TRANSAÇÃO NEON ==============
async function salvarTransacaoNeon(transaction, accountInfo) {
    try {
        const detected = detectNeonTransactionType(transaction, accountInfo);

        // Descrição enriquecida com o nome da conta/caixinha
        let descricaoFinal = transaction.description || 'Transação Neon';
        if (accountInfo.name) {
            descricaoFinal = `[${accountInfo.name}] ${descricaoFinal}`;
        }

        const resultado = await salvarTransacaoBancaria({
            banco: 'Neon',
            logLabel: `Neon - ${accountInfo.name || accountInfo.conta}`,
            txId: `neon_${transaction.id}`,
            description: descricaoFinal,
            amount: Math.abs(transaction.amount),
            type: detected.type,
            category: detected.category,
            paymentMethod: detected.paymentMethod,
            date: moment(transaction.date).format('YYYY-MM-DD'),
            userName: 'Usuário 1',
            notifyUserName: 'Sistema Neon',
            exigeAprovacao: pixEnviadoPrecisaAprovacao(transaction),
            pluggy: transaction
        });
        return resultado.saved;
    } catch (error) {
        console.error(`❌ Erro ao salvar transação Neon ${transaction && transaction.id}:`, error.message);
        return false;
    }
}
