function generateFinanceTXT(userRef, options = {}) {
  try {
    const timestamp = moment().format('YYYY-MM-DD_HH-mm-ss');
    const exportDir = path.join(DATA_DIR, 'ai_exports');
    
    if (!fs.existsSync(exportDir)) {
      fs.mkdirSync(exportDir, { recursive: true });
    }
    
    const ctx = resolveUserContext(userRef);
    const username = String(ctx && ctx.username ? ctx.username : (userRef && typeof userRef === 'object' ? (userRef.username || userRef.user || userRef.email || '') : (userRef || '')))
      .trim()
      .toLowerCase();
    const now = moment().tz('America/Sao_Paulo');
    const opt = options && typeof options === 'object' ? options : {};
    const requestedYear = Number(opt.year);
    const requestedMonth = typeof opt.month !== 'undefined' && opt.month !== null && opt.month !== '' ? Number(opt.month) : null;

    const usingYear = Number.isFinite(requestedYear) && requestedYear >= 2000 && requestedYear <= 2100;
    const usingMonth = usingYear && Number.isFinite(requestedMonth) && requestedMonth >= 1 && requestedMonth <= 12;

    const year = usingYear ? requestedYear : now.year();
    const month = usingMonth ? requestedMonth : (now.month() + 1);
    const periodLabel = usingYear ? (usingMonth ? `${year}-${String(month).padStart(2, '0')}` : `${year}`) : now.format('YYYY-MM');

    const safeUserLabel = username ? username.replace(/[^a-z0-9@._-]/gi, '_') : 'geral';
    const txtFilePath = path.join(exportDir, `financas_${safeUserLabel}_${periodLabel}.txt`);

    const txFilters = { limit: 5000 };
    if (Number.isFinite(Number(ctx && ctx.userId))) txFilters.userId = Number(ctx.userId);
    else if (username) txFilters.user = username;
    if (usingYear && !usingMonth) {
      txFilters.startDate = `${year}-01-01`;
      txFilters.endDate = `${year}-12-31`;
    } else {
      txFilters.month = month;
      txFilters.year = year;
    }

    const transactions = getTransactions(txFilters);
    
    const periodHuman = usingYear ? (usingMonth ? `${String(month).padStart(2, '0')}/${year}` : `${year}`) : now.format('MM/YYYY');
    let txtContent = `RELATÓRIO FINANCEIRO - GERADO EM: ${now.format('DD/MM/YYYY HH:mm:ss')}\n`;
    txtContent += `PERÍODO: ${periodHuman}\n`;
    txtContent += `USUÁRIO: ${username || 'SISTEMA COMPLETO'}\n`;
    txtContent += `TOTAL DE REGISTROS: ${transactions.length}\n`;
    txtContent += `----------------------------------------------------------\n\n`;

    const grouped = {};
    transactions.forEach(t => {
      if (!grouped[t.date]) grouped[t.date] = [];
      grouped[t.date].push(t);
    });

    Object.keys(grouped).sort().reverse().forEach(date => {
      txtContent += `DATA: ${date}\n`;
      grouped[date].forEach(t => {
        const sinal = t.type === 'income' ? '[+] RECEITA' : '[-] DESPESA';
        txtContent += `  ${sinal} | R$ ${t.amount.toFixed(2).padStart(10)} | ${t.description} | Cat: ${t.category} | Via: ${t.paymentMethod}\n`;
      });
      txtContent += `\n`;
    });

    const totalInc = transactions.filter(t => t.type === 'income').reduce((s, t) => s + t.amount, 0);
    const totalExp = transactions.filter(t => t.type === 'expense').reduce((s, t) => s + t.amount, 0);

    txtContent += `\n----------------------------------------------------------\n`;
    txtContent += `RESUMO FINAL:\n`;
    txtContent += `RECEITAS TOTAIS: R$ ${totalInc.toFixed(2)}\n`;
    txtContent += `DESPESAS TOTAIS: R$ ${totalExp.toFixed(2)}\n`;
    txtContent += `SALDO ATUAL: R$ ${(totalInc - totalExp).toFixed(2)}\n`;

    fs.writeFileSync(txtFilePath, txtContent, 'utf8');
    return { success: true, filePath: txtFilePath, content: txtContent, period: periodLabel };
  } catch (error) {
    console.error('❌ Erro ao gerar TXT:', error);
    return { success: false, error: error.message };
  }
}

function analyzeTransactionsForAI(user, period = 'mes') {
  try {
    let dateCondition = '';
    const userFilter = buildUserWhere('transactions', user, 'user');
    let params = [...userFilter.params];
    
    switch(period.toLowerCase()) {
      case 'hoje':
        dateCondition = `AND date = date('now')`;
        break;
      case 'ontem':
        dateCondition = `AND date = date('now', '-1 day')`;
        break;
      case 'semana':
        dateCondition = `AND date >= date('now', '-7 days')`;
        break;
      case 'mes':
        dateCondition = `AND strftime('%Y-%m', date) = strftime('%Y-%m', 'now', 'localtime')`;
        break;
      case 'ultimo_mes':
      case 'last_month':
        dateCondition = `AND strftime('%Y-%m', date) = strftime('%Y-%m', 'now', 'localtime', '-1 month')`;
        break;
      case 'trimestre':
        dateCondition = `AND strftime('%Y', date) = strftime('%Y', 'now', 'localtime') 
                        AND ((strftime('%m', date)-1)/3) = ((strftime('%m', 'now', 'localtime')-1)/3)`;
        break;
      case 'ano':
        dateCondition = `AND strftime('%Y', date) = strftime('%Y', 'now')`;
        break;
      case 'todos':
      case 'all':
        break;
      default:
        dateCondition = `AND strftime('%Y-%m', date) = strftime('%Y-%m', 'now')`;
    }
    
    const whereClause = `WHERE ${userFilter.clause} ${dateCondition}`.trim();
    
    const stats = db.prepare(`
      SELECT 
        COUNT(*) as total,
        COALESCE(SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END), 0) as income,
        COALESCE(SUM(CASE WHEN type = 'expense' THEN amount ELSE 0 END), 0) as expense,
        MIN(date) as start_date,
        MAX(date) as end_date
      FROM transactions
      ${whereClause}
    `).get(...params);
    
    const categories = db.prepare(`
      SELECT 
        category,
        type,
        SUM(amount) as total,
        COUNT(*) as count
      FROM transactions
      ${whereClause}
      GROUP BY category, type
      ORDER BY total DESC
      LIMIT 20
    `).all(...params);
    
    const largestTransactions = db.prepare(`
      SELECT 
        description,
        amount,
        type,
        category,
        date
      FROM transactions
      ${whereClause}
      ORDER BY amount DESC
      LIMIT 200
    `).all(...params);
    
    let days = 0;
    if (stats.start_date && stats.end_date) {
      const start = moment(stats.start_date);
      const end = moment(stats.end_date);
      days = Math.max(1, Math.ceil(end.diff(start, 'days')));
    } else if (dateCondition) {
      switch(period.toLowerCase()) {
        case 'hoje': days = 1; break;
        case 'ontem': days = 1; break;
        case 'semana': days = 7; break;
        case 'mes': days = 30; break;
        case 'ultimo_mes':
        case 'last_month': days = 30; break;
        case 'trimestre': days = 90; break;
        case 'ano': days = 365; break;
        default: days = 30;
      }
    }
    
    return {
      success: true,
      total: stats.total || 0,
      income: stats.income || 0,
      expense: stats.expense || 0,
      balance: (stats.income || 0) - (stats.expense || 0),
      dailyAverage: (stats.income + stats.expense) / (days || 30),
      period: {
        start: stats.start_date,
        end: stats.end_date,
        days: days || 30
      },
      categories: categories.reduce((acc, row) => {
        if (!acc[row.category]) {
          acc[row.category] = { income: 0, expense: 0, count: 0 };
        }
        acc[row.category][row.type] = row.total;
        acc[row.category].count += row.count;
        return acc;
      }, {}),
      largestTransaction: largestTransactions[0] || null,
      topExpenses: categories.filter(c => c.type === 'expense').slice(0, 5),
      topIncomes: categories.filter(c => c.type === 'income').slice(0, 5)
    };
  } catch (error) {
    console.error('❌ Erro em analyzeTransactionsForAI:', error);
    return { success: false, total: 0, income: 0, expense: 0, balance: 0, dailyAverage: 0 };
  }
}

function searchTransactionsForAI(user, searchTerm) {
  try {
    const userFilter = buildUserWhere('transactions', user, 'user');
    const searchLike = `%${searchTerm}%`;
    return db.prepare(`
      SELECT 
        description,
        amount,
        type,
        category,
        payment_method as paymentMethod,
        date
      FROM transactions
      WHERE ${userFilter.clause} AND (
        description LIKE ? OR 
        category LIKE ? OR 
        payment_method LIKE ?
      )
      ORDER BY date DESC
      LIMIT 40
    `).all(...userFilter.params, searchLike, searchLike, searchLike);
  } catch (error) {
    console.error('❌ Erro em searchTransactionsForAI:', error);
    return [];
  }
}

function getAICache(user, queryHash) {
  try {
    const userFilter = buildUserWhere('ai_cache', user, 'user');
    return db.prepare(`
      SELECT * FROM ai_cache 
      WHERE ${userFilter.clause} AND query_hash = ? AND expires_at > datetime('now')
    `).get(...userFilter.params, queryHash);
  } catch (error) {
    console.error('❌ Erro em getAICache:', error);
    return null;
  }
}

function setAICache(user, queryHash, response, period, ttlHours = 1) {
  try {
    const ctx = resolveUserContext(user);
    const hasUserId = tableHasColumn('ai_cache', 'user_id');
    if (hasUserId && ctx.userId !== null) {
      db.prepare(`
        INSERT OR REPLACE INTO ai_cache 
        (user_id, user, query_hash, response, period, expires_at)
        VALUES (?, ?, ?, ?, ?, datetime('now', ?))
      `).run(ctx.userId, ctx.username, queryHash, response, period, `+${ttlHours} hours`);
    } else {
      db.prepare(`
        INSERT OR REPLACE INTO ai_cache 
        (user, query_hash, response, period, expires_at)
        VALUES (?, ?, ?, ?, datetime('now', ?))
      `).run(ctx.username, queryHash, response, period, `+${ttlHours} hours`);
    }
    
    return true;
  } catch (error) {
    console.error('❌ Erro em setAICache:', error);
    return false;
  }
}

function logChatInteraction(user, question, answer, context, tokensUsed, responseTime) {
  try {
    const ctx = resolveUserContext(user);
    const hasUserId = tableHasColumn('chat_logs', 'user_id');
    if (hasUserId && ctx.userId !== null) {
      db.prepare(`
        INSERT INTO chat_logs 
        (user_id, user, question, answer, context, tokens_used, response_time_ms)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).run(ctx.userId, ctx.username, question, answer, JSON.stringify(context), tokensUsed, responseTime);
    } else {
      db.prepare(`
        INSERT INTO chat_logs 
        (user, question, answer, context, tokens_used, response_time_ms)
        VALUES (?, ?, ?, ?, ?, ?)
      `).run(ctx.username, question, answer, JSON.stringify(context), tokensUsed, responseTime);
    }
    
    return true;
  } catch (error) {
    console.error('❌ Erro em logChatInteraction:', error);
    return false;
  }
}

function formatTelegramResponse(rawResponse) {
  let formatted = String(rawResponse || '');
  formatted = formatted
    .replace(/\*\*(.*?)\*\*/g, '*$1*')
    .replace(/___(.*?)___/g, '*$1*');
  formatted = formatted.replace(/━{4,}/g, '━━━━━━━━━━━━━━━━━━━━');
  return sanitizeTelegramMarkdown(formatted);
}

function sanitizeTelegramMarkdown(text) {
  let cleaned = String(text || '');

  cleaned = cleaned
    .replace(/\r/g, '')
    .replace(/\*\*(.*?)\*\*/g, '*$1*')
    .replace(/___(.*?)___/g, '*$1*')
    .replace(/__(.*?)__/g, '_$1_')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1');

  const removeUnpaired = (input, marker) => {
    const chars = Array.from(String(input || ''));
    const positions = [];
    for (let i = 0; i < chars.length; i += 1) {
      if (chars[i] !== marker) continue;
      if (i > 0 && chars[i - 1] === '\\') continue;
      positions.push(i);
    }
    if (positions.length % 2 === 0) return chars.join('');
    chars[positions[positions.length - 1]] = '';
    return chars.join('');
  };

  cleaned = removeUnpaired(cleaned, '*');
  cleaned = removeUnpaired(cleaned, '_');
  cleaned = removeUnpaired(cleaned, '`');

  if (/\*[^*\n]*$/.test(cleaned)) cleaned = cleaned.replace(/\*/g, '');
  if (/_[^_\n]*$/.test(cleaned)) cleaned = cleaned.replace(/_/g, '');
  if (/`[^`\n]*$/.test(cleaned)) cleaned = cleaned.replace(/`/g, '');

  return cleaned;
}

function stripTelegramMarkdown(text) {
  return String(text || '')
    .replace(/```[\s\S]*?```/g, (m) => m.replace(/`/g, ''))
    .replace(/[`*_]/g, '')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/</g, '')
    .replace(/>/g, '');
}

async function replyWithMarkdownSafe(ctx, text, extra = {}) {
  const raw = sanitizeTelegramMarkdown(text);
  try {
    return await ctx.reply(raw, { ...extra, parse_mode: 'Markdown' });
  } catch (e) {
    const errMsg = e && (e.description || e.message) ? String(e.description || e.message) : 'Erro Telegram';
    console.error('❌ Markdown inválido (Telegram):', errMsg, raw.slice(0, 400));
    const fallback = stripTelegramMarkdown(raw);
    const { parse_mode, ...rest } = extra || {};
    return await ctx.reply(fallback, rest);
  }
}

async function sendTelegramMarkdownSafe(chatId, text, extra = {}) {
  const raw = sanitizeTelegramMarkdown(text);
  try {
    return await bot.telegram.sendMessage(chatId, raw, { ...extra, parse_mode: 'Markdown' });
  } catch (e) {
    const errMsg = e && (e.description || e.message) ? String(e.description || e.message) : 'Erro Telegram';
    console.error('❌ Markdown inválido (sendMessage):', errMsg, raw.slice(0, 400));
    const fallback = stripTelegramMarkdown(raw);
    const { parse_mode, ...rest } = extra || {};
    return await bot.telegram.sendMessage(chatId, fallback, rest);
  }
}

// ============== EXECUTOR SQL SEGURO PARA IA ==============
// UPPER/LOWER/LIKE nativos do SQLite só tratam ASCII: UPPER('Alimentação') = 'ALIMENTAçãO', e a IA
// escreve UPPER(category) LIKE '%ALIMENTAÇÃO%' -> sempre 0. Conexão própria (só leitura) com versões
// Unicode e LIKE sem acento/caixa, para não mudar o comportamento do resto do sistema.
let aiQueryDb = null;
function getAIQueryDb() {
  if (aiQueryDb) return aiQueryDb;
  const semAcento = (s) => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  const conn = new Database(DB_FILE, { readonly: true, fileMustExist: true });
  conn.function('upper', { deterministic: true }, (s) => (s == null ? null : String(s).toUpperCase()));
  conn.function('lower', { deterministic: true }, (s) => (s == null ? null : String(s).toLowerCase()));
  conn.function('like', { deterministic: true, varargs: true }, (pattern, value, escape) => {
    if (pattern == null || value == null) return null;
    const esc = escape == null ? null : String(escape);
    let re = '';
    const p = semAcento(pattern);
    for (let i = 0; i < p.length; i++) {
      const c = p[i];
      if (esc && c === esc && i + 1 < p.length) re += p[++i].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      else if (c === '%') re += '[\\s\\S]*';
      else if (c === '_') re += '[\\s\\S]';
      else re += c.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }
    return new RegExp(`^${re}$`).test(semAcento(value)) ? 1 : 0;
  });
  aiQueryDb = conn;
  return conn;
}

function safeExecuteSQL(sql, userId, userObj) {
    if (!db) throw new Error('DB_NOT_READY');
    const raw = String(sql || '').trim();
    if (!raw) throw new Error('SQL vazia.');

    const statements = raw
      .split(';')
      .map((s) => String(s || '').trim())
      .filter(Boolean);
    if (statements.length !== 1) throw new Error('Apenas uma consulta SQL é permitida.');

    const trimmed = statements[0];
    if (!/^SELECT\b/i.test(trimmed)) throw new Error('Apenas consultas SELECT são permitidas.');
    if (/[?]/.test(trimmed) || /:\w+/.test(trimmed)) throw new Error('Parâmetros SQL não são permitidos.');
    if (/--|\/\*/.test(trimmed)) throw new Error('Comentários SQL não são permitidos.');

    if (!/\bFROM\s+transactions\b/i.test(trimmed) && !/\bJOIN\s+transactions\b/i.test(trimmed)) {
      throw new Error('A consulta deve usar a tabela transactions.');
    }

    const dangerous = /\b(DROP|INSERT|UPDATE|DELETE|ALTER|CREATE|TRUNCATE|REPLACE|ATTACH|DETACH|PRAGMA|sqlite_master|randomblob)\b/i;
    if (dangerous.test(trimmed)) throw new Error('Operação não permitida.');

    let finalSQL = trimmed;
    if (!/LIMIT\s+\d+/i.test(finalSQL)) finalSQL += ' LIMIT 200';

    const userFilter = buildUserWhere('transactions', userObj || userId, 'user');
    const hasWhere = /\bWHERE\b/i.test(finalSQL);
    if (hasWhere) {
      finalSQL = finalSQL.replace(/\bWHERE\b/i, `WHERE (${userFilter.clause}) AND`);
    } else {
      const orderIdx = finalSQL.toUpperCase().indexOf('ORDER BY');
      const groupIdx = finalSQL.toUpperCase().indexOf('GROUP BY');
      const havingIdx = finalSQL.toUpperCase().indexOf('HAVING');
      const limitIdx = finalSQL.toUpperCase().indexOf('LIMIT');
      const insertPos = Math.min(
        orderIdx === -1 ? Infinity : orderIdx,
        groupIdx === -1 ? Infinity : groupIdx,
        havingIdx === -1 ? Infinity : havingIdx,
        limitIdx === -1 ? Infinity : limitIdx
      );
      if (insertPos === Infinity) {
        finalSQL += ` WHERE ${userFilter.clause}`;
      } else {
        const before = finalSQL.slice(0, insertPos);
        const after = finalSQL.slice(insertPos);
        finalSQL = `${before} WHERE ${userFilter.clause} ${after}`;
      }
    }

    console.log('🔐 SQL segura executada:', finalSQL, 'Params:', userFilter.params);
    const stmt = getAIQueryDb().prepare(finalSQL);
    return stmt.all(...userFilter.params);
}

// Resultado da consulta volta para o modelo em toda rodada seguinte: limita linhas e tamanho
// para uma listagem grande não estourar o limite de tokens por minuto do Groq.
const AI_TOOL_MAX_ROWS = 50;
const AI_TOOL_MAX_CHARS = 6000;
function toolRowsToContent(rows) {
  const list = Array.isArray(rows) ? rows : [];
  let shown = list.slice(0, AI_TOOL_MAX_ROWS);
  let json = JSON.stringify(shown);
  while (json.length > AI_TOOL_MAX_CHARS && shown.length > 1) {
    shown = shown.slice(0, Math.floor(shown.length * 0.7));
    json = JSON.stringify(shown);
  }
  if (shown.length === list.length) return json;
  return JSON.stringify({
    aviso: `Mostrando ${shown.length} de ${list.length} linhas (o banco limita a 200). Para totais use SUM/COUNT.`,
    linhas: shown
  });
}

async function processFinanceChat(user, question, channel = 'dashboard') {
  const startTime = Date.now();
  const q = String(question || '').trim();
  if (!q) {
    return { success: false, error: 'Mensagem não pode estar vazia', answer: '' };
  }

  try {
    const userMemKey =
      user && typeof user === 'object'
        ? (Number.isFinite(Number(user.id || user.userId)) ? String(user.id || user.userId) : String(user.username || user.email || user.name || 'user'))
        : String(user || 'user');
    // Histórico vai em toda rodada do tool-calling: só a última troca, com a resposta encurtada.
    const history = getChatHistory(userMemKey, 2);
    let historyText = '';
    if (history.length) {
      historyText =
        '\n## Conversa anterior (os valores podem estar errados; confira no banco se forem usados):\n' +
        history
          .map((h) => {
            const txt = String(h.content || '').replace(/\s+/g, ' ').trim();
            return h.role === 'user' ? `Usuário: ${txt.slice(0, 200)}` : `Assistente: ${txt.slice(0, 300)}`;
          })
          .join('\n');
    }

    const now = moment().tz('America/Sao_Paulo');
    const currentDay = now.date();
    const currentMonth = now.month() + 1;
    const currentYear = now.year();
    const currentMonthName = now.format('MMMM');
    const monthYearStr = now.format('YYYY-MM');

    const fmt = formatBRL;
    const userLabel = String(user?.name || user?.username || user?.email || 'Usuário');

    let context = '';
    const hasPastDate = /\b(ano passado|ano anterior|ano retrasado|m[eê]s passado|m[eê]s anterior|m[eê]s retrasado|20\d{2}|\d{4}-\d{2}-\d{2}|em \d{2}\/\d{4}|(n?est?e|ness?e|no|do|por|ao) ano|anual|anualmente|[uú]ltim[oa]s? \d+|semestre|trimestre|desde|hist[oó]rico|todos os meses|por m[eê]s|m[eé]dia mensal|janeiro|fevereiro|mar[cç]o|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro)\b/i.test(q);

    const userFilter = buildUserWhere('transactions', user, 'user');
    let recentTransactions = [];
    let stats = null;
    let cardBalances = null;
    let faturas = null;
    let totalIncome = 0;
    let totalExpense = 0;
    let balanceMonth = 0;

    if (!hasPastDate) {
      recentTransactions = db
        .prepare(
          `
          SELECT 
            id,
            transaction_id as transactionId,
            description,
            amount,
            type,
            category,
            payment_method as paymentMethod,
            date,
            user,
            user_name as userName,
            receipt_image as receiptImage,
            created_at as createdAt
          FROM transactions 
          WHERE ${userFilter.clause}
            AND strftime('%Y-%m', date) = ?
          ORDER BY date DESC, created_at DESC
        `
        )
        .all(...userFilter.params, monthYearStr);

      stats = getStats(user, currentMonth, currentYear);
      cardBalances = getCardBalances(user);
      faturas = calculateCardFaturas(user);

      totalIncome = recentTransactions.filter((t) => t.type === 'income').reduce((sum, t) => sum + Number(t.amount || 0), 0);
      totalExpense = recentTransactions.filter((t) => t.type === 'expense').reduce((sum, t) => sum + Number(t.amount || 0), 0);
      balanceMonth = totalIncome - totalExpense;

      const categoriesExpense = {};
      for (const t of recentTransactions) {
        if (t.type !== 'expense') continue;
        const amount = Number(t.amount || 0);
        const cat = String(t.category || 'Outros');
        categoriesExpense[cat] = (categoriesExpense[cat] || 0) + amount;
      }

      const flashBalance = cardBalances?.success ? Number(cardBalances.data?.Flash?.balance || 0) : 0;
      const pluxeeBalance = cardBalances?.success ? Number(cardBalances.data?.Pluxee?.balance || 0) : 0;

      context += `📊 *DADOS FINANCEIROS DO MÊS ATUAL*\n`;
      context += `━━━━━━━━━━━━━━━━━━━━\n`;
      context += `📅 *Período:* ${currentDay} de ${currentMonthName} de ${currentYear}\n`;
      context += `👤 *Usuário:* ${userLabel}\n`;
      context += `━━━━━━━━━━━━━━━━━━━━\n\n`;

      context += `💰 *RESUMO FINANCEIRO*\n`;
      context += `• Receitas totais: ${fmt(totalIncome)}\n`;
      context += `• Despesas totais: ${fmt(totalExpense)}\n`;
      context += `• Saldo do mês: ${balanceMonth >= 0 ? `🟢 ${fmt(balanceMonth)}` : `🔴 ${fmt(balanceMonth)}`}\n`;
      context += `• Total de transações: ${recentTransactions.length}\n\n`;

      if (cardBalances && cardBalances.success) {
        context += `💳 *SALDOS DOS CARTÕES*\n`;
        context += `• Flash: ${fmt(flashBalance)}\n`;
        context += `• Pluxee: ${fmt(pluxeeBalance)}\n\n`;
      }

      if (faturas && faturas.success) {
        context += `🏦 *FATURAS DE CARTÕES DE CRÉDITO*\n`;
        context += `• Banrisul: ${fmt(faturas.banrisul)}\n`;
        context += `• Magazine: ${fmt(faturas.magazine)}\n`;
        context += `• Bradesco: ${fmt(faturas.bradesco || 0)}\n\n`;
      }

      const topExpenses = Object.entries(categoriesExpense)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5);
      if (topExpenses.length > 0) {
        context += `📂 *GASTOS POR CATEGORIA (TOP 5)*\n`;
        topExpenses.forEach(([cat, val], i) => {
          context += `${i + 1}. ${cat}: ${fmt(val)}\n`;
        });
        context += `\n`;
      }

      if (recentTransactions.length > 0) {
        context += `📋 *ÚLTIMAS TRANSAÇÕES (5 mais recentes)*\n`;
        recentTransactions.slice(0, 5).forEach((t, i) => {
          const tipo = t.type === 'income' ? '💰' : '💸';
          const data = moment(t.date).format('DD/MM');
          const desc = String(t.description || '').slice(0, 30);
          context += `${i + 1}. ${tipo} ${data} - ${desc}: ${fmt(t.amount)}\n`;
        });
        context += `\n`;
      }

      if (stats && stats.success) {
        const dailyAvg = Number(stats.totalExpense || 0) / Math.max(1, currentDay);
        context += `📈 *MÉTRICAS*\n`;
        context += `• Média diária de gastos (mês atual): ${fmt(dailyAvg)}\n\n`;
      }
    }

    const formattingRules =
      channel === 'telegram'
        ? `Texto simples: sem asteriscos, underscores, crases ou links Markdown.`
        : `Markdown simples.`;

    // Categorias reais do usuário: a IA acerta o filtro na primeira consulta em vez de chutar nomes.
    let categoriesText = '';
    try {
      const cats = db
        .prepare(
          `SELECT category, COUNT(*) AS n FROM transactions
           WHERE ${userFilter.clause} AND category IS NOT NULL AND TRIM(category) <> ''
             AND date >= date('now', '-18 months')
           GROUP BY category ORDER BY n DESC LIMIT 80`
        )
        .all(...userFilter.params)
        .map((r) => r.category);
      if (cats.length) categoriesText = `Categorias existentes: ${cats.join(' | ')}\n`;
    } catch (_) {}

    const prompt = `Hoje: ${now.format('DD/MM/YYYY')}.
${context}${historyText}

PERGUNTA: "${q}"

REGRAS:
- Se o contexto do mês atual já responde, responda direto. Senão, consulte com query_transactions (uso interno: nunca mostre SQL, nomes de tabela/coluna nem "como foi calculado").
- Tabela transactions: description, amount, type ('income'|'expense'), category, payment_method, date ('YYYY-MM-DD').
${categoriesText}- Se a pergunta cita uma dessas categorias, filtre por category = 'nome exato'. Para outros termos (loja, produto, "conta de luz"), use LIKE '%termo%' em description OR category OR payment_method.
- Mensagem com só um termo (ex.: "smurf", "red bull") é um pedido de busca: some e liste os lançamentos com esse termo.
- Busca com várias palavras (ex.: "Ricardo piso"): um LIKE por palavra, unidos com AND — não busque a frase inteira.
- Busca por valor, filtre só pelo valor: "compra de 165,45" -> SELECT date, description, amount FROM transactions WHERE ABS(amount - 165.45) < 0.01
- Datas depois de hoje são parcelas futuras ou compras no cartão lançadas no dia 05 da fatura. "Quando/que dia comprei X" ou "última compra de X" -> ... AND date <= '${now.format('YYYY-MM-DD')}' ORDER BY date DESC. Totais por período seguem o período pedido, sem esse corte.
- Para totais prefira SUM/COUNT/GROUP BY a listar linhas.
- Valores em "R$ 1.234,56"; datas como "15 de março de ${currentYear}". Máx. 2000 caracteres, sem blocos de código, emojis com moderação. ${formattingRules}
`;

    const tools = [
      {
        type: "function",
        function: {
          name: "query_transactions",
          description: "Executa um SELECT (SQLite) na tabela transactions do usuário e retorna as linhas em JSON.",
          parameters: {
            type: "object",
            properties: {
              sql: {
                type: "string",
                description: "Um único SELECT. Ex.: SELECT SUM(amount) AS total, COUNT(*) AS qtd FROM transactions WHERE type='expense' AND category='Alimentação' AND date BETWEEN '2026-01-01' AND '2026-12-31'"
              }
            },
            required: ["sql"]
          }
        }
      }
    ];

    const messages = [
      {
        role: 'system',
        content: 'Você é um assistente financeiro pessoal. Responda em português, direto ao ponto, só com a resposta final.'
      },
      { role: 'user', content: prompt }
    ];

    const initialTemperature = hasPastDate ? GROQ_TEMPERATURES.tools : GROQ_TEMPERATURES.dataAnalysis;

    // Loop de tool-calling: permite até MAX_TOOL_ROUNDS-1 rodadas de query_transactions.
    // Se uma consulta vier vazia/zerada, a IA recebe um empurrão para tentar de novo com
    // uma busca mais ampla (LIKE em description/category/payment_method) antes de concluir
    // que não há dados — em vez de aceitar a primeira consulta (possivelmente restritiva
    // demais, ex.: category='X' com igualdade exata) como resposta final.
    const MAX_TOOL_ROUNDS = 3;
    let workingMessages = messages.slice();
    let finalAnswer = '';
    let executedSQL = null;
    let usedTool = false;
    let totalTokens = 0;

    for (let round = 0; round < MAX_TOOL_ROUNDS; round++) {
      const allowTools = round < MAX_TOOL_ROUNDS - 1;
      const roundCompletion = await createGroqChatCompletion({
        messages: workingMessages,
        model: 'openai/gpt-oss-120b',
        temperature: round === 0 ? initialTemperature : GROQ_TEMPERATURES.dataAnalysis,
        max_tokens: GROQ_MAX_TOKENS,
        reasoning_effort: 'low',
        ...(allowTools ? { tools, tool_choice: 'auto' } : {})
      }, {
        location: `sistema-mobile-3004.js:askAIWithTools.round${round}`
      });

      totalTokens += (roundCompletion.usage?.total_tokens || 0);
      const roundMessage = roundCompletion.choices[0]?.message || {};
      finalAnswer = roundMessage.content || finalAnswer;

      if (!allowTools || !Array.isArray(roundMessage.tool_calls) || roundMessage.tool_calls.length === 0) {
        break;
      }

      usedTool = true;
      const toolResponses = [];
      let sawEmptyResult = false;
      for (const toolCall of roundMessage.tool_calls) {
        const toolName = toolCall && toolCall.function && toolCall.function.name ? String(toolCall.function.name) : '';
        if (toolName !== 'query_transactions') continue;
        let args = {};
        try {
          args = toolCall.function && toolCall.function.arguments
            ? (typeof toolCall.function.arguments === 'string' ? JSON.parse(toolCall.function.arguments) : toolCall.function.arguments)
            : {};
        } catch (_) {
          args = {};
        }
        const sql = args && args.sql ? String(args.sql) : '';
        executedSQL = sql || executedSQL;

        try {
          const rows = safeExecuteSQL(sql, userFilter.ctx.userId, user);
          if (!Array.isArray(rows) || rows.length === 0) {
            sawEmptyResult = true;
          } else if (rows.length === 1 && rows[0] && typeof rows[0] === 'object') {
            const vals = Object.values(rows[0]);
            if (vals.length > 0 && vals.every((v) => v === null || v === 0 || v === '0')) sawEmptyResult = true;
          }
          toolResponses.push({
            role: 'tool',
            tool_call_id: toolCall.id,
            content: toolRowsToContent(rows)
          });
        } catch (err) {
          sawEmptyResult = true;
          toolResponses.push({
            role: 'tool',
            tool_call_id: toolCall.id,
            content: JSON.stringify({ error: err && err.message ? String(err.message) : 'Erro ao executar SQL' })
          });
        }
      }

      if (!toolResponses.length) break;

      workingMessages = workingMessages.concat([roundMessage], toolResponses);

      if (sawEmptyResult && round < MAX_TOOL_ROUNDS - 2) {
        workingMessages.push({
          role: 'user',
          content: "Veio vazio/zerado. Tente uma vez mais ampla: LIKE '%termo%' em description OR category OR payment_method (a busca já ignora acento e maiúsculas), com palavras separadas e sinônimos ou nomes usados nos lançamentos (ex.: energia -> luz/equatorial; remédio -> farmácia; supermercado -> mercado/super). Se vier vazio de novo, diga que não há registros."
        });
      } else {
        workingMessages.push({
          role: 'user',
          content: 'Responda agora em linguagem natural, direto ao ponto. NÃO mostre a consulta SQL, nomes de tabelas/colunas nem qualquer explicação técnica de "como foi calculado". Não use blocos de código.'
        });
      }
    }

    let aiResponse = finalAnswer || 'Desculpe, não consegui processar sua pergunta no momento.';
    if (channel === 'telegram') aiResponse = formatTelegramResponse(aiResponse);
    if (aiResponse.length > 2000) aiResponse = aiResponse.slice(0, 1990) + '…';

    addToChatMemory(userMemKey, 'user', q);
    addToChatMemory(userMemKey, 'assistant', aiResponse);

    const responseTime = Date.now() - startTime;
    logChatInteraction(
      user,
      q,
      aiResponse.substring(0, 500),
      {
        source: channel,
        period: usedTool ? 'sql-tool' : 'current-month',
        month: monthYearStr,
        transactionCount: recentTransactions.length,
        sql: executedSQL ? String(executedSQL).slice(0, 300) : null
      },
      totalTokens,
      responseTime
    );

    return {
      success: true,
      answer: aiResponse,
      metadata: {
        period: usedTool ? 'SQL (Text-to-SQL)' : 'Mês atual',
        currentDate: `${currentDay} de ${currentMonthName} de ${currentYear}`,
        transactionCount: recentTransactions.length,
        totalIncome,
        totalExpense,
        balanceMonth,
        responseTime: `${responseTime}ms`,
        tokens: totalTokens
      }
    };
  } catch (error) {
    console.error('❌ Erro na IA:', error && error.message ? error.message : error);
    return {
      success: false,
      error: error.message,
      answer:
        channel === 'telegram'
          ? '❌ *Erro na IA*\n\nDesculpe, estou com problemas técnicos no momento. Tente novamente mais tarde.'
          : 'Desculpe, estou com problemas técnicos no momento. Tente novamente mais tarde.'
    };
  }
}

// ============== FUNÇÕES DE INSIGHTS REVISADAS ==============
function getDetailedInsights(user) {
   const now = moment().tz('America/Sao_Paulo');
    const diaAtual = now.date();
    const mesAtual = now.month() + 1;
    const anoAtual = now.year();
    
    const ultimoDiaMes = now.endOf('month').date();
    const diasRestantes = (ultimoDiaMes - diaAtual) + 1;

    const stats = getStats(user, mesAtual, anoAtual);
    const saldos = getCardBalances(user);
    const faturas = calculateCardFaturas(user);

    const mediaGastoDiario = stats.totalExpense / diaAtual;
    const saldoTotalBeneficios = saldos.data.Flash.balance + saldos.data.Pluxee.balance;
    const disponivelDiarioBeneficio = saldoTotalBeneficios / diasRestantes;

    return {
        mediaGastoDiario,
        disponivelDiarioBeneficio,
        ultimoDiaMes,
        diasRestantes,
        saldoTotalBeneficios,
        faturas
    };
}
