function getTelegramLinkedAccountInfo(chatId) {
  try {
    if (!db) return { linked: false, isAdmin: false, id: null, name: '' };
    const row = db.prepare(`
      SELECT id, name, role
      FROM users
      WHERE telegram_id = ?
      LIMIT 1
    `).get(String(chatId || '').trim());
    if (!row) return { linked: false, isAdmin: false, id: null, name: '' };
    return {
      linked: true,
      isAdmin: String(row.role || '').toLowerCase() === 'admin',
      id: Number(row.id),
      name: String(row.name || '').trim()
    };
  } catch (_) {
    return { linked: false, isAdmin: false, id: null, name: '' };
  }
}

