function buildTelegramWelcomeMessage({ userName, linked = false, isAdmin = false, justLinked = false } = {}) {
  const displayName = String(userName || 'Usuário').trim() || 'Usuário';
  const statusLine = justLinked
    ? '✅ *Telegram vinculado com sucesso!*'
    : linked
      ? '✅ *Sua conta já está vinculada e pronta para receber notificações.*'
      : '🔗 *Seu Telegram ainda não está vinculado ao dashboard.*';

  const lines = [
    '🤖 *FINANCEIRO BOT*',
    '',
    statusLine,
    '',
    `Olá *${displayName}*! 👋`,
    '',
    'Sou seu assistente para registrar transações, consultar saldos e acompanhar automações do sistema.',
    '',
    '⚡ *O que faço hoje:*',
    '• Registro receitas e despesas por texto natural',
    '• Consulto saldo, extrato, cartões e transações',
    '• Mostro FGTS, IA financeira e monitoramento de combustível',
    '• Disparo alertas automáticos de transações, FGTS, CDI e ciclo',
    '',
    '🚀 *Comece assim:*',
    '• `paguei 50 no mercado`',
    '• `recebi 1200 de salário`',
    '• `gastei 30 no lanche`',
    '',
    buildTelegramQuickCommandsMessage({ isAdmin })
  ];

  if (!linked) {
    lines.push(
      '',
      '🔓 *Para liberar tudo na sua conta:*',
      '• Gere o código no dashboard',
      `• Use \`/link CODIGO\` ou abra o link do bot \`@${TG_BOT_USERNAME}\``,
      '• Depois disso, o sistema pode te enviar notificações automáticas'
    );
  }

  lines.push(
    '',
    '_Desenvolvido por Usuário 1_'
  );

  return lines.join('\n');
}

async function sendTelegramWelcomeToContext(ctx, options = {}) {
  return await replyWithMarkdownSafe(ctx, buildTelegramWelcomeMessage(options), getTelegramWelcomeKeyboard());
}

async function sendTelegramWelcomeToChat(chatId, options = {}) {
  return await sendTelegramMarkdownSafe(chatId, buildTelegramWelcomeMessage(options), getTelegramWelcomeKeyboard());
}

bot.start(async (ctx) => {
    const userId = ctx.from.id.toString();
    const text = String(ctx && ctx.message && ctx.message.text ? ctx.message.text : '');
    const payloadRaw = String(ctx && ctx.startPayload ? ctx.startPayload : '').trim();
    const payload = payloadRaw || (text.startsWith('/start ') ? text.slice(7).trim() : '');

    let linkJustCompleted = false;

    console.log(`🚀 Comando /start executado por ${ctx.from.first_name || 'Usuário'} (${userId})`);

    if (payload) {
        try {
            const linked = applyTelegramLinkToken(payload, userId);
            if (linked && linked.success) {
                linkJustCompleted = true;
            } else {
                await ctx.reply('❌ Não foi possível vincular. Gere um novo código no dashboard e tente novamente.');
            }
        } catch (e) {
            await ctx.reply('❌ Erro ao vincular. Tente novamente.');
        }
    }

    const accountInfo = getTelegramLinkedAccountInfo(userId);
    const resolvedName = accountInfo.name || ctx.from.first_name || 'Usuário';

    await sendTelegramWelcomeToContext(ctx, {
        userName: resolvedName,
        linked: accountInfo.linked,
        isAdmin: accountInfo.isAdmin,
        justLinked: linkJustCompleted
    });

    try {
        if (!accountInfo.linked) {
            setTimeout(async () => {
                await replyWithMarkdownSafe(ctx,
                    `🔗 Para liberar o bot na sua conta:\n\n` +
                    `1. Entre no dashboard\n` +
                    `2. Clique no ícone do Telegram\n` +
                    `3. Gere o código e abra \`@${TG_BOT_USERNAME}\`\n` +
                    `4. Use \`/link CODIGO\` se precisar manualmente\n\n` +
                    `Seu Telegram ID: \`${userId}\``
                );
            }, 1200);
        }
    } catch (_) {}
});

bot.command('link', async (ctx) => {
  try {
    const chatId = String(ctx && ctx.from && ctx.from.id ? ctx.from.id : '');
    const text = String(ctx && ctx.message && ctx.message.text ? ctx.message.text : '');
    const parts = text.split(' ').map(s => s.trim()).filter(Boolean);
    const token = parts.length >= 2 ? String(parts[1]) : '';
    if (!token) return ctx.reply('❌ Use: /link SEU_CODIGO');
    const result = applyTelegramLinkToken(token, chatId);
    if (result && result.success) {
      const accountInfo = getTelegramLinkedAccountInfo(chatId);
      await sendTelegramWelcomeToChat(chatId, {
        userName: accountInfo.name || ctx.from.first_name || 'Usuário',
        linked: true,
        isAdmin: accountInfo.isAdmin,
        justLinked: true
      });
      return;
    }
    if (result && result.error === 'TELEGRAM_ALREADY_LINKED') return ctx.reply('❌ Este Telegram já está vinculado a outra conta.');
    return ctx.reply('❌ Código inválido ou expirado. Gere um novo no dashboard.');
  } catch (error) {
    console.error('❌ Erro no /link:', error);
    return ctx.reply('❌ Erro ao vincular. Tente novamente.');
  }
});
