bot.command('transacoes', async (ctx) => {
    try {
        const userId = ctx.from.id.toString();
        const systemUser = USER1_TG_IDS.includes(userId) ? 'user1' : 'user2';
        
        const response = await fetch(`http://localhost:${PORT}/api/transactions?limit=20&user=${systemUser}`, {
            method: 'GET',
            headers: { 'Content-Type': 'application/json' }
        });
        
        const result = await response.json();
        
        if (result.success && result.data.length > 0) {
            let message = `📋 *ÚLTIMAS TRANSAÇÕES*\n`;
            message += `══════════════════════════\n\n`;
            
            result.data.slice(0, 200).forEach((t, i) => {
                const date = moment(t.date).format('DD/MM/YYYY');
                const typeEmoji = t.type === 'income' ? '💰' : '💸';
                const typeText = t.type === 'income' ? 'RECEITA' : 'DESPESA';
                const amount = parseFloat(t.amount).toFixed(2);
                
                message += `${i + 1}. ${date} ${typeEmoji}\n`;
                message += `   ${t.description.substring(0, 30)}\n`;
                message += `   ${typeText}: R$ ${amount}\n`;
                message += `   Categoria: ${t.category}\n`;
                message += `   Método: ${t.paymentMethod || 'Não informado'}\n\n`;
            });
            
            message += `\n_Total: ${result.data.length} transações_\n`;
            message += `📊 Ver mais no dashboard web`;
            
            await ctx.replyWithMarkdown(message, {
                disable_web_page_preview: true,
                ...Markup.inlineKeyboard([
                    [
                        Markup.button.url('🌐 Dashboard Completo', 'https://user1rosafinanceiro.tail7653f3.ts.net/'),
                        Markup.button.callback('🔄 Atualizar', 'refresh_transactions')
                    ]
                ])
            });
        } else {
            await ctx.replyWithMarkdown('📭 *Nenhuma transação encontrada.*\n\nEnvie uma mensagem como "paguei 50 no mercado" para começar!');
        }
    } catch (error) {
        console.error('Erro no comando /transacoes:', error);
        await ctx.reply('❌ Erro ao carregar transações. Tente novamente.');
    }
});

