// Item 7: /orcamento mostra o gasto do mês em cada categoria com limite configurado.
// Item 9: consulta a fatura atual do cartão de crédito Neon (Pluggy /bills).
bot.command('fatura', async (ctx) => {
  if (!checkTelegramPermission(ctx)) return ctx.reply('🚫 Sem permissão.');
  try {
    const resultado = await getNeonCreditCardBill();
    if (!resultado.success) return ctx.reply(`❌ Erro ao consultar fatura: ${resultado.error}`);
    if (!resultado.atual) return ctx.reply('ℹ️ Nenhuma fatura encontrada para o cartão Neon.');
    const b = resultado.atual;
    const msg = `💳 *FATURA DO CARTÃO (NEON)*\n\n` +
      `📅 Vencimento: ${moment(b.dueDate).format('DD/MM/YYYY')}\n` +
      `💰 Total: ${formatBRL(b.totalAmount)}\n` +
      (b.minimumPaymentAmount != null ? `💵 Pagamento mínimo: ${formatBRL(b.minimumPaymentAmount)}\n` : '') +
      (b.allowsInstallments ? `📌 Permite parcelamento\n` : '');
    await ctx.replyWithMarkdown(msg);
  } catch (error) {
    console.error('❌ Erro no /fatura:', error.message);
    await ctx.reply('❌ Erro ao consultar fatura.');
  }
});

bot.command('orcamento', async (ctx) => {
  if (!checkTelegramPermission(ctx)) return ctx.reply('🚫 Sem permissão.');
  try {
    const limites = db.prepare(`SELECT category, limite FROM category_budgets ORDER BY category`).all();
    if (!limites.length) {
      return ctx.replyWithMarkdown(
        `📊 *ORÇAMENTO POR CATEGORIA*\n\nNenhum limite configurado ainda.\n\n` +
        `Use: \`/orcamento_definir NomeDaCategoria 500\``
      );
    }
    const mesAtual = moment().format('YYYY-MM');
    const linhas = limites.map(l => {
      const gasto = db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total FROM transactions
        WHERE category = ? AND type = 'expense' AND strftime('%Y-%m', date) = ?
      `).get(l.category, mesAtual);
      const total = Number(gasto.total);
      const pct = l.limite > 0 ? Math.round((total / l.limite) * 100) : 0;
      const icone = pct >= 100 ? '🚨' : (pct >= 80 ? '⚠️' : '✅');
      return `${icone} ${l.category}: ${formatBRL(total)} / ${formatBRL(l.limite)} (${pct}%)`;
    });
    await ctx.replyWithMarkdown(`📊 *ORÇAMENTO POR CATEGORIA (${mesAtual})*\n\n${linhas.join('\n')}`);
  } catch (error) {
    console.error('❌ Erro no /orcamento:', error.message);
    await ctx.reply('❌ Erro ao consultar orçamento.');
  }
});

// Item 7: /orcamento_definir NomeDaCategoria 500  → define o limite mensal daquela categoria.
bot.command('orcamento_definir', async (ctx) => {
  if (!checkTelegramPermission(ctx)) return ctx.reply('🚫 Sem permissão.');
  try {
    const texto = String(ctx.message.text || '').replace(/^\/orcamento_definir(@\w+)?\s*/, '').trim();
    const match = texto.match(/^(.+?)\s+([\d.,]+)$/);
    if (!match) {
      return ctx.reply('Uso: /orcamento_definir NomeDaCategoria 500\n(o nome precisa ser igual ao da categoria já usada no sistema)');
    }
    const categoria = match[1].trim();
    const valor = parseMoneyBR ? parseMoneyBR(match[2]) : parseFloat(match[2].replace(',', '.'));
    if (!Number.isFinite(valor) || valor <= 0) {
      return ctx.reply('❌ Valor inválido.');
    }
    const nomeReal = normalizarNomeCategoria(categoria);
    db.prepare(`
      INSERT INTO category_budgets (category, limite, updated_at) VALUES (?, ?, ?)
      ON CONFLICT(category) DO UPDATE SET limite = excluded.limite, updated_at = excluded.updated_at
    `).run(nomeReal, valor, moment().toISOString());
    await ctx.replyWithMarkdown(`✅ Limite de *${nomeReal}* definido em ${formatBRL(valor)}/mês.`);
  } catch (error) {
    console.error('❌ Erro no /orcamento_definir:', error.message);
    await ctx.reply('❌ Erro ao definir limite.');
  }
});

bot.command('gasolina', async (ctx) => {
    try {
        const userId = ctx.from.id.toString();
        
        if (!ALLOWED_TG_IDS.includes(userId)) {
            console.warn(`⚠️ Tentativa de acesso não autorizada: ${userId}`);
            return ctx.reply('❌ Você não tem permissão para usar este comando.');
        }
        
        console.log(`⛽ Comando /gasolina solicitado por: ${ctx.from.first_name} (${userId})`);
        await ctx.sendChatAction('typing');
        
        // Determinar qual usuário do sistema (user1 ou user2)
        const systemUser = USER1_TG_IDS.includes(userId) ? 'user1' : 'user2';
        const userName = systemUser === 'user1' ? 'User1' : 'User2';
        
        // Verificar alerta de gasolina
        const alert = checkGasolinaAlert(systemUser);
        
        const now = moment().tz('America/Sao_Paulo');
        const currentMonth = now.format('MMMM [de] YYYY');
        const percentage = alert.total > 0 ? Math.min((alert.total / 640) * 100, 100) : 0;
        const progressBar = gerarBarraProgresso(percentage, 20);

        let message = `⛽ *GASTOS COM GASOLINA - ${userName}*\n`;
        message += `━━━━━━━━━━━━━━━━━━━━\n\n`;
        message += `📅 *Período:* ${currentMonth}\n`;
        message += `💰 *Gasto total:* R$ ${alert.total.toFixed(2)}\n`;
        message += `🎯 *Limite de reembolso:* R$ 640,00\n\n`;
        message += `📊 *Progresso:* ${percentage.toFixed(1)}%\n`;
        message += `\`${progressBar}\`\n\n`;

        // Status baseado na lógica CORRETA
        if (alert.total === 0) {
            message += `✅ *STATUS:* NENHUM GASTO\n_Sem registros este mês._`;
        } else if (alert.total < 640) {
            const remaining = 640 - alert.total;
            message += `✅ *STATUS:* DENTRO DO LIMITE\n_Restante disponível: R$ ${remaining.toFixed(2)}_`;
        } else if (alert.total >= 640 && alert.total < 641) {
            message += `⚠️ *ALERTA! LIMITE ATINGIDO!*\n`;
            message += `_Você atingiu o limite de reembolso!_\n`;
            message += `*"Daqui em diante o custo será do seu bolso!"*`;
        } else {
            const excedente = alert.total - 640;
            message += `🚨 *ALERTA! LIMITE ULTRAPASSADO!*\n`;
            message += `💸 *Do seu bolso:* R$ ${excedente.toFixed(2)}\n`;
            message += `_O reembolso cobre apenas R$ 640,00_`;
        }

        message += `\n\n📅 *HISTÓRICO RECENTE:*\n`;
        
        // Buscar últimas transações de gasolina
        const userFilter = buildUserWhere('transactions', systemUser, 'user');
        const gasolinaTransacoes = db.prepare(`
            SELECT date, description, amount 
            FROM transactions 
            WHERE ${userFilter.clause}
            AND strftime('%Y-%m', date) = strftime('%Y-%m', 'now')
            AND (
                LOWER(description) LIKE '%gasolina%' 
                OR LOWER(description) LIKE '%combustível%'
                OR LOWER(description) LIKE '%combustivel%'
                OR LOWER(description) LIKE '%posto%'
                OR LOWER(category) = 'gasolina'
            )
            AND type = 'expense'
            ORDER BY date DESC
            LIMIT 5
        `).all(...userFilter.params);
        
        if (gasolinaTransacoes.length > 0) {
            gasolinaTransacoes.forEach(t => {
                const data = moment(t.date).format('DD/MM');
                const desc = t.description.length > 25 ? t.description.substring(0, 25) + '...' : t.description;
                message += `   • ${data}: ${desc} - R$ ${t.amount.toFixed(2)}\n`;
            });
        } else {
            message += `   • Nenhuma transação de gasolina registrada este mês\n`;
        }
        
        message += `\n_Atualizado: ${now.format('DD/MM/YYYY [às] HH:mm')}_`;

        await ctx.replyWithMarkdown(message, {
            disable_web_page_preview: true,
            reply_markup: {
                inline_keyboard: [
                    [
                        { text: '🔄 Atualizar', callback_data: 'gasolina_refresh' },
                        { text: '📊 Dashboard', url: PUBLIC_URL }
                    ]
                ]
            }
        });

    } catch (error) {
        console.error('❌ Erro no comando /gasolina:', error);
        await ctx.reply('❌ Erro ao consultar dados de gasolina.');
    }
});

