function createProgressBar(percentage) {
    const size = 100;
    const filledBlocks = Math.max(0, Math.min(size, Math.round((percentage / 100) * size)));
    const emptyBlocks = size - filledBlocks;
    return '█'.repeat(filledBlocks) + '░'.repeat(emptyBlocks);
}
