bot.action(/confirm_save\|(.+)/, async (ctx) => {
    const tempId = ctx.match[1];
    const dados = pendingTransactions.get(tempId);
    if (!dados) {
        await safeAnswerCbQuery(ctx, '⚠️ Transação expirada');
        return;
    }

    const valor = Number(dados.valor || 0);
    if (!Number.isFinite(valor) || valor <= 0) {
        await safeAnswerCbQuery(ctx, '❌ Valor inválido');
        await ctx.reply('❌ O valor está inválido. Use "💰 Valor" para corrigir.');
        return;
    }

    await safeAnswerCbQuery(ctx);

    const telegramId = String(ctx.from.id || '');

    const traceId = `tg_tx_${telegramId}_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`;
    traceTx('tg_confirm_save_start', { traceId, tempId, telegramId, valor, input: { desc: dados.desc || null, tipo: dados.tipo || null, cat: dados.cat || null, paymentMethod: dados.paymentMethod || null, data: dados.data || null, hasReceipt: Boolean(dados.receipt_image) } });



    let dbUser = null;


    try {


        if (db) {


            dbUser = db.prepare(`SELECT id, name, email, role FROM users WHERE telegram_id = ? LIMIT 1`).get(telegramId);


        }


    } catch (e) {}



    const fallbackUsername = getSystemUserFromTelegramId(telegramId);


    const usernameFromEmail = dbUser && dbUser.email ? String(dbUser.email).split('@')[0] : '';


    const username = (usernameFromEmail || fallbackUsername || 'user1').toLowerCase();



    let resolvedUserId = dbUser && typeof dbUser.id !== 'undefined' ? Number(dbUser.id) : null;

    // Number(null) === 0 é finito -- "!Number.isFinite(Number(resolvedUserId))" nunca disparava
    // pra resolvedUserId === null, então esses fallbacks eram pulados e a transação ia pro banco
    // com userId null -> user_id = 0 (órfã, não aparece na dashboard de ninguém).
    if (resolvedUserId === null || !Number.isFinite(Number(resolvedUserId))) resolvedUserId = getUserIdByUsername(username);


    if (resolvedUserId === null || !Number.isFinite(Number(resolvedUserId))) resolvedUserId = username === 'user2' ? 2 : 1;



    const userName = String((dbUser && dbUser.name) || (USERS[username]?.name) || username);

    traceTx('tg_user_resolved', { traceId, tempId, telegramId, usernameFromEmail, fallbackUsername, username, resolvedUserId, dbUser: dbUser ? { id: dbUser.id, email: dbUser.email, name: dbUser.name, role: dbUser.role } : null });




    const transaction = {
        _traceId: traceId,
        _source: 'telegram',


        description: dados.desc || 'Sem descrição',


        amount: valor,


        type: dados.tipo === 'income' ? 'income' : 'expense',


        category: dados.cat || 'Outros Gastos',


        paymentMethod: dados.paymentMethod || 'Não informado',


        date: dados.data || moment().format('YYYY-MM-DD'),


        user: username,


        userId: resolvedUserId,


        userName,


        receipt_image: dados.receipt_image || null


    };

    try {
        const result = await addTransaction(transaction);
          traceTx('tg_addTransaction_result', { traceId, tempId, telegramId, success: Boolean(result && result.success), transaction_id: result && result.transaction_id ? String(result.transaction_id) : null, error: result && result.error ? String(result.error) : null });
        pendingTransactions.delete(tempId);
        editingTransactions.delete(ctx.from.id.toString());

        if (result.success) {
            await ctx.replyWithMarkdown(
                `✅ *Transação salva!*\n` +
                `📝 ${transaction.description}\n` +
                `💰 R$ ${valor.toFixed(2)}`,
                Markup.inlineKeyboard([
                    [
                        Markup.button.callback('📑 Ver Notinha', `view|${result.transaction_id}`),
                        Markup.button.callback('📸 Adicionar Foto', `edit_photo|${result.transaction_id}`)
                    ]
                ])
            );
        } else {
            await ctx.reply(`❌ Erro: ${result.error || 'Falha ao salvar'}`);
        }
    } catch (error) {
        await ctx.reply('❌ Erro ao salvar transação.');
    }
});

