async function handleTelegramReceiptFile(ctx, fileName, userDbId) {
    const userId = ctx && ctx.from && typeof ctx.from.id !== 'undefined' ? ctx.from.id : null;
    const userIdStr = String(userId || '');
    const captionHint = String(ctx && ctx.message && typeof ctx.message.caption === 'string' ? ctx.message.caption : '').trim();
    const lastTextHint = String(telegramLastTextHint.get(userIdStr) || '').trim();
    const userHint = captionHint || lastTextHint;

    const newEntryId = Array.from(pendingTransactions.keys()).find(key =>
        pendingTransactions.get(key).status === 'WAITING_PHOTO' &&
        pendingTransactions.get(key).tgUserId === userIdStr &&
        !key.startsWith('edit_')
    );

    const editEntry = pendingTransactions.get(`edit_${userId}`);

    if (newEntryId) {
        const dados = pendingTransactions.get(newEntryId);

        dados.receipt_image = fileName;
        dados.status = 'WAITING_CONFIRM_SAVE';
        if (!dados.data) dados.data = moment().format('YYYY-MM-DD');

        let ocrLoadingMsg = null;
        try { ocrLoadingMsg = await ctx.reply('⏳ Aguardando leitura OCR...'); } catch (e) {}

        const ocr = await processarComprovanteInteligente(fileName, userDbId, userHint);

        if (ocrLoadingMsg && ocrLoadingMsg.message_id) {
            try { await ctx.telegram.deleteMessage(ctx.chat.id, ocrLoadingMsg.message_id); } catch (e) {}
        }

        if (ocr.success) {
            if (ocr.desc) dados.desc = ocr.desc;
            if (Number.isFinite(ocr.valor) && ocr.valor > 0) dados.valor = ocr.valor;
            if (ocr.tipo) dados.tipo = ocr.tipo;
            if (ocr.cat) dados.cat = ocr.cat;
            if (!dados.paymentMethod && ocr.paymentMethod) dados.paymentMethod = ocr.paymentMethod;
            if (ocr.data) dados.data = ocr.data;
            dados._learn_text = ocr.learnText || ocr.rawText || dados.desc || '';
            dados._learn_initial_cat = dados.cat;
        }

        pendingTransactions.set(newEntryId, dados);
        await ctx.reply("✅ Foto recebida. Revise e confirme:");
        await perguntarCartaoOuMostrarPreview(ctx, newEntryId, dados);
        return;
    }

    if (editEntry) {
        db.prepare('UPDATE transactions SET receipt_image = ? WHERE transaction_id = ?')
          .run(fileName, editEntry.targetId);
        pendingTransactions.delete(`edit_${userId}`);
        await ctx.reply("✅ Foto adicionada ao registro!");
        return;
    }

    let ocrLoadingMsg = null;
    try { ocrLoadingMsg = await ctx.reply('⏳ Aguardando leitura OCR...'); } catch (e) {}

    const ocr = await processarComprovanteInteligente(fileName, userDbId, userHint);

    if (ocrLoadingMsg && ocrLoadingMsg.message_id) {
        try { await ctx.telegram.deleteMessage(ctx.chat.id, ocrLoadingMsg.message_id); } catch (e) {}
    }

    const tempId = `tx_${Date.now()}`;
    const dados = ocr.success
        ? { ...ocr }
        : {
            desc: 'Transação',
            valor: 0,
            tipo: 'expense',
            cat: 'Outros Gastos',
            paymentMethod: 'Não informado',
            data: moment().format('YYYY-MM-DD')
        };

    dados.receipt_image = fileName;
    dados.status = 'WAITING_CONFIRM_SAVE';
    dados.tgUserId = userIdStr;
    if (ocr && ocr.success) {
        dados._learn_text = ocr.learnText || ocr.rawText || dados.desc || '';
        dados._learn_initial_cat = dados.cat;
    }
    pendingTransactions.set(tempId, dados);

    if (ocr.success) {
        await ctx.reply("✅ OCR concluído. Revise e confirme:");
    } else {
        await ctx.reply("⚠️ OCR não conseguiu ler tudo. Ajuste os campos e confirme:");
    }
    await perguntarCartaoOuMostrarPreview(ctx, tempId, dados);
}

bot.on('photo', async (ctx) => {
    const userId = ctx && ctx.from && ctx.from.id ? String(ctx.from.id) : null;
    const chatId = ctx && ctx.chat && ctx.chat.id ? String(ctx.chat.id) : null;

    if (!userId) return;
    if (!ALLOWED_TG_IDS.includes(userId)) {
        console.log(`🚫 Foto ignorada: usuário ${userId} não está na lista ALLOWED_TG_IDS.`);
        return;
    }
    if (chatId && (chatId.startsWith('-100') || chatId.includes('broadcast'))) {
        console.log(`🚫 Foto ignorada: mensagem de canal/broadcast (chat: ${chatId}).`);
        return;
    }

    const photo = ctx.message.photo[ctx.message.photo.length - 1];
    const userDbId = getUserIdByTelegramId(userId);

    try {
        await ctx.sendChatAction('typing').catch(() => {});
        const fileLink = await ctx.telegram.getFileLink(photo.file_id);
        console.log(`📥 Baixando foto do Telegram: ${fileLink.href.substring(0, 80)}...`);
        const fileBuffer = await safeDownloadBuffer(fileLink.href, {
            maxRetries: 3,
            timeoutMs: 60000
        });

        const fileName = await saveReceiptFile(fileBuffer, 'telegram', 'image');
        if (!fileName) {
            throw new Error('Falha ao salvar a imagem no disco');
        }

        await handleTelegramReceiptFile(ctx, fileName, userDbId);
    } catch (e) {
        const code = String(e?.code || '').toUpperCase();
        const msgCurta = code ? `${code}` : (e?.message || 'erro desconhecido');
        console.error(`❌ Erro no processamento da foto (user ${userId}):`, code || '', e?.message || e);
        try {
            if (code === 'ECONNRESET' || code === 'ETIMEDOUT' || code === 'ECONNABORTED') {
                await ctx.reply(`⚠️ Erro de conexão ao baixar a foto (${code}). Tente novamente ou envie uma foto menor.`);
            } else {
                await ctx.reply(`❌ Erro ao processar foto (${msgCurta}). Tente novamente.`);
            }
        } catch (_) {}
    }
});

bot.on('document', async (ctx) => {
    const userId = ctx && ctx.from && ctx.from.id ? String(ctx.from.id) : null;
    const chatId = ctx && ctx.chat && ctx.chat.id ? String(ctx.chat.id) : null;

    if (!userId) return;
    if (!ALLOWED_TG_IDS.includes(userId)) {
        console.log(`🚫 Documento ignorado: usuário ${userId} não está na lista ALLOWED_TG_IDS.`);
        return;
    }
    if (chatId && (chatId.startsWith('-100') || chatId.includes('broadcast'))) {
        console.log(`🚫 Documento ignorado: mensagem de canal/broadcast (chat: ${chatId}).`);
        return;
    }

    const userDbId = getUserIdByTelegramId(userId);
    const doc = ctx && ctx.message ? ctx.message.document : null;
    if (!doc || !doc.file_id) return;

    const fileNameRaw = String(doc.file_name || '').toLowerCase();
    const mime = String(doc.mime_type || '').toLowerCase();
    const isPdf = mime === 'application/pdf' || fileNameRaw.endsWith('.pdf');
    const isImage = mime.startsWith('image/') || /\.(png|jpe?g|webp)$/i.test(fileNameRaw);

    if (!isPdf && !isImage) {
        await ctx.reply('⚠️ Envie uma imagem (foto) ou PDF para eu ler via OCR.').catch(() => {});
        return;
    }

    try {
        await ctx.sendChatAction('typing').catch(() => {});
        const fileLink = await ctx.telegram.getFileLink(doc.file_id);
        console.log(`📥 Baixando documento do Telegram: ${fileLink.href.substring(0, 80)}...`);
        const fileBuffer = await safeDownloadBuffer(fileLink.href, {
            maxRetries: 3,
            timeoutMs: 60000
        });

        const fileType = isPdf ? 'pdf' : 'image';
        const savedFileName = await saveReceiptFile(fileBuffer, 'telegram', fileType);
        if (!savedFileName) {
            await ctx.reply('❌ Não consegui salvar o arquivo. Tente novamente.').catch(() => {});
            return;
        }
        await handleTelegramReceiptFile(ctx, savedFileName, userDbId);
    } catch (e) {
        const code = String(e?.code || '').toUpperCase();
        const msgCurta = code ? `${code}` : (e?.message || 'erro desconhecido');
        console.error(`❌ Erro no processamento do documento (user ${userId}):`, code || '', e?.message || e);
        try {
            if (code === 'ECONNRESET' || code === 'ETIMEDOUT' || code === 'ECONNABORTED') {
                await ctx.reply(`⚠️ Erro de conexão ao baixar o arquivo (${code}). Tente novamente.`);
            } else {
                await ctx.reply(`❌ Erro ao processar arquivo (${msgCurta}). Tente novamente.`);
            }
        } catch (_) {}
    }
});
