const pwaIconCache = new Map();

async function getPwaIconPng(size) {
  const normalizedSize = Number(size);
  if (![180, 192, 512].includes(normalizedSize)) return null;
  const cached = pwaIconCache.get(normalizedSize);
  if (cached) return cached;

  const svg = `
<svg xmlns="http://www.w3.org/2000/svg" width="${normalizedSize}" height="${normalizedSize}" viewBox="0 0 512 512">
  <defs>
    <linearGradient id="g" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="#667eea"/>
      <stop offset="1" stop-color="#764ba2"/>
    </linearGradient>
  </defs>
  <rect x="32" y="32" width="448" height="448" rx="96" fill="url(#g)"/>
  <rect x="120" y="176" width="272" height="200" rx="32" fill="#ffffff" opacity="0.95"/>
  <rect x="152" y="208" width="208" height="24" rx="12" fill="#667eea" opacity="0.9"/>
  <rect x="152" y="256" width="160" height="24" rx="12" fill="#764ba2" opacity="0.9"/>
  <circle cx="368" cy="300" r="28" fill="#27ae60"/>
  <path d="M202 340c0-22 18-40 40-40h84c22 0 40 18 40 40v6c0 22-18 40-40 40h-84c-22 0-40-18-40-40v-6z" fill="#2c3e50" opacity="0.12"/>
</svg>`;

  const png = await sharp(Buffer.from(svg)).resize(normalizedSize, normalizedSize).png().toBuffer();
  pwaIconCache.set(normalizedSize, png);
  return png;
}
