app.get('/sw.js', (req, res) => {
  res.setHeader('Content-Type', 'application/javascript; charset=utf-8');
  res.setHeader('Cache-Control', 'no-cache');
  res.send(`
const CACHE_NAME = 'financeiro-pwa-v4';
const DATA_CACHE = 'financeiro-pwa-data-v3';
const CORE = ['/', '/login', '/manifest.webmanifest', '/pwa/icon-192.png', '/pwa/icon-512.png'];
const DATA_URL_PREFIXES = [
  '/api/transactions',
  '/api/stats',
  '/api/categories',
  '/api/total-invested',
  '/api/fgts',
  '/api/card-balances',
  '/api/card-faturas'
];

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    await cache.addAll(CORE);
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k !== CACHE_NAME && k !== DATA_CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;

  const url = new URL(req.url);
  const isSameOrigin = url.origin === self.location.origin;
  const isDataEndpoint = isSameOrigin && DATA_URL_PREFIXES.some((p) => url.pathname.startsWith(p));
  const isApi = isSameOrigin && url.pathname.startsWith('/api/');

  if (isDataEndpoint) {
    event.respondWith((async () => {
      const dataCache = await caches.open(DATA_CACHE);
      try {
        const fresh = await fetch(req);
        if (fresh && fresh.ok) {
          dataCache.put(req, fresh.clone()).catch(() => {});
        }
        return fresh;
      } catch (e) {
        const cached = await dataCache.match(req);
        return cached || Response.error();
      }
    })());
    return;
  }

  if (isApi) {
    event.respondWith(fetch(req));
    return;
  }

  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const fresh = await fetch(req);
        const cache = await caches.open(CACHE_NAME);
        cache.put(req, fresh.clone()).catch(() => {});
        return fresh;
      } catch (e) {
        const cached = await caches.match('/');
        return cached || Response.error();
      }
    })());
    return;
  }

  if (isSameOrigin) {
    event.respondWith((async () => {
      const cached = await caches.match(req);
      if (cached) return cached;
      const fresh = await fetch(req);
      const cache = await caches.open(CACHE_NAME);
      cache.put(req, fresh.clone()).catch(() => {});
      return fresh;
    })());
  }
});

self.addEventListener('message', (event) => {
  const data = event.data || {};
  if (data.type !== 'SHOW_NOTIFICATION') return;
  const title = data.title || 'Notificação';
  const options = data.options || {};
  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('push', (event) => {
  event.waitUntil((async () => {
    let data = {};
    try { data = event.data ? event.data.json() : {}; } catch (e) { data = {}; }
    const title = data.title || 'Controle Financeiro';
    const options = {
      body: data.body || '',
      icon: data.icon || '/pwa/icon-192.png',
      badge: data.badge || '/pwa/icon-192.png',
      data: { url: data.url || '/' }
    };
    await self.registration.showNotification(title, options);
  })());
});

self.addEventListener('notificationclick', (event) => {
  const url = (event.notification && event.notification.data && event.notification.data.url) ? event.notification.data.url : '/';
  event.notification.close();
  event.waitUntil((async () => {
    const allClients = await clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const client of allClients) {
      if (client.url && client.url.includes(url)) {
        await client.focus();
        return;
      }
    }
    await clients.openWindow(url);
  })());
});
`);
});

const sseClientsByUser = new Map();

function broadcastTransactionToPwa(transaction) {
  const payload = JSON.stringify({ type: 'transaction', transaction });
  const usernames = transaction && transaction.user ? [transaction.user] : Array.from(sseClientsByUser.keys());

  for (const username of usernames) {
    const clients = sseClientsByUser.get(username);
    if (!clients) continue;
    for (const res of clients) {
      try {
        res.write(`event: transaction\ndata: ${payload}\n\n`);
      } catch (e) {
      }
    }
  }
}

async function sendWebPushToUser(username, payload) {
  if (!WEB_PUSH_ENABLED) return { success: false, error: 'WEB_PUSH_DISABLED' };
  if (!db) return { success: false, error: 'DB_NOT_READY' };

  const rows = db.prepare(`
    SELECT endpoint, subscription_json
    FROM push_subscriptions
    WHERE username = ?
  `).all(username);

  if (!rows || rows.length === 0) {
    console.log(`📭 Nenhuma inscrição push para ${username}`);
    return { success: true, sent: 0 };
  }

  const deleteStmt = db.prepare('DELETE FROM push_subscriptions WHERE endpoint = ?');
  let sent = 0;

  for (const row of rows) {
    try {
      let subscription;
      try {
        subscription = JSON.parse(row.subscription_json);
      } catch (e) {
        console.error('❌ Erro ao parsear subscription_json:', e.message);
        continue;
      }

      console.log(`📤 Enviando push para ${String(row.endpoint || '').substring(0, 50)}...`);
      await webPush.sendNotification(subscription, JSON.stringify(payload));
      sent += 1;
      console.log('✅ Push enviado com sucesso');
    } catch (err) {
      const statusCode = err && (err.statusCode || (err.response && err.response.statusCode));
      if (statusCode === 404 || statusCode === 410) {
        try {
          deleteStmt.run(row.endpoint);
          console.log('🗑️ Inscrição expirada removida');
        } catch (e) {}
      } else {
        console.error(`❌ Erro ao enviar push (${statusCode || 'sem status'}):`, err && err.message ? err.message : err);
      }
    }
  }

  return { success: true, sent };
}

async function notificarPwaTransacao(transaction) {
  try {
    broadcastTransactionToPwa(transaction);

    const valorFormatado = formatBRL(transaction.amount);
    const isExpense = transaction.type === 'expense';
    const title = isExpense ? 'Nova despesa registrada' : 'Nova receita registrada';
    const body = `${transaction.description || 'Sem descrição'} • ${valorFormatado}`;

    if (transaction && transaction.user) {
      await sendWebPushToUser(transaction.user, {
        title,
        body,
        url: '/',
        icon: '/pwa/icon-192.png',
        badge: '/pwa/icon-192.png',
        transactionId: transaction.transactionId || transaction.transaction_id || null
      });
    }
  } catch (e) {
  }
}

app.get('/api/notifications/stream', requireAuth, (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream; charset=utf-8');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  if (typeof res.flushHeaders === 'function') res.flushHeaders();

  const username = req.session.user.username;
  let set = sseClientsByUser.get(username);
  if (!set) {
    set = new Set();
    sseClientsByUser.set(username, set);
  }
  set.add(res);

  res.write(`event: connected\ndata: ${JSON.stringify({ ok: true, at: moment().toISOString() })}\n\n`);

  const keepAlive = setInterval(() => {
    try { res.write('event: ping\ndata: {}\n\n'); } catch (e) {}
  }, 25000);

  req.on('close', () => {
    clearInterval(keepAlive);
    const current = sseClientsByUser.get(username);
    if (current) {
      current.delete(res);
      if (current.size === 0) sseClientsByUser.delete(username);
    }
  });
});

