app.post('/api/push/subscribe', requireAuth, (req, res) => {
  try {
    const username = req.session.user.username;

    if (!WEB_PUSH_ENABLED) {
      return res.status(503).json({
        success: false,
        error: 'WEB_PUSH_DISABLED',
        message: 'Web Push não configurado no servidor'
      });
    }
    if (!db) return res.status(503).json({ success: false, error: 'DB_NOT_READY' });

    const subscription = req.body && (req.body.subscription || req.body);
    if (!subscription || !subscription.endpoint) {
      return res.status(400).json({
        success: false,
        error: 'INVALID_SUBSCRIPTION',
        message: 'Dados de inscrição inválidos'
      });
    }

    const endpoint = subscription.endpoint;
    const now = moment().toISOString();

    const upsert = db.prepare(`
      INSERT INTO push_subscriptions (username, endpoint, subscription_json, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?)
      ON CONFLICT(endpoint) DO UPDATE SET
        username=excluded.username,
        subscription_json=excluded.subscription_json,
        updated_at=excluded.updated_at
    `);
    upsert.run(username, endpoint, JSON.stringify(subscription), now, now);

    const saved = db.prepare(`SELECT id, username, endpoint, created_at, updated_at FROM push_subscriptions WHERE endpoint = ?`).get(endpoint);
    if (!saved) {
      return res.status(500).json({
        success: false,
        error: 'SUBSCRIBE_VERIFY_FAILED',
        message: 'Falha ao verificar inscrição no banco'
      });
    }

    res.json({ success: true, message: 'Inscrição salva com sucesso' });
  } catch (error) {
    console.error('❌ Erro em /api/push/subscribe:', error);
    res.status(500).json({
      success: false,
      error: 'SUBSCRIBE_FAILED',
      message: 'Erro ao salvar inscrição'
    });
  }
});

app.post('/api/push/unsubscribe', requireAuth, (req, res) => {
  try {
    if (!db) return res.status(503).json({ success: false, error: 'DB_NOT_READY' });

    const subscription = req.body && (req.body.subscription || req.body);
    const endpoint = (subscription && subscription.endpoint) || (req.body && req.body.endpoint);
    if (!endpoint) return res.status(400).json({ success: false, error: 'INVALID_SUBSCRIPTION' });

    const result = db.prepare(`
      DELETE FROM push_subscriptions
      WHERE endpoint = ? AND username = ?
    `).run(endpoint, req.session.user.username);

    console.log(`🗑️ Unsubscribe: ${result.changes > 0 ? 'removido' : 'não encontrado'}`);
    res.json({ success: true });
  } catch (error) {
    res.status(500).json({ success: false, error: 'UNSUBSCRIBE_FAILED' });
  }
});

app.get('/api/fgts', requireAuth, (req, res) => {
  const reqId = `fgts_api_${Date.now()}_${Math.random().toString(16).slice(2)}`;
  try {
    if (!db) return res.status(503).json({ success: false, error: 'DB_NOT_READY' });
    fgtsLog('info', 'api.fgts.get.start', {
      reqId,
      userId: req.session && req.session.user ? req.session.user.id : null,
      username: req.session && req.session.user ? req.session.user.username : null,
      role: req.session && req.session.user ? req.session.user.role : null
    });

    if (req.session.user && req.session.user.role === 'admin') {
      const rows = db.prepare(`SELECT username, balance FROM fgts_balances WHERE username IN ('user1', 'user2')`).all();
      const data = { user1: 0, user2: 0 };
      for (const row of rows) data[row.username] = Number(row.balance) || 0;
      fgtsLog('info', 'api.fgts.get.done', { reqId, mode: 'admin', keys: Object.keys(data) });
      return res.json({ success: true, data });
    }

    const userId = Number(req.session.user && req.session.user.id);
    if (!Number.isFinite(userId)) return res.status(401).json({ success: false, error: 'NO_USER_ID' });

    const hasUserId = tableHasColumn('fgts_balances', 'user_id');
    if (hasUserId) {
      const row = db.prepare(`SELECT balance FROM fgts_balances WHERE user_id = ? LIMIT 1`).get(userId);
      fgtsLog('info', 'api.fgts.get.done', { reqId, mode: 'user', userId, balance: Number(row?.balance) || 0 });
      return res.json({ success: true, data: { [req.session.user.username]: Number(row?.balance) || 0 } });
    }

    fgtsLog('warn', 'api.fgts.get.no_user_id_column', { reqId, userId });
    return res.json({ success: true, data: { [req.session.user.username]: 0 } });
  } catch (error) {
    fgtsLog('error', 'api.fgts.get.failed', { reqId, error: error.message, stack: String(error && error.stack ? error.stack : '').slice(0, 1200) });
    res.status(500).json({ success: false, error: 'FGTS_FETCH_FAILED' });
  }
});

