// ============== ENDPOINT DE TRADUÇÃO DE LEGENDAS ==============
// Reutiliza o cliente Groq, configurações de temperatura e cache
app.post('/api/traduzir-legenda', express.json({ limit: '10mb' }), async (req, res) => {
    try {
        const { text, idioma = 'português do Brasil' } = req.body;
        if (!text || typeof text !== 'string' || text.trim().length === 0) {
            return res.status(400).json({ success: false, error: 'Texto vazio' });
        }

        const startTime = Date.now();
        
        // ========== 1. VERIFICAR CACHE (opcional, mas recomendado) ==========
        const cacheKey = `traducao_${idioma}_${Buffer.from(text.trim()).toString('base64').slice(0, 100)}`;
        // Se você tiver uma tabela de cache genérica, pode usar; senão, pule.
        // Exemplo: se existir tabela 'ai_cache', podemos adaptar.
        // Vou manter simples, mas você pode integrar com getAICache se quiser.

        // ========== 2. MONTAR PROMPT ==========
        const prompt = `Traduza o seguinte texto para o ${idioma}, mantendo o tom, estilo e significado originais. Retorne APENAS a tradução, sem comentários adicionais.\n\nTexto original:\n${text}`;

        // ========== 3. CHAMADA AO GROQ ==========
        const completion = await createGroqChatCompletion({
            messages: [
                { role: 'system', content: `Você é um tradutor especializado em ${idioma}. Traduza com precisão e fluência.` },
                { role: 'user', content: prompt }
            ],
            model: 'openai/gpt-oss-120b',
            temperature: GROQ_TEMPERATURES.ocr || 0.0,  // usamos a mesma temperatura do OCR
            max_tokens: GROQ_MAX_TOKENS || 2000
        }, {
            location: 'sistema-mobile-3004.js:/api/traduzir-legenda'
        });

        const translation = completion.choices[0]?.message?.content || text;
        const responseTime = Date.now() - startTime;
        const tokensUsed = completion.usage?.total_tokens || 0;

        // ========== 4. LOG (opcional) ==========
        console.log(`🔤 Tradução (${idioma}) em ${responseTime}ms, ${tokensUsed} tokens`);

        // ========== 5. SALVAR CACHE (opcional) ==========
        // Se quiser, pode chamar setAICache aqui, adaptando para texto.

        res.json({
            success: true,
            translation,
            responseTime,
            tokensUsed,
            idioma
        });

    } catch (error) {
        console.error('❌ Erro na tradução:', error && error.message ? error.message : error);
        // Fallback: retorna o texto original em caso de erro
        res.status(500).json({
            success: false,
            error: error.message,
            translation: req.body.text || '' // fallback
        });
    }
});
