app.get('/api/extrato-bancario', requireAuth, async (req, res) => {
  try {
    const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);
    const filtroBanco = ['Sicredi', 'Neon', MP_MAGAZINE_NOME].includes(req.query.banco) ? req.query.banco : null;

    const { transacoes, dataInicio, dataFim, falhas } = await buscarTransacoesBancariasRaw(filtroBanco);
    const ultimas = transacoes.slice(0, limit);

    res.json({
      success: true,
      periodo: { de: dataInicio, ate: dataFim },
      total: transacoes.length,
      falhas,
      transacoes: ultimas.map(t => ({
        id: t.id,
        banco: t.banco,
        conta: t.conta || null,
        icone: t.icone || null,
        data: t.date,
        descricao: t.description || 'Sem descrição',
        valor: Math.abs(t.amount || 0),
        // Prioriza o campo type (padrão Pluggy) quando presente — usar o sinal do
        // amount como critério principal quebra para Sicredi, cujas transações vêm
        // sempre com amount positivo e a direção só no campo type.
        tipo: t.type ? (t.type === 'CREDIT' ? 'Entrada' : 'Saída') : (t.amount > 0 ? 'Entrada' : 'Saída'),
        categoria: t.category || null
      }))
    });
  } catch (error) {
    console.error('❌ Erro na rota /api/extrato-bancario:', error);
    res.status(500).json({ success: false, error: 'Erro ao buscar extrato bancário' });
  }
});

