app.post('/api/transactions/:id/attach-receipt', upload.single('file'), async (req, res) => {
    try {
        const { id } = req.params;
        if (!req.file) return res.status(400).json({ error: 'Nenhum arquivo enviado.' });

        const fileType = req.file.mimetype.includes('pdf') ? 'pdf' : 'image';
        const fileName = await saveReceiptFile(req.file.buffer, req.file.originalname, fileType);

        if (!fileName) throw new Error("Erro ao salvar arquivo no disco.");

        const statement = db.prepare(`
            UPDATE transactions 
            SET receipt_image = ?, updated_at = CURRENT_TIMESTAMP 
            WHERE transaction_id = ?
        `);
        
        const info = statement.run(fileName, id);

        if (info.changes > 0) {
            res.json({ success: true, fileName });
        } else {
            res.status(404).json({ error: 'Transação não encontrada.' });
        }
    } catch (err) {
        console.error('Erro ao anexar arquivo:', err);
        res.status(500).json({ error: err.message });
    }
});

app.post('/api/transactions/:id/attach-receipt-base64', requireAuth, async (req, res) => {
  try {
    const { id } = req.params;
    const dataUrl = String(req.body?.dataUrl || '');
    if (!dataUrl.startsWith('data:image/')) {
      return res.status(400).json({ success: false, error: 'Envie dataUrl de imagem (data:image/...)' });
    }

    const row = db.prepare('SELECT transaction_id, user, receipt_image FROM transactions WHERE transaction_id = ?').get(id);
    if (!row) return res.status(404).json({ success: false, error: 'Transação não encontrada' });
    if (req.session.user.role !== 'admin' && row.user !== req.session.user.username) {
      return res.status(403).json({ success: false, error: 'Sem permissão para anexar comprovante' });
    }

    const processed = await processCroppedImage(dataUrl, null);
    if (!processed) return res.status(400).json({ success: false, error: 'Imagem inválida' });

    const fileName = await saveReceiptFile(processed, 'pwa', 'image');
    if (!fileName) return res.status(500).json({ success: false, error: 'Erro ao salvar arquivo' });

    db.prepare(`
      UPDATE transactions
      SET receipt_image = ?, updated_at = CURRENT_TIMESTAMP
      WHERE transaction_id = ?
    `).run(fileName, id);

    if (row.receipt_image) deleteReceiptImage(row.receipt_image);

    res.json({ success: true, fileName, fileUrl: `/uploads/receipts/${fileName}` });
  } catch (err) {
    console.error('Erro ao anexar comprovante base64:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

