app.post('/api/ai-chat', requireAuth, async (req, res) => {
  try {
    const { message } = req.body;
    
    if (!message || message.trim().length === 0) {
      return res.status(400).json({ success: false, error: 'Mensagem não pode estar vazia' });
    }
    
    const userId = req.session.user.id;
    const question = message.toLowerCase().trim();
    const startTime = Date.now();
    
    let period = 'todos';
    const periodKeywords = {
      'hoje': 'hoje',
      'ontem': 'ontem',
      'esta semana': 'semana',
      'este mês': 'mes',
      'mês atual': 'mes',
      'último mês': 'last_month',
      'mês passado': 'last_month',
      'este trimestre': 'trimestre',
      'este ano': 'ano',
      'ano atual': 'ano',
      'todos os tempos': 'todos',
      'todo o período': 'todos'
    };
    
    for (const [key, value] of Object.entries(periodKeywords)) {
      if (question.includes(key)) {
        period = value;
        break;
      }
    }
    
    const queryHash = crypto.createHash('md5').update(`${String(userId)}:${question}:${period}`).digest('hex');
    const cached = getAICache(userId, queryHash);
    
    if (cached) {
      const responseTime = Date.now() - startTime;
      logChatInteraction(userId, question, 'FROM CACHE', { period, cached: true }, 0, responseTime);
      
      return res.json({
        success: true,
        response: cached.response,
        metadata: {
          period: cached.period,
          cached: true,
          responseTime: `${responseTime}ms`
        },
        source: 'Groq AI (GPT-OSS 20B) - Cache'
      });
    }
    
    const aiStats = analyzeTransactionsForAI(userId, period);
    
    if (!aiStats.success) {
      return res.status(500).json({
        success: false,
        error: 'Erro ao analisar transações',
        response: "Desculpe, houve um erro ao analisar seus dados financeiros."
      });
    }
    
    let searchResults = [];
    const searchPatterns = [
      'quanto gastei com',
      'quanto eu gastei com',
      'quanto foi gasto com',
      'transações de',
      'gastos com',
      'despesas de',
      'receitas de',
      'procuro por',
      'encontre',
      'buscar'
    ];
    
    let isSearch = false;
    let searchQuery = '';
    
    for (const pattern of searchPatterns) {
      if (question.includes(pattern)) {
        isSearch = true;
        searchQuery = question.split(pattern)[1]?.trim() || '';
        break;
      }
    }
    
    if (isSearch && searchQuery) {
      searchResults = searchTransactionsForAI(userId, searchQuery);
    }
    
    const formatCurrency = formatBRL;
    
    const formatDate = (dateString) => {
      if (!dateString) return 'Data não disponível';
      try {
        // Garantir que a data seja interpretada no fuso local sem deslocamento
        return moment(dateString.includes('T') ? dateString : dateString + 'T12:00:00').format('DD/MM/YYYY');
      } catch {
        return dateString;
      }
    };
    
    let context = `
INFORMAÇÕES FINANCEIRAS DO USUÁRIO ${req.session.user.name.toUpperCase()}:
- Período analisado: ${period === 'todos' ? 'Todo o histórico' : period.toUpperCase()}
- Total de transações: ${aiStats.total}
- Total de Receitas: ${formatCurrency(aiStats.income)}
- Total de Despesas: ${formatCurrency(aiStats.expense)}
- Saldo: ${formatCurrency(aiStats.balance)}
- Média diária: ${formatCurrency(aiStats.dailyAverage)}
`;
    
    if (Object.keys(aiStats.categories).length > 0) {
      context += '\nPRINCIPAIS CATEGORIAS DE GASTOS:\n';
      Object.entries(aiStats.categories)
        .filter(([_, data]) => data.expense > 0)
        .sort((a, b) => (b[1].expense - a[1].expense))
        .slice(0, 5)
        .forEach(([category, data]) => {
          context += `  • ${category}: ${formatCurrency(data.expense)} (${data.count} transações)\n`;
        });
    }
    
    if (searchResults.length > 0) {
      context += `\nRESULTADOS DA BUSCA POR "${searchQuery.toUpperCase()}":\n`;
      searchResults.slice(0, 5).forEach(t => {
        context += `  • ${formatDate(t.date)}: ${t.description} - ${formatCurrency(t.amount)} (${t.category})\n`;
      });
      
      if (searchResults.length > 5) {
        context += `  • ... e mais ${searchResults.length - 5} transações\n`;
      }
    }
    
    const fullPrompt = `
Você é um assistente financeiro especializado em análise de dados. O usuário fez a seguinte pergunta:
"${message}"

${context}

INSTRUÇÕES:

Pergunta: "${message}"
`;
    
    const chatCompletion = await createGroqChatCompletion({
      messages: [{ role: "user", content: fullPrompt }],
      model: "openai/gpt-oss-20b",
      temperature: GROQ_TEMPERATURES.conversational,
      max_tokens: GROQ_MAX_TOKENS,
      stream: false
    }, {
      location: 'sistema-mobile-3004.js:/api/ai-chat'
    });

    const aiResponse = chatCompletion.choices[0]?.message?.content || 'Desculpe, não consegui processar sua pergunta.';
    const tokensUsed = chatCompletion.usage?.total_tokens || 0;
    const responseTime = Date.now() - startTime;
    
    setAICache(userId, queryHash, aiResponse, period);
    logChatInteraction(userId, question, aiResponse, { period, searchQuery }, tokensUsed, responseTime);
    
    res.json({
      success: true,
      response: aiResponse,
      metadata: {
        period,
        totalTransactions: aiStats.total,
        searchPerformed: isSearch,
        searchResultsCount: searchResults.length,
        tokensUsed,
        responseTime: `${responseTime}ms`,
        cached: false
      },
      source: 'Groq AI (GPT-OSS 20B)'
    });
    
  } catch (error) {
    console.error('❌ Erro no chat com IA:', error && error.message ? error.message : error);
    res.status(500).json({ 
      success: false, 
      error: 'Erro ao processar mensagem',
      response: "Desculpe, estou com problemas técnicos no momento. Por favor, tente novamente mais tarde."
    });
  }
});

app.get('/api/ai-analysis', requireAuth, async (req, res) => {
  try {
    const user = req.session.user;
    const cacheUserKey = (user && (user.id || user.username)) ? String(user.id || user.username) : 'unknown';
    const cacheKey = `${cacheUserKey}_${moment().format('YYYY-MM-DD_HH')}`;
    const queryHash = crypto.createHash('md5').update(cacheKey).digest('hex');
    const cached = getAICache(user, queryHash);
    if (cached) {
      try {
        const analysis = JSON.parse(cached.response);
        return res.json({
          success: true,
          analysis,
          user: req.session.user.name,
          generatedAt: moment().toISOString(),
          cached: true,
          source: 'Groq AI (GPT-OSS 20B)'
        });
      } catch (e) {
        console.error('❌ Erro ao parsear cache:', e);
      }
    }
    
    const aiStats = analyzeTransactionsForAI(user, 'mes');
    const faturas = calculateCardFaturas(user);
    
    if (!aiStats.success) {
      return res.status(500).json({ 
        success: false, 
        error: 'Erro ao analisar dados',
        analysis: {
          insights: ["Erro ao processar análise dos dados financeiros."],
          recommendations: ["Tente novamente mais tarde."],
          summary: "Erro na análise"
        }
      });
    }
    
    const prompt = `
Você é um especialista em finanças pessoais. Analise os seguintes dados financeiros e forneça:

DADOS DO USUÁRIO ${req.session.user.name.toUpperCase()}:
- Período analisado: Mês atual
- Total de transações: ${aiStats.total}
- Total de Receitas: R$ ${aiStats.income.toFixed(2)}
- Total de Despesas: R$ ${aiStats.expense.toFixed(2)}
- Saldo: R$ ${aiStats.balance.toFixed(2)}
- Média diária: R$ ${aiStats.dailyAverage.toFixed(2)}

FATURAS DOS CARTÕES DE CRÉDITO (MÊS ATUAL):
- Banrisul: R$ ${faturas.banrisul.toFixed(2)}
- Magazine: R$ ${faturas.magazine.toFixed(2)}
- Bradesco: R$ ${(faturas.bradesco || 0).toFixed(2)}

PRINCIPAIS CATEGORIAS DE GASTOS:
${Object.entries(aiStats.categories)
  .filter(([_, data]) => data.expense > 0)
  .sort((a, b) => b[1].expense - a[1].expense)
  .slice(0, 5)
  .map(([cat, data]) => `  • ${cat}: R$ ${data.expense.toFixed(2)} (${data.count} transações)`)
  .join('\n')}

MAIOR TRANSAÇÃO:
${aiStats.largestTransaction ? 
  `  • ${aiStats.largestTransaction.description}: R$ ${aiStats.largestTransaction.amount.toFixed(2)} (${aiStats.largestTransaction.type === 'income' ? 'Receita' : 'Despesa'})` 
  : 'Nenhuma transação significativa'}

Forneça a resposta APENAS em formato JSON válido com as seguintes chaves:
{
  "insights": ["insight 1", "insight 2", "insight 3"],
  "recommendations": ["recomendação 1", "recomendação 2", "recomendação 3"],
  "summary": "resumo conciso aqui"
}

INCLUA NAS INSIGHTS:
1. Como primeira linha: "O valor total da fatura do cartão Banrisul a ser paga este mês é de: R$ ${faturas.banrisul.toFixed(2)}"
2. Como segunda linha: "O valor total da fatura do cartão Magazine a ser paga este mês é de: R$ ${faturas.magazine.toFixed(2)}"
3. Como terceira linha: "O valor total da fatura do cartão Bradesco a ser paga este mês é de: R$ ${(faturas.bradesco || 0).toFixed(2)}"

Seja prático, objetivo e focado em melhorias tangíveis. Apenas retorne o JSON, sem texto adicional.`;

    // Groq fora (13/10/2026): cai no resumo montado com os números (o mesmo de quando a IA responde algo inválido)
    let chatCompletion = null;
    let iaIndisponivel = false;
    try {
      chatCompletion = await createGroqChatCompletion({
        messages: [{ role: "user", content: prompt }],
        model: "openai/gpt-oss-20b",
        temperature: GROQ_TEMPERATURES.insights,
        max_tokens: GROQ_MAX_TOKENS,
      }, {
        location: 'sistema-mobile-3004.js:/api/ai-analysis'
      });
    } catch (e) {
      iaIndisponivel = true;
      console.error('⚠️ IA indisponível na análise — usando o resumo local:', e && e.message ? e.message : e);
    }

    const aiResponse = chatCompletion?.choices?.[0]?.message?.content || '';
    
    let analysis;
    console.log("Resposta da IA recebida:", aiResponse.substring(0, 200) + (aiResponse.length > 200 ? "..." : ""));
    
    try {
      analysis = JSON.parse(aiResponse);
      
      // Garantir que as faturas estejam nas insights
      if (analysis.insights && analysis.insights.length > 0) {
        // Remover qualquer insight existente sobre faturas
        analysis.insights = analysis.insights.filter(insight => 
          !insight.includes("Banrisul") && !insight.includes("Magazine") && !insight.includes("Bradesco")
        );
        
        // Adicionar as novas insights sobre faturas
        analysis.insights = [
          `O valor total da fatura do cartão Banrisul a ser paga este mês é de: R$ ${faturas.banrisul.toFixed(2)}`,
          `O valor total da fatura do cartão Magazine a ser paga este mês é de: R$ ${faturas.magazine.toFixed(2)}`,
          `O valor total da fatura do cartão Bradesco a ser paga este mês é de: R$ ${(faturas.bradesco || 0).toFixed(2)}`,
          ...analysis.insights.slice(0, 1) // Mantém apenas a primeira insight adicional da IA
        ];
      }
    } catch (e) {
      console.error('❌ Erro ao parsear resposta da IA:', e);
      analysis = {
        insights: [
          `O valor total da fatura do cartão Banrisul a ser paga este mês é de: R$ ${faturas.banrisul.toFixed(2)}`,
          `O valor total da fatura do cartão Magazine a ser paga este mês é de: R$ ${faturas.magazine.toFixed(2)}`,
          `O valor total da fatura do cartão Bradesco a ser paga este mês é de: R$ ${(faturas.bradesco || 0).toFixed(2)}`,
          iaIndisponivel
            ? "⚠️ A análise por IA está indisponível agora — mostrando só o resumo dos números."
            : "Análise realizada com sucesso. Continue monitorando seus gastos."
        ],
        recommendations: ["Registre todas as suas transações para uma análise mais precisa.", "Estabeleça metas financeiras mensais.", "Revise suas despesas regularmente."],
        summary: `Situação financeira: Receitas R$ ${aiStats.income.toFixed(2)}, Despesas R$ ${aiStats.expense.toFixed(2)}, Saldo R$ ${aiStats.balance.toFixed(2)}. Faturas: Banrisul R$ ${faturas.banrisul.toFixed(2)}, Magazine R$ ${faturas.magazine.toFixed(2)}, Bradesco R$ ${(faturas.bradesco || 0).toFixed(2)}.`
      };
    }
    
    if (!iaIndisponivel) setAICache(user, queryHash, JSON.stringify(analysis), 'mes');   // resumo local não vale o mês
    
    res.json({
      success: true,
      analysis,
      user: req.session.user.name,
      generatedAt: moment().toISOString(),
      cached: false,
      source: iaIndisponivel ? 'Resumo local (IA indisponível)' : 'Groq AI (GPT-OSS 20B)'
    });
    
  } catch (error) {
    console.error('❌ Erro na análise com IA:', error);
    res.status(500).json({ 
      success: false, 
      error: 'Erro ao analisar dados com IA',
      analysis: {
        insights: ["Erro ao processar análise."],
        recommendations: ["Tente novamente mais tarde."],
        summary: "Erro na análise"
      }
    });
  }
});

