app.post('/api/investimento/simular', requireAuth, async (req, res) => {
  try {
    const { valor, prazo } = req.body;
    const valorInvestido = parseFloat(valor);
    const meses = parseInt(prazo);

    if (isNaN(valorInvestido) || valorInvestido <= 0 || isNaN(meses) || meses <= 0) {
      return res.status(400).json({ success: false, error: 'Valor e prazo inválidos' });
    }

    // ========== 1. BUSCAR TAXA CDI ATUALIZADA (API BCB) ==========
    let taxaCDIAnual = 0.14; // Fallback: 14% ao ano
    try {
      const hoje = moment().format('DD/MM/YYYY');
      const noventaDiasAtras = moment().subtract(90, 'days').format('DD/MM/YYYY');

      const url = `https://api.bcb.gov.br/dados/serie/bcdata.sgs.11/dados?formato=json&dataInicial=${noventaDiasAtras}&dataFinal=${hoje}`;
      const response = await axios.get(url, { timeout: 10000 });
      const dados = response.data;

      if (Array.isArray(dados) && dados.length > 0) {
        const ultimo = dados[dados.length - 1];
        const valorCDI = parseFloat(ultimo.valor);
        if (!isNaN(valorCDI) && valorCDI > 0) {
          if (valorCDI >= 5 && valorCDI <= 20) {
            taxaCDIAnual = valorCDI / 100; // Converte percentual para decimal
            console.log(`✅ Taxa CDI obtida: ${valorCDI}% a.a.`);
          } else {
            console.warn(`⚠️ Taxa CDI fora do intervalo esperado (${valorCDI}%), usando fallback de 14%`);
          }
        }
      }
    } catch (error) {
      console.warn('⚠️ Erro ao buscar taxa CDI (usando fallback de 14%):', error.message);
    }

    // ========== 2. CÁLCULOS FINANCEIROS ==========
    // Original calculations (for backward compatibility)
    const taxaMensal = Math.pow(1 + taxaCDIAnual, 1 / 12) - 1;
    const montante = valorInvestido * Math.pow(1 + taxaMensal, meses);
    const rendimento = montante - valorInvestido;
    const rendimentoPercentual = (rendimento / valorInvestido) * 100;

    // New detailed calculations
    const diasUteisPorAno = 252;
    const diasUteis = Math.round(meses * (diasUteisPorAno / 12)); // média
    const taxaDiaria = Math.pow(1 + taxaCDIAnual, 1 / diasUteisPorAno) - 1;
    const rendimentoBruto = valorInvestido * (Math.pow(1 + taxaDiaria, diasUteis) - 1);

    // Alíquota IR (tabela regressiva)
    const diasCorridos = meses * 30; // aproximação
    let aliquotaIR;
    if (diasCorridos <= 180) aliquotaIR = 0.225;
    else if (diasCorridos <= 360) aliquotaIR = 0.20;
    else if (diasCorridos <= 720) aliquotaIR = 0.175;
    else aliquotaIR = 0.15;

    const rendimentoLiquido = rendimentoBruto * (1 - aliquotaIR);
    const valorBrutoFinal = valorInvestido + rendimentoBruto;
    const valorLiquidoFinal = valorInvestido + rendimentoLiquido;

    // Calcular rendimento da poupança (70% do CDI, sem IR)
    const rendimentoPoupanca = valorInvestido * (0.7 * taxaCDIAnual) * (meses / 12);

    // ========== 3. ANÁLISE COM IA (GROQ) ==========
    const prompt = `
Você é um especialista em finanças e investimentos.
Analise a seguinte simulação de investimento em CDI com base nos dados fornecidos:

- Valor investido: R$ ${valorInvestido.toFixed(2)}
- Prazo: ${meses} meses
- Taxa CDI anual: ${(taxaCDIAnual * 100).toFixed(2)}%
- Alíquota de IR (tabela regressiva): ${(aliquotaIR * 100).toFixed(2)}%
- Rendimento bruto (antes do IR): R$ ${rendimentoBruto.toFixed(2)}
- Rendimento líquido (após IR): R$ ${rendimentoLiquido.toFixed(2)}
- Montante líquido final: R$ ${valorLiquidoFinal.toFixed(2)}

Para comparação, a Poupança renderia (isenta de IR):
- Rendimento da Poupança (70% do CDI): R$ ${rendimentoPoupanca.toFixed(2)}
- Montante na Poupança: R$ ${(valorInvestido + rendimentoPoupanca).toFixed(2)}

Com base nesses números, responda:
1. Se o investimento vale a pena no curto prazo.
2. Compare com a Poupança e indique qual é melhor.
3. Dê uma recomendação prática.

Retorne APENAS um JSON com as chaves:
- "analise": string (análise textual)
- "recomendacao": string (recomendação)
- "comparacao": string (comparação com poupança)
`;

    let iaResponse;
    try {
      // Groq fora (13/10/2026) cai no mesmo catch de resposta inválida: o cálculo é local e continua valendo
      const chatCompletion = await createGroqChatCompletion({
        messages: [
          { role: "system", content: "Você é um assistente financeiro especializado. Responda apenas em JSON." },
          { role: "user", content: prompt }
        ],
        model: 'openai/gpt-oss-120b', // Modelo gratuito e oficial da Groq
        temperature: GROQ_TEMPERATURES.insights,
        max_tokens: GROQ_MAX_TOKENS
      }, {
        location: 'sistema-mobile-3004.js:/api/simular-investimento-cdi'
      });
      iaResponse = JSON.parse(chatCompletion.choices[0].message.content);
    } catch (e) {
      console.error('⚠️ IA indisponível ou resposta inválida na simulação — usando a análise local:', e && e.message ? e.message : e);
      // Fallback caso a IA retorne algo inválido
      iaResponse = {
        analise: `O investimento renderia R$ ${rendimentoLiquido.toFixed(2)} líquido em ${meses} meses. A poupança renderia R$ ${rendimentoPoupanca.toFixed(2)} no mesmo período.`,
        recomendacao: 'Consulte um especialista para uma decisão mais precisa.',
        comparacao: `O CDI líquido supera a poupança em R$ ${(rendimentoLiquido - rendimentoPoupanca).toFixed(2)}.`
      };
    }

    // ========== 4. RESPOSTA FINAL ==========
    res.json({
      success: true,
      simulacao: {
        valorInvestido,
        meses,
        taxaCDI: taxaCDIAnual,
        taxaMensal,
        montante,
        rendimento,
        rendimentoPercentual
      },
      analise: iaResponse
    });

  } catch (error) {
    console.error('❌ Erro na simulação:', error && error.message ? error.message : error);
    res.status(500).json({ success: false, error: 'Erro ao processar simulação' });
  }
});

