app.get('/api/transactions/:id', requireAuth, (req, res) => {
  try {
    const transactionId = String(req.params.id || '').trim();
    if (!transactionId) {
      return res.status(400).json({ success: false, error: 'ID da transação é obrigatório' });
    }

    const actor = req.session && req.session.user ? req.session.user : null;
    const actorUserId = actor && Number.isFinite(Number(actor.id)) ? Number(actor.id) : null;
    const actorUsername = normalizeLedgerUsername((actor && actor.username) || '');
    const isAdmin = !!(actor && actor.role === 'admin');
    const hasUserId = tableHasColumn('transactions', 'user_id');

    const row = hasUserId
      ? db.prepare(`
          SELECT
            transaction_id AS transactionId,
            description,
            amount,
            type,
            category,
            payment_method AS paymentMethod,
            date,
            user,
            user_name AS userName,
            user_id AS userId
          FROM transactions
          WHERE transaction_id = ?
          LIMIT 1
        `).get(transactionId)
      : db.prepare(`
          SELECT
            transaction_id AS transactionId,
            description,
            amount,
            type,
            category,
            payment_method AS paymentMethod,
            date,
            user,
            user_name AS userName
          FROM transactions
          WHERE transaction_id = ?
          LIMIT 1
        `).get(transactionId);

    if (!row) {
      return res.status(404).json({ success: false, error: 'Transação não encontrada' });
    }

    if (!isAdmin) {
      if (hasUserId && actorUserId !== null && Number.isFinite(Number(row.userId))) {
        const actorLedgerUserId = mapUserIdToLedgerUserId(actorUserId);
        if (!Number.isFinite(Number(actorLedgerUserId)) || Number(row.userId) !== Number(actorLedgerUserId)) {
          return res.status(403).json({ success: false, error: 'Sem permissão para visualizar esta transação' });
        }
      } else {
        const rowUsername = normalizeLedgerUsername(row.user);
        if (!actorUsername || rowUsername !== actorUsername) {
          return res.status(403).json({ success: false, error: 'Sem permissão para visualizar esta transação' });
        }
      }
    }

    return res.json({ success: true, transaction: row });
  } catch (error) {
    console.error('❌ Erro ao buscar transação:', error);
    return res.status(500).json({ success: false, error: 'Erro ao buscar transação' });
  }
});

app.post('/api/transactions', requireAuth, async (req, res) => {
  try {
    const { description, amount, type, category, date, paymentMethod, receipt_image, cropData, calendarSync, calendarTime, calendarReminderMinutes } = req.body;
    
    if (!description || !amount || !type || !category) {
      return res.status(400).json({ 
        success: false, 
        error: 'Preencha todos os campos obrigatórios' 
      });
    }
    
    const transaction = {
      description,
      amount: parseFloat(amount),
      type,
      category,
      paymentMethod: paymentMethod || 'Não informado',
      date: date || moment().format('YYYY-MM-DD'),
      user: req.session.user.username,
      userId: req.session.user.id,
      userName: req.session.user.name,
      receipt_image: receipt_image || null,
      cropData: cropData || null
    };
    
    const result = await addTransaction(transaction);
    
    if (!result.success) {
      return res.status(500).json(result);
    }

    let calendar = null;
    const wantsCalendar = calendarSync === true || calendarSync === 'true' || calendarSync === 1 || calendarSync === '1';
    if (wantsCalendar) {
      try {
        const userId = req.session.user && req.session.user.id ? req.session.user.id : null;
        const txId = result && result.transaction_id ? String(result.transaction_id) : null;
        if (!db || !userId || !txId) {
          calendar = { success: false, error: 'CALENDAR_INTERNAL' };
        } else {
          const already = db.prepare(`
            SELECT event_id AS eventId
            FROM google_calendar_events
            WHERE user_id = ? AND transaction_id = ?
            LIMIT 1
          `).get(Number(userId), txId);
          if (already && already.eventId) {
            calendar = { success: true, eventId: String(already.eventId), alreadySynced: true };
          } else {
            const created = await createGoogleCalendarEventForTransaction(Number(userId), transaction, {
              time: calendarTime,
              reminderMinutes: calendarReminderMinutes
            });
            if (created && created.success && created.eventId) {
              try {
                db.prepare(`
                  INSERT OR IGNORE INTO google_calendar_events (user_id, transaction_id, event_id, calendar_id)
                  VALUES (?, ?, ?, 'primary')
                `).run(Number(userId), txId, String(created.eventId));
              } catch (e) {}
            }
            calendar = created;
          }
        }
      } catch (e) {
        calendar = { success: false, error: 'CALENDAR_INTERNAL' };
      }
    }
    
    console.log(`✅ Transação adicionada: ${description} - R$ ${amount}`);
    res.json({ 
      success: true, 
      message: 'Transação adicionada com sucesso',
      transaction: result,
      calendar
    });
  } catch (error) {
    console.error('❌ Erro ao adicionar transação:', error);
    res.status(500).json({ 
      success: false, 
      error: 'Erro ao adicionar transação' 
    });
  }
});

app.put('/api/transactions/:id', requireAuth, (req, res) => {
  try {
    const transactionId = String(req.params.id || '').trim();
    const description = String(req.body && req.body.description ? req.body.description : '').trim();
    const amountValue = Number(req.body && req.body.amount);
    const type = String(req.body && req.body.type ? req.body.type : '').trim();
    const category = String(req.body && req.body.category ? req.body.category : '').trim();
    const paymentMethod = String(req.body && req.body.paymentMethod ? req.body.paymentMethod : '').trim() || 'Não informado';
    const date = String(req.body && req.body.date ? req.body.date : '').trim();

    if (!transactionId) {
      return res.status(400).json({ success: false, error: 'ID da transação é obrigatório' });
    }

    if (!description || !Number.isFinite(amountValue) || amountValue <= 0 || !type || !category || !date) {
      return res.status(400).json({ success: false, error: 'Preencha todos os campos obrigatórios com valores válidos' });
    }

    if (!['income', 'expense'].includes(type)) {
      return res.status(400).json({ success: false, error: 'Tipo de transação inválido' });
    }

    if (!moment(date, 'YYYY-MM-DD', true).isValid()) {
      return res.status(400).json({ success: false, error: 'Data inválida' });
    }

    const actor = req.session && req.session.user ? req.session.user : null;
    const actorUserId = actor && Number.isFinite(Number(actor.id)) ? Number(actor.id) : null;
    const actorUsername = normalizeLedgerUsername((actor && actor.username) || '');
    const isAdmin = !!(actor && actor.role === 'admin');
    const hasUserId = tableHasColumn('transactions', 'user_id');

    const existing = hasUserId
      ? db.prepare(`
          SELECT transaction_id AS transactionId, user, user_id AS userId
          FROM transactions
          WHERE transaction_id = ?
          LIMIT 1
        `).get(transactionId)
      : db.prepare(`
          SELECT transaction_id AS transactionId, user
          FROM transactions
          WHERE transaction_id = ?
          LIMIT 1
        `).get(transactionId);

    if (!existing) {
      return res.status(404).json({ success: false, error: 'Transação não encontrada' });
    }

    if (!isAdmin) {
      if (hasUserId && actorUserId !== null && Number.isFinite(Number(existing.userId))) {
        const actorLedgerUserId = mapUserIdToLedgerUserId(actorUserId);
        if (!Number.isFinite(Number(actorLedgerUserId)) || Number(existing.userId) !== Number(actorLedgerUserId)) {
          return res.status(403).json({ success: false, error: 'Sem permissão para editar esta transação' });
        }
      } else {
        const rowUsername = normalizeLedgerUsername(existing.user);
        if (!actorUsername || rowUsername !== actorUsername) {
          return res.status(403).json({ success: false, error: 'Sem permissão para editar esta transação' });
        }
      }
    }

    const info = db.prepare(`
      UPDATE transactions
      SET description = ?, amount = ?, type = ?, category = ?, payment_method = ?, date = ?, updated_at = CURRENT_TIMESTAMP
      WHERE transaction_id = ?
    `).run(
      description,
      amountValue,
      type,
      category,
      paymentMethod,
      date,
      transactionId
    );

    if (!info || info.changes === 0) {
      return res.status(404).json({ success: false, error: 'Nenhuma alteração realizada' });
    }

    const updated = hasUserId
      ? db.prepare(`
          SELECT
            transaction_id AS transactionId,
            description,
            amount,
            type,
            category,
            payment_method AS paymentMethod,
            date,
            user,
            user_name AS userName,
            user_id AS userId
          FROM transactions
          WHERE transaction_id = ?
          LIMIT 1
        `).get(transactionId)
      : db.prepare(`
          SELECT
            transaction_id AS transactionId,
            description,
            amount,
            type,
            category,
            payment_method AS paymentMethod,
            date,
            user,
            user_name AS userName
          FROM transactions
          WHERE transaction_id = ?
          LIMIT 1
        `).get(transactionId);

    console.log(`✏️ Transação atualizada: ${transactionId}`);
    return res.json({
      success: true,
      message: 'Transação atualizada com sucesso',
      transaction: updated
    });
  } catch (error) {
    console.error('❌ Erro ao atualizar transação:', error);
    return res.status(500).json({ success: false, error: 'Erro ao atualizar transação' });
  }
});

app.post('/api/transactions/:id/calendar-sync', requireAuth, async (req, res) => {
  try {
    if (!db) return res.status(500).json({ success: false, error: 'DB_NOT_READY' });
    const transactionId = String(req.params.id || '').trim();
    if (!transactionId) return res.status(400).json({ success: false, error: 'MISSING_TRANSACTION_ID' });

    const actor = req.session && req.session.user ? req.session.user : null;
    const actorUserId = actor && Number.isFinite(Number(actor.id)) ? Number(actor.id) : null;
    const isAdmin = !!(actor && actor.role === 'admin');
    const hasUserId = tableHasColumn('transactions', 'user_id');

    const row = hasUserId
      ? db.prepare(`
          SELECT
            transaction_id AS transactionId,
            description,
            amount,
            type,
            category,
            payment_method AS paymentMethod,
            date,
            user,
            user_name AS userName,
            user_id AS userId
          FROM transactions
          WHERE transaction_id = ?
          LIMIT 1
        `).get(transactionId)
      : db.prepare(`
          SELECT
            transaction_id AS transactionId,
            description,
            amount,
            type,
            category,
            payment_method AS paymentMethod,
            date,
            user,
            user_name AS userName
          FROM transactions
          WHERE transaction_id = ?
          LIMIT 1
        `).get(transactionId);

    if (!row) return res.status(404).json({ success: false, error: 'TRANSACTION_NOT_FOUND' });

    if (!isAdmin) {
      if (hasUserId && actorUserId !== null && Number.isFinite(Number(row.userId))) {
        const actorLedgerUserId = mapUserIdToLedgerUserId(actorUserId);
        if (!Number.isFinite(Number(actorLedgerUserId)) || Number(row.userId) !== Number(actorLedgerUserId)) {
          return res.status(403).json({ success: false, error: 'Sem permissão para sincronizar esta transação' });
        }
      } else {
        const actorUsername = String((actor && actor.username) || '').toLowerCase();
        const actorLedgerUsername = normalizeLedgerUsername(actorUsername);
        const rowLedgerUsername = normalizeLedgerUsername(row.user);
        if (!actorLedgerUsername || rowLedgerUsername !== actorLedgerUsername) {
          return res.status(403).json({ success: false, error: 'Sem permissão para sincronizar esta transação' });
        }
      }
    }

    const txDate = String(row.date || '').trim();
    const isFuture = txDate ? moment(txDate, 'YYYY-MM-DD', true).isAfter(moment(), 'day') : false;
    if (!isFuture) {
      return res.json({ success: true, calendar: { success: false, error: 'NOT_FUTURE_TRANSACTION' } });
    }

    if (!actorUserId) {
      return res.json({ success: true, calendar: { success: false, error: 'CALENDAR_INTERNAL' } });
    }

    const { calendarTime, calendarReminderMinutes } = (req.body || {});
    const already = db.prepare(`
      SELECT event_id AS eventId
      FROM google_calendar_events
      WHERE user_id = ? AND transaction_id = ?
      LIMIT 1
    `).get(Number(actorUserId), transactionId);
    if (already && already.eventId) {
      return res.json({ success: true, calendar: { success: true, eventId: String(already.eventId), alreadySynced: true } });
    }

    const tx = {
      description: row.description,
      amount: Number(row.amount),
      type: row.type,
      category: row.category,
      paymentMethod: row.paymentMethod || 'Não informado',
      date: txDate
    };

    const created = await createGoogleCalendarEventForTransaction(Number(actorUserId), tx, {
      time: calendarTime,
      reminderMinutes: calendarReminderMinutes
    });

    if (created && created.success && created.eventId) {
      try {
        db.prepare(`
          INSERT OR IGNORE INTO google_calendar_events (user_id, transaction_id, event_id, calendar_id)
          VALUES (?, ?, ?, 'primary')
        `).run(Number(actorUserId), transactionId, String(created.eventId));
      } catch (e) {}
    }

    return res.json({ success: true, calendar: created });
  } catch (e) {
    return res.status(500).json({ success: false, error: 'Erro ao sincronizar com Google Agenda' });
  }
});

