// WebAuthn (impressão digital) — registro e verificação
const webauthnChallenges = new Map();

app.get('/api/biometric/fingerprint/register-options', requireAuth, async (req, res) => {
  try {
    const { generateRegistrationOptions } = require('@simplewebauthn/server');
    const userId = req.session.user && req.session.user.id;
    const userName = req.session.user && req.session.user.name || 'user';
    const options = await generateRegistrationOptions({
      rpName: 'Sistema Financeiro',
      rpID: req.hostname,
      userID: new Uint8Array(Buffer.from(String(userId))),
      userName,
      attestationType: 'none',
      authenticatorSelection: { authenticatorAttachment: 'platform', userVerification: 'required' }
    });
    webauthnChallenges.set(String(userId), options.challenge);
    res.json({ success: true, options });
  } catch (e) {
    console.error('❌ Erro WebAuthn register-options:', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

app.post('/api/biometric/fingerprint/register', requireAuth, async (req, res) => {
  try {
    const { verifyRegistrationResponse } = require('@simplewebauthn/server');
    const userId = String(req.session.user && req.session.user.id);
    const challenge = webauthnChallenges.get(userId);
    if (!challenge) return res.status(400).json({ success: false, error: 'Challenge expirado' });
    webauthnChallenges.delete(userId);
    const verification = await verifyRegistrationResponse({
      response: req.body,
      expectedChallenge: challenge,
      expectedOrigin: `${req.protocol}://${req.get('host')}`,
      expectedRPID: req.hostname
    });
    if (!verification.verified || !verification.registrationInfo) {
      return res.status(400).json({ success: false, error: 'Verificação falhou' });
    }
    const { credential } = verification.registrationInfo;
    const data = JSON.stringify({
      credentialID: Buffer.from(credential.id).toString('base64url'),
      credentialPublicKey: Buffer.from(credential.publicKey).toString('base64'),
      counter: credential.counter
    });
    db.prepare(`INSERT INTO user_biometrics (user_id, type, data) VALUES (?, 'fingerprint', ?)
      ON CONFLICT(user_id, type) DO UPDATE SET data = excluded.data, created_at = DATETIME('now','localtime')`)
      .run(Number(userId), data);
    console.log(`🔐 Digital cadastrada para user ${userId}`);
    res.json({ success: true, message: 'Impressão digital cadastrada' });
  } catch (e) {
    console.error('❌ Erro WebAuthn register:', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

app.get('/api/biometric/fingerprint/auth-options', requireAuth, async (req, res) => {
  try {
    const { generateAuthenticationOptions } = require('@simplewebauthn/server');
    const userId = req.session.user && req.session.user.id;
    const row = db.prepare(`SELECT data FROM user_biometrics WHERE user_id = ? AND type = 'fingerprint'`).get(userId);
    if (!row) return res.json({ success: false, error: 'Nenhuma digital cadastrada' });
    const cred = JSON.parse(row.data);
    const options = await generateAuthenticationOptions({
      rpID: req.hostname,
      allowCredentials: [{ id: cred.credentialID, type: 'public-key' }],
      userVerification: 'required'
    });
    webauthnChallenges.set(String(userId) + '_auth', options.challenge);
    res.json({ success: true, options });
  } catch (e) {
    console.error('❌ Erro WebAuthn auth-options:', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

app.post('/api/biometric/fingerprint/verify', requireAuth, async (req, res) => {
  try {
    const { verifyAuthenticationResponse } = require('@simplewebauthn/server');
    const userId = String(req.session.user && req.session.user.id);
    const challenge = webauthnChallenges.get(userId + '_auth');
    if (!challenge) return res.status(400).json({ success: false, error: 'Challenge expirado' });
    webauthnChallenges.delete(userId + '_auth');
    const row = db.prepare(`SELECT data FROM user_biometrics WHERE user_id = ? AND type = 'fingerprint'`).get(Number(userId));
    if (!row) return res.status(400).json({ success: false, error: 'Nenhuma digital cadastrada' });
    const cred = JSON.parse(row.data);
    const verification = await verifyAuthenticationResponse({
      response: req.body,
      expectedChallenge: challenge,
      expectedOrigin: `${req.protocol}://${req.get('host')}`,
      expectedRPID: req.hostname,
      credential: {
        id: cred.credentialID,
        publicKey: Buffer.from(cred.credentialPublicKey, 'base64'),
        counter: cred.counter
      }
    });
    if (verification.verified) {
      db.prepare(`UPDATE user_biometrics SET data = ? WHERE user_id = ? AND type = 'fingerprint'`)
        .run(JSON.stringify({ ...cred, counter: verification.authenticationInfo.newCounter }), Number(userId));
      db.prepare(`INSERT INTO biometric_verifications (user_id, type, success) VALUES (?, 'fingerprint', 1)`).run(Number(userId));
      console.log(`✅ Verificação digital OK para user ${userId}`);
    }
    res.json({ success: true, verified: verification.verified });
  } catch (e) {
    console.error('❌ Erro WebAuthn verify:', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

app.post('/api/register', registerRateLimit, (req, res) => {
  try {
    if (!db) return res.status(503).json({ success: false, error: 'DB_NOT_READY' });

    const name = String(req.body && req.body.name ? req.body.name : '').trim();
    const emailRaw = String(req.body && req.body.email ? req.body.email : '').trim().toLowerCase();
    const password = String(req.body && req.body.password ? req.body.password : '');

    if (!name || !emailRaw || !password) {
      return res.status(400).json({ success: false, error: 'INVALID_INPUT' });
    }
    if (!emailRaw.includes('@') || password.length < 6) {
      return res.status(400).json({ success: false, error: 'INVALID_INPUT' });
    }

    const existing = db.prepare(`SELECT id FROM users WHERE lower(email) = ?`).get(emailRaw);
    if (existing) return res.status(409).json({ success: false, error: 'EMAIL_IN_USE' });

    const now = moment().toISOString();
    const pwdHash = hashPassword(password);
    const info = db.prepare(`
      INSERT INTO users (email, password_hash, name, role, plan_type, plan_expires_at, telegram_id, created_at, updated_at)
      VALUES (?, ?, ?, 'user', 'free', NULL, NULL, ?, ?)
    `).run(emailRaw, pwdHash, name, now, now);

    try { copyGlobalCategoriesToUser(info.lastInsertRowid, String(emailRaw).split('@')[0]); } catch (e) {}
    res.json({ success: true, id: info.lastInsertRowid });
  } catch (error) {
    console.error('❌ Erro no register:', error);
    res.status(500).json({ success: false, error: 'REGISTER_FAILED' });
  }
});

