app.post('/api/admin/users', requireAuth, requireAdmin, (req, res) => {
  try {
    if (!db) return res.status(503).json({ success: false, error: 'DB_NOT_READY' });

    const name = String(req.body && req.body.name ? req.body.name : '').trim();
    const email = String(req.body && req.body.email ? req.body.email : '').trim().toLowerCase();
    const password = String(req.body && req.body.password ? req.body.password : '');
    const role = String(req.body && req.body.role ? req.body.role : 'user').trim().toLowerCase();
    const planType = String(req.body && req.body.plan_type ? req.body.plan_type : 'free').trim().toLowerCase();
    const planExpiresAt = req.body && typeof req.body.plan_expires_at !== 'undefined' ? req.body.plan_expires_at : null;
    const telegramId = req.body && typeof req.body.telegram_id !== 'undefined' ? String(req.body.telegram_id || '') : null;

    if (!name || !email || !password || !email.includes('@')) {
      return res.status(400).json({ success: false, error: 'INVALID_INPUT' });
    }
    if (!['admin', 'user', 'blocked'].includes(role)) {
      return res.status(400).json({ success: false, error: 'INVALID_ROLE' });
    }
    if (!['free', 'basic', 'pro'].includes(planType)) {
      return res.status(400).json({ success: false, error: 'INVALID_PLAN' });
    }

    const exists = db.prepare(`SELECT id FROM users WHERE lower(email) = ?`).get(email);
    if (exists) return res.status(409).json({ success: false, error: 'EMAIL_IN_USE' });

    const now = moment().toISOString();
    const pwdHash = hashPassword(password);
    const info = db.prepare(`
      INSERT INTO users (email, password_hash, name, role, plan_type, plan_expires_at, telegram_id, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(email, pwdHash, name, role, planType, planExpiresAt || null, telegramId || null, now, now);

    res.json({ success: true, id: info.lastInsertRowid });
  } catch (error) {
    console.error('❌ Erro em POST /api/admin/users:', error);
    res.status(500).json({ success: false, error: 'ADMIN_USERS_CREATE_FAILED' });
  }
});

app.put('/api/admin/users/:id', requireAuth, requireAdmin, (req, res) => {
  try {
    if (!db) return res.status(503).json({ success: false, error: 'DB_NOT_READY' });

    const id = Number(req.params.id);
    if (!Number.isFinite(id)) return res.status(400).json({ success: false, error: 'INVALID_ID' });

    const patch = {
      name: typeof req.body?.name === 'string' ? req.body.name.trim() : undefined,
      email: typeof req.body?.email === 'string' ? req.body.email.trim().toLowerCase() : undefined,
      role: typeof req.body?.role === 'string' ? req.body.role.trim().toLowerCase() : undefined,
      plan_type: typeof req.body?.plan_type === 'string' ? req.body.plan_type.trim().toLowerCase() : undefined,
      plan_expires_at: typeof req.body?.plan_expires_at !== 'undefined' ? req.body.plan_expires_at : undefined,
      telegram_id: typeof req.body?.telegram_id !== 'undefined' ? req.body.telegram_id : undefined
    };

    const sets = [];
    const params = [];

    if (typeof patch.name === 'string' && patch.name) { sets.push('name = ?'); params.push(patch.name); }
    if (typeof patch.email === 'string' && patch.email && patch.email.includes('@')) { sets.push('email = ?'); params.push(patch.email); }
    if (typeof patch.role === 'string' && ['admin', 'user', 'blocked'].includes(patch.role)) { sets.push('role = ?'); params.push(patch.role); }
    if (typeof patch.plan_type === 'string' && ['free', 'basic', 'pro'].includes(patch.plan_type)) { sets.push('plan_type = ?'); params.push(patch.plan_type); }
    if (typeof patch.plan_expires_at !== 'undefined') { sets.push('plan_expires_at = ?'); params.push(patch.plan_expires_at || null); }
    if (typeof patch.telegram_id !== 'undefined') { sets.push('telegram_id = ?'); params.push(patch.telegram_id ? String(patch.telegram_id) : null); }

    if (sets.length === 0) return res.status(400).json({ success: false, error: 'NO_CHANGES' });

    sets.push('updated_at = ?');
    params.push(moment().toISOString());
    params.push(id);

    db.prepare(`UPDATE users SET ${sets.join(', ')} WHERE id = ?`).run(...params);
    res.json({ success: true });
  } catch (error) {
    console.error('❌ Erro em PUT /api/admin/users/:id:', error);
    res.status(500).json({ success: false, error: 'ADMIN_USERS_UPDATE_FAILED' });
  }
});

