app.delete('/api/admin/users/:id', requireAuth, requireAdmin, (req, res) => {
  try {
    if (!db) return res.status(503).json({ success: false, error: 'DB_NOT_READY' });
    const id = Number(req.params.id);
    if (!Number.isFinite(id)) return res.status(400).json({ success: false, error: 'INVALID_ID' });

    const tx = db.transaction(() => {
      if (tableHasColumn('transactions', 'user_id')) db.prepare(`DELETE FROM transactions WHERE user_id = ?`).run(id);
      if (tableHasColumn('ai_cache', 'user_id')) db.prepare(`DELETE FROM ai_cache WHERE user_id = ?`).run(id);
      if (tableHasColumn('chat_logs', 'user_id')) db.prepare(`DELETE FROM chat_logs WHERE user_id = ?`).run(id);
      if (tableHasColumn('categories', 'user_id')) db.prepare(`DELETE FROM categories WHERE user_id = ?`).run(id);
      if (tableHasColumn('push_subscriptions', 'user_id')) db.prepare(`DELETE FROM push_subscriptions WHERE user_id = ?`).run(id);
      if (tableHasColumn('fgts_balances', 'user_id')) db.prepare(`DELETE FROM fgts_balances WHERE user_id = ?`).run(id);
      db.prepare(`DELETE FROM users WHERE id = ?`).run(id);
    });

    tx();
    res.json({ success: true });
  } catch (error) {
    console.error('❌ Erro em DELETE /api/admin/users/:id:', error);
    res.status(500).json({ success: false, error: 'ADMIN_USERS_DELETE_FAILED' });
  }
});

app.get('/api/debug/database', requireAuth, (req, res) => {
  try {
    const tables = db.prepare(`
      SELECT name FROM sqlite_master 
      WHERE type='table' 
      ORDER BY name
    `).all();
    
    const tableInfo = tables.map(table => {
      try {
        const count = db.prepare(`SELECT COUNT(*) as count FROM ${table.name}`).get();
        return {
          table: table.name,
          count: count.count
        };
      } catch (e) {
        return {
          table: table.name,
          count: 0,
          error: e.message
        };
      }
    });
    
    const dbSize = fs.existsSync(DB_FILE) ? fs.statSync(DB_FILE).size : 0;
    
    let receiptsCount = 0;
    let receiptsSize = 0;
    try {
      if (fs.existsSync(RECEIPTS_DIR)) {
        const files = fs.readdirSync(RECEIPTS_DIR);
        receiptsCount = files.length;
        files.forEach(file => {
          try {
            const stat = fs.statSync(path.join(RECEIPTS_DIR, file));
            receiptsSize += stat.size;
          } catch (e) {}
        });
      }
    } catch (e) {
      console.error('Erro ao ler pasta de recibos:', e);
    }
    
    res.json({
      success: true,
      database: {
        file: DB_FILE,
        size: `${(dbSize / 1024 / 1024).toFixed(2)} MB`,
        tables: tableInfo,
        betterSqlite3Version: Database.version
      },
      receipts: {
        folder: RECEIPTS_DIR,
        count: receiptsCount,
        size: `${(receiptsSize / 1024).toFixed(2)} KB`,
        exists: fs.existsSync(RECEIPTS_DIR)
      },
      performance: {
        transactions: getTransactions({ limit: 5 }).length,
        categories: getCategories(),
        cacheHits: db.prepare('SELECT COUNT(*) as count FROM ai_cache WHERE expires_at > datetime("now")').get().count
      }
    });
    
  } catch (error) {
    console.error('❌ Erro no diagnóstico:', error);
    res.status(500).json({ 
      success: false, 
      error: error.message 
    });
  }
});

app.post('/api/whatsapp/send-link', requireAuth, async (req, res) => {
  try {
    const userId = req.session.user.id;
    const email = req.session.user.email;
    if (!email) {
      return res.status(400).json({ success: false, error: 'E-mail do usuário não disponível' });
    }

    const now = moment().format('YYYY-MM-DD HH:mm:ss');
    // Remove tokens expirados antigos do mesmo usuário (opcional)
    db.prepare(`DELETE FROM pending_wa_links WHERE user_id = ? OR expires_at <= ?`).run(userId, now);

    const token = crypto.randomBytes(32).toString('hex');
    const expiresAt = moment().add(15, 'minutes').format('YYYY-MM-DD HH:mm:ss');
    db.prepare(`INSERT INTO pending_wa_links (user_id, token, expires_at) VALUES (?, ?, ?)`).run(userId, token, expiresAt);

    const baseUrl = (process.env.PUBLIC_URL || `http://localhost:${PORT}`).replace(/\/+$/, '');
    const confirmLink = `${baseUrl}/confirmar-whatsapp?token=${token}`;

    const html = `
      <h2>Confirmação de WhatsApp</h2>
      <p>Olá, ${req.session.user.name || req.session.user.username}!</p>
      <p>Clique no link abaixo para vincular seu número de WhatsApp ao sistema financeiro:</p>
      <p><a href="${confirmLink}" target="_blank">${confirmLink}</a></p>
      <p>Este link expira em 15 minutos.</p>
      <p>Se você não solicitou, ignore este e-mail.</p>
    `;

    const enviado = await enviarEmail(email, '🔐 Vincular WhatsApp ao Financeiro', html);
    if (!enviado.success) {
      return res.status(500).json({ success: false, error: 'Falha ao enviar e-mail' });
    }

    res.json({ success: true, message: 'Link enviado para seu e-mail. Verifique sua caixa de entrada.', email });
  } catch (error) {
    console.error('❌ Erro em /api/whatsapp/send-link:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

