app.post('/api/whatsapp/confirm', async (req, res) => {
  try {
    const { token, whatsapp } = req.body;
    if (!token || !whatsapp) {
      return res.status(400).json({ success: false, error: 'Token e número são obrigatórios.' });
    }

    // Normaliza o número: remove espaços, traços, parênteses e mantém apenas dígitos
    const numeroLimpo = whatsapp.replace(/\D/g, '');
    if (numeroLimpo.length < 10 || numeroLimpo.length > 15) {
      return res.status(400).json({ success: false, error: 'Número inválido. Use formato internacional (ex: 5511999999999).' });
    }

    // Verifica token no banco
    const now = moment().format('YYYY-MM-DD HH:mm:ss');
    const pending = db.prepare(`
      SELECT user_id, expires_at FROM pending_wa_links
      WHERE token = ? AND expires_at > ?
    `).get(token, now);

    if (!pending) {
      return res.status(400).json({ success: false, error: 'Token inválido ou expirado.' });
    }

    // Atualiza o número do usuário
    const update = db.prepare(`UPDATE users SET whatsapp = ? WHERE id = ?`).run(numeroLimpo, pending.user_id);
    if (update.changes === 0) {
      return res.status(500).json({ success: false, error: 'Usuário não encontrado.' });
    }

    // Remove o token usado (e quaisquer outros expirados)
    db.prepare(`DELETE FROM pending_wa_links WHERE user_id = ? OR expires_at <= ?`).run(pending.user_id, now);

    // Notifica o usuário pelo próprio WhatsApp (se disponível) – opcional
    try {
      if (typeof enviarWhatsApp === 'function') {
        const msgBoasVindas = `✅ *CONEXÃO CONCLUÍDA COM SUCESSO!*\n\n` +
                             `Olá! Seu WhatsApp foi vinculado ao *Sistema Financeiro*.\n\n` +
                             `A partir de agora, você receberá aqui notificações em tempo real de suas receitas e despesas. 🚀\n\n` +
                             `_Gestão inteligente na palma da sua mão._`;
        await enviarWhatsApp(numeroLimpo, msgBoasVindas);
      }
    } catch (e) {}

    res.json({ success: true, message: 'Número vinculado com sucesso.' });
  } catch (error) {
    console.error('❌ Erro em /api/whatsapp/confirm:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

app.get('/auth/google', (req, res, next) => {
  if (!passport || !googleAuthEnabled) {
    return res.status(503).send('Google OAuth não está configurado neste servidor.');
  }
  next();
}, passport ? passport.authenticate('google', { scope: ['profile', 'email'] }) : (req, res) => res.status(503).send('Google OAuth indisponível'));

app.get('/auth/google/calendar', (req, res, next) => {
  if (!passport || !googleAuthEnabled) {
    return res.status(503).send('Google OAuth não está configurado neste servidor.');
  }
  next();
}, passport ? passport.authenticate('google', {
  scope: ['profile', 'email', GOOGLE_CALENDAR_SCOPE],
  accessType: 'offline',
  prompt: 'consent',
  includeGrantedScopes: true
}) : (req, res) => res.status(503).send('Google OAuth indisponível'));

app.get('/auth/google/callback', (req, res, next) => {
  if (!passport || !googleAuthEnabled) {
    return res.redirect('/login');
  }
  // Admin já logado conectando o Google Agenda: mantém a conta dele (não troca de usuário pelo e-mail do Google).
  // Precisa ser capturado aqui, antes do passport, pois o passport regenera a sessão ao autenticar.
  const su = req.session && req.session.user;
  req.adminLinkUserId = su && String(su.role || '') === 'admin' && Number.isFinite(Number(su.id)) ? Number(su.id) : null;
  next();
}, passport ? passport.authenticate('google', { failureRedirect: '/login' }) : (req, res) => res.redirect('/login'), (req, res) => {
  try {
    if (!req.user) return res.redirect('/login');
    const derivedUsername = req.user.email && String(req.user.email).includes('@') ? String(req.user.email).split('@')[0] : String(req.user.email || '');
    const legacy = USERS && USERS[derivedUsername] ? USERS[derivedUsername] : null;

    const sessionUser = {
      id: req.user.id,
      username: derivedUsername,
      email: req.user.email,
      name: req.user.name,
      role: req.user.role,
      plan: req.user.plan_type,
      expires_at: null,
      theme: legacy && legacy.theme ? legacy.theme : 'dark',
      loggedIn: true,
      loginTime: moment().toISOString()
    };

    req.session.regenerate((regenErr) => {
      if (regenErr) {
        req.session.user = sessionUser;
        return req.session.save(() => res.redirect('/'));
      }

      req.login(req.user, () => {
        req.session.user = sessionUser;
        req.session.save(() => res.redirect('/'));
      });
    });
  } catch (e) {
    res.redirect('/login');
  }
});

app.get('/api/google-calendar/status', requireAuth, (req, res) => {
  try {
    if (!db) return res.json({ success: true, connected: false });
    const uid = Number(req.session && req.session.user ? req.session.user.id : NaN);
    if (!Number.isFinite(uid)) return res.json({ success: true, connected: false });
    if (!tableHasColumn('users', 'google_refresh_token')) return res.json({ success: true, connected: false });
    const row = db.prepare(`SELECT google_refresh_token AS refreshToken FROM users WHERE id = ? LIMIT 1`).get(uid);
    const connected = !!(row && row.refreshToken);
    res.json({ success: true, connected });
  } catch (e) {
    res.json({ success: true, connected: false });
  }
});

