        async function saveReceiptEdit() {
            if (!pendingReceiptEdit.transactionId || !pendingReceiptEdit.dataUrl) return;
            try {
                showToast('Enviando comprovante...', 'success');
                const response = await fetch('/api/transactions/' + encodeURIComponent(pendingReceiptEdit.transactionId) + '/attach-receipt-base64', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ dataUrl: pendingReceiptEdit.dataUrl })
                });
                const result = await response.json().catch(() => ({}));
                if (result && result.success) {
                    showToast('✅ Comprovante atualizado com sucesso!');
                    closeReceiptEditModal();
                    setTimeout(() => { window.location.reload(); }, 600);
                } else {
                    showToast(result?.error || 'Erro ao enviar comprovante', 'error');
                }
            } catch (error) {
                showToast('❌ Falha ao enviar arquivo.', 'error');
            }
        }
        
        function confirmCrop() {
            let activeCropper = cropper || editCropper;
            if (!activeCropper) return;

            const rawCanvas = activeCropper.getCroppedCanvas({
                fillColor: '#fff',
                imageSmoothingEnabled: true,
                imageSmoothingQuality: 'high'
            });

            const maxSide = 1200;
            const scale = Math.min(1, maxSide / Math.max(rawCanvas.width || 1, rawCanvas.height || 1));
            const outW = Math.max(1, Math.round((rawCanvas.width || 1) * scale));
            const outH = Math.max(1, Math.round((rawCanvas.height || 1) * scale));
            const outCanvas = document.createElement('canvas');
            outCanvas.width = outW;
            outCanvas.height = outH;
            const outCtx = outCanvas.getContext('2d');
            outCtx.fillStyle = '#fff';
            outCtx.fillRect(0, 0, outW, outH);
            outCtx.drawImage(rawCanvas, 0, 0, outW, outH);
            const croppedImage = outCanvas.toDataURL('image/jpeg', 0.82);

            if (cropper) {
                document.getElementById('imageData').value = croppedImage;
                const cropData = cropper.getData(true);
                document.getElementById('cropData').value = JSON.stringify(cropData);
                document.getElementById('previewContainer').style.display = 'block';
                document.getElementById('fileName').textContent = 'Imagem recortada.jpg';
                document.getElementById('preview').src = croppedImage;
                document.getElementById('preview').style.display = 'block';
                document.getElementById('pdfPreview').style.display = 'none';
            }

            if (editCropper) {
                pendingReceiptEdit.dataUrl = croppedImage;
                cancelCrop();
                openReceiptEditModal();
                showToast('Imagem recortada com sucesso!');
                return;
            }

            cancelCrop();
            showToast('Imagem recortada com sucesso!');
        }
        
        function cancelCrop() {
            document.getElementById('cropModal').style.display = 'none';
            document.body.style.overflow = 'auto';
            if (cropper) {
                cropper.destroy();
                cropper = null;
            }
            if (editCropper) {
                editCropper.destroy();
                editCropper = null;
            }
        }
        
