        function adminGetUser(id) {
            return (window.adminUsers || []).find(u => Number(u.id) === Number(id));
        }

        async function adminCreateUser() {
            const name = prompt('Nome do cliente:');
            if (name === null) return;
            const email = prompt('Email do cliente:');
            if (email === null) return;
            const password = prompt('Senha inicial (mínimo 6 caracteres):');
            if (password === null) return;
            const role = prompt('Role (admin/user/blocked):', 'user');
            if (role === null) return;
            const plan_type = prompt('Plano (free/basic/pro):', 'free');
            if (plan_type === null) return;
            const plan_expires_at = prompt('Expiração do plano (YYYY-MM-DD) ou vazio:', '');
            if (plan_expires_at === null) return;
            const telegram_id = prompt('Telegram ID (opcional):', '');
            if (telegram_id === null) return;

            try {
                const response = await fetch('/api/admin/users', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name, email, password, role, plan_type, plan_expires_at: plan_expires_at || null, telegram_id: telegram_id || null })
                });
                const result = await response.json();
                if (!result.success) throw new Error(result.error || 'Falha ao criar');
                showToast('Cliente criado');
                await loadAdminUsers();
            } catch (error) {
                console.error('Erro ao criar cliente:', error);
                showToast('Erro ao criar cliente', 'error');
            }
        }

        async function adminEditUser(id) {
            const u = adminGetUser(id);
            if (!u) return;
            const name = prompt('Nome:', u.name || '');
            if (name === null) return;
            const email = prompt('Email:', u.email || '');
            if (email === null) return;
            const role = prompt('Role (admin/user/blocked):', u.role || 'user');
            if (role === null) return;
            const plan_type = prompt('Plano (free/basic/pro):', u.plan_type || 'free');
            if (plan_type === null) return;
            const plan_expires_at = prompt('Expiração do plano (YYYY-MM-DD) ou vazio:', u.plan_expires_at ? moment(u.plan_expires_at).format('YYYY-MM-DD') : '');
            if (plan_expires_at === null) return;
            const telegram_id = prompt('Telegram ID (opcional):', u.telegram_id || '');
            if (telegram_id === null) return;

            try {
                const response = await fetch('/api/admin/users/' + id, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name, email, role, plan_type, plan_expires_at: plan_expires_at || null, telegram_id: telegram_id || null })
                });
                const result = await response.json();
                if (!result.success) throw new Error(result.error || 'Falha ao salvar');
                showToast('Cliente atualizado');
                await loadAdminUsers();
            } catch (error) {
                console.error('Erro ao editar cliente:', error);
                showToast('Erro ao salvar cliente', 'error');
            }
        }

        async function adminResetPassword(id) {
            const u = adminGetUser(id);
            const password = prompt('Nova senha (mínimo 6 caracteres) para ' + (u ? u.email : id) + ':');
            if (password === null) return;
            try {
                const response = await fetch('/api/admin/users/' + id + '/reset-password', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ password })
                });
                const result = await response.json();
                if (!result.success) throw new Error(result.error || 'Falha ao resetar');
                showToast('Senha resetada');
            } catch (error) {
                console.error('Erro ao resetar senha:', error);
                showToast('Erro ao resetar senha', 'error');
            }
        }

        async function adminDeleteUser(id) {
            const u = adminGetUser(id);
            if (!confirm('Excluir usuário ' + (u ? u.email : id) + '? Essa ação remove dados vinculados.')) return;
            try {
                const response = await fetch('/api/admin/users/' + id, { method: 'DELETE' });
                const result = await response.json();
                if (!result.success) throw new Error(result.error || 'Falha ao excluir');
                showToast('Usuário excluído');
                await loadAdminUsers();
            } catch (error) {
                console.error('Erro ao excluir usuário:', error);
                showToast('Erro ao excluir usuário', 'error');
            }
        }
        
