        function escapeHtmlClient(text) {
            return String(text || '')
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#39;');
        }

        async function loadCreditCards() {
            try {
                const container = document.getElementById('creditCardsList');
                const countEl = document.getElementById('creditCardsCount');
                if (!container || !countEl) return;

                container.innerHTML = '<div style="padding: 20px; text-align: center; opacity: 0.7;">Carregando...</div>';
                const res = await fetch('/api/credit-cards');
                const data = await res.json().catch(() => ({}));
                if (!data || !data.success) throw new Error((data && data.error) ? data.error : 'Falha ao carregar cartões');

                const cards = Array.isArray(data.cards) ? data.cards : [];
                countEl.innerText = String(cards.length);

                if (cards.length === 0) {
                    container.innerHTML = '<div style="padding: 20px; text-align: center; opacity: 0.7;">Nenhum cartão cadastrado</div>';
                    return;
                }

                container.innerHTML = cards.map((card) => {
                    const name = escapeHtmlClient(card && card.name ? card.name : '');
                    const id = card && typeof card.id !== 'undefined' ? Number(card.id) : NaN;
                    if (!Number.isFinite(id)) return '';
                    return (
                        '<div class="category-item">' +
                        '<span class="category-name">' + name + '</span>' +
                        '<button class="delete-category-btn" onclick="deleteCreditCard(' + id + ')"><i class="fas fa-trash"></i></button>' +
                        '</div>'
                    );
                }).join('');
            } catch (err) {
                console.error('Erro ao carregar cartões:', err);
            }
        }

        async function addCreditCard() {
            const input = document.getElementById('newCardName');
            if (!input) return;
            const name = String(input.value || '').trim();
            if (!name) {
                showToast('Digite o nome do cartão', 'error');
                return;
            }
            try {
                const res = await fetch('/api/credit-cards', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ name })
                });
                const data = await res.json().catch(() => ({}));
                if (data && data.success) {
                    input.value = '';
                    await loadCreditCards();
                    showToast('Cartão adicionado');
                    return;
                }
                showToast((data && data.error) ? data.error : 'Erro ao adicionar cartão', 'error');
            } catch (err) {
                showToast('Erro ao adicionar cartão', 'error');
            }
        }

