        function ensureSelectOption(selectElement, value) {
            if (!selectElement || !value) return;
            const exists = Array.from(selectElement.options).some(option => option.value === value);
            if (!exists) {
                const option = document.createElement('option');
                option.value = value;
                option.textContent = value;
                selectElement.appendChild(option);
            }
        }

        async function openEditModal(transactionId) {
            try {
                if (!transactionId) {
                    showToast('Transação inválida', 'error');
                    return;
                }

                if (!categories || (!categories.income.length && !categories.expense.length && !categories.paymentMethods.length)) {
                    await loadCategoriesData();
                }

                const response = await fetch('/api/transactions/' + encodeURIComponent(transactionId), {
                    credentials: 'same-origin'
                });
                const result = await response.json().catch(() => null);

                if (!response.ok || !result || !result.success || !result.transaction) {
                    throw new Error(result && result.error ? result.error : 'Erro ao carregar transação');
                }

                const t = result.transaction;
                resetForm();
                setTransactionModalMode(true);

                document.getElementById('editTransactionId').value = t.transactionId || '';
                document.getElementById('description').value = t.description || '';
                document.getElementById('amount').value = t.amount != null ? t.amount : '';
                document.getElementById('type').value = t.type || '';
                updateCategories();
                ensureSelectOption(document.getElementById('category'), t.category);
                document.getElementById('category').value = t.category || '';
                ensureSelectOption(document.getElementById('paymentMethod'), t.paymentMethod);
                document.getElementById('paymentMethod').value = t.paymentMethod || '';
                document.getElementById('date').value = t.date ? String(t.date).split('T')[0] : '';
                updateCalendarUi();

                document.getElementById('addTransactionModal').style.display = 'flex';
                document.body.style.overflow = 'hidden';
            } catch (error) {
                console.error('Erro ao carregar transação para edição:', error);
                showToast(error && error.message ? error.message : 'Erro ao carregar transação', 'error');
            }
        }
        
        function closeModal() {
            document.getElementById('addTransactionModal').style.display = 'none';
            document.body.style.overflow = 'auto';
            resetForm();
        }
        
        function resetForm() {
            document.getElementById('transactionForm').reset();
            document.getElementById('editTransactionId').value = '';
            document.getElementById('date').value = moment().format('YYYY-MM-DD');
            document.getElementById('preview').src = '';
            document.getElementById('previewContainer').style.display = 'none';
            document.getElementById('imageData').value = '';
            document.getElementById('cropData').value = '';
            const calSyncEl = document.getElementById('calendarSync');
            if (calSyncEl) calSyncEl.checked = false;
            const optionsEl = document.getElementById('calendarOptions');
            if (optionsEl) optionsEl.style.display = 'none';
            const timeEl = document.getElementById('calendarTime');
            if (timeEl) timeEl.value = '09:00';
            const minutesEl = document.getElementById('calendarReminderMinutes');
            if (minutesEl) minutesEl.value = '60';
            setTransactionModalMode(false);
            try { updateCalendarUi(); } catch (e) {}
        }
        
