// Estado REAL de cada integração, preenchido pelos próprios passos de inicialização e exibido no resumo
// (antes o banner imprimia "✅" fixo mesmo com o Telegram fora do ar e o webhook da Pluggy falhando).
const startupStatus = {
  telegram: 'iniciando...',
  webhookSicredi: 'pendente',
  webhookNeon: 'pendente',
  primeiraVerificacao: 'pendente',
  saldoSicredi: 'pendente',
  saldoNeon: 'pendente',
  caixinhasNeon: 'pendente'
};

// Erro de API (axios) em uma linha: "HTTP 404 ACCOUNT_NOT_FOUND — Account not found".
function descreverErroApi(error) {
  const d = error && error.response && error.response.data;
  if (d && typeof d === 'object') {
    const partes = [error.response.status ? `HTTP ${error.response.status}` : null, d.codeDescription || d.code, d.message]
      .filter(Boolean);
    return partes.join(' — ');
  }
  return (error && error.message) || String(error);
}

// Sobe o bot do Telegram. Se falhar (ex.: DNS/rede ainda fora do ar logo após o boot da máquina) tenta de novo
// com espera crescente (15s → 5min) em vez de ficar sem comandos até alguém reiniciar o serviço.
// Token inválido (401/404) não adianta repetir.
async function iniciarBotTelegram(tentativa = 1) {
  try {
    await bot.launch({ dropPendingUpdates: true });
    startupStatus.telegram = 'online';
    console.log(`✅ Bot do Telegram iniciado com sucesso!${tentativa > 1 ? ` (na tentativa ${tentativa})` : ''}`);
  } catch (err) {
    const code = err && err.response && err.response.error_code;
    const motivo = err && err.code ? `${err.code} - ${err.message}` : ((err && err.message) || String(err));
    if (code === 401 || code === 404) {
      startupStatus.telegram = `OFFLINE — token recusado (HTTP ${code})`;
      console.error(`❌ Bot Telegram: token recusado pelo Telegram (HTTP ${code}). Verifique TG_TOKEN. Sem novas tentativas.`);
      return;
    }
    const espera = Math.min(15000 * 2 ** Math.min(tentativa - 1, 5), 5 * 60 * 1000);
    startupStatus.telegram = `OFFLINE (tentativa ${tentativa}: ${motivo}) — nova tentativa em ${Math.round(espera / 1000)}s`;
    console.error(`❌ Erro ao iniciar bot Telegram (tentativa ${tentativa}): ${motivo}. Nova tentativa em ${Math.round(espera / 1000)}s.`);
    setTimeout(() => iniciarBotTelegram(tentativa + 1), espera);
  }
}

