async function askFgtsAmount(ctx, action) {
  const actionName = action === 'set' ? 'definir o saldo' : action === 'add' ? 'aumentar o saldo' : 'diminuir o saldo';
  const fromId = String(ctx.from.id);
  const prev = telegramPendingInputs.get(fromId);
  if (prev && prev.timeout) clearTimeout(prev.timeout);
  awaitingUserInput.add(fromId);
  const timeout = setTimeout(async () => {
    const current = telegramPendingInputs.get(fromId);
    if (!current || current.timeout !== timeout) return;
    telegramPendingInputs.delete(fromId);
    awaitingUserInput.delete(fromId);
    try { await bot.telegram.sendMessage(fromId, '⏱️ Tempo esgotado. Toque no botão novamente para tentar.'); } catch (_) {}
  }, 60000);
  telegramPendingInputs.set(fromId, { kind: 'fgts_amount', action, timeout });

  await safeAnswerCbQuery(ctx);
  fgtsLog('info', 'tg.fgts.amount.prompt', { telegramId: String(ctx.from.id), action });
  await ctx.reply(`📝 Digite o valor para ${actionName} (ex: 150,75):`);
}

bot.action('fgts_edit_saldo', async (ctx) => askFgtsAmount(ctx, 'set'));
