// ============== SHUTDOWN GRACEFUL ==============
function setupGracefulShutdown(server, bot) {
    let shuttingDown = false;
    
    const shutdown = async (signal) => {
        if (shuttingDown) {
            console.log('⚠️ Shutdown já em andamento...');
            return;
        }
        shuttingDown = true;
        
        console.log(`\n🛑 Recebido ${signal}, encerrando...`);
        
        // 1. Fechar servidor HTTP
        if (server && server.listening) {
            await new Promise((resolve) => {
                server.close(() => {
                    console.log('✅ Servidor HTTP fechado');
                    resolve();
                });
            });
        }
        
        // 2. Parar bot Telegram (apenas se estiver rodando)
        if (bot && bot.isRunning) {
            try {
                await bot.stop(signal);
                console.log('✅ Bot Telegram parado');
            } catch (err) {
                console.log('⚠️ Bot Telegram já estava parado');
            }
        }
        
        // 3. Parar bot WhatsApp se existir
        if (global.whatsappBot && global.whatsappBot.isConnected) {
            try {
                console.log('📱 Desconectando WhatsApp...');
                // Baileys não tem método stop, apenas fechamos a conexão
                if (global.whatsappBot.sock) {
                    await global.whatsappBot.sock.end();
                }
                console.log('✅ WhatsApp desconectado');
            } catch (err) {
                console.log('⚠️ Erro ao desconectar WhatsApp:', err.message);
            }
        }
        
        // 4. Fechar banco de dados
        if (db && db.open) {
            db.close();
            console.log('✅ Banco de dados fechado');
        }
        
        console.log('✅ Encerramento completo');
        process.exit(0);
    };
    
    // Timeout de segurança
    const timeout = setTimeout(() => {
        console.log('⚠️ Timeout de encerramento - forçando saída');
        process.exit(1);
    }, 10000);
    
    // Capturar sinais
    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));
    
    // Limpar timeout quando terminar
    process.on('exit', () => clearTimeout(timeout));
}

