async function fetchJsonWithTimeout(url, options = {}, timeoutMs = 7000) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), timeoutMs);
    try {
        const res = await fetch(url, { ...options, signal: controller.signal });
        const text = await res.text();
        let json = null;
        try { json = JSON.parse(text); } catch (e) {}
        if (!res.ok) {
            const msg = (json && json.error) ? String(json.error) : (text || `HTTP_${res.status}`);
            throw new Error(msg);
        }
        return json || { success: true };
    } finally {
        clearTimeout(timeout);
    }
}

async function enviarWhatsApp(numero, mensagem) {
    const number = String(numero || '').replace(/\D/g, '');
    if (!WHATSAPP_ENABLED) return false;
    if (!number) return false;
    const msg = String(mensagem || '').trim();
    if (!msg) return false;

    if (WHATSAPP_API_URL) {
        try {
            const result = await fetchJsonWithTimeout(`${WHATSAPP_API_URL.replace(/\/+$/, '')}/send`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ number, message: msg })
            }, 9000);
            if (result && result.success) {
                console.log(`✅ WhatsApp enviado para ${number}`);
                return true;
            }
            console.log(`⚠️ WhatsApp falhou para ${number}:`, result && result.error ? result.error : 'UNKNOWN');
        } catch (error) {
            console.error(`❌ Erro WhatsApp ${number}:`, error.message);
        }
    }

    if (whatsappBot && whatsappBot.isConnected) {
        try {
            const sent = await whatsappBot.sendMessage(number, msg);
            if (sent) console.log(`✅ WhatsApp (bot) enviado para ${number}`);
            return Boolean(sent);
        } catch (error) {
            console.error(`❌ Erro WhatsApp (bot) ${number}:`, error.message);
        }
    }

    return false;
}

// Todo broadcast de WhatsApp vai só pro grupo fixo (WHATSAPP_GRUPO_TRANSACOES) — antes ia para
// cada número de WHATSAPP_NUMBERS. Nome mantido para não mexer nos ~15 pontos que chamam.
// Retorno no mesmo formato de antes ([{ ..., resultado }]) pra quem conta os envios.
async function enviarWhatsAppParaTodos(mensagem) {
    if (!WHATSAPP_ENABLED) return [];
    // #region debug-point C:whatsapp-broadcast-targets
    reportWaDebug('C', 'sistema-mobile-3004.js:enviarWhatsAppParaTodos', 'Iniciando envio WhatsApp para o grupo fixo', {
        grupo: WHATSAPP_GRUPO_TRANSACOES,
        messageLength: String(mensagem || '').length
    }, 'wa-broadcast');
    // #endregion
    const ok = await enviarWhatsAppGrupoTexto(WHATSAPP_GRUPO_TRANSACOES, mensagem);
    return [{ grupo: WHATSAPP_GRUPO_TRANSACOES, resultado: ok }];
}

async function enviarWhatsAppArquivo(numero, filePath, caption = '') {
    const number = String(numero || '').replace(/\D/g, '');
    if (!WHATSAPP_ENABLED) return false;
    if (!number) return false;
    const fp = String(filePath || '').trim();
    if (!fp) return false;

    const cap = String(caption || '').trim();

    if (WHATSAPP_API_URL) {
        try {
            const result = await fetchJsonWithTimeout(`${WHATSAPP_API_URL.replace(/\/+$/, '')}/send-file`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    number,
                    filePath: fp,
                    fileName: path.basename(fp),
                    caption: cap
                })
            }, 20000);
            if (result && result.success) {
                console.log(`✅ WhatsApp arquivo enviado para ${number}`);
                return true;
            }
            console.log(`⚠️ WhatsApp arquivo falhou para ${number}:`, result && result.error ? result.error : 'UNKNOWN');
        } catch (error) {
            console.error(`❌ Erro WhatsApp arquivo ${number}:`, error.message);
        }
    }

    if (whatsappBot && whatsappBot.isConnected && whatsappBot.sock) {
        try {
            // Usa o mesmo resolvedor de JID do whatsapp-bot.js (com suporte a @lid)
            // quando disponível, em vez de montar "<numero>@s.whatsapp.net" na mão.
            const jid = typeof whatsappBot.resolveJid === 'function'
                ? await whatsappBot.resolveJid(number)
                : (number.endsWith('@s.whatsapp.net') ? number : number + '@s.whatsapp.net');
            const buffer = fs.readFileSync(fp);
            const ext = path.extname(fp).toLowerCase();
            const isImage = ext === '.jpg' || ext === '.jpeg' || ext === '.png' || ext === '.webp';
            if (isImage) {
                await whatsappBot.sock.sendMessage(jid, {
                    image: buffer,
                    mimetype: 'image/jpeg',
                    fileName: path.basename(fp),
                    caption: cap || undefined
                });
                console.log(`✅ WhatsApp imagem (bot) enviada para ${number} com metadados`);
            } else {
                let mimetype = 'application/octet-stream';
                if (ext === '.pdf') mimetype = 'application/pdf';
                await whatsappBot.sock.sendMessage(jid, {
                    document: buffer,
                    fileName: path.basename(fp),
                    mimetype: mimetype,
                    caption: cap || undefined
                });
                console.log(`✅ WhatsApp documento (bot) enviado para ${number}`);
            }
            return true;
        } catch (error) {
            console.error(`❌ Erro WhatsApp arquivo (bot) ${number}:`, error.message);
            const fallbackMsg = `${cap}\n\nArquivo: ${fp}`.trim();
            if (fallbackMsg) return await enviarWhatsApp(number, fallbackMsg);
            return false;
        }
    }


    const fallbackMsg = `${cap}\n\nArquivo: ${fp}`.trim();
    if (fallbackMsg) return await enviarWhatsApp(number, fallbackMsg);
    return false;
}

// Mesmo destino de enviarWhatsAppParaTodos: só o grupo fixo.
async function enviarWhatsAppArquivoParaTodos(filePath, caption = '') {
    if (!WHATSAPP_ENABLED) return [];
    const ok = await enviarWhatsAppGrupoArquivo(WHATSAPP_GRUPO_TRANSACOES, filePath, caption);
    return [{ grupo: WHATSAPP_GRUPO_TRANSACOES, resultado: ok }];
}

// Envia texto direto pra um JID de grupo. Não usa enviarWhatsApp() porque ela faz
// number.replace(/\D/g, ''), que apagaria o "@g.us" e quebraria o envio ao grupo.
async function enviarWhatsAppGrupoTexto(jid, mensagem) {
    if (!WHATSAPP_ENABLED) return false;
    const alvo = String(jid || '').trim();
    const msg = String(mensagem || '').trim();
    if (!alvo || !msg) return false;

    if (WHATSAPP_API_URL) {
        try {
            const result = await fetchJsonWithTimeout(`${WHATSAPP_API_URL.replace(/\/+$/, '')}/send`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ number: alvo, message: msg })
            }, 9000);
            if (result && result.success) {
                console.log(`✅ WhatsApp (grupo) enviado para ${alvo}`);
                return true;
            }
            console.log(`⚠️ WhatsApp (grupo) falhou para ${alvo}:`, result && result.error ? result.error : 'UNKNOWN');
        } catch (error) {
            console.error(`❌ Erro WhatsApp (grupo) ${alvo}:`, error.message);
        }
    }

    if (whatsappBot && whatsappBot.isConnected && whatsappBot.sock) {
        try {
            await whatsappBot.sock.sendMessage(alvo, { text: msg });
            console.log(`✅ WhatsApp (bot, grupo) enviado para ${alvo}`);
            return true;
        } catch (error) {
            console.error(`❌ Erro WhatsApp (bot, grupo) ${alvo}:`, error.message);
        }
    }

    return false;
}

// Mesma ideia de enviarWhatsAppGrupoTexto, mas para arquivo (recibo/comprovante).
async function enviarWhatsAppGrupoArquivo(jid, filePath, caption = '') {
    if (!WHATSAPP_ENABLED) return false;
    const alvo = String(jid || '').trim();
    const fp = String(filePath || '').trim();
    if (!alvo || !fp) return false;
    const cap = String(caption || '').trim();

    if (WHATSAPP_API_URL) {
        try {
            const result = await fetchJsonWithTimeout(`${WHATSAPP_API_URL.replace(/\/+$/, '')}/send-file`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ number: alvo, filePath: fp, fileName: path.basename(fp), caption: cap })
            }, 20000);
            if (result && result.success) {
                console.log(`✅ WhatsApp arquivo (grupo) enviado para ${alvo}`);
                return true;
            }
            console.log(`⚠️ WhatsApp arquivo (grupo) falhou para ${alvo}:`, result && result.error ? result.error : 'UNKNOWN');
        } catch (error) {
            console.error(`❌ Erro WhatsApp arquivo (grupo) ${alvo}:`, error.message);
        }
    }

    if (whatsappBot && whatsappBot.isConnected && whatsappBot.sock) {
        try {
            const buffer = fs.readFileSync(fp);
            const ext = path.extname(fp).toLowerCase();
            const isImage = ext === '.jpg' || ext === '.jpeg' || ext === '.png' || ext === '.webp';
            if (isImage) {
                await whatsappBot.sock.sendMessage(alvo, { image: buffer, mimetype: 'image/jpeg', fileName: path.basename(fp), caption: cap || undefined });
            } else {
                let mimetype = 'application/octet-stream';
                if (ext === '.pdf') mimetype = 'application/pdf';
                await whatsappBot.sock.sendMessage(alvo, { document: buffer, fileName: path.basename(fp), mimetype, caption: cap || undefined });
            }
            console.log(`✅ WhatsApp arquivo (bot, grupo) enviado para ${alvo}`);
            return true;
        } catch (error) {
            console.error(`❌ Erro WhatsApp arquivo (bot, grupo) ${alvo}:`, error.message);
            return await enviarWhatsAppGrupoTexto(alvo, `${cap}\n\nArquivo: ${fp}`.trim());
        }
    }

    return await enviarWhatsAppGrupoTexto(alvo, `${cap}\n\nArquivo: ${fp}`.trim());
}

async function notificarTransacaoWhatsApp(transaction, fileBuffer = null) {
    if (!WHATSAPP_ENABLED) return [];
    const amount = Number(transaction && transaction.amount ? transaction.amount : 0);
    const valorFormatado = formatBRL(amount);
    const tipo = String(transaction && transaction.type ? transaction.type : '').toLowerCase();
    const tipoEmoji = tipo === 'income' ? '💰' : '💸';
    const tipoTexto = tipo === 'income' ? 'RECEITA' : 'DESPESA';
    const descricao = String(transaction && transaction.description ? transaction.description : 'Transação');
    const categoria = String(transaction && transaction.category ? transaction.category : 'Outros');
    const metodo = String(transaction && (transaction.paymentMethod || transaction.payment_method) ? (transaction.paymentMethod || transaction.payment_method) : 'Não informado');
    const usuario = String(transaction && (transaction.userName || transaction.user_name || transaction.user) ? (transaction.userName || transaction.user_name || transaction.user) : '');

    const ci = transaction && transaction.cnpjInfo;
    let linhaCnpj = '';
    if (ci) {
        const partes = [];
        if (ci.fantasia) partes.push(`🏢 ${ci.fantasia}`);
        if (ci.cnpj) {
            const c = ci.cnpj;
            const fmt = c.length === 14 ? `${c.slice(0,2)}.${c.slice(2,5)}.${c.slice(5,8)}/${c.slice(8,12)}-${c.slice(12)}` : c;
            partes.push(`📋 CNPJ: ${fmt}`);
        }
        if (ci.cnaeTxt) partes.push(`🏭 ${ci.cnaeTxt}`);
        if (ci.cidadeUf) partes.push(`📍 ${ci.cidadeUf}`);
        if (partes.length) linhaCnpj = partes.join('\n') + '\n';
    }

    const mensagem =
        `${tipoEmoji} *NOVA ${tipoTexto}*\n` +
        `━━━━━━━━━━━━━━━━━━━━\n` +
        `📝 ${descricao}\n` +
        `💵 ${valorFormatado}\n` +
        `📂 ${categoria}\n` +
        `💳 ${metodo}\n` +
        (usuario ? `👤 ${usuario}\n` : '') +
        `━━━━━━━━━━━━━━━━━━━━\n` +
        linhaCnpj +
        (transaction && transaction.note && transaction.registrada !== false ? `${transaction.note}\n` : '') +
        `⏰ ${moment().tz('America/Sao_Paulo').format('DD/MM/YYYY HH:mm:ss')}`;

    let tempPath = null;
    let filePath = null;

    try {
        const receiptName = transaction && (transaction.receipt_image || transaction.receiptImage) ? String(transaction.receipt_image || transaction.receiptImage) : '';
        if (fileBuffer && Buffer.isBuffer(fileBuffer) && fileBuffer.length > 0) {
            const tempFileName = `wa_temp_${Date.now()}_${Math.random().toString(16).slice(2, 8)}.jpg`;
            tempPath = path.join(RECEIPTS_DIR, tempFileName);
            fs.writeFileSync(tempPath, fileBuffer);
            filePath = tempPath;
        } else if (receiptName) {
            const fp = path.join(RECEIPTS_DIR, receiptName);
            if (fs.existsSync(fp)) filePath = fp;
        }

        // Todas as notificações de transação vão só pro grupo fixo (antes iam pro
        // número do usuário + cópia pra User2 quando a transação era do User1).
        if (filePath) {
            const ok = await enviarWhatsAppGrupoArquivo(WHATSAPP_GRUPO_TRANSACOES, filePath, mensagem);
            return [{ grupo: WHATSAPP_GRUPO_TRANSACOES, resultado: ok }];
        }

        const ok = await enviarWhatsAppGrupoTexto(WHATSAPP_GRUPO_TRANSACOES, mensagem);
        return [{ grupo: WHATSAPP_GRUPO_TRANSACOES, resultado: ok }];
    } finally {
        if (tempPath) {
            try { fs.unlinkSync(tempPath); } catch (e) {}
        }
    }
}

async function initWhatsAppIntegration() {
    try {
        const wantsEmbedded = String(process.env.WHATSAPP_USE_EMBEDDED || '').toLowerCase() === 'true';
        if (!wantsEmbedded) {
            console.log(`📱 WhatsApp via API HTTP: ${WHATSAPP_API_URL}`);
            return;
        }

        const fs = require('fs');
        const waPath = path.join(__dirname, 'whatsapp-bot.js');
        
        if (fs.existsSync(waPath)) {
            console.log('\n📱 Inicializando integração com WhatsApp...');
            
            // Importar o módulo
            const waModule = require('./whatsapp-bot.js');
            
            // Aguardar conexão do WhatsApp
            setTimeout(() => {
                if (waModule.isConnected) {
                    console.log('✅ WhatsApp integrado ao sistema financeiro!');
                    global.whatsappBot = waModule;
                    whatsappBot = waModule;
                } else if (waModule.sock) {
                    console.log('⚠️ WhatsApp Bot iniciado, aguardando conexão...');
                    global.whatsappBot = waModule;
                    whatsappBot = waModule;
                    
                    // Monitorar conexão
                    const checkInterval = setInterval(() => {
                        if (waModule.isConnected) {
                            console.log('✅ WhatsApp conectado com sucesso!');
                            clearInterval(checkInterval);
                        }
                    }, 2000);
                    
                    setTimeout(() => clearInterval(checkInterval), 30000);
                } else {
                    console.log('⚠️ WhatsApp Bot não respondeu');
                }
            }, 3000);
        } else {
            console.log('ℹ️ WhatsApp Bot não encontrado. Para ativar, crie o arquivo whatsapp-bot.js');
            console.log('   Execute: npm install @whiskeysockets/baileys qrcode-terminal pino');
        }
    } catch (error) {
        console.log('⚠️ WhatsApp Bot não disponível:', error.message);
    }
}

// ============== FUNÇÃO DE NOTIFICAÇÃO HÍBRIDA ==============
// Salvar referência da função original
const originalNotifyTelegram = notificarTelegram;

// Sobrescrever função de notificação para enviar também para WhatsApp
notificarTelegram = async (transaction, fileBuffer) => {
    let result = { telegram: false, whatsapp: false };
    
    // 1. Notificar Telegram (sempre)
    try {
        result.telegram = await originalNotifyTelegram(transaction, fileBuffer);
    } catch (error) {
        console.error('❌ Erro no Telegram:', error.message);
    }
    
    if (transaction && transaction.__waSent) return result;

    if (WHATSAPP_ENABLED) {
        try {
            const envios = await notificarTransacaoWhatsApp(transaction, fileBuffer);
            result.whatsapp = Array.isArray(envios) ? envios.some((e) => e && e.resultado) : false;
        } catch (waError) {
            console.error('❌ Erro ao enviar para WhatsApp:', waError.message);
            result.whatsapp = false;
        }
    }
    
    return result;
};

